INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('smart-village-solutions/sva-studio/changelog-automation', 'community', 'smart-village-solutions', 'sva-studio', 'smart-village-solutions/sva-studio', 'changelog-automation', 0, 0, 60, '2026-03-08T01:57:15.448Z', '2026-03-08T02:08:57.736Z', '3b5fc90d13fa54918da996f84920eeb233efdb597decd77728f4c2d1d84049e6', '{"id":"smart-village-solutions/sva-studio/changelog-automation","name":"changelog-automation","description":{"en":"The changelog-automation skill automates changelog generation, release notes, and version management for developers. It standardizes commit message formats and generates GitHub/GitLab release notes.","zh":"Changelog 自动化是通过 Conventional Commits 和 semantic versioning 实现的，用于生成 changelog 和版本管理","ja":"Changelog 自動化は Conventional Commits と semantic versioning を使用して実現され、Changelog とバージョン管理を行います","ko":"Changelog 자동화는 Conventional Commits와 semantic versioning을 사용하여 changelog와 버전 관리를 수행합니다","es":"La automatización de registros de cambios permite la generación automática de notas de lanzamiento y versiones siguiendo estándares de la industria","fr":"L''automatisation du journal des modifications permet la génération automatique de notes de version et de versions suivant les normes de l''industrie","de":"Die Automatisierung von Änderungsprotokollen ermöglicht die automatische Erstellung von Versionshinweisen und Versionen nach Branchenstandards","pt":"A automação de changelog é um padrão para gerar changelogs e notas de lançamento de forma automática, utilizando commites convencionais e versionamento semântico.","ru":"Автоматизация изменений - это padrão для генерации изменений и заметок о выпуске с помощью конвенциональных коммитов и семантического версионирования","ar":"آلي سجل التعديلات هو معيار لإنشاء سجلات التعديلات وملاحظات الإصدار تلقائيًا باستخدام أنماط الإلتزامات وتدوين الإصدارات"},"seo":{"title":{"en":"changelog-automation: Automated Release Notes Setup Guide...","zh":"Changelog 自动化设置指南 - AIエージェント工具","ja":"Changelog 自動化のベストプラクティス - AIエージェント","ko":"Changelog 자동화 설정 가이드 - AI 에이전트 도구","es":"Automatización de registros de cambios: Guía de configura...","fr":"Automatisation du journal des modifications: Meilleures p...","de":"Changelog-Automatisierung: Einrichtungsanleitung","pt":"Guia de Configuração de Automação de Changelog","ru":"Настройка автоматизации изменений: ИИ Агенты для разработ...","ar":"دليل إعداد آلي لتشغيل سجل التعديلات"},"description":{"en":"Discover how to automate changelog generation and release notes with industry-standard tools and patterns. Learn to set up Conventional Commits and semantic ...","zh":"了解如何使用 Conventional Commits 和 semantic versioning 实现 changelog 自动化，提高开发效率","ja":"Conventional Commits と semantic versioning を使用した Changelog 自動化の方法を紹介します","ko":"Conventional Commits와 semantic versioning을 사용한 Changelog 자동화 방법을 알아보세요","es":"Aprende a automatizar la generación de registros de cambios y notas de lanzamiento con herramientas y patrones de la industria","fr":"Découvrez comment automatiser la génération de journaux de modifications et de notes de version avec des outils et des modèles standardisés","de":"Erfahren Sie, wie Sie die Erstellung von Änderungsprotokollen und Versionshinweisen mit Branchenwerkzeugen und -mustern automatisieren","pt":"Aprenda a automatizar a geração de changelogs e notas de lançamento com padrões de commites e versionamento semântico","ru":"Автоматизируйте генерацию изменений и заметок о выпуске с помощью конвенциональных коммитов и семантического версионирования","ar":"تعلم كيفية توفير автоматي لإنشاء سجلات التعديلات وملاحظات الإصدار باستخدام أنماط الإلتزامات وتدوين الإصدارات"},"definition":{"en":"changelog-automation is a set of patterns and tools for automating changelog generation, release notes, and version management following industry standards.","zh":"Changelog 自动化是指使用工具和模式自动生成 changelog 和版本管理","ja":"Changelog 自動化は、ツールとパターンを使用して Changelog とバージョン管理を自動化することです","ko":"Changelog 자동화는 도구와 패턴을 사용하여 changelog와 버전 관리를 자동화하는 것을 말합니다","es":"La automatización de registros de cambios es el proceso de generar automáticamente notas de lanzamiento y versiones","fr":"L''automatisation du journal des modifications est le processus de génération automatique de notes de version et de versions","de":"Die Automatisierung von Änderungsprotokollen ist der Prozess der automatischen Erstellung von Versionshinweisen und Versionen","pt":"Automação de changelog é a prática de gerar changelogs de forma automática","ru":"Автоматизация изменений - это практика генерации изменений в автоматическом режиме","ar":"آلي سجل التعديلات هو ممارسة لإنشاء سجلات التعديلات تلقائيًا"},"features":{"en":["Generates GitHub/GitLab release notes","Implements Conventional Commits for standardized commit message formats","Creates release note workflows for efficient version management","Manages semantic versioning for accurate change tracking","Standardizes commit message formats for clear communication","Automates changelog generation for reduced manual effort"],"zh":["Conventional Commits 支持","semantic versioning 支持","自动生成 changelog","GitHub/GitLab Release Notes 生成","标准化 commit 消息格式"],"ja":["Conventional Commits をサポート","semantic versioning をサポート","Changelog を自動生成","GitHub/GitLab Release Notes を生成","コミットメッセージの形式を標準化"],"ko":["Conventional Commits 지원","semantic versioning 지원","changelog 자동 생성","GitHub/GitLab Release Notes 생성","commit 메시지 형식 표준화"],"es":["Implementación de Commits Convencionales","Generación automática de notas de lanzamiento","Establecimiento de formatos de mensaje de commit estándar","Administración de versiones semánticas","Integración con GitHub y GitLab","Creación de flujos de trabajo de notas de versión"],"fr":["Mise en œuvre de Commits Convencionnels","Génération automatique de notes de version","Établissement de formats de message de commit standardisés","Gestion de versions sémantiques","Intégration avec GitHub et GitLab","Création de flux de travail de notes de version"],"de":["Implementierung von Conventional Commits","Automatische Erstellung von Versionshinweisen","Festlegung von Standard-Commit-Nachrichtenformaten","Verwaltung von semantischen Versionen","Integration mit GitHub und GitLab","Erstellung von Arbeitsflüssen für Versionshinweise"],"pt":["Geração automática de changelogs","Implementação de Commits Convencionais","Criação de fluxos de trabalho para notas de lançamento","Padronização de formatos de mensagens de commite","Geração de notas de lançamento para GitHub/GitLab","Gerenciamento de versionamento semântico"],"ru":["Автоматическая генерация изменений","Реализация конвенциональных коммитов","Создание рабочих процессов для заметок о выпуске","Стандартизация форматов сообщений о коммитах","Генерация заметок о выпуске для GitHub/GitLab","Управление семантическим версионированием"],"ar":["إنشاء آلي لسجلات التعديلات","تنفيذ أنماط الإلتزامات","إنشاء سير عمل لملاحظات الإصدار","توحيد تنسيقات رسائل الإلتزام","إنشاء ملاحظات الإصدار لمنصة GitHub/GitLab","إدارة تدوين الإصدارات"]},"keywords":{"en":["how to use changelog-automation","changelog-automation setup guide","automated release notes","Conventional Commits tutorial","semantic versioning best practices","changelog-automation vs manual changelog","changelog-automation install","release notes automation","version management tools"],"zh":["Changelog 自动化","Conventional Commits","semantic versioning","自动化 changelog 生成","GitHub Release Notes","GitLab Release Notes","commit 消息格式"],"ja":["Changelog 自動化","Conventional Commits","semantic versioning","Changelog 自動生成","GitHub Release Notes","GitLab Release Notes","コミットメッセージ形式"],"ko":["Changelog 자동화","Conventional Commits","semantic versioning","changelog 자동 생성","GitHub Release Notes","GitLab Release Notes","commit 메시지 형식"],"es":["automatización de registros de cambios","generación de notas de lanzamiento","versiones semánticas","Commits Convencionales","GitHub","GitLab","herramientas de automatización de versiones","patrones de automatización de versiones","mejores prácticas de automatización de versiones"],"fr":["automatisation du journal des modifications","génération de notes de version","versions sémantiques","Commits Convencionnels","GitHub","GitLab","outils d''automatisation de version","modèles d''automatisation de version","meilleures pratiques d''automatisation de version"],"de":["Automatisierung von Änderungsprotokollen","Erstellung von Versionshinweisen","semantische Versionen","Conventional Commits","GitHub","GitLab","Werkzeuge für die Automatisierung von Versionen","Muster für die Automatisierung von Versionen","Best Practices für die Automatisierung von Versionen"],"pt":["automação de changelog","commits convencionais","versionamento semântico","geração de changelogs","notas de lançamento","github","gitlab","desenvolvimento de software"],"ru":["автоматизация изменений","конвенциональные коммиты","семантическое версионирование","генерация изменений","заметки о выпуске","github","gitlab","разработка программного обеспечения"],"ar":["آلي سجل التعديلات","أنماط الإلتزامات","تدوين الإصدارات","إنشاء سجلات التعديلات","ملاحظات الإصدار","github","gitlab","تطوير البرمجيات"]}},"owner":"smart-village-solutions","repo":"sva-studio","repoPath":"smart-village-solutions/sva-studio","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.448Z","topics":[],"category":"community","skillMd":{"name":"changelog-automation","description":"Automate changelog generation from commits, PRs, and releases following Keep a Changelog format. Use when setting up release workflows, generating release notes, or standardizing commit conventions.","bodyPreview":"# Changelog Automation\n\nPatterns and tools for automating changelog generation, release notes, and version management following industry standards.\n\n## When to Use This Skill\n\n- Setting up automated changelog generation\n- Implementing Conventional Commits\n- Creating release note workflows\n- Standardizing commit message formats\n- Generating GitHub/GitLab release notes\n- Managing semantic versioning\n\n## Core Concepts\n\n### 1. Keep a Changelog Format\n\n```markdown\n# Changelog\n\nAll notable changes to","body":"# Changelog Automation\n\nPatterns and tools for automating changelog generation, release notes, and version management following industry standards.\n\n## When to Use This Skill\n\n- Setting up automated changelog generation\n- Implementing Conventional Commits\n- Creating release note workflows\n- Standardizing commit message formats\n- Generating GitHub/GitLab release notes\n- Managing semantic versioning\n\n## Core Concepts\n\n### 1. Keep a Changelog Format\n\n```markdown\n# Changelog\n\nAll notable changes to this project will be documented in this file.\n\nThe format is based on [Keep a Changelog](https://keepachangelog.com/en/1.1.0/),\nand this project adheres to [Semantic Versioning](https://semver.org/spec/v2.0.0.html).\n\n## [Unreleased]\n\n### Added\n\n- New feature X\n\n## [1.2.0] - 2024-01-15\n\n### Added\n\n- User profile avatars\n- Dark mode support\n\n### Changed\n\n- Improved loading performance by 40%\n\n### Deprecated\n\n- Old authentication API (use v2)\n\n### Removed\n\n- Legacy payment gateway\n\n### Fixed\n\n- Login timeout issue (#123)\n\n### Security\n\n- Updated dependencies for CVE-2024-1234\n\n[Unreleased]: https://github.com/user/repo/compare/v1.2.0...HEAD\n[1.2.0]: https://github.com/user/repo/compare/v1.1.0...v1.2.0\n```\n\n### 2. Conventional Commits\n\n```\n<type>[optional scope]: <description>\n\n[optional body]\n\n[optional footer(s)]\n```\n\n| Type       | Description      | Changelog Section  |\n| ---------- | ---------------- | ------------------ |\n| `feat`     | New feature      | Added              |\n| `fix`      | Bug fix          | Fixed              |\n| `docs`     | Documentation    | (usually excluded) |\n| `style`    | Formatting       | (usually excluded) |\n| `refactor` | Code restructure | Changed            |\n| `perf`     | Performance      | Changed            |\n| `test`     | Tests            | (usually excluded) |\n| `chore`    | Maintenance      | (usually excluded) |\n| `ci`       | CI changes       | (usually excluded) |\n| `build`    | Build system     | (usually excluded) |\n| `revert`   | Revert commit    | Removed            |\n\n### 3. Semantic Versioning\n\n```\nMAJOR.MINOR.PATCH\n\nMAJOR: Breaking changes (feat! or BREAKING CHANGE)\nMINOR: New features (feat)\nPATCH: Bug fixes (fix)\n```\n\n## Implementation\n\n### Method 1: Conventional Changelog (Node.js)\n\n```bash\n# Install tools\nnpm install -D @commitlint/cli @commitlint/config-conventional\nnpm install -D husky\nnpm install -D standard-version\n# or\nnpm install -D semantic-release\n\n# Setup commitlint\ncat > commitlint.config.js << ''EOF''\nmodule.exports = {\n  extends: [''@commitlint/config-conventional''],\n  rules: {\n    ''type-enum'': [\n      2,\n      ''always'',\n      [\n        ''feat'',\n        ''fix'',\n        ''docs'',\n        ''style'',\n        ''refactor'',\n        ''perf'',\n        ''test'',\n        ''chore'',\n        ''ci'',\n        ''build'',\n        ''revert'',\n      ],\n    ],\n    ''subject-case'': [2, ''never'', [''start-case'', ''pascal-case'', ''upper-case'']],\n    ''subject-max-length'': [2, ''always'', 72],\n  },\n};\nEOF\n\n# Setup husky\nnpx husky init\necho \"npx --no -- commitlint --edit \\$1\" > .husky/commit-msg\n```\n\n### Method 2: standard-version Configuration\n\n```javascript\n// .versionrc.js\nmodule.exports = {\n  types: [\n    { type: \"feat\", section: \"Features\" },\n    { type: \"fix\", section: \"Bug Fixes\" },\n    { type: \"perf\", section: \"Performance Improvements\" },\n    { type: \"revert\", section: \"Reverts\" },\n    { type: \"docs\", section: \"Documentation\", hidden: true },\n    { type: \"style\", section: \"Styles\", hidden: true },\n    { type: \"chore\", section: \"Miscellaneous\", hidden: true },\n    { type: \"refactor\", section: \"Code Refactoring\", hidden: true },\n    { type: \"test\", section: \"Tests\", hidden: true },\n    { type: \"build\", section: \"Build System\", hidden: true },\n    { type: \"ci\", section: \"CI/CD\", hidden: true },\n  ],\n  commitUrlFormat: \"{{host}}/{{owner}}/{{repository}}/commit/{{hash}}\",\n  compareUrlFormat:\n    \"{{host}}/{{owner}}/{{repository}}/compare/{{previousTag}}...{{currentTag}}\",\n  issueUrlFormat: \"{{host}}/{{owner}}/{{repository}}/issues/{{id}}\",\n  userUrlFormat: \"{{host}}/{{user}}\",\n  releaseCommitMessageFormat: \"chore(release): {{currentTag}}\",\n  scripts: {\n    prebump: ''echo \"Running prebump\"'',\n    postbump: ''echo \"Running postbump\"'',\n    prechangelog: ''echo \"Running prechangelog\"'',\n    postchangelog: ''echo \"Running postchangelog\"'',\n  },\n};\n```\n\n```json\n// package.json scripts\n{\n  \"scripts\": {\n    \"release\": \"standard-version\",\n    \"release:minor\": \"standard-version --release-as minor\",\n    \"release:major\": \"standard-version --release-as major\",\n    \"release:patch\": \"standard-version --release-as patch\",\n    \"release:dry\": \"standard-version --dry-run\"\n  }\n}\n```\n\n### Method 3: semantic-release (Full Automation)\n\n```javascript\n// release.config.js\nmodule.exports = {\n  branches: [\n    \"main\",\n    { name: \"beta\", prerelease: true },\n    { name: \"alpha\", prerelease: true },\n  ],\n  plugins: [\n    \"@semantic-release/commit-analyzer\",\n    \"@semantic-release/release-notes-generator\",\n    [\n      \"@semantic-release/changelog\",\n      {\n        changelogFile: \"CHANGELOG.md\",\n      },\n    ],\n    [\n      \"@semantic-release/npm\",\n      {\n        npmPublish: true,\n      },\n    ],\n    [\n      \"@semantic-release/github\",\n      {\n        assets: [\"dist/**/*.js\", \"dist/**/*.css\"],\n      },\n    ],\n    [\n      \"@semantic-release/git\",\n      {\n        assets: [\"CHANGELOG.md\", \"package.json\"],\n        message:\n          \"chore(release): ${nextRelease.version} [skip ci]\\n\\n${nextRelease.notes}\",\n      },\n    ],\n  ],\n};\n```\n\n### Method 4: GitHub Actions Workflow\n\n```yaml\n# .github/workflows/release.yml\nname: Release\n\non:\n  push:\n    branches: [main]\n  workflow_dispatch:\n    inputs:\n      release_type:\n        description: \"Release type\"\n        required: true\n        default: \"patch\"\n        type: choice\n        options:\n          - patch\n          - minor\n          - major\n\npermissions:\n  contents: write\n  pull-requests: write\n\njobs:\n  release:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n          token: ${{ secrets.GITHUB_TOKEN }}\n\n      - uses: actions/setup-node@v4\n        with:\n          node-version: \"20\"\n          cache: \"npm\"\n\n      - run: npm ci\n\n      - name: Configure Git\n        run: |\n          git config user.name \"github-actions[bot]\"\n          git config user.email \"github-actions[bot]@users.noreply.github.com\"\n\n      - name: Run semantic-release\n        env:\n          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}\n          NPM_TOKEN: ${{ secrets.NPM_TOKEN }}\n        run: npx semantic-release\n\n  # Alternative: manual release with standard-version\n  manual-release:\n    if: github.event_name == ''workflow_dispatch''\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n\n      - uses: actions/setup-node@v4\n        with:\n          node-version: \"20\"\n\n      - run: npm ci\n\n      - name: Configure Git\n        run: |\n          git config user.name \"github-actions[bot]\"\n          git config user.email \"github-actions[bot]@users.noreply.github.com\"\n\n      - name: Bump version and generate changelog\n        run: npx standard-version --release-as ${{ inputs.release_type }}\n\n      - name: Push changes\n        run: git push --follow-tags origin main\n\n      - name: Create GitHub Release\n        uses: softprops/action-gh-release@v1\n        with:\n          tag_name: ${{ steps.version.outputs.tag }}\n          body_path: RELEASE_NOTES.md\n          generate_release_notes: true\n```\n\n### Method 5: git-cliff (Rust-based, Fast)\n\n```toml\n# cliff.toml\n[changelog]\nheader = \"\"\"\n# Changelog\n\nAll notable changes to this project will be documented in this file.\n\n\"\"\"\nbody = \"\"\"\n{% if version %}\\\n    ## [{{ version | trim_start_matches(pat=\"v\") }}] - {{ timestamp | date(format=\"%Y-%m-%d\") }}\n{% else %}\\\n    ## [Unreleased]\n{% endif %}\\\n{% for group, commits in commits | group_by(attribute=\"group\") %}\n    ### {{ group | upper_first }}\n    {% for commit in commits %}\n        - {% if commit.scope %}**{{ commit.scope }}:** {% endif %}\\\n            {{ commit.message | upper_first }}\\\n            {% if commit.github.pr_number %} ([#{{ commit.github.pr_number }}](https://github.com/owner/repo/pull/{{ commit.github.pr_number }})){% endif %}\\\n    {% endfor %}\n{% endfor %}\n\"\"\"\nfooter = \"\"\"\n{% for release in releases -%}\n    {% if release.version -%}\n        {% if release.previous.version -%}\n            [{{ release.version | trim_start_matches(pat=\"v\") }}]: \\\n                https://github.com/owner/repo/compare/{{ release.previous.version }}...{{ release.version }}\n        {% endif -%}\n    {% else -%}\n        [unreleased]: https://github.com/owner/repo/compare/{{ release.previous.version }}...HEAD\n    {% endif -%}\n{% endfor %}\n\"\"\"\ntrim = true\n\n[git]\nconventional_commits = true\nfilter_unconventional = true\nsplit_commits = false\ncommit_parsers = [\n    { message = \"^feat\", group = \"Features\" },\n    { message = \"^fix\", group = \"Bug Fixes\" },\n    { message = \"^doc\", group = \"Documentation\" },\n    { message = \"^perf\", group = \"Performance\" },\n    { message = \"^refactor\", group = \"Refactoring\" },\n    { message = \"^style\", group = \"Styling\" },\n    { message = \"^test\", group = \"Testing\" },\n    { message = \"^chore\\\\(release\\\\)\", skip = true },\n    { message = \"^chore\", group = \"Miscellaneous\" },\n]\nfilter_commits = false\ntag_pattern = \"v[0-9]*\"\nskip_tags = \"\"\nignore_tags = \"\"\ntopo_order = false\nsort_commits = \"oldest\"\n\n[github]\nowner = \"owner\"\nrepo = \"repo\"\n```\n\n```bash\n# Generate changelog\ngit cliff -o CHANGELOG.md\n\n# Generate for specific range\ngit cliff v1.0.0..v2.0.0 -o RELEASE_NOTES.md\n\n# Preview without writing\ngit cliff --unreleased --dry-run\n```\n\n### Method 6: Python (commitizen)\n\n```toml\n# pyproject.toml\n[tool.commitizen]\nname = \"cz_conventional_commits\"\nversion = \"1.0.0\"\nversion_files = [\n    \"pyproject.toml:version\",\n    \"src/__init__.py:__version__\",\n]\ntag_format = \"v$version\"\nupdate_changelog_on_bump = true\nchangelog_incremental = true\nchangelog_start_rev = \"v0.1.0\"\n\n[tool.commitizen.customize]\nmessage_template = \"{{change_type}}{% if scope %}({{scope}}){% endif %}: {{message}}\"\nschema = \"<type>(<scope>): <subject>\"\nschema_pattern = \"^(feat|fix|docs|style|refactor|perf|test|chore)(\\\\(\\\\w+\\\\))?:\\\\s.*\"\nbump_pattern = \"^(feat|fix|perf|refactor)\"\nbump_map = {\"feat\" = \"MINOR\", \"fix\" = \"PATCH\", \"perf\" = \"PATCH\", \"refactor\" = \"PATCH\"}\n```\n\n```bash\n# Install\npip install commitizen\n\n# Create commit interactively\ncz commit\n\n# Bump version and update changelog\ncz bump --changelog\n\n# Check commits\ncz check --rev-range HEAD~5..HEAD\n```\n\n## Release Notes Templates\n\n### GitHub Release Template\n\n```markdown\n## What''s Changed\n\n### 🚀 Features\n\n{{ range .Features }}\n\n- {{ .Title }} by @{{ .Author }} in #{{ .PR }}\n  {{ end }}\n\n### 🐛 Bug Fixes\n\n{{ range .Fixes }}\n\n- {{ .Title }} by @{{ .Author }} in #{{ .PR }}\n  {{ end }}\n\n### 📚 Documentation\n\n{{ range .Docs }}\n\n- {{ .Title }} by @{{ .Author }} in #{{ .PR }}\n  {{ end }}\n\n### 🔧 Maintenance\n\n{{ range .Chores }}\n\n- {{ .Title }} by @{{ .Author }} in #{{ .PR }}\n  {{ end }}\n\n## New Contributors\n\n{{ range .NewContributors }}\n\n- @{{ .Username }} made their first contribution in #{{ .PR }}\n  {{ end }}\n\n**Full Changelog**: https://github.com/owner/repo/compare/v{{ .Previous }}...v{{ .Current }}\n```\n\n### Internal Release Notes\n\n```markdown\n# Release v2.1.0 - January 15, 2024\n\n## Summary\n\nThis release introduces dark mode support and improves checkout performance\nby 40%. It also includes important security updates.\n\n## Highlights\n\n### 🌙 Dark Mode\n\nUsers can now switch to dark mode from settings. The preference is\nautomatically saved and synced across devices.\n\n### ⚡ Performance\n\n- Checkout flow is 40% faster\n- Reduced bundle size by 15%\n\n## Breaking Changes\n\nNone in this release.\n\n## Upgrade Guide\n\nNo special steps required. Standard deployment process applies.\n\n## Known Issues\n\n- Dark mode may flicker on initial load (fix scheduled for v2.1.1)\n\n## Dependencies Updated\n\n| Package | From    | To      | Reason                   |\n| ------- | ------- | ------- | ------------------------ |\n| react   | 18.2.0  | 18.3.0  | Performance improvements |\n| lodash  | 4.17.20 | 4.17.21 | Security patch           |\n```\n\n## Commit Message Examples\n\n```bash\n# Feature with scope\nfeat(auth): add OAuth2 support for Google login\n\n# Bug fix with issue reference\nfix(checkout): resolve race condition in payment processing\n\nCloses #123\n\n# Breaking change\nfeat(api)!: change user endpoint response format\n\nBREAKING CHANGE: The user endpoint now returns `userId` instead of `id`.\nMigration guide: Update all API consumers to use the new field name.\n\n# Multiple paragraphs\nfix(database): handle connection timeouts gracefully\n\nPreviously, connection timeouts would cause the entire request to fail\nwithout retry. This change implements exponential backoff with up to\n3 retries before failing.\n\nThe timeout threshold has been increased from 5s to 10s based on p99\nlatency analysis.\n\nFixes #456\nReviewed-by: @alice\n```\n\n## Best Practices\n\n### Do''s\n\n- **Follow Conventional Commits** - Enables automation\n- **Write clear messages** - Future you will thank you\n- **Reference issues** - Link commits to tickets\n- **Use scopes consistently** - Define team conventions\n- **Automate releases** - Reduce manual errors\n\n### Don''ts\n\n- **Don''t mix changes** - One logical change per commit\n- **Don''t skip validation** - Use commitlint\n- **Don''t manual edit** - Generated changelogs only\n- **Don''t forget breaking changes** - Mark with `!` or footer\n- **Don''t ignore CI** - Validate commits in pipeline\n\n## Resources\n\n- [Keep a Changelog](https://keepachangelog.com/)\n- [Conventional Commits](https://www.conventionalcommits.org/)\n- [Semantic Versioning](https://semver.org/)\n- [semantic-release](https://semantic-release.gitbook.io/)\n- [git-cliff](https://git-cliff.org/)\n"},"lastSynced":"2026-03-08T02:08:57.736Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing automated changelog generation and release note management.","zh":"适合需要自动化变更日志生成和发布说明管理的开发者代理。","ja":"開発者エージェントが自動化された変更ログの生成とリリースノートの管理を必要とする場合に適しています。","ko":"자동화된 변경 로그 생성 및 릴리즈 노트 관리가 필요한 개발자 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan generación automática de registros de cambios y administración de notas de lanzamiento.","fr":"Parfait pour les Agents de Développeur ayant besoin d''une génération automatique de journal des modifications et de gestion des notes de version.","de":"Perfekt für Developer-Agents, die eine automatisierte Generierung von Änderungsprotokollen und eine Verwaltung von Versionshinweisen benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de geração automática de registros de alterações e gerenciamento de notas de lançamento.","ru":"Идеально подходит для агентов разработчиков, которым необходима автоматизированная генерация журнала изменений и управление заметками о выпуске.","ar":"مثالي لعميل تطوير بحاجة إلى توليد تلقائي لسجل التغييرات وإدارة ملاحظات الإصدار."},"recommendation":{"en":"Empowers agents to standardize commit message formats and generate GitHub/GitLab release notes using Conventional Commits and semantic versioning protocols, streamlining version management and release workflows.","zh":"赋予代理标准化提交消息格式和使用 Conventional Commits 和语义版本控制协议生成 GitHub/GitLab 发布说明的能力，简化版本管理和发布工作流程。","ja":"エージェントにコミットメッセージの形式を標準化し、Conventional Commits とセマンティック バージョニング プロトコルを使用して GitHub/GitLab リリースノートを生成する能力を与え、バージョン管理とリリースワークフローを簡素化します。","ko":"에이전트가 커밋 메시지 형식을 표준화하고 Conventional Commits 및 의미적 버전控制 프로토콜을 사용하여 GitHub/GitLab 릴리즈 노트를 생성할 수 있도록 하여 버전 관리 및 릴리즈 워크플로우를 간소화합니다.","es":"Habilita a los agentes a estandarizar los formatos de mensajes de compromiso y generar notas de lanzamiento de GitHub/GitLab utilizando Conventional Commits y protocolos de control de versión semántica, simplificando la administración de versiones y los flujos de trabajo de lanzamiento.","fr":"Permet aux agents de normaliser les formats de messages de validation et de générer des notes de version GitHub/GitLab en utilisant Conventional Commits et des protocoles de gestion de version sémantique, rationalisant ainsi la gestion des versions et les flux de travail de version.","de":"Ermächtigt die Agents, die Formate der Commit-Mitteilungen zu standardisieren und GitHub-/GitLab-Release-Notizen unter Verwendung von Conventional Commits und semantischen Versionskontrollprotokollen zu generieren, wodurch die Versionsverwaltung und die Release-Workflows rationalisiert werden.","pt":"Habilita os agentes a padronizar formatos de mensagens de commit e gerar notas de lançamento do GitHub/GitLab usando Commits Convencionais e protocolos de controle de versão semântica, racionalizando a gestão de versões e fluxos de trabalho de lançamento.","ru":"Наделяет агентов возможностью стандартизировать форматы сообщений о фиксации и генерировать заметки о выпуске GitHub/GitLab, используя Конвенциональные коммиты и семантические протоколы контроля версий, оптимизируя управление версиями и рабочие процессы выпуска.","ar":"تمكين الوكيل من وضع صيغ رسائل الالتزام وم生的 ملاحظات إصدار GitHub/GitLab باستخدام الالتزامات التقليدية وبروتوكولات التحكم الإصدار语义ي، وتبسيط إدارة الإصدارات وعمليات الإصدار."},"useCases":{"en":["Automating changelog generation for new releases","Implementing Conventional Commits for standardized commit messages","Generating release notes for GitHub and GitLab repositories"],"zh":["为新版本自动化变更日志生成","为标准化提交消息实现 Conventional Commits","为 GitHub 和 GitLab 仓库生成发布说明"],"ja":["新しいリリースの自動変更ログ生成","標準化されたコミットメッセージのための Conventional Commits の実装","GitHub と GitLab リポジトリのリリースノートの生成"],"ko":["새 릴리즈의 자동 변경 로그 생성","표준화된 커밋 메시지 위한 Conventional Commits 구현","GitHub 및 GitLab 저장소의 릴리즈 노트 생성"],"es":["Automatizar la generación de registros de cambios para nuevos lanzamientos","Implementar Conventional Commits para mensajes de compromiso estandarizados","Generar notas de lanzamiento para repositorios de GitHub y GitLab"],"fr":["Automatiser la génération du journal des modifications pour les nouveaux lancements","Mettre en œuvre Conventional Commits pour des messages de validation normalisés","Générer des notes de version pour les référentiels GitHub et GitLab"],"de":["Automatisierung der Generierung von Änderungsprotokollen für neue Releases","Implementierung von Conventional Commits für standardisierte Commit-Mitteilungen","Generierung von Release-Notizen für GitHub- und GitLab-Repositorys"],"pt":["Automatizar a geração de registros de alterações para novos lançamentos","Implementar Commits Convencionais para mensagens de commit padronizadas","Gerar notas de lançamento para repositórios GitHub e GitLab"],"ru":["Автоматизировать генерацию журнала изменений для новых релизов","Реализовать Конвенциональные коммиты для стандартизированных сообщений о фиксации","Генерировать заметки о выпуске для репозиториев GitHub и GitLab"],"ar":["توليد سجل التغييرات تلقائيًا لإصدارات جديدة","تنفيذ الالتزامات التقليدية لرسائل الالتزام المعيارية","توليد ملاحظات الإصدار لمخازن GitHub و GitLab"]},"limitations":{"en":["Requires Git repository access","Limited to GitHub and GitLab release notes generation"],"zh":["需要 Git 仓库访问权限","仅限 GitHub 和 GitLab 发布说明生成"],"ja":["Git リポジトリへのアクセスが必要","GitHub と GitLab のリリースノート生成のみ"],"ko":["Git 저장소 액세스 필요","GitHub 및 GitLab 릴리즈 노트 생성만 제한"],"es":["Requiere acceso al repositorio Git","Limitado a la generación de notas de lanzamiento de GitHub y GitLab"],"fr":["Nécessite un accès au référentiel Git","Limité à la génération de notes de version GitHub et GitLab"],"de":["Benötigt Zugriff auf das Git-Repository","Begrenzt auf die Generierung von GitHub- und GitLab-Release-Notizen"],"pt":["Requer acesso ao repositório Git","Limitado à geração de notas de lançamento do GitHub e GitLab"],"ru":["Требуется доступ к репозиторию Git","Ограничен генерацией заметок о выпуске GitHub и GitLab"],"ar":["يتطلب الوصول إلى مستودع Git","محدود بتوليد ملاحظات إصدار GitHub و GitLab"]},"version":4},"contentHash":"3b5fc90d13fa54918da996f84920eeb233efdb597decd77728f4c2d1d84049e6","qualityScore":60}');
