INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('smart-village-solutions/sva-studio/changelog-automation', 'changelog-automation', 'smart-village-solutions', 'sva-studio', 'community', 'changelog-automation smart-village-solutions sva-studio community The changelog-automation skill automates changelog generation, release notes, and version management for developers. It standardizes commit message formats and generates GitHub/GitLab release notes. Changelog 自动化是通过 Conventional Commits 和 semantic versioning 实现的，用于生成 changelog 和版本管理 Changelog 自動化は Conventional Commits と semantic versioning を使用して実現され、Changelog とバージョン管理を行います Changelog 자동화는 Conventional Commits와 semantic versioning을 사용하여 changelog와 버전 관리를 수행합니다 La automatización de registros de cambios permite la generación automática de notas de lanzamiento y versiones siguiendo estándares de la industria L''automatisation du journal des modifications permet la génération automatique de notes de version et de versions suivant les normes de l''industrie Die Automatisierung von Änderungsprotokollen ermöglicht die automatische Erstellung von Versionshinweisen und Versionen nach Branchenstandards A automação de changelog é um padrão para gerar changelogs e notas de lançamento de forma automática, utilizando commites convencionais e versionamento semântico. Автоматизация изменений - это padrão для генерации изменений и заметок о выпуске с помощью конвенциональных коммитов и семантического версионирования آلي سجل التعديلات هو معيار لإنشاء سجلات التعديلات وملاحظات الإصدار تلقائيًا باستخدام أنماط الإلتزامات وتدوين الإصدارات how to use changelog-automation changelog-automation setup guide automated release notes Conventional Commits tutorial semantic versioning best practices changelog-automation vs manual changelog changelog-automation install release notes automation version management tools Changelog 自动化 Conventional Commits semantic versioning 自动化 changelog 生成 GitHub Release Notes GitLab Release Notes commit 消息格式 Generates GitHub/GitLab release notes Implements Conventional Commits for standardized commit message formats Creates release note workflows for efficient version management Manages semantic versioning for accurate change tracking Standardizes commit message formats for clear communication Automates changelog generation for reduced manual effort changelog-automation is a set of patterns and tools for automating changelog generation, release notes, and version management following industry standards.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fyndx/coinx-backend/code-review-excellence', 'community', 'fyndx', 'coinx-backend', 'fyndx/coinx-backend', 'code-review-excellence', 0, 0, 60, '2026-03-08T01:57:15.451Z', '2026-03-08T02:08:59.208Z', 'a765bd62c6ee22eab0cb56e96b5a811b49a9b4dfc1f85a86776aa1d3d6e87532', '{"id":"fyndx/coinx-backend/code-review-excellence","name":"code-review-excellence","description":{"en":"Code-review-excellence transforms code reviews into constructive feedback and collaborative improvement for developers. It benefits teams by establishing review standards and reducing cycle time.","zh":"代码审查卓越性是通过构造性反馈、系统分析和协作改进来实现的","ja":"コードレビューの質を高めるための方法を紹介します","ko":"코드 리뷰의 우수성을 높이는 방법을 소개합니다","es":"Code Review Excellence es una habilidad que ayuda a los desarrolladores a mejorar la calidad del código a través de revisiones constructivas y colaborativas","fr":"L''excellence de la revue de code est une compétence qui aide les développeurs à améliorer la qualité du code grâce à des revues constructives et collaboratives","de":"Code-Review-Excellence ist eine Fähigkeit, die Entwickler dabei hilft, die Code-Qualität durch konstruktives und kollaboratives Feedback zu verbessern","pt":"Excelência em revisão de código transforma revisões de código em compartilhamento de conhecimento com feedback construtivo e análise sistemática","ru":"Совершенство код-ревью превращает код-ревью в обмен знаниями с помощью конструктивной обратной связи и системного анализа","ar":"براعة استعراض الكود تحول استعراضات الكود إلى مشاركة معرفة مع ملاحظات بناءة وتحليل منهجي"},"seo":{"title":{"en":"Code-Review-Excellence: Best Practices for AI Agents | Co...","zh":"Code Review Excellence_SETUP GUIDE","ja":"AIエージェントを使用したCode Review Excellence_BEST PRACTICES","ko":"코드 리뷰 우수성_Setup 및 사용 방법","es":"Guía de configuración de Code Review Excellence para desa...","fr":"Configurer l''excellence de la revue de code pour les déve...","de":"Einrichtungsleitfaden für Code-Review-Excellence für Entw...","pt":"Guia de Configuração de Excelência em Revisão de Código","ru":"Руководство по настройке ИИ Агентов для совершенства код-...","ar":"دليل إعداد براعة استعراض الكود"},"description":{"en":"Unlock efficient code reviews with code-review-excellence. Discover how to transform gatekeeping into knowledge sharing and improve team collaboration - lear...","zh":"通过构造性反馈、系统分析和协作改进，实现代码审查的卓越性","ja":"AIエージェントを使用してコードレビューを徹底的に改善する方法","ko":"코드 리뷰의 우수성을 높이는 방법: 체계적인 분석과 협력","es":"Aprende a transformar las revisiones de código en un proceso de intercambio de conocimientos con comentarios constructivos y análisis sistemáticos","fr":"Découvrez comment transformer les revues de code en un processus de partage de connaissances avec des commentaires constructifs et des analyses systématiques","de":"Erfahren Sie, wie Sie Code-Reviews in einen Wissensaustauschprozess mit konstruktivem Feedback und systematischer Analyse verwandeln","pt":"Aprenda a transformar revisões de código em compartilhamento de conhecimento com feedback construtivo e análise sistemática","ru":"Преобразуйте код-ревью в обмен знаниями с помощью конструктивной обратной связи и системного анализа с ИИ Агентами","ar":"تعلم تحويل استعراضات الكود إلى مشاركة معرفة مع ملاحظات بناءة وتحليل منهجي"},"definition":{"en":"Code-review-excellence is a skill that enables systematic analysis and collaborative improvement of code reviews through constructive feedback and review guidelines.","zh":"代码审查卓越性是指通过构造性反馈和系统分析来改进代码质量","ja":"コードレビューの質を高めるための手法","ko":"코드 리뷰의 우수성을 높이는 기술","es":"Code Review Excellence es una habilidad que se refiere a la transformación de las revisiones de código en un proceso de intercambio de conocimientos","fr":"L''excellence de la revue de code est une compétence qui se réfère à la transformation des revues de code en un processus de partage de connaissances","de":"Code-Review-Excellence ist eine Fähigkeit, die sich auf die Umwandlung von Code-Reviews in einen Wissensaustauschprozess bezieht","pt":"Excelência em revisão de código é uma abordagem que visa melhorar a qualidade do código","ru":"Совершенство код-ревью - это подход, направленный на повышение качества кода","ar":"براعة استعراض الكود هي نهج يهدف إلى تحسين جودة الكود"},"features":{"en":["Conducts architecture reviews for improved code quality","Creates review checklists and guidelines for teams","Establishes code review standards for consistent feedback","Mentors junior developers through constructive code reviews","Reduces code review cycle time through systematic analysis","Improves team collaboration through collaborative improvement"],"zh":["构造性反馈","系统分析","协作改进","代码审查标准","代码检查清单","团队协作"],"ja":["構造的なフィードバック","システム分析","協力的な改善","コードレビュー標準","コードチェックリスト","チームコラボレーション"],"ko":["구조적인 피드백","시스템 분석","협력적인 개선","코드 리뷰 표준","코드 체크리스트","팀 협업"],"es":["Revisión de solicitudes de extracción y cambios de código","Establecimiento de estándares de revisión de código para equipos","Mentoría de desarrolladores junior a través de revisiones","Análisis de arquitectura","Creación de listas de verificación y directrices para revisiones","Mejora de la colaboración en equipo"],"fr":["Revues de pull requests et de modifications de code","Établissement de normes de revue de code pour les équipes","Mentorat de développeurs juniors via des revues","Analyse d''architecture","Création de listes de vérification et de lignes directrices pour les revues","Amélioration de la collaboration d''équipe"],"de":["Überprüfung von Pull-Requests und Code-Änderungen","Festlegung von Code-Review-Standards für Teams","Mentoring von Junior-Entwicklern durch Code-Reviews","Architekturanalyse","Erstellung von Prüflisten und Richtlinien für Code-Reviews","Verbesserung der Teamzusammenarbeit"],"pt":["Revisão de pull requests e alterações de código","Estabelecimento de padrões de revisão de código para equipes","Mentoria de desenvolvedores júnior por meio de revisões","Análise de arquitetura","Criação de listas de verificação e diretrizes de revisão"],"ru":["Проверка pull requests и изменений кода","Установление стандартов код-ревью для команд","Наставничество младших разработчиков через код-ревью","Анализ архитектуры","Создание чек-листов и руководств по код-ревью"],"ar":["استعراض طلبات السحب وتغييرات الكود","إنشاء معايير مراجعة الكود للفرق","التوجيه والتوجيه للمطورين الأوائل من خلال المراجعات","تحليل الهندسة المعمارية","إنشاء قوائم المراجعة والإرشادات"]},"keywords":{"en":["how to use code-review-excellence","code-review-excellence best practices","code-review-excellence alternative","code-review-excellence vs peer review","code-review-excellence setup guide","code-review-excellence for junior developers","improving code quality with code-review-excellence","code-review-excellence for AI agents","code-review-excellence and team collaboration"],"zh":["代码审查","代码质量","构造性反馈","系统分析","协作改进","代码审查标准","代码检查清单","团队协作"],"ja":["コードレビュー","コード品質","構造的なフィードバック","システム分析","協力的な改善","コードレビュー標準","コードチェックリスト","チームコラボレーション","AIエージェント"],"ko":["코드 리뷰","코드 품질","구조적인 피드백","시스템 분석","협력적인 개선","코드 리뷰 표준","코드 체크리스트","팀 협업","코드 리뷰 우수성"],"es":["code review","revisión de código","desarrollo de software","colaboración en equipo","mejora de la calidad del código","revisiones de código constructivas","análisis de arquitectura","mentoring de desarrolladores","herramientas de revisión de código"],"fr":["revue de code","développement de logiciels","collaboration d''équipe","amélioration de la qualité du code","revues de code constructives","analyse d''architecture","mentorat de développeurs","outils de revue de code","excellence de la revue de code"],"de":["Code-Review","Software-Entwicklung","Teamzusammenarbeit","Verbesserung der Code-Qualität","konstruktives Code-Review","Architekturanalyse","Mentoring von Entwicklern","Code-Review-Tools","Code-Review-Excellence"],"pt":["revisão de código","excelência em revisão de código","feedback construtivo","análise sistemática","revisão de pull requests","padrões de revisão de código","mentoria de desenvolvedores júnior"],"ru":["код-ревью","совершенство код-ревью","конструктивная обратная связь","системный анализ","проверка pull requests","стандарты код-ревью","наставничество младших разработчиков"],"ar":["استعراض الكود","براعة استعراض الكود","ملاحظات بناءة","تحليل منهجي","استعراض طلبات السحب","معايير مراجعة الكود","توجيه المطورين الأوائل"]}},"owner":"fyndx","repo":"coinx-backend","repoPath":"fyndx/coinx-backend","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.451Z","topics":[],"category":"community","skillMd":{"name":"code-review-excellence","description":"Master effective code review practices to provide constructive feedback, catch bugs early, and foster knowledge sharing while maintaining team morale. Use when reviewing pull requests, establishing review standards, or mentoring developers.","bodyPreview":"# Code Review Excellence\n\nTransform code reviews from gatekeeping to knowledge sharing through constructive feedback, systematic analysis, and collaborative improvement.\n\n## When to Use This Skill\n\n- Reviewing pull requests and code changes\n- Establishing code review standards for teams\n- Mentoring junior developers through reviews\n- Conducting architecture reviews\n- Creating review checklists and guidelines\n- Improving team collaboration\n- Reducing code review cycle time\n- Maintaining code qual","body":"# Code Review Excellence\n\nTransform code reviews from gatekeeping to knowledge sharing through constructive feedback, systematic analysis, and collaborative improvement.\n\n## When to Use This Skill\n\n- Reviewing pull requests and code changes\n- Establishing code review standards for teams\n- Mentoring junior developers through reviews\n- Conducting architecture reviews\n- Creating review checklists and guidelines\n- Improving team collaboration\n- Reducing code review cycle time\n- Maintaining code quality standards\n\n## Core Principles\n\n### 1. The Review Mindset\n\n**Goals of Code Review:**\n\n- Catch bugs and edge cases\n- Ensure code maintainability\n- Share knowledge across team\n- Enforce coding standards\n- Improve design and architecture\n- Build team culture\n\n**Not the Goals:**\n\n- Show off knowledge\n- Nitpick formatting (use linters)\n- Block progress unnecessarily\n- Rewrite to your preference\n\n### 2. Effective Feedback\n\n**Good Feedback is:**\n\n- Specific and actionable\n- Educational, not judgmental\n- Focused on the code, not the person\n- Balanced (praise good work too)\n- Prioritized (critical vs nice-to-have)\n\n```markdown\n❌ Bad: \"This is wrong.\"\n✅ Good: \"This could cause a race condition when multiple users\naccess simultaneously. Consider using a mutex here.\"\n\n❌ Bad: \"Why didn''t you use X pattern?\"\n✅ Good: \"Have you considered the Repository pattern? It would\nmake this easier to test. Here''s an example: [link]\"\n\n❌ Bad: \"Rename this variable.\"\n✅ Good: \"[nit] Consider `userCount` instead of `uc` for\nclarity. Not blocking if you prefer to keep it.\"\n```\n\n### 3. Review Scope\n\n**What to Review:**\n\n- Logic correctness and edge cases\n- Security vulnerabilities\n- Performance implications\n- Test coverage and quality\n- Error handling\n- Documentation and comments\n- API design and naming\n- Architectural fit\n\n**What Not to Review Manually:**\n\n- Code formatting (use Prettier, Black, etc.)\n- Import organization\n- Linting violations\n- Simple typos\n\n## Review Process\n\n### Phase 1: Context Gathering (2-3 minutes)\n\n```markdown\nBefore diving into code, understand:\n\n1. Read PR description and linked issue\n2. Check PR size (>400 lines? Ask to split)\n3. Review CI/CD status (tests passing?)\n4. Understand the business requirement\n5. Note any relevant architectural decisions\n```\n\n### Phase 2: High-Level Review (5-10 minutes)\n\n```markdown\n1. **Architecture & Design**\n   - Does the solution fit the problem?\n   - Are there simpler approaches?\n   - Is it consistent with existing patterns?\n   - Will it scale?\n\n2. **File Organization**\n   - Are new files in the right places?\n   - Is code grouped logically?\n   - Are there duplicate files?\n\n3. **Testing Strategy**\n   - Are there tests?\n   - Do tests cover edge cases?\n   - Are tests readable?\n```\n\n### Phase 3: Line-by-Line Review (10-20 minutes)\n\n```markdown\nFor each file:\n\n1. **Logic & Correctness**\n   - Edge cases handled?\n   - Off-by-one errors?\n   - Null/undefined checks?\n   - Race conditions?\n\n2. **Security**\n   - Input validation?\n   - SQL injection risks?\n   - XSS vulnerabilities?\n   - Sensitive data exposure?\n\n3. **Performance**\n   - N+1 queries?\n   - Unnecessary loops?\n   - Memory leaks?\n   - Blocking operations?\n\n4. **Maintainability**\n   - Clear variable names?\n   - Functions doing one thing?\n   - Complex code commented?\n   - Magic numbers extracted?\n```\n\n### Phase 4: Summary & Decision (2-3 minutes)\n\n```markdown\n1. Summarize key concerns\n2. Highlight what you liked\n3. Make clear decision:\n   - ✅ Approve\n   - 💬 Comment (minor suggestions)\n   - 🔄 Request Changes (must address)\n4. Offer to pair if complex\n```\n\n## Review Techniques\n\n### Technique 1: The Checklist Method\n\n```markdown\n## Security Checklist\n\n- [ ] User input validated and sanitized\n- [ ] SQL queries use parameterization\n- [ ] Authentication/authorization checked\n- [ ] Secrets not hardcoded\n- [ ] Error messages don''t leak info\n\n## Performance Checklist\n\n- [ ] No N+1 queries\n- [ ] Database queries indexed\n- [ ] Large lists paginated\n- [ ] Expensive operations cached\n- [ ] No blocking I/O in hot paths\n\n## Testing Checklist\n\n- [ ] Happy path tested\n- [ ] Edge cases covered\n- [ ] Error cases tested\n- [ ] Test names are descriptive\n- [ ] Tests are deterministic\n```\n\n### Technique 2: The Question Approach\n\nInstead of stating problems, ask questions to encourage thinking:\n\n```markdown\n❌ \"This will fail if the list is empty.\"\n✅ \"What happens if `items` is an empty array?\"\n\n❌ \"You need error handling here.\"\n✅ \"How should this behave if the API call fails?\"\n\n❌ \"This is inefficient.\"\n✅ \"I see this loops through all users. Have we considered\nthe performance impact with 100k users?\"\n```\n\n### Technique 3: Suggest, Don''t Command\n\n````markdown\n## Use Collaborative Language\n\n❌ \"You must change this to use async/await\"\n✅ \"Suggestion: async/await might make this more readable:\n`typescript\n    async function fetchUser(id: string) {\n        const user = await db.query(''SELECT * FROM users WHERE id = ?'', id);\n        return user;\n    }\n    `\nWhat do you think?\"\n\n❌ \"Extract this into a function\"\n✅ \"This logic appears in 3 places. Would it make sense to\nextract it into a shared utility function?\"\n````\n\n### Technique 4: Differentiate Severity\n\n```markdown\nUse labels to indicate priority:\n\n🔴 [blocking] - Must fix before merge\n🟡 [important] - Should fix, discuss if disagree\n🟢 [nit] - Nice to have, not blocking\n💡 [suggestion] - Alternative approach to consider\n📚 [learning] - Educational comment, no action needed\n🎉 [praise] - Good work, keep it up!\n\nExample:\n\"🔴 [blocking] This SQL query is vulnerable to injection.\nPlease use parameterized queries.\"\n\n\"🟢 [nit] Consider renaming `data` to `userData` for clarity.\"\n\n\"🎉 [praise] Excellent test coverage! This will catch edge cases.\"\n```\n\n## Language-Specific Patterns\n\n### Python Code Review\n\n```python\n# Check for Python-specific issues\n\n# ❌ Mutable default arguments\ndef add_item(item, items=[]):  # Bug! Shared across calls\n    items.append(item)\n    return items\n\n# ✅ Use None as default\ndef add_item(item, items=None):\n    if items is None:\n        items = []\n    items.append(item)\n    return items\n\n# ❌ Catching too broad\ntry:\n    result = risky_operation()\nexcept:  # Catches everything, even KeyboardInterrupt!\n    pass\n\n# ✅ Catch specific exceptions\ntry:\n    result = risky_operation()\nexcept ValueError as e:\n    logger.error(f\"Invalid value: {e}\")\n    raise\n\n# ❌ Using mutable class attributes\nclass User:\n    permissions = []  # Shared across all instances!\n\n# ✅ Initialize in __init__\nclass User:\n    def __init__(self):\n        self.permissions = []\n```\n\n### TypeScript/JavaScript Code Review\n\n```typescript\n// Check for TypeScript-specific issues\n\n// ❌ Using any defeats type safety\nfunction processData(data: any) {  // Avoid any\n    return data.value;\n}\n\n// ✅ Use proper types\ninterface DataPayload {\n    value: string;\n}\nfunction processData(data: DataPayload) {\n    return data.value;\n}\n\n// ❌ Not handling async errors\nasync function fetchUser(id: string) {\n    const response = await fetch(`/api/users/${id}`);\n    return response.json();  // What if network fails?\n}\n\n// ✅ Handle errors properly\nasync function fetchUser(id: string): Promise<User> {\n    try {\n        const response = await fetch(`/api/users/${id}`);\n        if (!response.ok) {\n            throw new Error(`HTTP ${response.status}`);\n        }\n        return await response.json();\n    } catch (error) {\n        console.error(''Failed to fetch user:'', error);\n        throw error;\n    }\n}\n\n// ❌ Mutation of props\nfunction UserProfile({ user }: Props) {\n    user.lastViewed = new Date();  // Mutating prop!\n    return <div>{user.name}</div>;\n}\n\n// ✅ Don''t mutate props\nfunction UserProfile({ user, onView }: Props) {\n    useEffect(() => {\n        onView(user.id);  // Notify parent to update\n    }, [user.id]);\n    return <div>{user.name}</div>;\n}\n```\n\n## Advanced Review Patterns\n\n### Pattern 1: Architectural Review\n\n```markdown\nWhen reviewing significant changes:\n\n1. **Design Document First**\n   - For large features, request design doc before code\n   - Review design with team before implementation\n   - Agree on approach to avoid rework\n\n2. **Review in Stages**\n   - First PR: Core abstractions and interfaces\n   - Second PR: Implementation\n   - Third PR: Integration and tests\n   - Easier to review, faster to iterate\n\n3. **Consider Alternatives**\n   - \"Have we considered using [pattern/library]?\"\n   - \"What''s the tradeoff vs. the simpler approach?\"\n   - \"How will this evolve as requirements change?\"\n```\n\n### Pattern 2: Test Quality Review\n\n```typescript\n// ❌ Poor test: Implementation detail testing\ntest(''increments counter variable'', () => {\n    const component = render(<Counter />);\n    const button = component.getByRole(''button'');\n    fireEvent.click(button);\n    expect(component.state.counter).toBe(1);  // Testing internal state\n});\n\n// ✅ Good test: Behavior testing\ntest(''displays incremented count when clicked'', () => {\n    render(<Counter />);\n    const button = screen.getByRole(''button'', { name: /increment/i });\n    fireEvent.click(button);\n    expect(screen.getByText(''Count: 1'')).toBeInTheDocument();\n});\n\n// Review questions for tests:\n// - Do tests describe behavior, not implementation?\n// - Are test names clear and descriptive?\n// - Do tests cover edge cases?\n// - Are tests independent (no shared state)?\n// - Can tests run in any order?\n```\n\n### Pattern 3: Security Review\n\n```markdown\n## Security Review Checklist\n\n### Authentication & Authorization\n\n- [ ] Is authentication required where needed?\n- [ ] Are authorization checks before every action?\n- [ ] Is JWT validation proper (signature, expiry)?\n- [ ] Are API keys/secrets properly secured?\n\n### Input Validation\n\n- [ ] All user inputs validated?\n- [ ] File uploads restricted (size, type)?\n- [ ] SQL queries parameterized?\n- [ ] XSS protection (escape output)?\n\n### Data Protection\n\n- [ ] Passwords hashed (bcrypt/argon2)?\n- [ ] Sensitive data encrypted at rest?\n- [ ] HTTPS enforced for sensitive data?\n- [ ] PII handled according to regulations?\n\n### Common Vulnerabilities\n\n- [ ] No eval() or similar dynamic execution?\n- [ ] No hardcoded secrets?\n- [ ] CSRF protection for state-changing operations?\n- [ ] Rate limiting on public endpoints?\n```\n\n## Giving Difficult Feedback\n\n### Pattern: The Sandwich Method (Modified)\n\n```markdown\nTraditional: Praise + Criticism + Praise (feels fake)\n\nBetter: Context + Specific Issue + Helpful Solution\n\nExample:\n\"I noticed the payment processing logic is inline in the\ncontroller. This makes it harder to test and reuse.\n\n[Specific Issue]\nThe calculateTotal() function mixes tax calculation,\ndiscount logic, and database queries, making it difficult\nto unit test and reason about.\n\n[Helpful Solution]\nCould we extract this into a PaymentService class? That\nwould make it testable and reusable. I can pair with you\non this if helpful.\"\n```\n\n### Handling Disagreements\n\n```markdown\nWhen author disagrees with your feedback:\n\n1. **Seek to Understand**\n   \"Help me understand your approach. What led you to\n   choose this pattern?\"\n\n2. **Acknowledge Valid Points**\n   \"That''s a good point about X. I hadn''t considered that.\"\n\n3. **Provide Data**\n   \"I''m concerned about performance. Can we add a benchmark\n   to validate the approach?\"\n\n4. **Escalate if Needed**\n   \"Let''s get [architect/senior dev] to weigh in on this.\"\n\n5. **Know When to Let Go**\n   If it''s working and not a critical issue, approve it.\n   Perfection is the enemy of progress.\n```\n\n## Best Practices\n\n1. **Review Promptly**: Within 24 hours, ideally same day\n2. **Limit PR Size**: 200-400 lines max for effective review\n3. **Review in Time Blocks**: 60 minutes max, take breaks\n4. **Use Review Tools**: GitHub, GitLab, or dedicated tools\n5. **Automate What You Can**: Linters, formatters, security scans\n6. **Build Rapport**: Emoji, praise, and empathy matter\n7. **Be Available**: Offer to pair on complex issues\n8. **Learn from Others**: Review others'' review comments\n\n## Common Pitfalls\n\n- **Perfectionism**: Blocking PRs for minor style preferences\n- **Scope Creep**: \"While you''re at it, can you also...\"\n- **Inconsistency**: Different standards for different people\n- **Delayed Reviews**: Letting PRs sit for days\n- **Ghosting**: Requesting changes then disappearing\n- **Rubber Stamping**: Approving without actually reviewing\n- **Bike Shedding**: Debating trivial details extensively\n\n## Templates\n\n### PR Review Comment Template\n\n```markdown\n## Summary\n\n[Brief overview of what was reviewed]\n\n## Strengths\n\n- [What was done well]\n- [Good patterns or approaches]\n\n## Required Changes\n\n🔴 [Blocking issue 1]\n🔴 [Blocking issue 2]\n\n## Suggestions\n\n💡 [Improvement 1]\n💡 [Improvement 2]\n\n## Questions\n\n❓ [Clarification needed on X]\n❓ [Alternative approach consideration]\n\n## Verdict\n\n✅ Approve after addressing required changes\n```\n\n## Resources\n\n- **references/code-review-best-practices.md**: Comprehensive review guidelines\n- **references/common-bugs-checklist.md**: Language-specific bugs to watch for\n- **references/security-review-guide.md**: Security-focused review checklist\n- **assets/pr-review-template.md**: Standard review comment template\n- **assets/review-checklist.md**: Quick reference checklist\n- **scripts/pr-analyzer.py**: Analyze PR complexity and suggest reviewers\n"},"lastSynced":"2026-03-08T02:08:59.208Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing advanced code analysis and review capabilities for collaborative improvement.","zh":"非常适合需要高级代码分析和审查功能以进行协作改进的开发代理。","ja":"コラボレーションによる改善のために高度なコード分析とレビュー機能を必要とする開発エージェントに最適です。","ko":"협업 개선을 위한 고급 코드 분석 및 검토 기능이 필요한 개발 에이전트에 완벽합니다.","es":"Ideal para Development Agents que necesitan capacidades avanzadas de análisis y revisión de código para la mejora colaborativa.","fr":"Parfait pour les Development Agents nécessitant des capacités avancées d''analyse et de revue de code pour une amélioration collaborative.","de":"Perfekt für Development Agents, die erweiterte Code-Analyse- und Überprüfungsfunktionen für kollaborative Verbesserungen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de capacidades avançadas de análise e revisão de código para melhoria colaborativa.","ru":"Идеально подходит для агентов разработки, которым требуются передовые возможности анализа и проверки кода для совместного совершенствования.","ar":"مثالي لعميل التطوير الذي يحتاج إلىقدرات متقدمة لتحليل وتحقق الشفرة لتحسين التعاوني."},"recommendation":{"en":"Empowers agents to transform code reviews into constructive feedback and collaborative improvement through systematic analysis, establishing review standards, and reducing code review cycle time using protocols like pull requests and review checklists.","zh":"通过系统分析、建立审查标准以及使用拉取请求和审查清单等协议减少代码审查周期时间，使代理能够将代码审查转化为建设性反馈和协作改进。","ja":"体系的な分析、レビュー基準の確立、プルリクエストやレビューチェックリストなどのプロトコルを使用したコードレビューサイクル時間の短縮を通じて、エージェントがコードレビューを建設的なフィードバックと協調的改善に変えることを可能にします。","ko":"시스템적 분석, 검토 기준 수립 및 풀 리퀘스트와 검토 체크리스트 같은 프로토콜을 사용하여 코드 검토 주기 시간을 단축함으로써 에이전트가 코드 검토를 건설적인 피드백과 협력적 개선으로 전환할 수 있도록 합니다.","es":"Permite a los agentes transformar las revisiones de código en comentarios constructivos y mejora colaborativa mediante análisis sistemático, establecimiento de estándares de revisión y reducción del tiempo del ciclo de revisión de código utilizando protocolos como pull requests y listas de verificación de revisión.","fr":"Permet aux agents de transformer les revues de code en retours constructifs et en amélioration collaborative grâce à une analyse systématique, à l''établissement de normes de revue et à la réduction du temps de cycle de revue de code en utilisant des protocoles comme les pull requests et les listes de contrôle de revue.","de":"Ermöglicht es Agents, Code-Reviews in konstruktives Feedback und kollaborative Verbesserung umzuwandeln durch systematische Analyse, die Einführung von Review-Standards und die Verkürzung der Code-Review-Zykluszeit unter Verwendung von Protokollen wie Pull Requests und Review-Checklisten.","pt":"Habilita os agentes a transformar revisões de código em feedback construtivo e melhoria colaborativa por meio de análise sistemática, estabelecendo padrões de revisão e reduzindo o tempo de ciclo de revisão de código usando protocolos como solicitações de pull e listas de verificação de revisão.","ru":"Наделяет агентов возможностью превратить проверку кода в конструктивную обратную связь и совместное совершенствование посредством систематического анализа, установления стандартов проверки и сокращения времени цикла проверки кода с помощью протоколов, таких как запросы на включение и контрольные списки проверки.","ar":"يُمكّن الوكيل من تحويل مراجعة الشفرة إلى ملاحظات بناءة وتحسين تعاوني من خلال التحليل المنهجي، ووضع معايير المراجعة، وتقليل دورة وقت مراجعة الشفرة باستخدام بروتوكولات مثل طلبات السحب وقوائم مراجعة التحقق."},"useCases":{"en":["Automating code review standards for teams","Generating review guidelines for junior developers","Optimizing code review cycle time through systematic analysis"],"zh":["为团队自动化代码审查标准","为初级开发人员生成审查指南","通过系统分析优化代码审查周期时间"],"ja":["チームのためのコードレビュー基準の自動化","ジュニア開発者のためのレビューガイドラインの生成","体系的分析によるコードレビューサイクル時間の最適化"],"ko":["팀을 위한 코드 검토 기준 자동화","주니어 개발자를 위한 검토 가이드라인 생성","시스템적 분석을 통한 코드 검토 주기 시간 최적화"],"es":["Automatización de estándares de revisión de código para equipos","Generación de directrices de revisión para desarrolladores junior","Optimización del tiempo del ciclo de revisión de código mediante análisis sistemático"],"fr":["Automatisation des normes de revue de code pour les équipes","Génération de directives de revue pour les développeurs juniors","Optimisation du temps de cycle de revue de code par une analyse systématique"],"de":["Automatisierung von Code-Review-Standards für Teams","Erstellung von Review-Richtlinien für Junior-Entwickler","Optimierung der Code-Review-Zykluszeit durch systematische Analyse"],"pt":["Automatizar padrões de revisão de código para equipes","Gerar diretrizes de revisão para desenvolvedores júnior","Otimizar tempo de ciclo de revisão de código por meio de análise sistemática"],"ru":["Автоматизировать стандарты проверки кода для команд","Генерировать руководства для проверки для младших разработчиков","Оптимизировать время цикла проверки кода посредством систематического анализа"],"ar":["توفير معايير مراجعة الشفرة آليًا للفرق","توليد إرشادات المراجعة لمطوري الجونيور","تحسين وقت دورة مراجعة الشفرة من خلال التحليل المنهجي"]},"limitations":{"en":["Requires access to code repositories","Team collaboration environment needed"],"zh":["需要访问代码仓库","需要团队协作环境"],"ja":["コードリポジトリへのアクセスが必要","チームコラボレーション環境が必要"],"ko":["코드 저장소에 대한 접근 필요","팀 협업 환경 필요"],"es":["Requiere acceso a repositorios de código","Se necesita un entorno de colaboración en equipo"],"fr":["Nécessite un accès aux dépôts de code","Environnement de collaboration d''équipe nécessaire"],"de":["Erfordert Zugriff auf Code-Repositories","Team-Kollaborationsumgebung erforderlich"],"pt":["Requer acesso a repositórios de código","Ambiente de colaboração de equipe necessário"],"ru":["Требуется доступ к репозиториям кода","Необходима среда командной работы"],"ar":["يتطلب الوصول إلى مستودعات الشفرة","بيئة تعاون الفريق ضرورية"]},"version":4},"contentHash":"a765bd62c6ee22eab0cb56e96b5a811b49a9b4dfc1f85a86776aa1d3d6e87532","qualityScore":60}');
