INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fyndx/coinx-backend/code-review-excellence', 'code-review-excellence', 'fyndx', 'coinx-backend', 'community', 'code-review-excellence fyndx coinx-backend community Code-review-excellence transforms code reviews into constructive feedback and collaborative improvement for developers. It benefits teams by establishing review standards and reducing cycle time. 代码审查卓越性是通过构造性反馈、系统分析和协作改进来实现的 コードレビューの質を高めるための方法を紹介します 코드 리뷰의 우수성을 높이는 방법을 소개합니다 Code Review Excellence es una habilidad que ayuda a los desarrolladores a mejorar la calidad del código a través de revisiones constructivas y colaborativas L''excellence de la revue de code est une compétence qui aide les développeurs à améliorer la qualité du code grâce à des revues constructives et collaboratives Code-Review-Excellence ist eine Fähigkeit, die Entwickler dabei hilft, die Code-Qualität durch konstruktives und kollaboratives Feedback zu verbessern Excelência em revisão de código transforma revisões de código em compartilhamento de conhecimento com feedback construtivo e análise sistemática Совершенство код-ревью превращает код-ревью в обмен знаниями с помощью конструктивной обратной связи и системного анализа براعة استعراض الكود تحول استعراضات الكود إلى مشاركة معرفة مع ملاحظات بناءة وتحليل منهجي how to use code-review-excellence code-review-excellence best practices code-review-excellence alternative code-review-excellence vs peer review code-review-excellence setup guide code-review-excellence for junior developers improving code quality with code-review-excellence code-review-excellence for AI agents code-review-excellence and team collaboration 代码审查 代码质量 构造性反馈 系统分析 协作改进 代码审查标准 代码检查清单 团队协作 Conducts architecture reviews for improved code quality Creates review checklists and guidelines for teams Establishes code review standards for consistent feedback Mentors junior developers through constructive code reviews Reduces code review cycle time through systematic analysis Improves team collaboration through collaborative improvement Code-review-excellence is a skill that enables systematic analysis and collaborative improvement of code reviews through constructive feedback and review guidelines.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Nexprove-Team/hykehyre/design-md', 'community', 'Nexprove-Team', 'hykehyre', 'Nexprove-Team/hykehyre', 'design-md', 0, 0, 60, '2026-03-08T01:57:15.453Z', '2026-03-08T02:09:03.355Z', '27afae5ca1a1fac3a19f00759fcc42d1b9f43398708134426b93ed0f8d2a48cc', '{"id":"Nexprove-Team/hykehyre/design-md","name":"design-md","description":{"en":"The design-md skill helps create DESIGN.md files that serve as the source of truth for prompting Stitch to generate new screens. It interprets design through Visual Descriptions supported by specific color values, benefiting Design Systems Leads.","zh":"设计-md 技术帮助您创建 DESIGN.md 文件，作为 Stitch 生成新屏幕的『源真实』，支持 Visual Descriptions 和特定色值","ja":"design-md 技術は、DESIGN.md ファイルを作成し、Stitch が既存のデザイン言語と完全に一致する新しいスクリーンを生成するための『ソース・オブ・トゥルース』となります","ko":"디자인-md 기술은 DESIGN.md 파일을 생성하여 Stitch가 기존 디자인 언어와 완전히 일치하는 새로운 화면을 생성하는 『소스 오브 트루스』가 됩니다","es":"La habilidad design-md permite crear archivos DESIGN.md que sirven como fuente de verdad para generar nuevas pantallas que se ajusten al lenguaje de diseño existente","fr":"La compétence design-md permet de créer des fichiers DESIGN.md qui servent de source de vérité pour générer de nouveaux écrans alignés sur le langage de conception existant","de":"Die Fähigkeit design-md ermöglicht die Erstellung von DESIGN.md-Dateien, die als Wahrheitsquelle dienen, um neue Bildschirme zu generieren, die sich an die bestehende Designsprache anpassen","pt":"O design-md é uma habilidade que ajuda a criar arquivos DESIGN.md que servem como fonte de verdade para gerar telas que alinham perfeitamente com a linguagem de design existente","ru":"ИИ Агент design-md - это навык, который помогает создавать файлы DESIGN.md, которые служат источником истины для генерации экранов, идеально соответствующих существующему языку дизайна","ar":"التصميم-md هو مهارة تساعد في إنشاء ملفات DESIGN.md التي تعمل كمصدر للحقيقة لجعل الشاشات تتماشى بشكل مثالي مع لغة التصميم الحالية"},"seo":{"title":{"en":"design-md: Semantic Design System Setup Guide | AI Agent ...","zh":"设计-md 技术指南：创建语义设计系统","ja":"design-md セットアップガイド：Semantic Design System の作成","ko":"디자인-md 설정 가이드: 시맨틱 디자인 시스템 생성","es":"Guía de configuración de design-md para Agentes de IA","fr":"Guide de mise en place de design-md pour les Outils d''IA","de":"Einrichtungsanleitung für design-md in KI-Agents","pt":"Guia de Configuração do design-md: Crie um Sistema de Des...","ru":"Настройка ИИ Агента design-md: Создание Семантической Сис...","ar":"دليل إعداد design-md: إنشاء نظام ديزاين семантиكي"},"description":{"en":"Discover how design-md creates a source of truth for prompting Stitch to generate new screens. Learn to synthesize a Semantic Design System into a DESIGN.md ...","zh":"了解设计-md 技术，创建 DESIGN.md 文件，实现语义设计系统，支持 Visual Descriptions 和特定色值","ja":"design-md 技術をマスターして、DESIGN.md ファイルを作成し、Visual Descriptions と特定の色値をサポートしたシ맨ティックデザインシステムを実現します","ko":"디자인-md 기술을 익히고 DESIGN.md 파일을 생성하여 시맨틱 디자인 시스템을 구현하고 Visual Descriptions 및 특정 색상 값을 지원합니다","es":"Aprende a crear archivos DESIGN.md para generar pantallas que se ajusten a tu lenguaje de diseño existente con la habilidad design-md","fr":"Découvrez comment créer des fichiers DESIGN.md pour générer des écrans alignés sur votre langage de conception existant avec la compétence design-md","de":"Erfahren Sie, wie Sie DESIGN.md-Dateien erstellen, um Bildschirme zu generieren, die sich an Ihre bestehende Designsprache anpassen, mit der Fähigkeit design-md","pt":"Aprenda a configurar o design-md para criar um Sistema de Design Semântico que ajude a gerar telas alinhadas com a linguagem de design existente","ru":"Узнайте, как настроить ИИ Агент design-md для создания Семантической Системы Дизайна, которая поможет генерировать экраны, соответствующие существующему язык...","ar":"تعلم كيفية إعداد design-md لإنشاء نظام ديزاين семантиكي يساعد في生成 شاشات متوافقة مع لغة التصميم الحالية"},"definition":{"en":"design-md is a skill that synthesizes a Semantic Design System into a DESIGN.md file, serving as the source of truth for generating new screens that align with existing design language.","zh":"设计-md 是一种创建语义设计系统的技术，通过 DESIGN.md 文件支持 Visual Descriptions 和特定色值","ja":"design-md は、DESIGN.md ファイルを通じて Visual Descriptions と特定の色値をサポートするシ맨ティックデザインシステムを作成する技術です","ko":"디자인-md는 DESIGN.md 파일을 통해 시각적 설명과 특정 색상 값을 지원하는 시맨틱 디자인 시스템을 생성하는 기술입니다","es":"design-md es una habilidad que permite crear un Sistema de Diseño Semántico en un archivo DESIGN.md","fr":"design-md est une compétence qui permet de créer un Système de Conception Sémantique dans un fichier DESIGN.md","de":"design-md ist eine Fähigkeit, die die Erstellung eines semantischen Designsystems in einer DESIGN.md-Datei ermöglicht","pt":"O design-md é uma habilidade que cria um Sistema de Design Semântico para gerar telas alinhadas com a linguagem de design existente","ru":"ИИ Агент design-md - это навык, который создает Семантическую Систему Дизайна для генерации экранов, соответствующих существующему языку дизайна","ar":"التصميم-md هو مهارة تنشئ نظام ديزاين семантиكي لجعل الشاشات تتماشى مع لغة التصميم الحالية"},"features":{"en":["Creates DESIGN.md files as the source of truth for prompting Stitch","Interprets design through Visual Descriptions supported by specific color values","Synthesizes a Semantic Design System into a DESIGN.md file","Supports Design Systems Leads in generating new screens","Uses DESIGN.md files to align new screens with existing design language"],"zh":["创建 DESIGN.md 文件作为语义设计系统的『源真实』","支持 Visual Descriptions 和特定色值","实现 Stitch 生成新屏幕的设计语言一致性","设计-md 技术作为设计系统lead的专家工具","可用于生成新屏幕和设计语言的完美对齐"],"ja":["DESIGN.md ファイルを作成し、シ맨ティックデザインシステムの『ソース・オブ・トゥルース』とする","Visual Descriptions と特定の色値をサポートする","Stitch が生成する新しいスクリーンのデザイン言語の一致性を実現する","design-md 技術はデザインシステムリードの専門ツールとして使用できる","新しいスクリーンとデザイン言語の完全な一致を生成するために使用できる"],"ko":["DESIGN.md 파일을 생성하여 시맨틱 디자인 시스템의 『소스 오브 트루스』로 사용","시각적 설명과 특정 색상 값을 지원","Stitch가 생성하는 새로운 화면의 디자인 언어 일치성을 구현","디자인-md 기술은 디자인 시스템 리드의 전문 도구로 사용할 수 있다","새로운 화면과 디자인 언어의 완전한 일치성을 생성하는 데 사용할 수 있다"],"es":["Crea archivos DESIGN.md como fuente de verdad para la generación de pantallas","Interpreta el diseño a través de descripciones visuales y valores de color específicos","Permite la generación de nuevas pantallas que se ajusten al lenguaje de diseño existente","Se basa en la creación de un Sistema de Diseño Semántico","Soporta la interpretación de diseño a través de valores de color específicos"],"fr":["Crée des fichiers DESIGN.md comme source de vérité pour la génération d''écrans","Interprète la conception à travers des descriptions visuelles et des valeurs de couleur spécifiques","Permet la génération de nouveaux écrans alignés sur le langage de conception existant","Se base sur la création d''un Système de Conception Sémantique","Prend en charge l''interprétation de la conception à travers des valeurs de couleur spécifiques"],"de":["Erstellt DESIGN.md-Dateien als Wahrheitsquelle für die Generierung von Bildschirmen","Interpretiert das Design durch visuelle Beschreibungen und spezifische Farbwerte","Ermöglicht die Generierung neuer Bildschirme, die sich an die bestehende Designsprache anpassen","Basierend auf der Erstellung eines semantischen Designsystems","Unterstützt die Interpretation von Design durch spezifische Farbwerte"],"pt":["Criação de arquivos DESIGN.md como fonte de verdade","Geração de telas alinhadas com a linguagem de design existente","Interpretação de design por meio de descrições visuais","Suporte a valores de cor específicos"],"ru":["Создание файлов DESIGN.md как источника истины","Генерация экранов, идеально соответствующих существующему языку дизайна","Интерпретация дизайна через визуальные описания","Поддержка конкретных цветовых значений"],"ar":["إنشاء ملفات DESIGN.md كمصدر للحقيقة","جعل الشاشات تتماشى بشكل مثالي مع لغة التصميم الحالية","التفسير التصميمي من خلال الوصف المرئي","دعم القيم اللونية المحددة"]},"keywords":{"en":["how to use design-md","what is design-md","design-md alternative","design-md vs stitch","design-md install","design-md setup guide","semantic design system","visual descriptions in design-md","design-md for design systems leads"],"zh":["设计-md","语义设计系统","DESIGN.md","Visual Descriptions","特定色值","Stitch","设计语言一致性","设计系统lead","AIエージェント"],"ja":["design-md","シ맨ティックデザインシステム","DESIGN.md","Visual Descriptions","特定の色値","Stitch","デザイン言語の一致性","デザインシステムリード","AIエージェント"],"ko":["디자인-md","시맨틱 디자인 시스템","DESIGN.md","시각적 설명","특정 색상 값","Stitch","디자인 언어 일치성","디자인 시스템 리드","AI 에이전트"],"es":["design-md","Agentes de IA","Sistema de Diseño Semántico","DESIGN.md","generación de pantallas","lenguaje de diseño","descripciones visuales","valores de color","configuración de design-md"],"fr":["design-md","Outils d''IA","Système de Conception Sémantique","DESIGN.md","génération d''écrans","langage de conception","descriptions visuelles","valeurs de couleur","mise en place de design-md"],"de":["design-md","KI-Agents","semantisches Designsystem","DESIGN.md","Generierung von Bildschirmen","Designsprache","visuelle Beschreibungen","Farbwerte","Einrichtung von design-md"],"pt":["design-md","Sistema de Design Semântico","geração de telas","linguagem de design","arquivos DESIGN.md","descrições visuais","valores de cor"],"ru":["ИИ Агент design-md","Семантическая Система Дизайна","генерация экранов","язык дизайна","файлы DESIGN.md","визуальные описания","цветовые значения"],"ar":["التصميم-md","نظام ديزاين семантиكي","جعل الشاشات","لغة التصميم","ملفات DESIGN.md","الوصف المرئي","القيم اللونية"]}},"owner":"Nexprove-Team","repo":"hykehyre","repoPath":"Nexprove-Team/hykehyre","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.453Z","topics":[],"category":"community","skillMd":{"name":"design-md","description":"Analyze Stitch projects and synthesize a semantic design system into DESIGN.md files","bodyPreview":"# Stitch DESIGN.md Skill\n\nYou are an expert Design Systems Lead. Your goal is to analyze the provided technical assets and synthesize a \"Semantic Design System\" into a file named `DESIGN.md`.\n\n## Overview\n\nThis skill helps you create `DESIGN.md` files that serve as the \"source of truth\" for prompting Stitch to generate new screens that align perfectly with existing design language. Stitch interprets design through \"Visual Descriptions\" supported by specific color values.\n\n## Prerequisites\n\n- Acc","body":"# Stitch DESIGN.md Skill\n\nYou are an expert Design Systems Lead. Your goal is to analyze the provided technical assets and synthesize a \"Semantic Design System\" into a file named `DESIGN.md`.\n\n## Overview\n\nThis skill helps you create `DESIGN.md` files that serve as the \"source of truth\" for prompting Stitch to generate new screens that align perfectly with existing design language. Stitch interprets design through \"Visual Descriptions\" supported by specific color values.\n\n## Prerequisites\n\n- Access to the Stitch MCP Server\n- A Stitch project with at least one designed screen\n- Access to the Stitch Effective Prompting Guide: https://stitch.withgoogle.com/docs/learn/prompting/\n\n## The Goal\n\nThe `DESIGN.md` file will serve as the \"source of truth\" for prompting Stitch to generate new screens that align perfectly with the existing design language. Stitch interprets design through \"Visual Descriptions\" supported by specific color values.\n\n## Retrieval and Networking\n\nTo analyze a Stitch project, you must retrieve screen metadata and design assets using the Stitch MCP Server tools:\n\n1. **Namespace discovery**: Run `list_tools` to find the Stitch MCP prefix. Use this prefix (e.g., `mcp_stitch:`) for all subsequent calls.\n\n2. **Project lookup** (if Project ID is not provided):\n   - Call `[prefix]:list_projects` with `filter: \"view=owned\"` to retrieve all user projects\n   - Identify the target project by title or URL pattern\n   - Extract the Project ID from the `name` field (e.g., `projects/13534454087919359824`)\n\n3. **Screen lookup** (if Screen ID is not provided):\n   - Call `[prefix]:list_screens` with the `projectId` (just the numeric ID, not the full path)\n   - Review screen titles to identify the target screen (e.g., \"Home\", \"Landing Page\")\n   - Extract the Screen ID from the screen''s `name` field\n\n4. **Metadata fetch**:\n   - Call `[prefix]:get_screen` with both `projectId` and `screenId` (both as numeric IDs only)\n   - This returns the complete screen object including:\n     - `screenshot.downloadUrl` - Visual reference of the design\n     - `htmlCode.downloadUrl` - Full HTML/CSS source code\n     - `width`, `height`, `deviceType` - Screen dimensions and target platform\n     - Project metadata including `designTheme` with color and style information\n\n5. **Asset download**:\n   - Use `web_fetch` or `read_url_content` to download the HTML code from `htmlCode.downloadUrl`\n   - Optionally download the screenshot from `screenshot.downloadUrl` for visual reference\n   - Parse the HTML to extract Tailwind classes, custom CSS, and component patterns\n\n6. **Project metadata extraction**:\n   - Call `[prefix]:get_project` with the project `name` (full path: `projects/{id}`) to get:\n     - `designTheme` object with color mode, fonts, roundness, custom colors\n     - Project-level design guidelines and descriptions\n     - Device type preferences and layout principles\n\n## Analysis & Synthesis Instructions\n\n### 1. Extract Project Identity (JSON)\n\n- Locate the Project Title\n- Locate the specific Project ID (e.g., from the `name` field in the JSON)\n\n### 2. Define the Atmosphere (Image/HTML)\n\nEvaluate the screenshot and HTML structure to capture the overall \"vibe.\" Use evocative adjectives to describe the mood (e.g., \"Airy,\" \"Dense,\" \"Minimalist,\" \"Utilitarian\").\n\n### 3. Map the Color Palette (Tailwind Config/JSON)\n\nIdentify the key colors in the system. For each color, provide:\n\n- A descriptive, natural language name that conveys its character (e.g., \"Deep Muted Teal-Navy\")\n- The specific hex code in parentheses for precision (e.g., \"#294056\")\n- Its specific functional role (e.g., \"Used for primary actions\")\n\n### 4. Translate Geometry & Shape (CSS/Tailwind)\n\nConvert technical `border-radius` and layout values into physical descriptions:\n\n- Describe `rounded-full` as \"Pill-shaped\"\n- Describe `rounded-lg` as \"Subtly rounded corners\"\n- Describe `rounded-none` as \"Sharp, squared-off edges\"\n\n### 5. Describe Depth & Elevation\n\nExplain how the UI handles layers. Describe the presence and quality of shadows (e.g., \"Flat,\" \"Whisper-soft diffused shadows,\" or \"Heavy, high-contrast drop shadows\").\n\n## Output Guidelines\n\n- **Language:** Use descriptive design terminology and natural language exclusively\n- **Format:** Generate a clean Markdown file following the structure below\n- **Precision:** Include exact hex codes for colors while using descriptive names\n- **Context:** Explain the \"why\" behind design decisions, not just the \"what\"\n\n## Output Format (DESIGN.md Structure)\n\n```markdown\n# Design System: [Project Title]\n\n**Project ID:** [Insert Project ID Here]\n\n## 1. Visual Theme & Atmosphere\n\n(Description of the mood, density, and aesthetic philosophy.)\n\n## 2. Color Palette & Roles\n\n(List colors by Descriptive Name + Hex Code + Functional Role.)\n\n## 3. Typography Rules\n\n(Description of font family, weight usage for headers vs. body, and letter-spacing character.)\n\n## 4. Component Stylings\n\n- **Buttons:** (Shape description, color assignment, behavior).\n- **Cards/Containers:** (Corner roundness description, background color, shadow depth).\n- **Inputs/Forms:** (Stroke style, background).\n\n## 5. Layout Principles\n\n(Description of whitespace strategy, margins, and grid alignment.)\n```\n\n## Usage Example\n\nTo use this skill for the Furniture Collection project:\n\n1. **Retrieve project information:**\n\n   ```\n   Use the Stitch MCP Server to get the Furniture Collection project\n   ```\n\n2. **Get the Home page screen details:**\n\n   ```\n   Retrieve the Home page screen''s code, image, and screen object information\n   ```\n\n3. **Reference best practices:**\n\n   ```\n   Review the Stitch Effective Prompting Guide at:\n   https://stitch.withgoogle.com/docs/learn/prompting/\n   ```\n\n4. **Analyze and synthesize:**\n   - Extract all relevant design tokens from the screen\n   - Translate technical values into descriptive language\n   - Organize information according to the DESIGN.md structure\n\n5. **Generate the file:**\n   - Create `DESIGN.md` in the project directory\n   - Follow the prescribed format exactly\n   - Ensure all color codes are accurate\n   - Use evocative, designer-friendly language\n\n## Best Practices\n\n- **Be Descriptive:** Avoid generic terms like \"blue\" or \"rounded.\" Use \"Ocean-deep Cerulean (#0077B6)\" or \"Gently curved edges\"\n- **Be Functional:** Always explain what each design element is used for\n- **Be Consistent:** Use the same terminology throughout the document\n- **Be Visual:** Help readers visualize the design through your descriptions\n- **Be Precise:** Include exact values (hex codes, pixel values) in parentheses after natural language descriptions\n\n## Tips for Success\n\n1. **Start with the big picture:** Understand the overall aesthetic before diving into details\n2. **Look for patterns:** Identify consistent spacing, sizing, and styling patterns\n3. **Think semantically:** Name colors by their purpose, not just their appearance\n4. **Consider hierarchy:** Document how visual weight and importance are communicated\n5. **Reference the guide:** Use language and patterns from the Stitch Effective Prompting Guide\n\n## Common Pitfalls to Avoid\n\n- ❌ Using technical jargon without translation (e.g., \"rounded-xl\" instead of \"generously rounded corners\")\n- ❌ Omitting color codes or using only descriptive names\n- ❌ Forgetting to explain functional roles of design elements\n- ❌ Being too vague in atmosphere descriptions\n- ❌ Ignoring subtle design details like shadows or spacing patterns\n"},"lastSynced":"2026-03-08T02:09:03.355Z","agentAnalysis":{"suitability":{"en":"Perfect for Design Systems Lead Agents needing advanced visual description interpretation and DESIGN.md file generation.","zh":"非常适合需要高级视觉描述解释和 DESIGN.md 文件生成的设计系统主导代理。","ja":"デザインシステムのリードエージェントが高度な視覚的な説明の解釈と DESIGN.md ファイルの生成を必要とする場合に最適です。","ko":"DESIGN.md 파일 생성 및 고급 시각적 설명 해석이 필요한 디자인 시스템 리드 에이전트에게 적합합니다.","es":"Perfecto para Líderes de Sistemas de Diseño que necesitan interpretación avanzada de descripciones visuales y generación de archivos DESIGN.md.","fr":"Parfait pour les agents principaux de systèmes de conception nécessitant une interprétation avancée de descriptions visuelles et une génération de fichiers DESIGN.md.","de":"Perfekt für Design-System-Lead-Agents, die eine erweiterte Interpretation von visuellen Beschreibungen und eine Generierung von DESIGN.md-Dateien benötigen.","pt":"Perfeito para Lead Agents de Design Systems que necessitam de interpretação avançada de descrições visuais e geração de arquivos DESIGN.md.","ru":"Идеально подходит для руководителей агентов дизайн-систем, которым необходима расширенная интерпретация визуальных описаний и генерация файлов DESIGN.md.","ar":"مثالي لتقنيي DESIGN Systems الذين يحتاجون إلى تفسير متقدم لوصف المرئيات وتوليد ملفات DESIGN.md."},"recommendation":{"en":"Empowers agents to create comprehensive DESIGN.md files, interpreting design through Visual Descriptions supported by specific color values, and generating new screens that align perfectly with existing design language using Stitch.","zh":"能够使代理创建全面性的 DESIGN.md 文件，通过视觉描述解释设计并支持特定的颜色值，并使用 Stitch 生成与现有设计语言完美对齐的新屏幕。","ja":"エージェントが包括的な DESIGN.md ファイルを作成できるようにし、視覚的な説明を通じてデザインを解釈し、特定の色値をサポートし、Stitch を使用して既存のデザイン言語と完璧に一致する新しいスクリーンを生成します。","ko":"에이전트가 포괄적인 DESIGN.md 파일을 생성할 수 있도록 하며, 시각적 설명을 통해 디자인을 해석하고 특정 색상 값을 지원하며, Stitch를 사용하여 기존 디자인 언어와 완벽하게 일치하는 새로운 화면을 생성합니다.","es":"Habilita a los agentes a crear archivos DESIGN.md completos, interpretando el diseño a través de descripciones visuales respaldadas por valores de color específicos y generando nuevas pantallas que se alinean perfectamente con el lenguaje de diseño existente utilizando Stitch.","fr":"Permet aux agents de créer des fichiers DESIGN.md complets, en interprétant la conception à travers des descriptions visuelles prises en charge par des valeurs de couleur spécifiques et en générant de nouveaux écrans qui s''alignent parfaitement sur le langage de conception existant en utilisant Stitch.","de":"Ermächtigt Agenten, umfassende DESIGN.md-Dateien zu erstellen, indem sie das Design durch visuelle Beschreibungen interpretieren, die durch spezifische Farbwerte unterstützt werden, und neue Bildschirme generieren, die sich perfekt an die bestehende Designsprache anpassen, indem sie Stitch verwenden.","pt":"Habilita os agentes a criar arquivos DESIGN.md abrangentes, interpretando o design por meio de Descrições Visuais apoiadas por valores de cor específicos, e gerando novas telas que se alinham perfeitamente com a linguagem de design existente usando Stitch.","ru":"Наделяет агентов возможностью создавать полные файлы DESIGN.md, интерпретируя дизайн посредством Визуальных Описаний, поддерживаемых определенными цветовыми значениями, и генерируя новые экраны, которые идеально соответствуют существующему языку дизайна, используя Stitch.","ar":"يمنح الوكلاء khảية إنشاء ملفات DESIGN.md شاملة، وتفسير التصميم من خلال وصف المرئيات بدعم من قيم الألوان المحددة، وإنشاء شاشات جديدة تتماشى بشكل مثالي مع لغة التصميم الحالية باستخدام Stitch."},"useCases":{"en":["Generating DESIGN.md files for new screen development","Interpreting Visual Descriptions for design consistency","Creating a Semantic Design System for existing design language"],"zh":["为新屏幕开发生成 DESIGN.md 文件","解释视觉描述以保持设计的一致性","为现有设计语言创建语义设计系统"],"ja":["新しいスクリーンの開発のために DESIGN.md ファイルを生成する","デザインの一貫性を維持するために視覚的な説明を解釈する","既存のデザイン言語のためのセマンティックデザインシステムを作成する"],"ko":["새로운 화면 개발을 위한 DESIGN.md 파일 생성","디자인 일관성을 유지하기 위한 시각적 설명 해석","기존 디자인 언어를 위한 의미론적 디자인 시스템 생성"],"es":["Generación de archivos DESIGN.md para el desarrollo de nuevas pantallas","Interpretación de descripciones visuales para la coherencia del diseño","Creación de un sistema de diseño semántico para el lenguaje de diseño existente"],"fr":["Génération de fichiers DESIGN.md pour le développement d''écrans nouveaux","Interprétation de descriptions visuelles pour la cohérence de la conception","Création d''un système de conception sémantique pour le langage de conception existant"],"de":["Generierung von DESIGN.md-Dateien für die Entwicklung neuer Bildschirme","Interpretation von visuellen Beschreibungen für die Konsistenz des Designs","Erstellung eines semantischen Design-Systems für die bestehende Designsprache"],"pt":["Geração de arquivos DESIGN.md para desenvolvimento de novas telas","Interpretação de Descrições Visuais para consistência de design","Criação de um Sistema de Design Semântico para linguagem de design existente"],"ru":["Генерация файлов DESIGN.md для разработки новых экранов","Интерпретация Визуальных Описаний для согласованности дизайна","Создание Семантической Системы Дизайна для существующего языка дизайна"],"ar":["توليد ملفات DESIGN.md لتنمية الشاشات الجديدة","تفسير وصف المرئيات للاتساق في التصميم","إنشاء نظام ديزاين دلالي للغة التصميم الحالية"]},"limitations":{"en":["Requires Stitch for screen generation","Limited to design systems leads"],"zh":["需要 Stitch 进行屏幕生成","仅限设计系统主导"],"ja":["スクリーン生成のために Stitch が必要","デザインシステムのリードに限定される"],"ko":["화면 생성을 위해 Stitch가 필요함","디자인 시스템 리드로 제한됨"],"es":["Requiere Stitch para la generación de pantallas","Limitado a líderes de sistemas de diseño"],"fr":["Nécessite Stitch pour la génération d''écrans","Limité aux leaders de systèmes de conception"],"de":["Benötigt Stitch für die Bildschirmgenerierung","Begrenzt auf Design-System-Leiter"],"pt":["Requer Stitch para geração de telas","Limitado a leads de design systems"],"ru":["Требуется Stitch для генерации экранов","Ограничен для руководителей дизайн-систем"],"ar":["يتطلب Stitch لتوليد الشاشات","محدود لقيادات أنظمة التصميم"]},"version":4},"contentHash":"27afae5ca1a1fac3a19f00759fcc42d1b9f43398708134426b93ed0f8d2a48cc","qualityScore":60}');
