INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Nexprove-Team/hykehyre/design-md', 'design-md', 'Nexprove-Team', 'hykehyre', 'community', 'design-md Nexprove-Team hykehyre community The design-md skill helps create DESIGN.md files that serve as the source of truth for prompting Stitch to generate new screens. It interprets design through Visual Descriptions supported by specific color values, benefiting Design Systems Leads. 设计-md 技术帮助您创建 DESIGN.md 文件，作为 Stitch 生成新屏幕的『源真实』，支持 Visual Descriptions 和特定色值 design-md 技術は、DESIGN.md ファイルを作成し、Stitch が既存のデザイン言語と完全に一致する新しいスクリーンを生成するための『ソース・オブ・トゥルース』となります 디자인-md 기술은 DESIGN.md 파일을 생성하여 Stitch가 기존 디자인 언어와 완전히 일치하는 새로운 화면을 생성하는 『소스 오브 트루스』가 됩니다 La habilidad design-md permite crear archivos DESIGN.md que sirven como fuente de verdad para generar nuevas pantallas que se ajusten al lenguaje de diseño existente La compétence design-md permet de créer des fichiers DESIGN.md qui servent de source de vérité pour générer de nouveaux écrans alignés sur le langage de conception existant Die Fähigkeit design-md ermöglicht die Erstellung von DESIGN.md-Dateien, die als Wahrheitsquelle dienen, um neue Bildschirme zu generieren, die sich an die bestehende Designsprache anpassen O design-md é uma habilidade que ajuda a criar arquivos DESIGN.md que servem como fonte de verdade para gerar telas que alinham perfeitamente com a linguagem de design existente ИИ Агент design-md - это навык, который помогает создавать файлы DESIGN.md, которые служат источником истины для генерации экранов, идеально соответствующих существующему языку дизайна التصميم-md هو مهارة تساعد في إنشاء ملفات DESIGN.md التي تعمل كمصدر للحقيقة لجعل الشاشات تتماشى بشكل مثالي مع لغة التصميم الحالية how to use design-md what is design-md design-md alternative design-md vs stitch design-md install design-md setup guide semantic design system visual descriptions in design-md design-md for design systems leads 设计-md 语义设计系统 DESIGN.md Visual Descriptions 特定色值 Stitch 设计语言一致性 设计系统lead AIエージェント Creates DESIGN.md files as the source of truth for prompting Stitch Interprets design through Visual Descriptions supported by specific color values Synthesizes a Semantic Design System into a DESIGN.md file Supports Design Systems Leads in generating new screens Uses DESIGN.md files to align new screens with existing design language design-md is a skill that synthesizes a Semantic Design System into a DESIGN.md file, serving as the source of truth for generating new screens that align with existing design language.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MoonshotAI/kimi-cli/codex-worker', 'community', 'MoonshotAI', 'kimi-cli', 'MoonshotAI/kimi-cli', 'codex-worker', 0, 0, 60, '2026-03-08T01:57:15.461Z', '2026-03-08T02:09:13.396Z', '3abb4cf9cf6bea74ba6fb6bdb63f69b455d21fd58dc3b6df200c44188e0dd556', '{"id":"MoonshotAI/kimi-cli/codex-worker","name":"codex-worker","description":{"en":"codex-worker automates parallel tasks for AI agents, utilizing git worktree and tmux sessions. It benefits developers by streamlining tasks like issue triage and code refactoring.","zh":"Codex-Worker 是一个 CLI 代理，能够并行运行多个 Codex CLI 代理，每个代理在自己的 git worktree 和 tmux 会话中运行。","ja":"Codex-Worker は、AIエージェントとして機能する CLI 代理で、複数の Codex CLI 代理を並列に実行します。","ko":"Codex-Worker는 병렬로 여러 개의 Codex CLI 에이전트를 실행하는 CLI 에이전트입니다. 각 에이전트는 자신의 git worktree와 tmux 세션에서 실행됩니다.","es":"codex-worker es una herramienta para orquestar múltiples agentes de CLI en paralelo, cada uno en su propio git worktree y sesión de tmux","fr":"codex-worker est un outil pour orchestrer plusieurs agents CLI en parallèle, chacun dans son propre git worktree et session tmux","de":"codex-worker ist ein Tool zur Orchestrierung mehrerer CLI-Agents in Parallelsitzungen, jeweils in einem eigenen git worktree und tmux-Sitzung","pt":"O Codex-Worker é uma ferramenta de orquestração de agentes CLI que permite executar tarefas em paralelo, utilizando git worktree e tmux","ru":"Codex-Worker - это инструмент оркестровки агентов CLI, позволяющий выполнять задачи параллельно, используя git worktree и tmux","ar":"Codex-Worker هو أداة لتوجيه وكلاء CLI التي تسمح بتنفيذ المهام في متناول اليد، باستخدام git worktree و tmux"},"seo":{"title":{"en":"codex-worker: Parallel Task Automation for AI Agents | AI...","zh":"Codex-Worker_SETUP GUIDE: 平行运行多个 Codex CLI 代理","ja":"Codex-Worker セットアップガイド: AIエージェントによる並列処理","ko":"Codex-Worker 설정 가이드: 병렬 코덱스 CLI 에이전트 실행","es":"Guía de configuración de codex-worker para agentes de CLI","fr":"Guide d''installation de codex-worker pour les agents CLI","de":"Einrichtungsleitfaden für codex-worker: Orchestrierung vo...","pt":"Guia de Configuração do Codex-Worker: Orquestração de Age...","ru":"Настройка Codex-Worker: Руководство по ИИ Агентам для CLI","ar":"دليل إعداد Codex-Worker: إدارة وكلاء CLI بالذكاء الاصطناعي"},"description":{"en":"Unlock efficient task management with codex-worker. Learn how to orchestrate multiple Codex CLI agents in parallel and boost productivity. Get started now!","zh":"了解 Codex-Worker 的优势，实现并行任务处理，提升开发效率。查看设置指南和最佳实践。","ja":"Codex-Worker を使用して並列タスク処理を実現し、開発効率を向上させる。セットアップガイドとベストプラクティスを参照。","ko":"Codex-Worker를 사용하여 병렬 태스크 처리를 구현하고 개발 효율성을 높여보세요. 설정 가이드와 모범 사례를 확인하세요.","es":"Aprende a utilizar codex-worker para ejecutar múltiples agentes de CLI en paralelo y aprovecha al máximo sus capacidades","fr":"Découvrez comment utiliser codex-worker pour exécuter plusieurs agents CLI en parallèle et exploiter leurs fonctionnalités","de":"Erfahren Sie, wie Sie codex-worker einsetzen, um mehrere CLI-Agents parallel auszuführen und ihre Fähigkeiten optimal zu nutzen","pt":"Aprenda a configurar o Codex-Worker para orquestrar múltiplos agentes CLI em paralelo, melhorando a eficiência dos seus projetos de desenvolvimento","ru":"Узнайте, как настроить Codex-Worker для управления несколькими агентами CLI в параллели, повышая эффективность ваших проектов разработки","ar":"تعرف على كيفية إعداد Codex-Worker لتنسيق عملاء CLI متعدد في متناول اليد، وتحسين كفاءة مشاريع التطوير الخاصة بك"},"definition":{"en":"codex-worker is a CLI agent that orchestrates multiple Codex CLI agents in parallel, each in its own git worktree and tmux session, for efficient task automation.","zh":"Codex-Worker 是一个用于并行任务处理的 CLI 代理，能够提高开发效率。","ja":"Codex-Worker は、並列タスク処理を実現する AIエージェントとしての CLI 代理です。","ko":"Codex-Worker는 병렬 태스크 처리를 위한 CLI 에이전트로 개발 효율성을 높이는 데 사용됩니다.","es":"codex-worker es un agente de CLI que permite la ejecución paralela de tareas independientes","fr":"codex-worker est un agent CLI qui permet l''exécution parallèle de tâches indépendantes","de":"codex-worker ist ein CLI-Agent, der die parallele Ausführung unabhängiger Aufgaben ermöglicht","pt":"O que é Codex-Worker? É uma ferramenta de orquestração de agentes CLI que executa tarefas em paralelo","ru":"Что такое Codex-Worker? Это инструмент оркестровки агентов CLI, выполняющий задачи параллельно","ar":"ما هو Codex-Worker؟ هو أداة لتوجيه وكلاء CLI التي تنفذ المهام في متناول اليد"},"features":{"en":["Orchestrate multiple Codex CLI agents in parallel","Utilize git worktree for independent task management","Leverage tmux sessions for efficient task automation","Spawn workers for tasks like issue triage and code refactoring","Supports tasks that can be split into independent subtasks","Enables parallelism for tasks like fetching issue lists and refactoring modules"],"zh":["并行运行多个 Codex CLI 代理","每个代理在自己的 git worktree 中运行","每个代理在自己的 tmux 会话中运行","支持独立子任务处理","提高开发效率"],"ja":["複数の Codex CLI 代理を並列に実行","各代理は独自の git worktree で実行","各代理は独自の tmux セッションで実行","独立したサブタスク処理をサポート","開発効率の向上"],"ko":["여러 개의 Codex CLI 에이전트를 병렬로 실행","각 에이전트는 자신의 git worktree에서 실행","각 에이전트는 자신의 tmux 세션에서 실행","독립적인 서브태스크 처리 지원","개발 효율성 향상"],"es":["Ejecución paralela de múltiples agentes de CLI","Cada agente se ejecuta en su propio git worktree","Cada agente se ejecuta en su propia sesión de tmux","Permite la división de tareas en subtareas independientes","Se puede utilizar para tareas como la refactorización de módulos y la corrección de errores"],"fr":["Exécution parallèle de plusieurs agents CLI","Chaque agent s''exécute dans son propre git worktree","Chaque agent s''exécute dans sa propre session tmux","Permet la division de tâches en sous-tâches indépendantes","Peut être utilisé pour des tâches telles que la refactoring de modules et la correction d''erreurs"],"de":["Parallele Ausführung mehrerer CLI-Agents","Jeder Agent wird in seinem eigenen git worktree ausgeführt","Jeder Agent wird in seiner eigenen tmux-Sitzung ausgeführt","Ermöglicht die Aufteilung von Aufgaben in unabhängige Teilaufgaben","Kann für Aufgaben wie die Refactoring von Modulen und die Fehlerkorrektur verwendet werden"],"pt":["Orquestração de múltiplos agentes CLI em paralelo","Utilização de git worktree para gerenciar repositórios","Integração com tmux para gerenciar sessões","Execução de tarefas independentes em paralelo","Suporte a refatoração de módulos e triagem de issues"],"ru":["Оркестровка нескольких агентов CLI в параллели","Использование git worktree для управления репозиториями","Интеграция с tmux для управления сессиями","Выполнение независимых задач параллельно","Поддержка рефакторинга модулей и триажа issues"],"ar":["تنسيق عملاء CLI متعدد في متناول اليد","استخدام git worktree لإدارة المستودعات","التكامل مع tmux لإدارة الجلسات","تنفيذ المهام المستقلة في متناول اليد","دعم إعادة بناء الوحدات وترشيح القضايا"]},"keywords":{"en":["how to use codex-worker","codex-worker alternative","codex-worker setup guide","what is codex-worker","codex-worker vs other CLI agents","codex-worker install","codex-worker parallel task automation","codex-worker git worktree integration","codex-worker tmux session management"],"zh":["Codex-Worker","CLI 代理","并行任务处理","git worktree","tmux","AI 工具","开发效率","并行处理"],"ja":["Codex-Worker","CLI 代理","AIエージェント","並列タスク処理","git worktree","tmux","開発効率","並列処理"],"ko":["Codex-Worker","CLI 에이전트","병렬 태스크 처리","git worktree","tmux","AI 도구","개발 효율성","병렬 처리"],"es":["agentes de CLI","Herramientas de desarrollo","Orquestación de tareas","Ejecución paralela","git worktree","tmux","Refactorización de código","Corrección de errores","Desarrollo de software"],"fr":["agents CLI","Outils de développement","Orchestration de tâches","Exécution parallèle","git worktree","tmux","Refactoring de code","Correction d''erreurs","Développement de logiciels"],"de":["CLI-Agents","Entwicklungstools","Aufgaben-Orchestrierung","Parallele Ausführung","git worktree","tmux","Code-Refactoring","Fehlerkorrektur","Software-Entwicklung"],"pt":["codex-worker","orquestração de agentes CLI","git worktree","tmux","refatoração de módulos","triação de issues","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["codex-worker","оркестровка агентов CLI","git worktree","tmux","рефакторинг модулей","триаж issues","разработка программного обеспечения","инструменты разработки"],"ar":["codex-worker","تنسيق وكلاء CLI","git worktree","tmux","إعادة بناء الوحدات","ترشيح القضايا","تطوير البرمجيات","أدوات التطوير"]}},"owner":"MoonshotAI","repo":"kimi-cli","repoPath":"MoonshotAI/kimi-cli","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.461Z","topics":[],"category":"community","skillMd":{"name":"codex-worker","description":"Spawn and manage multiple Codex CLI agents via tmux to work on tasks in parallel. Use whenever a task can be decomposed into independent subtasks (e.g. batch triage, parallel fixes, multi-file refactors). When codex and tmux are available, prefer this over the built-in Task tool for parallelism.","bodyPreview":"# codex-worker\n\nOrchestrate multiple Codex CLI (`codex`) agents running in parallel, each in its\nown git worktree and tmux session.\n\n**When to use:** Whenever you identify that a task can be split into independent\nsubtasks — don''t wait for the user to ask for parallelism. Examples:\n- User says \"triage all open issues updated in the last 7 days\" → fetch the\n  issue list, then spawn one codex worker per issue.\n- User says \"refactor these 5 modules\" → one worker per module.\n- User says \"fix lint er","body":"# codex-worker\n\nOrchestrate multiple Codex CLI (`codex`) agents running in parallel, each in its\nown git worktree and tmux session.\n\n**When to use:** Whenever you identify that a task can be split into independent\nsubtasks — don''t wait for the user to ask for parallelism. Examples:\n- User says \"triage all open issues updated in the last 7 days\" → fetch the\n  issue list, then spawn one codex worker per issue.\n- User says \"refactor these 5 modules\" → one worker per module.\n- User says \"fix lint errors across packages\" → one worker per package.\n\n**Replaces Task tool:** When `codex` and `tmux` are available in the\nenvironment, use codex workers instead of the built-in Task (subagent) tool.\nCodex workers are full-featured agents with their own file system access, shell,\nand isolated worktree — far more capable than subagents.\n\n## Preflight check\n\n```bash\ncommand -v codex && codex login status && command -v tmux\n```\n\nAll three must succeed. The project must be a git repository.\n\n## Naming convention\n\nGit branch and worktree directory share a **task name**:\n\n```\n<type>-<issue number (optional)>-<short description>\n```\n\nThe tmux session adds a `codex-worker-` prefix so workers are easy to filter:\n\n| | Format | Example |\n|---|---|---|\n| Task name | `<type>-<number>-<desc>` | `issue-836-prompt-dollar-sign` |\n| Git branch | same as task name | `issue-836-prompt-dollar-sign` |\n| Worktree dir | `<project>.worktrees/<task>` | `kimi-cli.worktrees/issue-836-prompt-dollar-sign` |\n| tmux session | `codex-worker-<task>` | `codex-worker-issue-836-prompt-dollar-sign` |\n\nMore examples:\n- `issue-518-mcp-config-isolation`\n- `fix-share-dir-skills-path`\n- `feat-ask-user-tool`\n- `refactor-jinja-templates`\n\nList only codex workers: `tmux ls | grep ^codex-worker-`\n\n## Usage\n\nPrefer tmux + interactive codex for all tasks. It supports multi-turn dialogue,\nthe user can `tmux attach` to inspect or intervene, and you can send follow-up\nprompts from outside.\n\n### Spawn a worker\n\n```bash\nNAME=\"issue-836-prompt-dollar-sign\"        # task name\nSESSION=\"codex-worker-$NAME\"               # tmux session name\nPROJECT_DIR=\"$(pwd)\"\nWORKTREE_DIR=\"$PROJECT_DIR.worktrees\"\n\n# 1. Create worktree (skip if exists)\ngit worktree add \"$WORKTREE_DIR/$NAME\" -b \"$NAME\" main 2>/dev/null\n\n# 2. Launch interactive codex inside tmux\ntmux new-session -d -s \"$SESSION\" -x 200 -y 50 \\\n  \"cd $WORKTREE_DIR/$NAME && codex --dangerously-bypass-approvals-and-sandbox\"\n```\n\n### Send a prompt\n\nThe Codex TUI needs time to initialize before it accepts input.\nAfter launching a session, **wait at least 5 seconds** before sending\na prompt. Then send the text followed by `Enter`. If the prompt stays\nin the input field without being submitted, send an additional `Enter`.\n\n```bash\nsleep 5  # wait for Codex TUI to initialize\ntmux send-keys -t \"$SESSION\" \"Your prompt here\" Enter\n# If it doesn''t submit, send another Enter:\n# tmux send-keys -t \"$SESSION\" Enter\n```\n\n### Peek at output\n\n```bash\ntmux capture-pane -t \"$SESSION\" -p | tail -30\n```\n\n### Attach for hands-on interaction\n\n```bash\ntmux attach -t \"$SESSION\"\n```\n\n### Parallel fan-out\n\n```bash\nTASKS=(\n  \"issue-518-mcp-config-isolation|Triage #518: MCP config 被子 agent 继承的隔离问题。分析根因，给出修复方案。\"\n  \"issue-836-prompt-dollar-sign|Triage #836: prompt 包含 $ 时启动静默失败。分析根因，给出修复方案。\"\n)\n\nPROJECT_DIR=\"$(pwd)\"\nWORKTREE_DIR=\"$PROJECT_DIR.worktrees\"\n\nfor entry in \"${TASKS[@]}\"; do\n  NAME=\"${entry%%|*}\"\n  PROMPT=\"${entry#*|}\"\n  SESSION=\"codex-worker-$NAME\"\n  git worktree add \"$WORKTREE_DIR/$NAME\" -b \"$NAME\" main 2>/dev/null\n  tmux new-session -d -s \"$SESSION\" -x 200 -y 50 \\\n    \"cd $WORKTREE_DIR/$NAME && codex --dangerously-bypass-approvals-and-sandbox\"\n  sleep 5  # wait for Codex TUI to fully initialize\n  tmux send-keys -t \"$SESSION\" \"$PROMPT\" Enter\ndone\n```\n\n### Fallback: `codex exec`\n\nOnly use `codex exec` when you explicitly don''t need follow-up (e.g. CI, pure\nanalysis with `-o` output). It does not support multi-turn dialogue.\n\n```bash\ncodex exec --dangerously-bypass-approvals-and-sandbox \\\n  -o \"/tmp/$NAME-result.md\" \\\n  \"Your prompt here\"\n```\n\n## Lifecycle management\n\nList active workers:\n\n```bash\ntmux ls | grep ^codex-worker-\n```\n\nKill a finished worker:\n\n```bash\ntmux kill-session -t \"codex-worker-$NAME\"\n```\n\nClean up worktree after merging:\n\n```bash\ntmux kill-session -t \"codex-worker-$NAME\" 2>/dev/null\ngit worktree remove \"$WORKTREE_DIR/$NAME\"\ngit branch -d \"$NAME\"\n```\n\nBatch cleanup of dead sessions:\n\n```bash\ntmux list-sessions -F ''#{session_name}:#{pane_dead}'' \\\n  | grep '':1$'' \\\n  | cut -d: -f1 \\\n  | xargs -I{} tmux kill-session -t {}\n```\n"},"lastSynced":"2026-03-08T02:09:13.396Z","agentAnalysis":{"suitability":{"en":"Ideal for Autonomous Agents like AutoGPT and LangChain needing parallel task automation for enhanced productivity.","zh":"适合像 AutoGPT 和 LangChain 这样的自主代理，需要并行任务自动化以提高生产力。","ja":"AutoGPT や LangChain のような自律エージェントに適しており、生産性の向上のために並行タスクの自動化が必要です。","ko":"AutoGPT와 LangChain 같은 자율 에이전트에 적합하며, 생산성을 향상시키기 위해 병렬 작업 자동화가 필요합니다.","es":"Ideal para Autonomous Agents como AutoGPT y LangChain que necesitan automatización de tareas en paralelo para una productividad mejorada.","fr":"Idéal pour les Autonomous Agents comme AutoGPT et LangChain nécessitant une automatisation de tâches parallèles pour une productivité accrue.","de":"Ideal für Autonomous Agents wie AutoGPT und LangChain, die eine Automatisierung paralleler Aufgaben für eine gesteigerte Produktivität benötigen.","pt":"Ideal para Agentes Autónomos como AutoGPT e LangChain que necessitam de automação de tarefas paralelas para produtividade aprimorada.","ru":"Идеально подходит для автономных агентов, таких как AutoGPT и LangChain, которым требуется автоматизация параллельных задач для повышения производительности.","ar":"مثالي للوكلاء المستقلين مثل AutoGPT وLangChain الذين يحتاجون إلى أتمتة المهام المتوازية لتعزيز الإنتاجية."},"recommendation":{"en":"Empowers agents to orchestrate multiple Codex CLI agents in parallel using git worktree and tmux sessions, streamlining tasks like issue triage and code refactoring with efficient utilization of system resources.","zh":"使代理能够使用 git worktree 和 tmux 会话并行编排多个 Codex CLI 代理，简化诸如问题分类和代码重构等任务，并高效利用系统资源。","ja":"エージェントが git worktree と tmux セッションを使用して複数の Codex CLI エージェントを並行してオーケストレーションできるようにし、問題のトリアージやコードのリファクタリングなどのタスクを簡素化し、システム リソースを効率的に利用できるようにします。","ko":"에이전트가 git worktree와 tmux 세션을 사용하여 여러 개의 Codex CLI 에이전트를 병렬로 오케스트레이션 할 수 있도록 해주어, 문제 분류 및 코드 리팩토링과 같은 작업을 간소화하고 시스템 리소스를 효율적으로 활용할 수 있습니다.","es":"Permite a los agentes orquestar múltiples agentes Codex CLI en paralelo utilizando git worktree y sesiones de tmux, optimizando tareas como la clasificación de incidencias y la refactorización de código con una utilización eficiente de los recursos del sistema.","fr":"Permet aux agents d''orchestrer plusieurs agents Codex CLI en parallèle en utilisant git worktree et les sessions tmux, rationalisant des tâches comme la triage des problèmes et la refactorisation du code avec une utilisation efficace des ressources système.","de":"Ermöglicht es Agents, mehrere Codex CLI Agents parallel unter Verwendung von git worktree und tmux-Sitzungen zu orchestrieren, wodurch Aufgaben wie Issue-Triage und Code-Refactoring mit effizienter Nutzung von Systemressourcen optimiert werden.","pt":"Capacita os agentes a orquestrar múltiplos agentes Codex CLI em paralelo usando git worktree e sessões tmux, simplificando tarefas como triagem de issues e refatoração de código com utilização eficiente de recursos do sistema.","ru":"Позволяет агентам оркестрировать несколько агентов Codex CLI параллельно с использованием git worktree и сессий tmux, упрощая такие задачи, как сортировка проблем и рефакторинг кода, с эффективным использованием системных ресурсов.","ar":"يمكّن الوكلاء من تنظيم عدة وكلاء Codex CLI بشكل متوازٍ باستخدام git worktree وجلسات tmux، مما يبسط مهام مثل فرز المشكلات وإعادة هيكلة الكود مع الاستخدام الفعال لموارد النظام."},"useCases":{"en":["Automating issue triage for multiple open issues","Parallelizing code refactoring across several modules","Accelerating lint error fixes for large codebases"],"zh":["自动化多个打开问题的问题分类","跨多个模块的代码重构并行化","大型代码库的 lint 错误修复加速"],"ja":["複数のオープン問題の問題トリアージの自動化","複数のモジュールにわたるコードリファクタリングの並列化","大規模コードベースの lint エラー修復の加速"],"ko":["여러 개의 오픈된 문제에 대한 문제 분류 자동화","여러 모듈에 걸쳐서 코드 리팩토링 병렬화","대형 코드베이스의 lint 오류修复 가속"],"es":["Automatización de la clasificación de incidencias para múltiples issues abiertos","Paralelización de la refactorización de código en varios módulos","Aceleración de la corrección de errores de linting para grandes bases de código"],"fr":["Automatisation du triage des problèmes pour plusieurs issues ouverts","Parallélisation de la refactorisation du code sur plusieurs modules","Accélération des corrections d''erreurs de linting pour les grandes bases de code"],"de":["Automatisierung des Issue-Triage für mehrere offene Issues","Parallelisierung der Code-Refaktorisierung über mehrere Module","Beschleunigung der Behebung von Linting-Fehlern für große Codebasen"],"pt":["Automatização da triagem de issues para múltiplos problemas abertos","Paralelização da refatoração de código em vários módulos","Aceleração da correção de erros de lint para grandes bases de código"],"ru":["Автоматизация сортировки проблем для нескольких открытых вопросов","Параллельный рефакторинг кода в нескольких модулях","Ускорение исправления ошибок линтинга для больших кодовых баз"],"ar":["أتمتة فرز المشكلات للعديد من القضايا المفتوحة","توازي إعادة هيكلة الكود عبر عدة وحدات","تسريع إصلاح أخطاء lint لقواعد التعليمات البرمجية الكبيرة"]},"limitations":{"en":["Requires git worktree and tmux session management","Dependent on Codex CLI compatibility","Optimized for tasks that can be split into independent subtasks"],"zh":["需要 git worktree 和 tmux 会话管理","依赖于 Codex CLI 兼容性","针对可以拆分为独立子任务的任务进行优化"],"ja":["git worktree と tmux セッション管理が必要","Codex CLI との互換性に依存","独立したサブタスクに分割できるタスクに最適化"],"ko":["git worktree와 tmux 세션 관리가 필요","Codex CLI와의 호환성에 의존","독립적인 하위 작업으로 분할할 수 있는 작업에 최적화"],"es":["Requiere la gestión de git worktree y sesiones de tmux","Dependiente de la compatibilidad con Codex CLI","Optimizado para tareas que pueden dividirse en subtareas independientes"],"fr":["Nécessite la gestion de git worktree et des sessions tmux","Dépend de la compatibilité avec Codex CLI","Optimisé pour les tâches pouvant être divisées en sous-tâches indépendantes"],"de":["Erfordert die Verwaltung von git worktree und tmux-Sitzungen","Abhängig von der Codex CLI-Kompatibilität","Optimiert für Aufgaben, die in unabhängige Teilaufgaben aufgeteilt werden können"],"pt":["Requer gestão de git worktree e sessões tmux","Dependente da compatibilidade com Codex CLI","Otimizado para tarefas que podem ser divididas em subtarefas independentes"],"ru":["Требует управления git worktree и сессиями tmux","Зависит от совместимости с Codex CLI","Оптимизирован для задач, которые можно разделить на независимые подзадачи"],"ar":["يتطلب إدارة git worktree وجلسات tmux","يعتمد على التوافق مع Codex CLI","مُحسّن للمهام التي يمكن تقسيمها إلى مهام فرعية مستقلة"]},"version":4},"contentHash":"3abb4cf9cf6bea74ba6fb6bdb63f69b455d21fd58dc3b6df200c44188e0dd556","qualityScore":60}');
