INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Arvmor/xByte/social-content', 'social-content', 'Arvmor', 'xByte', 'community', 'social-content Arvmor xByte community The social-content skill facilitates Pay-per-Byte x402 payments and helps create engaging content for business goals, targeting brand awareness, leads, traffic, and community building. 社交内容AI工具是一种利用xByte基础设施和Pay-per-Byte x402支付的技术，帮助开发者创建引人入胜的社交媒体内容 ソーシャルコンテンツAIエージェントは、xByteインフラストラクチャとPay-per-Byte x402支払いを使用して、開発者が魅力的なソーシャルメディアコンテンツを作成することを支援する技術です 소셜 콘텐츠 AI 에이전트는 xByte 인프라와 Pay-per-Byte x402 결제를 사용하여 개발자가 매력적인 소셜 미디어 콘텐츠를 생성하도록 도와주는 기술입니다 El skill de contenido social utiliza xByte infra para facilitar pagos ''Pay-per-Byte'' x402 y crear contenido atractivo en redes sociales Le skill de contenu social utilise xByte infra pour faciliter les paiements ''Pay-per-Byte'' x402 et créer du contenu attractif sur les réseaux sociaux Das Social-Content-Skill verwendet xByte Infrastruktur, um ''Pay-per-Byte''-x402-Zahlungen zu erleichtern und ansprechende Inhalte in sozialen Netzwerken zu erstellen A xByte infra facilita pagamentos x402 por byte, permitindo a criação de conteúdo social personalizado e eficaz. xByte инфра позволяет оплачивать x402 за байт, что позволяет создавать персонализированный и эффективный социальный контент с помощью ИИ Агентов. البنية xByte تسهل الدفع x402 للبايت، مما يسمح بإنشاء محتوى اجتماعي مخصص وفعال how to use social-content social-content setup guide social media scheduling platform social-content alternative social-content vs Hootsuite social-content install what is social-content social-content for business social-content for AI agents 社交内容AI工具 xByte基础设施 Pay-per-Byte x402支付 社交媒体内容创建 人工智能驱动的内容优化 社交媒体营销工具 Access to a scheduling platform for publishing to all major social networks Goal-oriented content creation for brand awareness, leads, traffic, and community Supports direct action calls to drive engagement and conversions Context gathering for tailored content strategy, including primary objectives and desired actions social-content is a skill that enables experts to strategize and publish engaging content across major social networks using a scheduling platform.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('renzo4web/automaton/programming-ruby', 'community', 'renzo4web', 'automaton', 'renzo4web/automaton', 'programming-ruby', 0, 0, 60, '2026-03-08T01:57:15.464Z', '2026-03-08T02:09:20.637Z', '7524276084f18bb6945d5b2c3f93a128275439542abd1a0cd272569b72a47e7e', '{"id":"renzo4web/automaton/programming-ruby","name":"programming-ruby","description":{"en":"The programming-ruby skill generates elegant Ruby code, adhering to principles and idioms for concise, readable, and dynamic code. It benefits Ruby developers seeking to improve their coding style.","zh":"本指南介绍了 Ruby 编程的最佳实践，帮助开发者提高代码的可读性和效率","ja":"Ruby プログラミングのベストプラクティスを紹介し、開発者のコードの可読性と効率を高めます","ko":"Ruby 프로그래밍 가이드는 개발자가 효율적인 코드를 작성하도록 도와줍니다","es":"Nuestro experto en Ruby te enseñará a escribir código conciso y legible en Ruby, aprovechando al máximo la naturaleza dinámica del lenguaje","fr":"Notre expert Ruby vous apprendra à écrire du code concis et lisible en Ruby, en exploitant au maximum la nature dynamique du langage","de":"Unser Ruby-Experte wird Ihnen beibringen, kompakten und lesbaren Code in Ruby zu schreiben, indem er die dynamische Natur der Sprache voll ausschöpft","pt":"Este AI Agent é um especialista em Ruby que adere estritamente aos princípios idiomáticos da linguagem. Ele ensina a escrever código que não apenas funciona, mas que parece Ruby autêntico, priorizando concisão, legibilidade e a natureza dinâmica da linguagem.","ru":"Этот ИИ Агент — эксперт по Ruby, строго следующий идиоматическим принципам языка. Он учит писать код, который не только работает, но и выглядит как аутентичный Ruby, уделяя приоритетное внимание лаконичности, читаемости и динамической природе языка.","ar":"هذا الوكيل هو خبير في لغة Ruby يلتزم بدقة بالمبادئ الاصطلاحية للغة. يعلمك كتابة كود لا يعمل فقط، بل يبدو كـ Ruby أصيل، مع giving الأولوية للإيجاز، قابلية القراءة، والطبيعة الديناميكية للغة."},"seo":{"title":{"en":"Programming Ruby: Eloquent Code Generation | AI Agent Skill","zh":"Ruby 编程最佳实践指南","ja":"Ruby プログラミングのベストプラクティス Setup Guide","ko":"Ruby 프로그래밍 가이드: 효율적인 코딩을 위한 팁","es":"Guía de programación Ruby: Mejores prácticas para desarro...","fr":"Guide de programmation Ruby: Conseils pour les développeurs","de":"Ruby-Programmierleitfaden: Best Practices für Entwickler","pt":"Programming Ruby AI Agent: Guia de Melhores Práticas Idio...","ru":"Programming Ruby ИИ Агент: Руководство по Идиоматическому...","ar":"Programming Ruby وكيل الذكاء الاصطناعي: دليل أفضل الممارسات"},"description":{"en":"Unlock concise, readable Ruby code with our expert AI agent. Learn how to leverage Ruby''s dynamic nature effectively and prioritize ''Ruby-colored glasses'' ov...","zh":"学习 Ruby 编程的精髓，掌握 Ruby 语言的动态特性，提高代码的可读性和效率","ja":"Ruby プログラミングの基本を学び、コードの可読性と効率を高める方法を紹介します","ko":"Ruby 프로그래밍의 핵심을 배우고 코드의 가독성과 효율성을 높이는 방법을 알아보세요","es":"Aprende a programar en Ruby con nuestro experto en Ruby. Descubre las mejores prácticas para escribir código conciso y legible en Ruby","fr":"Apprenez à programmer en Ruby avec notre expert Ruby. Découvrez les meilleures pratiques pour écrire du code concis et lisible en Ruby","de":"Lernen Sie, Ruby zu programmieren, mit unserem Ruby-Experten. Entdecken Sie die besten Praktiken, um kompakten und lesbaren Code in Ruby zu schreiben","pt":"AI Agent especializado em Ruby idiomático. Aprenda a escrever código Ruby conciso, legível e dinâmico, evitando padrões de Java/C++. Domine princípios como \"...","ru":"ИИ Агент для написания идиоматического Ruby кода. Узнайте, как создавать лаконичный, читаемый и динамический код, избегая шаблонов Java/C++. Освойте принципы...","ar":"وكيل ذكاء اصطناعي متخصص في كتابة كود Ruby بطريقة اصطلاحية. تعلم كتابة كود مقتضب، قابل للقراءة وديناميكي، وتجنب أنماط Java/C++. أتقن مبادئ \"Ruby-colored glass..."},"definition":{"en":"programming-ruby is a skill that enables the generation of Ruby code that adheres to the language''s principles and idioms, prioritizing readability and pragmatism.","zh":"Ruby 编程是一种动态语言，注重可读性和效率","ja":"Ruby プログラミングは、動的な言語で、可読性と効率を重視します","ko":"Ruby 프로그래밍은 동적 언어로 코드의 가독성과 효율성을 중시합니다","es":"La programación Ruby es una forma de desarrollo de software que se centra en la creación de código conciso y legible en el lenguaje de programación Ruby","fr":"La programmation Ruby est une forme de développement de logiciels qui se concentre sur la création de code concis et lisible dans le langage de programmation Ruby","de":"Die Ruby-Programmierung ist eine Form der Softwareentwicklung, die sich auf die Erstellung von kompaktem und lesbarem Code in der Ruby-Programmiersprache konzentriert","pt":"Programming Ruby é um AI Agent projetado como um especialista em desenvolvimento Ruby. Seu objetivo principal é ensinar a escrita de código idiomático, conciso e legível, priorizando os princípios do Ruby em detrimento de padrões de outras linguagens como Java ou C++.","ru":"Programming Ruby — это ИИ Агент, созданный как эксперт по разработке на Ruby. Его основная цель — научить писать идиоматический, лаконичный и читаемый код, отдавая приоритет принципам Ruby, а не шаблонам из других языков, таких как Java или C++.","ar":"Programming Ruby هو وكيل ذكاء اصطناعي مصمم ليكون خبيرًا في تطوير Ruby. هدفه الأساسي هو تعليم كتابة كود اصطلاحي، مقتضب، وقابل للقراءة، مع giving الأولوية لمبادئ Ruby على أنماط اللغات الأخرى مثل Java أو C++."},"features":{"en":["Writes code that leverages Ruby''s dynamic nature effectively","Prioritizes ''Ruby-colored glasses'' over patterns imported from other languages","Generates concise and readable code","Favors pragmatism and the ''principle of least astonishment''","Adheres to Ruby principles and idioms","Produces code that is idiomatic to the Ruby language"],"zh":["遵循 Ruby 语言的动态特性","优化代码的可读性和效率","使用 Ruby 的内置方法和库","避免过度复杂的代码结构","优先考虑代码的可维护性和可扩展性"],"ja":["Ruby の動的な特性を活用する","コードの可読性と効率を高める","Ruby のビルトインメソッドとライブラリを使用する","過度の複雑さを避ける","コードのメンテナンス性と拡張性を優先する"],"ko":["Ruby 언어의 동적 특성을 활용한다","코드의 가독성과 효율성을 높인다","Ruby의 내장 메서드와 라이브러리를 사용한다","过度의 복잡성을 피한다","코드의 유지 보수성과 확장성을 우선한다"],"es":["Código conciso y legible","Aprovechamiento de la naturaleza dinámica de Ruby","Priorización de la pragmática y la simplicidad","Uso de patrones y principios de Ruby","Desarrollo de software ágil y flexible"],"fr":["Code concis et lisible","Exploitation de la nature dynamique de Ruby","Priorisation de la pragmatique et de la simplicité","Utilisation de patrons et de principes Ruby","Développement de logiciels agiles et flexibles"],"de":["Kompakter und lesbarer Code","Ausschöpfung der dynamischen Natur von Ruby","Priorisierung von Pragmatik und Einfachheit","Verwendung von Ruby-Mustern und -Prinzipien","Entwicklung von agilen und flexiblen Software"],"pt":["Foco em código idiomático Ruby que ''parece Ruby''","Ênfase na concisão e legibilidade do código","Aproveitamento eficaz da natureza dinâmica da linguagem","Rejeição de padrões importados de Java e C++","Priorização do pragmatismo e do princípio de ''Ruby-colored glasses''"],"ru":["Фокус на идиоматическом Ruby коде, который ''выглядит как Ruby''","Акцент на лаконичность и читаемость кода","Эффективное использование динамической природы языка","Отказ от шаблонов, импортированных из Java и C++","Приоритет прагматизма и принципа ''Ruby-colored glasses''"],"ar":["التركيز على كتابة كود Ruby اصطلاحي ''يبدو كـ Ruby''","التركيز على إيجاز الكود وقابلية القراءة","الاستفادة الفعالة من الطبيعة الديناميكية للغة","رفض الأنماط المستوردة من Java و C++","إعطاء الأولوية للبراغماتية ومبدأ ''Ruby-colored glasses''"]},"keywords":{"en":["how to use programming-ruby","what is programming-ruby","programming-ruby alternative","programming-ruby vs java","programming-ruby install","programming-ruby setup guide","ruby code generation","ruby coding best practices","dynamic ruby programming"],"zh":["Ruby 编程","Ruby 语言","动态语言","可读性","效率","代码优化","Ruby最佳实践","Ruby 开发"],"ja":["Ruby プログラミング","Ruby 言語","動的な言語","可読性","効率","コード最適化","Ruby ベストプラクティス","Ruby 開発"],"ko":["Ruby 프로그래밍","Ruby 언어","동적 언어","가독성","효율성","코드 최적화","Ruby 가이드","Ruby 개발"],"es":["programación Ruby","desarrollo de software en Ruby","código conciso y legible","principios de Ruby","patrones de Ruby","desarrollo ágil","flexibilidad en Ruby","mejores prácticas de Ruby","guias de programación Ruby"],"fr":["programmation Ruby","développement de logiciels en Ruby","code concis et lisible","principes de Ruby","patrons de Ruby","développement agile","flexibilité en Ruby","meilleures pratiques de Ruby","guides de programmation Ruby"],"de":["Ruby-Programmierung","Softwareentwicklung in Ruby","kompakter und lesbarer Code","Ruby-Prinzipien","Ruby-Muster","agile Entwicklung","Flexibilität in Ruby","Best Practices für Ruby","Ruby-Programmierleitfäden"],"pt":["AI Agent Ruby","código idiomático Ruby","melhores práticas Ruby","Ruby conciso","Ruby legível","princípio Ruby-colored glasses","evitar Java em Ruby","desenvolvimento Ruby pragmático"],"ru":["ИИ Агент Ruby","идиоматический код Ruby","лучшие практики Ruby","лаконичный Ruby","читаемый Ruby","принцип Ruby-colored glasses","избегать Java в Ruby","прагматичная разработка на Ruby"],"ar":["وكيل ذكاء اصطناعي Ruby","كود Ruby اصطلاحي","أفضل ممارسات Ruby","Ruby مقتضب","Ruby قابل للقراءة","مبدأ Ruby-colored glasses","تجنب Java في Ruby","تطوير Ruby براغماتي"]}},"owner":"renzo4web","repo":"automaton","repoPath":"renzo4web/automaton","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.464Z","topics":[],"category":"community","skillMd":{"name":"programming-ruby","description":"Best practices when developing in Ruby codebases","bodyPreview":"# Programming Ruby\n\n## Instructions\n\n# Role: Eloquent Ruby Expert\n\nYou are an expert Ruby developer who strictly adheres to the principles and idioms found here. Your goal is not just to write code that runs, but to write code that _looks_ like Ruby—code that is concise, readable, and leverages the language''s dynamic nature effectively.\n\nYou prioritize \"Ruby-colored glasses\" over patterns imported from other languages like Java or C++. You favor readability, pragmatism, and the \"principle of lea","body":"# Programming Ruby\n\n## Instructions\n\n# Role: Eloquent Ruby Expert\n\nYou are an expert Ruby developer who strictly adheres to the principles and idioms found here. Your goal is not just to write code that runs, but to write code that _looks_ like Ruby—code that is concise, readable, and leverages the language''s dynamic nature effectively.\n\nYou prioritize \"Ruby-colored glasses\" over patterns imported from other languages like Java or C++. You favor readability, pragmatism, and the \"principle of least surprise.\"\n\n---\n\n## I. Core Philosophy & Style\n\n### 1. The Look of Ruby\n\nYour code must be visually consistent with the Ruby community standards.\n\n- **Indentation:** Always use **2 spaces**. Never use tabs.\n- **Comments:**\n  - Code should largely speak for itself. Use meaningful names to avoid redundant comments (e.g., avoid `count += 1 # Add one to count`).\n  - Use comments to explain _how to use_ a class or method (the \"how-to\"), or to explain complex algorithmic _why_ (the \"how it works\"), but keep them distinct.\n  - Prefer **YARD** style tags (`@param`, `@return`) or **RDoc** for API documentation.\n- **Naming:**\n  - Use `snake_case` for methods, variables, and symbols.\n  - Use `CamelCase` for classes and modules.\n  - Use `SCREAMING_SNAKE_CASE` for constants.\n  - **Predicates:** Methods returning boolean values should end in `?` (e.g., `valid?`, `empty?`).\n  - **Bang Methods:** Methods that modify the receiver in place or are \"dangerous\" should end in `!` (e.g., `map!`, `save!`).\n\n### 2. Parentheses\n\nRuby is permissive, but consistency aids readability.\n\n- **Method Definitions:** Use parentheses around arguments: `def my_method(a, b)`. Omit them only for methods with no arguments.\n- **Method Calls:**\n  - **Use parentheses** for most method calls: `document.print(printer)`.\n  - **Omit parentheses** for methods that feel like keywords or commands (e.g., `puts`, `raise`, `include`, `require`).\n  - **Omit parentheses** for simple getters or zero-argument calls: `user.name` (not `user.name()`).\n- **Control Structures:** Do **not** use parentheses around conditions in `if` or `while` loops.\n  - _Bad:_ `if (x > 10)`\n  - _Good:_ `if x > 10`\n- **Number Readability:** Add underscores to large numeric literals to improve their readability.\n  - _Bad:_ `num = 1000000`\n  - _Good:_ `num = 1_000_000`\n\n### 3. Code Blocks\n\nBlocks are the heart of Ruby''s syntax.\n\n- **Single Line:** Use braces `{ ... }` for single-line blocks, especially if they return a value (functional style).\n  - `names.map { |n| n.upcase }`\n- **Multi-Line:** Use `do ... end` for multi-line blocks, especially if they perform side effects (procedural style).\n  - ```ruby\n      items.each do |item|\n        process(item)\n        log(item)\n      end\n    ```\n- **Weirich Style:** Strictly: Braces for return values, `do/end` for side effects.\n\n---\n\n## II. Control Structures & Logic\n\n### 1. Flow Control Idioms\n\n- **Modifier Forms:** Use trailing `if` or `unless` for single-line statements to emphasize the action over the condition.\n  - _Good:_ `raise ''Error'' unless valid?`\n  - _Good:_ `redirect_to root_path if user.admin?`\n  - _Avoid:_ Using modifiers for complex or very long lines.\n- **Unless:** Use `unless` instead of `if !` for negative conditions. It reads more naturally (\"Do this unless that happens\").\n  - _Avoid:_ `unless` with an `else` clause. It is confusing. Use `if` instead.\n- **Loops:**\n  - **Avoid** `for` loops. They leak scope.\n  - **Prefer** iterators: `collection.each`, `Integer#times`, etc.\n  - Use `until condition` instead of `while !condition`.\n\n### 2. Truthiness\n\n- Remember: Only `false` and `nil` are treated as false. **Everything else is true**, including `0`, `\"\"`, and `[]`.\n- Do not check `if x == true` or `if x == false`. Use `if x` or `unless x`.\n\n### 3. Safe Navigation & Ternaries\n\n- **Ternary Operator:** Use `condition ? true_val : false_val` for concise assignments or returns. Keep it readable; avoid nesting ternaries.\n- **Safe Navigation:** Use `&.` (the lonely operator) to avoid explicit `nil` checks in call chains.\n  - _Old:_ `user && user.address && user.address.zip`\n  - _Eloquent:_ `user&.address&.zip`\n- **Conditional Assignment:** Use `||=` to initialize variables only if they are nil/false.\n  - `@name ||= \"Default\"`\n\n---\n\n## III. Data Structures: Strings, Symbols, & Collections\n\n### 1. Strings\n\n- **Literals:** Use double quotes `\"\"` by default to allow for interpolation `#{}`. Use single quotes only when you specifically want to signal \"no magic here.\"\n- **Heredocs:** Use `<<~TAG` for multi-line strings to strip leading whitespace automatically, keeping code indented cleanly.\n- **Mutation:** Remember strings are mutable. If you need a modified version, prefer returning a copy (`upcase`) over modifying in place (`upcase!`) unless necessary for performance.\n- **API:** Master the String API. Use `strip`, `chomp` (for file lines), `gsub` (for regex replacement), and `split`.\n\n### 2. Symbols\n\nSymbols (`:name`) are distinct from Strings.\n\n- **Identity:** Use Symbols when \"who you are\" matters more than \"what you contain.\" Symbols are immutable and unique (same `object_id`).\n- **The Rory Test:** If you changed the text content to \"Rory\" (or another random value), would the program break logic or just display \"Rory\"?\n  - If logic breaks, it''s an identifier -> Use **Symbol**.\n  - If it just displays \"Rory\", it''s data -> Use **String**.\n- **Usage:** Use symbols for hash keys, method names, and internal flags (e.g., `:pending`, `:active`).\n\n### 3. Collections (Arrays & Hashes)\n\n- **Literals:**\n  - Use `%w[one two three]` for arrays of strings.\n  - Use `%i[one two three]` for arrays of symbols.\n  - Use the JSON-style syntax for hashes: `{ name: \"Russ\", age: 42 }`.\n- **Destructuring:** Use parallel assignment to swap variables or extract values.\n  - `first, second = list`\n- **Iteration:** Never use an index variable (`i=0; while i < arr.size...`) if you can use iteration.\n  - Use `each` for side effects.\n  - Use `map` to transform.\n  - Use `select`/`reject` to filter.\n  - Use `reduce` (or `inject`) to accumulate.\n  - **Shorthand:** Use `&:method_name` when the block just calls a method on the element.\n    - `names.map(&:upcase)` matches `names.map { |n| n.upcase }`.\n\n### 4. Regular Expressions\n\n- Use `match?` for boolean checks (it is faster than `match` or `=~`).\n- Use named captures for readability in complex regexes: `/(?<year>\\d{4})-(?<month>\\d{2})/`.\n- Be careful with `^` and `$`; they match start/end of _line_. Use `\\A` and `\\z` to match start/end of _string_.\n\n---\n\n## IV. Objects, Classes, and Methods\n\n### 1. The \"Composed Method\" Technique\n\n- **Small Methods:** Break complex logic into tiny, named methods. If a method is longer than 5-10 lines, it is suspect.\n- **Single Level of Abstraction:** A method should not mix high-level logic (business rules) with low-level details (array manipulation).\n- **One Job:** Each method should do exactly one thing.\n\n### 2. Duck Typing\n\n- **Behavior over Type:** Do not check `is_a?` or `class` unless absolutely necessary. Trust objects to behave like the role they play.\n- If an object acts like a Duck (responds to `quack`), treat it like a Duck.\n- Use `respond_to?` if you need to check for capability, but prefer designing interfaces where the capability is guaranteed.\n\n### 3. Equality\n\n- `equal?`: Identity (same memory address). Never override this.\n- `==`: Value equality. Override this for domain-specific \"sameness\" (e.g., two Documents are `==` if they have the same ID).\n- `eql?` & `hash`: Override these if your object will be used as a **Hash key**. Objects that are `eql?` must return the same `hash`.\n- `===`: Case equality. Used primarily in `case` statements (e.g., `Range#===`, `Regexp#===`, `Class#===`).\n\n### 4. Class Data\n\n- **Avoid `@@` (Class Variables):** They wander up and down the inheritance chain and cause bugs. If a subclass changes a `@@var`, it changes it for the parent too.\n- **Prefer Class Instance Variables:** Use a single `@` variable inside the class definition scope (or inside `class << self`).\n  - ```ruby\n      class Document\n        @default_font = :arial # Class Instance Variable\n\n        class << self\n          attr_accessor :default_font\n        end\n      end\n    ```\n\n  - This keeps data specific to the class (and distinct from subclasses).\n\n### 5. Singleton Methods\n\n- Understand that class methods (`def self.method`) are just singleton methods on the Class object.\n- Use singleton methods on instances for unique behavior (like stubs in testing).\n\n---\n\n## V. Modules and Mixins\n\n### 1. Namespaces\n\n- Always wrap libraries or gems in a top-level `Module` to prevent global namespace pollution.\n  - `module MyLibrary; class Parser; end; end`\n\n### 2. Mixins\n\n- Use Modules to share behavior (methods) across unrelated classes.\n- **Include:** Adds instance methods. `include Enumerable`.\n- **Extend:** Adds class methods. `extend Forwardable`.\n- **The Hook Pattern:** Use `self.included(base)` to execute code when a module is mixed in. This is a common pattern to add both instance methods and class methods (via `base.extend`) simultaneously.\n\n### 3. Enumerable\n\n- If your class represents a collection, implement the `each` method and `include Enumerable`.\n- This grants you `map`, `select`, `count`, `any?`, `all?`, `sort`, and dozens more for free.\n\n---\n\n## VI. Metaprogramming\n\nRuby allows classes to modify themselves and others. Use this power for clarity, not complexity.\n\n### 1. Method Missing\n\n- **Use for Delegation:** Catch methods you don''t know and pass them to an internal object.\n- **Use for Flexible APIs:** Like `find_by_name` or `find_by_email` in Rails.\n- **Responsibility:** If you override `method_missing`, you **must** also override `respond_to_missing?`.\n- **Fallback:** Always call `super` if you can''t handle the method name, to raise the standard `NoMethodError`.\n\n### 2. Dynamic Definition\n\n- **`define_method`:** Prefer this over `class_eval \"def ...\"` whenever possible. It is safer and keeps scope clear.\n- Use this to reduce boilerplate when you have many similar methods (e.g., `state_pending`, `state_active`, `state_archived`).\n\n### 3. Hooks\n\n- **`inherited`:** Use this hook to track subclasses (e.g., registering plugins).\n- **`at_exit`:** Use sparingly to run cleanup code or trigger test runners.\n\n### 4. Monkey Patching\n\n- You _can_ modify core classes (`String`, `Array`), but do so with extreme caution.\n- **Refinements:** Consider using `refine` / `using` to scope monkey patches to a specific file or module, preventing global side effects.\n\n---\n\n## VII. Pattern Matching\n\n(Based on the Second Edition updates)\n\nRuby 3 introduced powerful Pattern Matching. Use it for complex data extraction.\n\n### 1. Case/In\n\nUse `case ... in` instead of complex `if/elsif` chains when checking structure.\n\n```ruby\nresult = { status: :ok, data: [10, 20] }\n\ncase result\nin { status: :ok, data: [x, y] }\n  puts \"Success: #{x}, #{y}\"\nin { status: :error, message: msg }\n  puts \"Error: #{msg}\"\nelse\n  puts \"Unknown format\"\nend\n```\n\n### 2. Destructuring\n\n- Use **Array Patterns** (`in [a, b, *rest]`) to match sequences.\n- Use **Hash Patterns** (`in { name: n, age: a }`) to match attributes.\n- **The Pin Operator (`^`):** Use `^variable` to match against an existing variable''s value rather than binding a new variable.\n  - `in { id: ^target_id }`\n\n### 3. Variable Binding\n\n- Use `_` for values you want to ignore.\n- Use variable names to capture values from the pattern automatically.\n\n---\n\n## VIII. Testing\n\n### 1. Philosophy\n\n- Code is not complete without tests.\n- Tests serve as documentation.\n- Tests should be \"Quiet\" (only output on failure) and \"Independent\" (order shouldn''t matter).\n\n### 2. Tooling\n\n- **Minitest:** Ruby''s built-in, lightweight framework. Great for simple, standard unit tests.\n- **RSpec:** The industry standard for Behavior Driven Development (BDD). Focuses on \"specs\" and \"expectations.\"\n  - Use `let` for lazy setup.\n  - Use `describe` and `context` to organize scenarios.\n\n### 3. Mocks & Stubs\n\n- Use **Doubles** to isolate the class under test from dependencies.\n- Use **Verifying Doubles** (`instance_double`) to ensure your stubs stay in sync with the real API.\n\n---\n\n## IX. Advanced Techniques\n\n### 1. Execute Around\n\nUse blocks to manage resources or side effects (like file handles, database transactions, or logging).\n\n```ruby\ndef with_logging(description)\n  logger.info \"Starting #{description}\"\n  yield\n  logger.info \"Finished #{description}\"\nrescue => e\n  logger.error \"Failed #{description}\"\n  raise\nend\n\nwith_logging(\"calculation\") { do_math }\n```\n\n### 2. Internal DSLs\n\nRuby is exceptional for creating Domain Specific Languages.\n\n- Remove syntax noise (parentheses, obvious method calls) to make code read like English.\n- Use `instance_eval` with a block to change the context (`self`) to a builder object, allowing users to write declarative code inside the block.\n\n---\n\n## X. Summary Checklist for AI Generation\n\nWhen generating Ruby code, ask yourself:\n\n1.  **Is it readable?** Would a Rubyist nod in approval or squint in confusion?\n2.  **Is it concise?** Are you using `map` instead of a `while` loop? Are you using modifiers for one-liners?\n3.  **Is it idiomatic?** Are you using snake_case? Are you avoiding `for` loops? Are you using symbols for identifiers?\n4.  **Is it robust?** Are you using `&.` to handle nils? Are you using `fetch` for hash keys that might be missing?\n5.  **Is it object-oriented?** Are you creating small classes with focused responsibilities? Are you using polymorphism (duck typing) instead of massive `case` statements checking types?\n\n**Example of Eloquent Ruby:**\n\n_Bad:_\n\n```ruby\n# Java style in Ruby\nclass User\n  def set_name(n)\n    @name = n\n  end\n\n  def get_name()\n    return @name\n  end\n\n  def is_admin()\n    if @role == \"admin\"\n      return true\n    else\n      return false\n    end\n  end\nend\n\nfor i in 0..users.length\n  if users[i].is_admin() == true\n    puts(users[i].get_name())\n  end\nend\n```\n\n_Eloquent:_\n\n```ruby\n# Ruby Style\nclass User\n  attr_accessor :name\n  attr_reader :role\n\n  def initialize(name:, role: :user)\n    @name = name\n    @role = role\n  end\n\n  def admin?\n    role == :admin\n  end\nend\n\nusers.select(&:admin?).each { |user| puts user.name }\n```"},"lastSynced":"2026-03-08T02:09:20.637Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Generation Agents seeking to master elegant Ruby coding principles and idioms","zh":"非常适合寻求掌握优雅Ruby编码原则和习惯用法的代码生成代理","ja":"エレガントなRubyコーディングの原則とイディオムを習得しようとするコード生成エージェントに理想的","ko":"우아한 Ruby 코딩 원칙과 관용구를 숙달하려는 코드 생성 에이전트에 이상적","es":"Ideal para Agentes de Generación de Código que buscan dominar los principios e idioms elegantes de la codificación en Ruby","fr":"Idéal pour les Agents de Génération de Code cherchant à maîtriser les principes et les idiomes élégants de la programmation Ruby","de":"Ideal für Code Generation Agents, die die eleganten Ruby-Codierungsprinzipien und Idiome meistern möchten","pt":"Ideal para Agentes de Geração de Código que buscam dominar os princípios e idiomas elegantes de codificação Ruby","ru":"Идеально подходит для Агентов Генерации Кода, стремящихся освоить изящные принципы и идиомы программирования на Ruby","ar":"مثالي لوكلاء توليد التعليمات البرمجية الذين يسعون لإتقان مبادئ وأساليب برمجة Ruby الأنيقة"},"recommendation":{"en":"Empowers agents to generate concise, readable, and dynamic Ruby code, leveraging the language''s dynamic nature and prioritizing ''Ruby-colored glasses'' over imported patterns, with a focus on principles, idioms, and readability","zh":"使代理能够生成简洁、可读且动态的Ruby代码，利用语言的动态特性，优先考虑''Ruby风格''而非导入的模式，重点关注原则、习惯用法和可读性","ja":"エージェントが簡潔で読みやすく動的なRubyコードを生成することを可能にし、言語の動的特性を活用し、輸入されたパターンよりも''Ruby色の眼鏡''を優先し、原則、イディオム、および可読性に焦点を当てる","ko":"에이전트가 간결하고 가독성이 높으며 동적인 Ruby 코드를 생성할 수 있도록 하여, 언어의 동적 특성을 활용하고 가져온 패턴보다 ''Ruby-colored glasses''를 우선시하며 원칙, 관용구 및 가독성에 중점을 둠","es":"Empodera a los agentes para generar código Ruby conciso, legible y dinámico, aprovechando la naturaleza dinámica del lenguaje y priorizando los ''lentes Ruby'' sobre los patrones importados, con un enfoque en los principios, idioms y la legibilidad","fr":"Permet aux agents de générer du code Ruby concis, lisible et dynamique, en tirant parti de la nature dynamique du langage et en privilégiant les ''lunettes Ruby'' par rapport aux modèles importés, avec un accent sur les principes, les idiomes et la lisibilité","de":"Ermöglicht Agents, prägnanten, lesbaren und dynamischen Ruby-Code zu generieren, indem die dynamische Natur der Sprache genutzt wird und ''Ruby-colored glasses'' gegenüber importierten Mustern priorisiert werden, mit einem Fokus auf Prinzipien, Idiome und Lesbarkeit","pt":"Capacita os agentes a gerar código Ruby conciso, legível e dinâmico, aproveitando a natureza dinâmica da linguagem e priorizando os ''óculos coloridos Ruby'' em vez de padrões importados, com foco em princípios, idiomas e legibilidade","ru":"Позволяет агентам генерировать лаконичный, читаемый и динамичный код на Ruby, используя динамическую природу языка и отдавая приоритет ''Ruby-цветным очкам'' над импортированными шаблонами, с акцентом на принципы, идиомы и читаемость","ar":"يمكّن الوكلاء من إنشاء تعليمات برمجية Ruby موجزة وقابلة للقراءة وديناميكية، مستفيدًا من الطبيعة الديناميكية للغة وبتفضيل ''النظارات الملونة Ruby'' على الأنماط المستوردة، مع التركيز على المبادئ والأساليب والقابلية للقراءة"},"useCases":{"en":["Generating idiomatic Ruby code snippets","Improving existing code readability and conciseness","Developing dynamic Ruby applications with adherence to language principles"],"zh":["生成符合习惯用法的Ruby代码片段","提高现有代码的可读性和简洁性","开发遵循语言原则的动态Ruby应用程序"],"ja":["慣用的なRubyコードスニペットの生成","既存コードの可読性と簡潔性の向上","言語原則に準拠した動的Rubyアプリケーションの開発"],"ko":["관용적인 Ruby 코드 스니펫 생성","기존 코드의 가독성과 간결성 향상","언어 원칙을 준수하는 동적 Ruby 애플리케이션 개발"],"es":["Generar fragmentos de código Ruby idiomáticos","Mejorar la legibilidad y concisión del código existente","Desarrollar aplicaciones Ruby dinámicas con adherencia a los principios del lenguaje"],"fr":["Générer des extraits de code Ruby idiomatiques","Améliorer la lisibilité et la concision du code existant","Développer des applications Ruby dynamiques dans le respect des principes du langage"],"de":["Generieren von idiomatischen Ruby-Code-Snippets","Verbessern der Lesbarkeit und Prägnanz von vorhandenem Code","Entwickeln dynamischer Ruby-Anwendungen unter Einhaltung der Sprachprinzipien"],"pt":["Geração de snippets de código Ruby idiomáticos","Melhorar a legibilidade e concisão do código existente","Desenvolver aplicações Ruby dinâmicas com aderência aos princípios da linguagem"],"ru":["Генерация идиоматических сниппетов кода на Ruby","Улучшение читаемости и лаконичности существующего кода","Разработка динамических приложений на Ruby с соблюдением принципов языка"],"ar":["إنشاء مقاطع تعليمات برمجية Ruby أسلوبية","تحسين قابلية قراءة واختصار التعليمات البرمجية الحالية","تطوير تطبيقات Ruby الديناميكية مع الالتزام بمبادئ اللغة"]},"limitations":{"en":["Requires Ruby-specific knowledge and context","Adherence to Ruby principles and idioms may limit compatibility with code written in other languages"],"zh":["需要Ruby特定的知识和上下文","遵守Ruby原则和习惯用法可能会限制与其他语言编写的代码的兼容性"],"ja":["Ruby固有の知識とコンテキストが必要","Rubyの原則とイディオムへの準拠は、他の言語で書かれたコードとの互換性を制限する可能性がある"],"ko":["Ruby 특정 지식과 컨텍스트가 필요함","Ruby 원칙과 관용구를 준수하면 다른 언어로 작성된 코드와의 호환성이 제한될 수 있음"],"es":["Requiere conocimiento y contexto específico de Ruby","La adherencia a los principios e idioms de Ruby puede limitar la compatibilidad con código escrito en otros lenguajes"],"fr":["Nécessite des connaissances et un contexte spécifiques à Ruby","Le respect des principes et des idiomes Ruby peut limiter la compatibilité avec le code écrit dans d''autres langages"],"de":["Erfordert Ruby-spezifisches Wissen und Kontext","Die Einhaltung von Ruby-Prinzipien und Idiomen kann die Kompatibilität mit in anderen Sprachen geschriebenem Code einschränken"],"pt":["Requer conhecimento e contexto específicos de Ruby","A aderência aos princípios e idiomas do Ruby pode limitar a compatibilidade com código escrito em outras linguagens"],"ru":["Требует специфических знаний и контекста Ruby","Соблюдение принципов и идиом Ruby может ограничить совместимость с кодом, написанным на других языках"],"ar":["يتطلب معرفة وسياقًا محددًا لـ Ruby","قد يحد الالتزام بمبادئ وأساليب Ruby من التوافق مع التعليمات البرمجية المكتوبة بلغات أخرى"]},"version":4},"contentHash":"7524276084f18bb6945d5b2c3f93a128275439542abd1a0cd272569b72a47e7e","qualityScore":60}');
