INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('renzo4web/automaton/programming-ruby', 'programming-ruby', 'renzo4web', 'automaton', 'community', 'programming-ruby renzo4web automaton community The programming-ruby skill generates elegant Ruby code, adhering to principles and idioms for concise, readable, and dynamic code. It benefits Ruby developers seeking to improve their coding style. 本指南介绍了 Ruby 编程的最佳实践，帮助开发者提高代码的可读性和效率 Ruby プログラミングのベストプラクティスを紹介し、開発者のコードの可読性と効率を高めます Ruby 프로그래밍 가이드는 개발자가 효율적인 코드를 작성하도록 도와줍니다 Nuestro experto en Ruby te enseñará a escribir código conciso y legible en Ruby, aprovechando al máximo la naturaleza dinámica del lenguaje Notre expert Ruby vous apprendra à écrire du code concis et lisible en Ruby, en exploitant au maximum la nature dynamique du langage Unser Ruby-Experte wird Ihnen beibringen, kompakten und lesbaren Code in Ruby zu schreiben, indem er die dynamische Natur der Sprache voll ausschöpft Este AI Agent é um especialista em Ruby que adere estritamente aos princípios idiomáticos da linguagem. Ele ensina a escrever código que não apenas funciona, mas que parece Ruby autêntico, priorizando concisão, legibilidade e a natureza dinâmica da linguagem. Этот ИИ Агент — эксперт по Ruby, строго следующий идиоматическим принципам языка. Он учит писать код, который не только работает, но и выглядит как аутентичный Ruby, уделяя приоритетное внимание лаконичности, читаемости и динамической природе языка. هذا الوكيل هو خبير في لغة Ruby يلتزم بدقة بالمبادئ الاصطلاحية للغة. يعلمك كتابة كود لا يعمل فقط، بل يبدو كـ Ruby أصيل، مع giving الأولوية للإيجاز، قابلية القراءة، والطبيعة الديناميكية للغة. how to use programming-ruby what is programming-ruby programming-ruby alternative programming-ruby vs java programming-ruby install programming-ruby setup guide ruby code generation ruby coding best practices dynamic ruby programming Ruby 编程 Ruby 语言 动态语言 可读性 效率 代码优化 Ruby最佳实践 Ruby 开发 Writes code that leverages Ruby''s dynamic nature effectively Prioritizes ''Ruby-colored glasses'' over patterns imported from other languages Generates concise and readable code Favors pragmatism and the ''principle of least astonishment'' Adheres to Ruby principles and idioms Produces code that is idiomatic to the Ruby language programming-ruby is a skill that enables the generation of Ruby code that adheres to the language''s principles and idioms, prioritizing readability and pragmatism.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ollieb89/ugro/python-packaging', 'community', 'ollieb89', 'ugro', 'ollieb89/ugro', 'python-packaging', 0, 0, 60, '2026-03-08T01:57:15.466Z', '2026-03-08T02:09:25.934Z', '58082e4b1e32ba36e8bdac8c2f9c534282b8f426fd3f8ac40f485dce43521ee8', '{"id":"ollieb89/ugro/python-packaging","name":"python-packaging","description":{"en":"python-packaging enables developers to create, manage, and distribute Python packages efficiently. It''s ideal for creating libraries, command-line tools, and setting up project structures.","zh":"本项目提供了创建、结构化和分发Python包的综合指南，涵盖了pyproject.toml和发布到PyPI","ja":"Pythonパッケージの作成、構造化、配布方法についての包括的なガイドを提供し、pyproject.tomlとPyPIへの公開をサポートする","ko":"Python 패키지 생성, 구조화, 배포 방법에 대한 종합 가이드를 제공하며 pyproject.toml 및 PyPI 배포를 지원한다","es":"Python-packaging es una guía completa para crear, estructurar y distribuir paquetes Python","fr":"Python-packaging est un guide complet pour créer, structurer et distribuer des packages Python","de":"Python-packaging ist ein umfassender Leitfaden zur Erstellung, Strukturierung und Verteilung von Python-Paketen","pt":"O python-packaging é uma ferramenta para criar e distribuir pacotes Python. Aprenda a usar pyproject.toml e publicar no PyPI.","ru":"ИИ Агенты: python-packaging - это инструмент для создания и распространения пакетов Python. Узнайте, как использовать pyproject.toml и публиковать в PyPI.","ar":"python-packaging هو أداة لإنشاء وتوزيع حزم بايثون. تعلم كيفية استخدام pyproject.toml ونشرها على PyPI"},"seo":{"title":{"en":"python-packaging: Comprehensive Guide to Creating Python ...","zh":"Python Packaging Setup Guide - AIエージェント开发指南","ja":"Python Packaging ベストプラクティス - AIエージェント開発ガイド","ko":"Python Packaging 시작하기 - AI Tools 개발자 가이드","es":"Guía de configuración de python-packaging para desarrolla...","fr":"Guide de mise en place de python-packaging pour les dével...","de":"Einrichtungsleitfaden für python-packaging-Entwickler","pt":"Guia de Configuração de python-packaging: Criando Pacotes...","ru":"ИИ Агенты: Руководство по Настройке python-packaging для ...","ar":"دليل ضبط python-packaging: إنشاء حزم بايثون"},"description":{"en":"Learn how to create, structure, and distribute Python packages with python-packaging. Get started with pyproject.toml and publish to PyPI today!","zh":"了解如何使用现代包管理工具创建、结构化和分发Python包，包括pyproject.toml和发布到PyPI","ja":"Pythonパッケージの作成、構造化、配布方法を学び、pyproject.tomlとPyPIへの公開をマスターする","ko":"Python 패키지 생성, 구조화, 배포 방법을 알아보고 pyproject.toml 및 PyPI 배포를 위한 최고의 실践을 배운다","es":"Aprende a crear y distribuir paquetes Python con pyproject.toml y publicar en PyPI","fr":"Découvrez comment créer et distribuer des packages Python avec pyproject.toml et publier sur PyPI","de":"Erfahren Sie, wie Sie Python-Pakete mit pyproject.toml erstellen und auf PyPI veröffentlichen","pt":"Aprenda a criar e distribuir pacotes Python com o python-packaging, incluindo pyproject.toml e publicação no PyPI","ru":"Узнайте, как создавать и распространять пакеты Python с помощью python-packaging, включая pyproject.toml и публикацию в PyPI","ar":"تعلم كيفية إنشاء وتوزيع حزم بايثون مع python-packaging، بما في ذلك pyproject.toml ونشرها على PyPI"},"definition":{"en":"python-packaging is a comprehensive guide to creating, structuring, and distributing Python packages using modern packaging tools and pyproject.toml.","zh":"Python Packaging是指使用现代包管理工具创建、结构化和分发Python包的过程","ja":"Pythonパッケージングは、Pythonパッケージを作成、構造化、配布するためのプロセスである","ko":"Python 패키징은 Python 패키지를 생성, 구조화, 배포하는 프로세스를 말한다","es":"Python-packaging es una técnica para crear y distribuir paquetes Python","fr":"Python-packaging est une technique pour créer et distribuer des packages Python","de":"Python-packaging ist eine Technik zur Erstellung und Verteilung von Python-Paketen","pt":"O que é python-packaging? É uma ferramenta para criar e distribuir pacotes Python de forma eficiente","ru":"Что такое python-packaging? Это инструмент для создания и распространения пакетов Python","ar":"ما هو python-packaging؟ هو أداة لإنشاء وتوزيع حزم بايثون بفعالية"},"features":{"en":["Creates Python libraries for distribution","Builds command-line tools with entry points","Publishes packages to PyPI or private repositories","Sets up Python project structure","Creates installable packages with dependencies","Builds wheels and source distributions"],"zh":["使用pyproject.toml创建和管理Python包","发布包到PyPI或私有仓库","创建命令行工具和入口点","设置Python项目结构和依赖关系","构建轮子和源码分发包","版本管理和发布"],"ja":["pyproject.tomlを使用してPythonパッケージを作成および管理する","PyPIまたはプライベートリポジトリにパッケージを公開する","コマンドラインツールとエントリーポイントを作成する","Pythonプロジェクト構造と依存関係を設定する","ホイールとソースコード配布パッケージを作成する","バージョン管理とリリースを行う"],"ko":["pyproject.toml을 사용하여 Python 패키지를 생성 및 관리한다","PyPI 또는 프라이빗 저장소에 패키지를 배포한다","명령줄 도구와入口 포인트를 생성한다","Python 프로젝트 구조와 의존성을 설정한다","휠과 소스 코드 배포 패키지를 생성한다","버전 관리와 릴리즈를 진행한다"],"es":["Creación de paquetes Python con pyproject.toml","Publicación de paquetes en PyPI","Creación de herramientas de línea de comandos con puntos de entrada","Configuración de la estructura de proyectos Python","Creación de paquetes instalables con dependencias","Creación de distribuciones de fuente y ruedas"],"fr":["Création de packages Python avec pyproject.toml","Publication de packages sur PyPI","Création d''outils de ligne de commande avec des points d''entrée","Configuration de la structure de projets Python","Création de packages installables avec des dépendances","Création de distributions de source et de roues"],"de":["Erstellung von Python-Paketen mit pyproject.toml","Veröffentlichung von Paketen auf PyPI","Erstellung von Befehlszeilen-Tools mit Einstiegspunkten","Konfiguration der Projektstruktur von Python","Erstellung von installierbaren Paketen mit Abhängigkeiten","Erstellung von Quell- und Radverteilungen"],"pt":["Criação de pacotes Python com pyproject.toml","Publicação de pacotes no PyPI","Criação de pacotes com dependências","Criação de wheels e distribuições de código-fonte","Versionamento e lançamento de pacotes"],"ru":["Создание пакетов Python с помощью pyproject.toml","Публикация пакетов в PyPI","Создание пакетов с зависимостями","Создание колес и распространение исходного кода","Версионирование и выпуск пакетов"],"ar":["إنشاء حزم بايثون مع pyproject.toml","نشر الحزم على PyPI","إنشاء حزم مع الاعتماديات","إنشاء عجلات وتوزيع الشفرة المصدرية","إصدار وتوزيع الحزم"]},"keywords":{"en":["how to use python-packaging","python-packaging tutorial","python-packaging vs pip","python-packaging install guide","creating python packages with pyproject.toml","publishing to PyPI with python-packaging","python-packaging setup","python-packaging best practices","python packaging tools"],"zh":["Python Packaging","pyproject.toml","PyPI","Python包管理","AIエージェント开发","Python开发工具","包管理最佳实践","Python项目结构","依赖关系管理"],"ja":["Pythonパッケージング","pyproject.toml","PyPI","Pythonパッケージ管理","AIエージェント開発","Python開発ツール","パッケージ管理ベストプラクティス","Pythonプロジェクト構造","依存関係管理"],"ko":["Python 패키징","pyproject.toml","PyPI","Python 패키지 관리","AI Tools 개발","Python 개발 도구","패키지 관리 최고의 실践","Python 프로젝트 구조","의존성 관리"],"es":["python packaging","pyproject.toml","PyPI","creación de paquetes python","publicación de paquetes python","herramientas de línea de comandos python","estructura de proyectos python","paquetes instalables python","distribuciones de fuente y ruedas python"],"fr":["python packaging","pyproject.toml","PyPI","création de packages python","publication de packages python","outils de ligne de commande python","structure de projets python","packages installables python","distributions de source et de roues python"],"de":["python packaging","pyproject.toml","PyPI","erstellung von python-paketen","veröffentlichung von python-paketen","befehlszeilen-tools python","projektstruktur von python","installierbare python-pakete","quell- und radverteilungen python"],"pt":["python-packaging","criar pacotes python","pyproject.toml","publicar no pypi","pacotes python com dependências","wheels e distribuições de código-fonte","versionamento de pacotes","lançamento de pacotes"],"ru":["python-packaging","создание пакетов python","pyproject.toml","публикация в pypi","пакеты python с зависимостями","колеса и распространение исходного кода","версионирование пакетов","выпуск пакетов"],"ar":["python-packaging","إنشاء حزم بايثون","pyproject.toml","نشر على pypi","حزم بايثون مع الاعتماديات","عجلات وتوزيع الشفرة المصدرية","إصدار الحزم","توزيع الحزم"]}},"owner":"ollieb89","repo":"ugro","repoPath":"ollieb89/ugro","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.466Z","topics":[],"category":"community","skillMd":{"name":"python-packaging","description":"Create distributable Python packages with proper project structure, setup.py/pyproject.toml, and publishing to PyPI. Use when packaging Python libraries, creating CLI tools, or distributing Python code.","bodyPreview":"# Python Packaging\n\nComprehensive guide to creating, structuring, and distributing Python packages using modern packaging tools, pyproject.toml, and publishing to PyPI.\n\n## When to Use This Skill\n\n- Creating Python libraries for distribution\n- Building command-line tools with entry points\n- Publishing packages to PyPI or private repositories\n- Setting up Python project structure\n- Creating installable packages with dependencies\n- Building wheels and source distributions\n- Versioning and releasin","body":"# Python Packaging\n\nComprehensive guide to creating, structuring, and distributing Python packages using modern packaging tools, pyproject.toml, and publishing to PyPI.\n\n## When to Use This Skill\n\n- Creating Python libraries for distribution\n- Building command-line tools with entry points\n- Publishing packages to PyPI or private repositories\n- Setting up Python project structure\n- Creating installable packages with dependencies\n- Building wheels and source distributions\n- Versioning and releasing Python packages\n- Creating namespace packages\n- Implementing package metadata and classifiers\n\n## Core Concepts\n\n### 1. Package Structure\n- **Source layout**: `src/package_name/` (recommended)\n- **Flat layout**: `package_name/` (simpler but less flexible)\n- **Package metadata**: pyproject.toml, setup.py, or setup.cfg\n- **Distribution formats**: wheel (.whl) and source distribution (.tar.gz)\n\n### 2. Modern Packaging Standards\n- **PEP 517/518**: Build system requirements\n- **PEP 621**: Metadata in pyproject.toml\n- **PEP 660**: Editable installs\n- **pyproject.toml**: Single source of configuration\n\n### 3. Build Backends\n- **setuptools**: Traditional, widely used\n- **hatchling**: Modern, opinionated\n- **flit**: Lightweight, for pure Python\n- **poetry**: Dependency management + packaging\n\n### 4. Distribution\n- **PyPI**: Python Package Index (public)\n- **TestPyPI**: Testing before production\n- **Private repositories**: JFrog, AWS CodeArtifact, etc.\n\n## Quick Start\n\n### Minimal Package Structure\n\n```\nmy-package/\n├── pyproject.toml\n├── README.md\n├── LICENSE\n├── src/\n│   └── my_package/\n│       ├── __init__.py\n│       └── module.py\n└── tests/\n    └── test_module.py\n```\n\n### Minimal pyproject.toml\n\n```toml\n[build-system]\nrequires = [\"setuptools>=61.0\"]\nbuild-backend = \"setuptools.build_meta\"\n\n[project]\nname = \"my-package\"\nversion = \"0.1.0\"\ndescription = \"A short description\"\nauthors = [{name = \"Your Name\", email = \"you@example.com\"}]\nreadme = \"README.md\"\nrequires-python = \">=3.8\"\ndependencies = [\n    \"requests>=2.28.0\",\n]\n\n[project.optional-dependencies]\ndev = [\n    \"pytest>=7.0\",\n    \"black>=22.0\",\n]\n```\n\n## Package Structure Patterns\n\n### Pattern 1: Source Layout (Recommended)\n\n```\nmy-package/\n├── pyproject.toml\n├── README.md\n├── LICENSE\n├── .gitignore\n├── src/\n│   └── my_package/\n│       ├── __init__.py\n│       ├── core.py\n│       ├── utils.py\n│       └── py.typed          # For type hints\n├── tests/\n│   ├── __init__.py\n│   ├── test_core.py\n│   └── test_utils.py\n└── docs/\n    └── index.md\n```\n\n**Advantages:**\n- Prevents accidentally importing from source\n- Cleaner test imports\n- Better isolation\n\n**pyproject.toml for source layout:**\n```toml\n[tool.setuptools.packages.find]\nwhere = [\"src\"]\n```\n\n### Pattern 2: Flat Layout\n\n```\nmy-package/\n├── pyproject.toml\n├── README.md\n├── my_package/\n│   ├── __init__.py\n│   └── module.py\n└── tests/\n    └── test_module.py\n```\n\n**Simpler but:**\n- Can import package without installing\n- Less professional for libraries\n\n### Pattern 3: Multi-Package Project\n\n```\nproject/\n├── pyproject.toml\n├── packages/\n│   ├── package-a/\n│   │   └── src/\n│   │       └── package_a/\n│   └── package-b/\n│       └── src/\n│           └── package_b/\n└── tests/\n```\n\n## Complete pyproject.toml Examples\n\n### Pattern 4: Full-Featured pyproject.toml\n\n```toml\n[build-system]\nrequires = [\"setuptools>=61.0\", \"wheel\"]\nbuild-backend = \"setuptools.build_meta\"\n\n[project]\nname = \"my-awesome-package\"\nversion = \"1.0.0\"\ndescription = \"An awesome Python package\"\nreadme = \"README.md\"\nrequires-python = \">=3.8\"\nlicense = {text = \"MIT\"}\nauthors = [\n    {name = \"Your Name\", email = \"you@example.com\"},\n]\nmaintainers = [\n    {name = \"Maintainer Name\", email = \"maintainer@example.com\"},\n]\nkeywords = [\"example\", \"package\", \"awesome\"]\nclassifiers = [\n    \"Development Status :: 4 - Beta\",\n    \"Intended Audience :: Developers\",\n    \"License :: OSI Approved :: MIT License\",\n    \"Programming Language :: Python :: 3\",\n    \"Programming Language :: Python :: 3.8\",\n    \"Programming Language :: Python :: 3.9\",\n    \"Programming Language :: Python :: 3.10\",\n    \"Programming Language :: Python :: 3.11\",\n    \"Programming Language :: Python :: 3.12\",\n]\n\ndependencies = [\n    \"requests>=2.28.0,<3.0.0\",\n    \"click>=8.0.0\",\n    \"pydantic>=2.0.0\",\n]\n\n[project.optional-dependencies]\ndev = [\n    \"pytest>=7.0.0\",\n    \"pytest-cov>=4.0.0\",\n    \"black>=23.0.0\",\n    \"ruff>=0.1.0\",\n    \"mypy>=1.0.0\",\n]\ndocs = [\n    \"sphinx>=5.0.0\",\n    \"sphinx-rtd-theme>=1.0.0\",\n]\nall = [\n    \"my-awesome-package[dev,docs]\",\n]\n\n[project.urls]\nHomepage = \"https://github.com/username/my-awesome-package\"\nDocumentation = \"https://my-awesome-package.readthedocs.io\"\nRepository = \"https://github.com/username/my-awesome-package\"\n\"Bug Tracker\" = \"https://github.com/username/my-awesome-package/issues\"\nChangelog = \"https://github.com/username/my-awesome-package/blob/main/CHANGELOG.md\"\n\n[project.scripts]\nmy-cli = \"my_package.cli:main\"\nawesome-tool = \"my_package.tools:run\"\n\n[project.entry-points.\"my_package.plugins\"]\nplugin1 = \"my_package.plugins:plugin1\"\n\n[tool.setuptools]\npackage-dir = {\"\" = \"src\"}\nzip-safe = false\n\n[tool.setuptools.packages.find]\nwhere = [\"src\"]\ninclude = [\"my_package*\"]\nexclude = [\"tests*\"]\n\n[tool.setuptools.package-data]\nmy_package = [\"py.typed\", \"*.pyi\", \"data/*.json\"]\n\n# Black configuration\n[tool.black]\nline-length = 100\ntarget-version = [\"py38\", \"py39\", \"py310\", \"py311\"]\ninclude = ''\\.pyi?$''\n\n# Ruff configuration\n[tool.ruff]\nline-length = 100\ntarget-version = \"py38\"\n\n[tool.ruff.lint]\nselect = [\"E\", \"F\", \"I\", \"N\", \"W\", \"UP\"]\n\n# MyPy configuration\n[tool.mypy]\npython_version = \"3.8\"\nwarn_return_any = true\nwarn_unused_configs = true\ndisallow_untyped_defs = true\n\n# Pytest configuration\n[tool.pytest.ini_options]\ntestpaths = [\"tests\"]\npython_files = [\"test_*.py\"]\naddopts = \"-v --cov=my_package --cov-report=term-missing\"\n\n# Coverage configuration\n[tool.coverage.run]\nsource = [\"src\"]\nomit = [\"*/tests/*\"]\n\n[tool.coverage.report]\nexclude_lines = [\n    \"pragma: no cover\",\n    \"def __repr__\",\n    \"raise AssertionError\",\n    \"raise NotImplementedError\",\n]\n```\n\n### Pattern 5: Dynamic Versioning\n\n```toml\n[build-system]\nrequires = [\"setuptools>=61.0\", \"setuptools-scm>=8.0\"]\nbuild-backend = \"setuptools.build_meta\"\n\n[project]\nname = \"my-package\"\ndynamic = [\"version\"]\ndescription = \"Package with dynamic version\"\n\n[tool.setuptools.dynamic]\nversion = {attr = \"my_package.__version__\"}\n\n# Or use setuptools-scm for git-based versioning\n[tool.setuptools_scm]\nwrite_to = \"src/my_package/_version.py\"\n```\n\n**In __init__.py:**\n```python\n# src/my_package/__init__.py\n__version__ = \"1.0.0\"\n\n# Or with setuptools-scm\nfrom importlib.metadata import version\n__version__ = version(\"my-package\")\n```\n\n## Command-Line Interface (CLI) Patterns\n\n### Pattern 6: CLI with Click\n\n```python\n# src/my_package/cli.py\nimport click\n\n@click.group()\n@click.version_option()\ndef cli():\n    \"\"\"My awesome CLI tool.\"\"\"\n    pass\n\n@cli.command()\n@click.argument(\"name\")\n@click.option(\"--greeting\", default=\"Hello\", help=\"Greeting to use\")\ndef greet(name: str, greeting: str):\n    \"\"\"Greet someone.\"\"\"\n    click.echo(f\"{greeting}, {name}!\")\n\n@cli.command()\n@click.option(\"--count\", default=1, help=\"Number of times to repeat\")\ndef repeat(count: int):\n    \"\"\"Repeat a message.\"\"\"\n    for i in range(count):\n        click.echo(f\"Message {i + 1}\")\n\ndef main():\n    \"\"\"Entry point for CLI.\"\"\"\n    cli()\n\nif __name__ == \"__main__\":\n    main()\n```\n\n**Register in pyproject.toml:**\n```toml\n[project.scripts]\nmy-tool = \"my_package.cli:main\"\n```\n\n**Usage:**\n```bash\npip install -e .\nmy-tool greet World\nmy-tool greet Alice --greeting=\"Hi\"\nmy-tool repeat --count=3\n```\n\n### Pattern 7: CLI with argparse\n\n```python\n# src/my_package/cli.py\nimport argparse\nimport sys\n\ndef main():\n    \"\"\"Main CLI entry point.\"\"\"\n    parser = argparse.ArgumentParser(\n        description=\"My awesome tool\",\n        prog=\"my-tool\"\n    )\n\n    parser.add_argument(\n        \"--version\",\n        action=\"version\",\n        version=\"%(prog)s 1.0.0\"\n    )\n\n    subparsers = parser.add_subparsers(dest=\"command\", help=\"Commands\")\n\n    # Add subcommand\n    process_parser = subparsers.add_parser(\"process\", help=\"Process data\")\n    process_parser.add_argument(\"input_file\", help=\"Input file path\")\n    process_parser.add_argument(\n        \"--output\", \"-o\",\n        default=\"output.txt\",\n        help=\"Output file path\"\n    )\n\n    args = parser.parse_args()\n\n    if args.command == \"process\":\n        process_data(args.input_file, args.output)\n    else:\n        parser.print_help()\n        sys.exit(1)\n\ndef process_data(input_file: str, output_file: str):\n    \"\"\"Process data from input to output.\"\"\"\n    print(f\"Processing {input_file} -> {output_file}\")\n\nif __name__ == \"__main__\":\n    main()\n```\n\n## Building and Publishing\n\n### Pattern 8: Build Package Locally\n\n```bash\n# Install build tools\npip install build twine\n\n# Build distribution\npython -m build\n\n# This creates:\n# dist/\n#   my-package-1.0.0.tar.gz (source distribution)\n#   my_package-1.0.0-py3-none-any.whl (wheel)\n\n# Check the distribution\ntwine check dist/*\n```\n\n### Pattern 9: Publishing to PyPI\n\n```bash\n# Install publishing tools\npip install twine\n\n# Test on TestPyPI first\ntwine upload --repository testpypi dist/*\n\n# Install from TestPyPI to test\npip install --index-url https://test.pypi.org/simple/ my-package\n\n# If all good, publish to PyPI\ntwine upload dist/*\n```\n\n**Using API tokens (recommended):**\n```bash\n# Create ~/.pypirc\n[distutils]\nindex-servers =\n    pypi\n    testpypi\n\n[pypi]\nusername = __token__\npassword = pypi-...your-token...\n\n[testpypi]\nusername = __token__\npassword = pypi-...your-test-token...\n```\n\n### Pattern 10: Automated Publishing with GitHub Actions\n\n```yaml\n# .github/workflows/publish.yml\nname: Publish to PyPI\n\non:\n  release:\n    types: [created]\n\njobs:\n  publish:\n    runs-on: ubuntu-latest\n\n    steps:\n      - uses: actions/checkout@v3\n\n      - name: Set up Python\n        uses: actions/setup-python@v4\n        with:\n          python-version: \"3.11\"\n\n      - name: Install dependencies\n        run: |\n          pip install build twine\n\n      - name: Build package\n        run: python -m build\n\n      - name: Check package\n        run: twine check dist/*\n\n      - name: Publish to PyPI\n        env:\n          TWINE_USERNAME: __token__\n          TWINE_PASSWORD: ${{ secrets.PYPI_API_TOKEN }}\n        run: twine upload dist/*\n```\n\n## Advanced Patterns\n\n### Pattern 11: Including Data Files\n\n```toml\n[tool.setuptools.package-data]\nmy_package = [\n    \"data/*.json\",\n    \"templates/*.html\",\n    \"static/css/*.css\",\n    \"py.typed\",\n]\n```\n\n**Accessing data files:**\n```python\n# src/my_package/loader.py\nfrom importlib.resources import files\nimport json\n\ndef load_config():\n    \"\"\"Load configuration from package data.\"\"\"\n    config_file = files(\"my_package\").joinpath(\"data/config.json\")\n    with config_file.open() as f:\n        return json.load(f)\n\n# Python 3.9+\nfrom importlib.resources import files\n\ndata = files(\"my_package\").joinpath(\"data/file.txt\").read_text()\n```\n\n### Pattern 12: Namespace Packages\n\n**For large projects split across multiple repositories:**\n\n```\n# Package 1: company-core\ncompany/\n└── core/\n    ├── __init__.py\n    └── models.py\n\n# Package 2: company-api\ncompany/\n└── api/\n    ├── __init__.py\n    └── routes.py\n```\n\n**Do NOT include __init__.py in the namespace directory (company/):**\n\n```toml\n# company-core/pyproject.toml\n[project]\nname = \"company-core\"\n\n[tool.setuptools.packages.find]\nwhere = [\".\"]\ninclude = [\"company.core*\"]\n\n# company-api/pyproject.toml\n[project]\nname = \"company-api\"\n\n[tool.setuptools.packages.find]\nwhere = [\".\"]\ninclude = [\"company.api*\"]\n```\n\n**Usage:**\n```python\n# Both packages can be imported under same namespace\nfrom company.core import models\nfrom company.api import routes\n```\n\n### Pattern 13: C Extensions\n\n```toml\n[build-system]\nrequires = [\"setuptools>=61.0\", \"wheel\", \"Cython>=0.29\"]\nbuild-backend = \"setuptools.build_meta\"\n\n[tool.setuptools]\next-modules = [\n    {name = \"my_package.fast_module\", sources = [\"src/fast_module.c\"]},\n]\n```\n\n**Or with setup.py:**\n```python\n# setup.py\nfrom setuptools import setup, Extension\n\nsetup(\n    ext_modules=[\n        Extension(\n            \"my_package.fast_module\",\n            sources=[\"src/fast_module.c\"],\n            include_dirs=[\"src/include\"],\n        )\n    ]\n)\n```\n\n## Version Management\n\n### Pattern 14: Semantic Versioning\n\n```python\n# src/my_package/__init__.py\n__version__ = \"1.2.3\"\n\n# Semantic versioning: MAJOR.MINOR.PATCH\n# MAJOR: Breaking changes\n# MINOR: New features (backward compatible)\n# PATCH: Bug fixes\n```\n\n**Version constraints in dependencies:**\n```toml\ndependencies = [\n    \"requests>=2.28.0,<3.0.0\",  # Compatible range\n    \"click~=8.1.0\",              # Compatible release (~= 8.1.0 means >=8.1.0,<8.2.0)\n    \"pydantic>=2.0\",             # Minimum version\n    \"numpy==1.24.3\",             # Exact version (avoid if possible)\n]\n```\n\n### Pattern 15: Git-Based Versioning\n\n```toml\n[build-system]\nrequires = [\"setuptools>=61.0\", \"setuptools-scm>=8.0\"]\nbuild-backend = \"setuptools.build_meta\"\n\n[project]\nname = \"my-package\"\ndynamic = [\"version\"]\n\n[tool.setuptools_scm]\nwrite_to = \"src/my_package/_version.py\"\nversion_scheme = \"post-release\"\nlocal_scheme = \"dirty-tag\"\n```\n\n**Creates versions like:**\n- `1.0.0` (from git tag)\n- `1.0.1.dev3+g1234567` (3 commits after tag)\n\n## Testing Installation\n\n### Pattern 16: Editable Install\n\n```bash\n# Install in development mode\npip install -e .\n\n# With optional dependencies\npip install -e \".[dev]\"\npip install -e \".[dev,docs]\"\n\n# Now changes to source code are immediately reflected\n```\n\n### Pattern 17: Testing in Isolated Environment\n\n```bash\n# Create virtual environment\npython -m venv test-env\nsource test-env/bin/activate  # Linux/Mac\n# test-env\\Scripts\\activate  # Windows\n\n# Install package\npip install dist/my_package-1.0.0-py3-none-any.whl\n\n# Test it works\npython -c \"import my_package; print(my_package.__version__)\"\n\n# Test CLI\nmy-tool --help\n\n# Cleanup\ndeactivate\nrm -rf test-env\n```\n\n## Documentation\n\n### Pattern 18: README.md Template\n\n```markdown\n# My Package\n\n[![PyPI version](https://badge.fury.io/py/my-package.svg)](https://pypi.org/project/my-package/)\n[![Python versions](https://img.shields.io/pypi/pyversions/my-package.svg)](https://pypi.org/project/my-package/)\n[![Tests](https://github.com/username/my-package/workflows/Tests/badge.svg)](https://github.com/username/my-package/actions)\n\nBrief description of your package.\n\n## Installation\n\n```bash\npip install my-package\n```\n\n## Quick Start\n\n```python\nfrom my_package import something\n\nresult = something.do_stuff()\n```\n\n## Features\n\n- Feature 1\n- Feature 2\n- Feature 3\n\n## Documentation\n\nFull documentation: https://my-package.readthedocs.io\n\n## Development\n\n```bash\ngit clone https://github.com/username/my-package.git\ncd my-package\npip install -e \".[dev]\"\npytest\n```\n\n## License\n\nMIT\n```\n\n## Common Patterns\n\n### Pattern 19: Multi-Architecture Wheels\n\n```yaml\n# .github/workflows/wheels.yml\nname: Build wheels\n\non: [push, pull_request]\n\njobs:\n  build_wheels:\n    name: Build wheels on ${{ matrix.os }}\n    runs-on: ${{ matrix.os }}\n    strategy:\n      matrix:\n        os: [ubuntu-latest, windows-latest, macos-latest]\n\n    steps:\n      - uses: actions/checkout@v3\n\n      - name: Build wheels\n        uses: pypa/cibuildwheel@v2.16.2\n\n      - uses: actions/upload-artifact@v3\n        with:\n          path: ./wheelhouse/*.whl\n```\n\n### Pattern 20: Private Package Index\n\n```bash\n# Install from private index\npip install my-package --index-url https://private.pypi.org/simple/\n\n# Or add to pip.conf\n[global]\nindex-url = https://private.pypi.org/simple/\nextra-index-url = https://pypi.org/simple/\n\n# Upload to private index\ntwine upload --repository-url https://private.pypi.org/ dist/*\n```\n\n## File Templates\n\n### .gitignore for Python Packages\n\n```gitignore\n# Build artifacts\nbuild/\ndist/\n*.egg-info/\n*.egg\n.eggs/\n\n# Python\n__pycache__/\n*.py[cod]\n*$py.class\n*.so\n\n# Virtual environments\nvenv/\nenv/\nENV/\n\n# IDE\n.vscode/\n.idea/\n*.swp\n\n# Testing\n.pytest_cache/\n.coverage\nhtmlcov/\n\n# Distribution\n*.whl\n*.tar.gz\n```\n\n### MANIFEST.in\n\n```\n# MANIFEST.in\ninclude README.md\ninclude LICENSE\ninclude pyproject.toml\n\nrecursive-include src/my_package/data *.json\nrecursive-include src/my_package/templates *.html\nrecursive-exclude * __pycache__\nrecursive-exclude * *.py[co]\n```\n\n## Checklist for Publishing\n\n- [ ] Code is tested (pytest passing)\n- [ ] Documentation is complete (README, docstrings)\n- [ ] Version number updated\n- [ ] CHANGELOG.md updated\n- [ ] License file included\n- [ ] pyproject.toml is complete\n- [ ] Package builds without errors\n- [ ] Installation tested in clean environment\n- [ ] CLI tools work (if applicable)\n- [ ] PyPI metadata is correct (classifiers, keywords)\n- [ ] GitHub repository linked\n- [ ] Tested on TestPyPI first\n- [ ] Git tag created for release\n\n## Resources\n\n- **Python Packaging Guide**: https://packaging.python.org/\n- **PyPI**: https://pypi.org/\n- **TestPyPI**: https://test.pypi.org/\n- **setuptools documentation**: https://setuptools.pypa.io/\n- **build**: https://pypa-build.readthedocs.io/\n- **twine**: https://twine.readthedocs.io/\n\n## Best Practices Summary\n\n1. **Use src/ layout** for cleaner package structure\n2. **Use pyproject.toml** for modern packaging\n3. **Pin build dependencies** in build-system.requires\n4. **Version appropriately** with semantic versioning\n5. **Include all metadata** (classifiers, URLs, etc.)\n6. **Test installation** in clean environments\n7. **Use TestPyPI** before publishing to PyPI\n8. **Document thoroughly** with README and docstrings\n9. **Include LICENSE** file\n10. **Automate publishing** with CI/CD\n"},"lastSynced":"2026-03-08T02:09:25.934Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing efficient Python package creation and distribution.","zh":"非常适合需要高效创建和分发 Python 包的开发智能体。","ja":"効率的なPythonパッケージの作成と配布を必要とする開発エージェントに最適です。","ko":"효율적인 Python 패키지 생성 및 배포가 필요한 개발 에이전트에 완벽합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan una creación y distribución eficiente de paquetes Python.","fr":"Parfait pour les Agents de Développement ayant besoin d''une création et d''une distribution efficaces de paquets Python.","de":"Perfekt für Entwicklungs-Agents, die eine effiziente Erstellung und Verteilung von Python-Paketen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de criação e distribuição eficientes de pacotes Python.","ru":"Идеально для агентов разработки, которым необходима эффективная создание и распространение пакетов Python.","ar":"مثالي للوكلاء النموزجيين الذين يحتاجون إلى إنشاء وتوزيع كفء لحزم بايثون."},"recommendation":{"en":"Empowers agents to create, manage, and distribute Python packages efficiently using modern packaging tools like pyproject.toml, and publish to PyPI, enabling the creation of libraries, command-line tools, and setting up project structures with dependencies.","zh":"使智能体能够使用 pyproject.toml 等现代打包工具高效地创建、管理和分发 Python 包，并发布到 PyPI，从而支持创建库、命令行工具以及设置具有依赖关系的项目结构。","ja":"pyproject.tomlなどの最新のパッケージングツールを使用してPythonパッケージを効率的に作成、管理、配布し、PyPIに公開することを可能にし、ライブラリやコマンドラインツールの作成、依存関係を含むプロジェクト構造の設定を可能にします。","ko":"pyproject.toml과 같은 현대적인 패키징 도구를 사용하여 Python 패키지를 효율적으로 생성, 관리 및 배포하고 PyPI에 게시할 수 있도록 하여 라이브러리 및 명령줄 도구 생성, 종속성을 포함한 프로젝트 구조 설정을 가능하게 합니다.","es":"Permite a los agentes crear, gestionar y distribuir paquetes Python de manera eficiente utilizando herramientas modernas de empaquetado como pyproject.toml, y publicar en PyPI, lo que permite la creación de bibliotecas, herramientas de línea de comandos y la configuración de estructuras de proyecto con dependencias.","fr":"Permet aux agents de créer, gérer et distribuer des paquets Python efficacement en utilisant des outils d''empaquetage modernes comme pyproject.toml, et de publier sur PyPI, permettant ainsi la création de bibliothèques, d''outils en ligne de commande et la mise en place de structures de projet avec des dépendances.","de":"Ermöglicht es Agents, Python-Pakete effizient mit modernen Packaging-Tools wie pyproject.toml zu erstellen, zu verwalten und zu verteilen und auf PyPI zu veröffentlichen, was die Erstellung von Bibliotheken, Command-Line-Tools und das Einrichten von Projektstrukturen mit Abhängigkeiten ermöglicht.","pt":"Habilita os agentes a criar, gerenciar e distribuir pacotes Python de forma eficiente usando ferramentas de embalagem modernas como pyproject.toml, e publicar no PyPI, permitindo a criação de bibliotecas, ferramentas de linha de comando e configuração de estruturas de projeto com dependências.","ru":"Наделяет агентов возможностью создавать, управлять и распространять пакеты Python эффективно с помощью современных инструментов упаковки, таких как pyproject.toml, и публиковать в PyPI, что позволяет создавать библиотеки, инструменты командной строки и настраивать структуры проектов с зависимостями.","ar":"يمكن للوكلاء من إنشاء وإدارة وتوزيع حزم بايثون بفعالية باستخدام أدوات التغليف الحديثة مثل pyproject.toml، ونشرها على PyPI، مما يتيح إنشاء المكتبات وأدوات سطر الأوامر وضبط هياكل المشروع مع الاعتماديات."},"useCases":{"en":["Creating and publishing Python libraries to PyPI","Building and distributing command-line tools with entry points","Setting up and managing Python project structures with pyproject.toml"],"zh":["创建 Python 库并发布到 PyPI","使用入口点构建和分发命令行工具","使用 pyproject.toml 设置和管理 Python 项目结构"],"ja":["PyPIへのPythonライブラリの作成と公開","エントリーポイントを使用したコマンドラインツールの構築と配布","pyproject.tomlを使用したPythonプロジェクト構造の設定と管理"],"ko":["Python 라이브러리를 생성하여 PyPI에 게시","엔트리 포인트를 사용한 명령줄 도구 구축 및 배포","pyproject.toml을 사용한 Python 프로젝트 구조 설정 및 관리"],"es":["Crear y publicar bibliotecas Python en PyPI","Construir y distribuir herramientas de línea de comandos con puntos de entrada","Configurar y gestionar estructuras de proyectos Python con pyproject.toml"],"fr":["Créer et publier des bibliothèques Python sur PyPI","Construire et distribuer des outils en ligne de commande avec des points d''entrée","Configurer et gérer des structures de projet Python avec pyproject.toml"],"de":["Erstellen und Veröffentlichen von Python-Bibliotheken auf PyPI","Erstellen und Verteilen von Command-Line-Tools mit Entry Points","Einrichten und Verwalten von Python-Projektstrukturen mit pyproject.toml"],"pt":["Criar e publicar bibliotecas Python no PyPI","Construir e distribuir ferramentas de linha de comando com pontos de entrada","Configurar e gerenciar estruturas de projeto Python com pyproject.toml"],"ru":["Создание и публикация библиотек Python в PyPI","Создание и распространение инструментов командной строки с точками входа","Настройка и управление структурами проектов Python с pyproject.toml"],"ar":["إنشاء ونشر مكتبات بايثون على PyPI","بناء وتوزيع أدوات سطر الأوامر مع نقاط الدخول","تكوين وإدارة هياكل مشروع بايثون مع pyproject.toml"]},"limitations":{"en":["Requires Python environment","PyPI or private repository access needed","Python 3.x compatible only"],"zh":["需要 Python 环境","需要访问 PyPI 或私有仓库","仅与 Python 3.x 兼容"],"ja":["Python環境が必要","PyPIまたはプライベートリポジトリへのアクセスが必要","Python 3.x とのみ互換性あり"],"ko":["Python 환경 필요","PyPI 또는 개인 저장소 접근 권한 필요","Python 3.x 와만 호환됨"],"es":["Requiere un entorno Python","Se necesita acceso a PyPI o a un repositorio privado","Compatible solo con Python 3.x"],"fr":["Nécessite un environnement Python","Accès à PyPI ou à un dépôt privé requis","Compatible uniquement avec Python 3.x"],"de":["Erfordert eine Python-Umgebung","Zugriff auf PyPI oder ein privates Repository erforderlich","Nur mit Python 3.x kompatibel"],"pt":["Requer ambiente Python","Acesso ao PyPI ou repositório privado necessário","Somente compatível com Python 3.x"],"ru":["Требуется среда Python","Необходим доступ к PyPI или приватному репозиторию","Только совместимо с Python 3.x"],"ar":["يتطلب بيئة بايثون","مطلوب الوصول إلى PyPI أو المستودع الخاص","متوافق فقط مع بايثون 3.x"]},"version":4},"contentHash":"58082e4b1e32ba36e8bdac8c2f9c534282b8f426fd3f8ac40f485dce43521ee8","qualityScore":60}');
