INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ollieb89/ugro/python-packaging', 'python-packaging', 'ollieb89', 'ugro', 'community', 'python-packaging ollieb89 ugro community python-packaging enables developers to create, manage, and distribute Python packages efficiently. It''s ideal for creating libraries, command-line tools, and setting up project structures. 本项目提供了创建、结构化和分发Python包的综合指南，涵盖了pyproject.toml和发布到PyPI Pythonパッケージの作成、構造化、配布方法についての包括的なガイドを提供し、pyproject.tomlとPyPIへの公開をサポートする Python 패키지 생성, 구조화, 배포 방법에 대한 종합 가이드를 제공하며 pyproject.toml 및 PyPI 배포를 지원한다 Python-packaging es una guía completa para crear, estructurar y distribuir paquetes Python Python-packaging est un guide complet pour créer, structurer et distribuer des packages Python Python-packaging ist ein umfassender Leitfaden zur Erstellung, Strukturierung und Verteilung von Python-Paketen O python-packaging é uma ferramenta para criar e distribuir pacotes Python. Aprenda a usar pyproject.toml e publicar no PyPI. ИИ Агенты: python-packaging - это инструмент для создания и распространения пакетов Python. Узнайте, как использовать pyproject.toml и публиковать в PyPI. python-packaging هو أداة لإنشاء وتوزيع حزم بايثون. تعلم كيفية استخدام pyproject.toml ونشرها على PyPI how to use python-packaging python-packaging tutorial python-packaging vs pip python-packaging install guide creating python packages with pyproject.toml publishing to PyPI with python-packaging python-packaging setup python-packaging best practices python packaging tools Python Packaging pyproject.toml PyPI Python包管理 AIエージェント开发 Python开发工具 包管理最佳实践 Python项目结构 依赖关系管理 Creates Python libraries for distribution Builds command-line tools with entry points Publishes packages to PyPI or private repositories Sets up Python project structure Creates installable packages with dependencies Builds wheels and source distributions python-packaging is a comprehensive guide to creating, structuring, and distributing Python packages using modern packaging tools and pyproject.toml.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('furystack/pi-rat/fill-changelog', 'community', 'furystack', 'pi-rat', 'furystack/pi-rat', 'fill-changelog', 0, 0, 60, '2026-03-08T01:57:15.472Z', '2026-03-08T02:09:38.218Z', '7f934309e6801e3b3cf9c3c28996a6d9aba3684dfbe0863c17b30f0f28415efd', '{"id":"furystack/pi-rat/fill-changelog","name":"fill-changelog","description":{"en":"fill-changelog automates filling changelog entries based on branch changes, benefiting developers who need to manage version updates efficiently.","zh":"fill-changelog 是一个自动化版本日志填充的工具，基于当前分支的更改来生成版本日志。它需要版本号配置，并可以通过 yarn version check 来验证","ja":"fill-changelog は、現在のブランチの変更に基づいて変更ログを自動生成するツールです。バージョン番号の設定と yarn version check による検証が必要です","ko":"fill-changelog는 현재 분기의 변경 사항을 기반으로 버전 로그를 자동 생성하는 도구입니다. 버전 번호 구성과 yarn version check를 통해 검증할 수 있습니다","es":"fill-changelog es una herramienta que automatiza la creación de registros de cambios en función de las modificaciones en la rama actual, utilizando yarn y versiones.","fr":"fill-changelog est un outil qui automatise la création de journaux de modifications en fonction des modifications dans la branche actuelle, en utilisant yarn et versions.","de":"fill-changelog ist ein Tool, das die Erstellung von Änderungsprotokollen automatisiert, basierend auf den Änderungen im aktuellen Branch, mit yarn und Versionen.","pt":"O fill-changelog é uma ferramenta que automatiza a criação de entradas de changelog com base nas alterações no branch atual","ru":"fill-changelog - это инструмент, который автоматизирует создание записей журнала изменений на основе изменений в текущей ветке","ar":"fill-changelog هو أداة لتحويل automatizar إنشاء إدخال سجل التغييرات بناءً على التغييرات في الفرع الحالي"},"seo":{"title":{"en":"fill-changelog: Automated Changelog Setup Guide | AI Agen...","zh":"fill-changelog 自动化版本日志填充指南","ja":"fill-changelog の設定方法: 自動化された変更ログの作成","ko":"fill-changelog 자동 버전 로그 작성 가이드","es":"Configuración de fill-changelog: Guía para automatizar re...","fr":"Mise en place de fill-changelog : Guide pour automatiser ...","de":"Einrichtung von fill-changelog: Anleitung zur Automatisie...","pt":"Guia de Configuração do fill-changelog para Desenvolvedores","ru":"Настройка fill-changelog: Руководство для Разработчиков И...","ar":"دليل إعداد fill-changelog للطورين - أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how fill-changelog simplifies version management. Learn to automate changelog entries and streamline your workflow with this AI agent skill.","zh":"了解如何使用 fill-changelog 自动化版本日志填充，并提高开发效率。查看我们的指南，学习如何配置和使用此功能","ja":"fill-changelog を使用して変更ログを自動化しよう。設定方法とベストプラクティスを学びましょう","ko":"fill-changelog를 사용하여 자동 버전 로그 작성 기능을 구현하고 개발 효율성을 향상시키는 방법에 대해 알아보세요","es":"Aprende a configurar fill-changelog para automatizar registros de cambios en tu proyecto con yarn y versiones","fr":"Découvrez comment configurer fill-changelog pour automatiser les journaux de modifications dans votre projet avec yarn et versions","de":"Erfahren Sie, wie Sie fill-changelog einrichten, um Änderungsprotokolle in Ihrem Projekt mit yarn und Versionen zu automatisieren","pt":"Aprenda a configurar o fill-changelog para automatizar entradas de changelog com base nas alterações no branch atual","ru":"Узнайте, как настроить fill-changelog для автоматизации записей журнала изменений на основе изменений в текущей ветке","ar":"تعلم كيفية إعداد fill-changelog لتوفير automatizar إدخال سجل التغييرات بناءً على التغييرات في الفرع الحالي"},"definition":{"en":"fill-changelog is an AI agent skill that automates the process of filling changelog entries based on changes in the current branch.","zh":"fill-changelog 是一个自动化工具，用于生成版本日志，基于 Git 分支的更改","ja":"fill-changelog は、Git ブランチの変更に基づいて変更ログを自動生成するツールです","ko":"fill-changelog는 Git 분기의 변경 사항을 기반으로 버전 로그를 자동 생성하는 도구입니다","es":"fill-changelog es una herramienta de automatización de registros de cambios que utiliza yarn y versiones para generar jornadas de modificaciones","fr":"fill-changelog est un outil d''automatisation de journaux de modifications qui utilise yarn et versions pour générer des journaux de modifications","de":"fill-changelog ist ein Tool zur Automatisierung von Änderungsprotokollen, das yarn und Versionen verwendet, um Änderungsprotokolle zu generieren","pt":"O fill-changelog é uma ferramenta de automação que cria entradas de changelog","ru":"fill-changelog - это инструмент автоматизации, который создает записи журнала изменений","ar":"fill-changelog هو أداة تلقائية لإنشاء إدخال سجل التغييرات"},"features":{"en":["Validates version configuration using `yarn version check`","Runs `yarn version patch/minor/major` or `yarn bumpVersions` for version adjustments","Automates changelog entry filling based on current branch changes","Requires version bumps to be configured before running the skill","Supports interactive version bumping using `yarn bumpVersions`"],"zh":["自动化版本日志填充","基于当前分支的更改来生成版本日志","需要版本号配置","支持 yarn version check 来验证版本号","可以使用 yarn version patch/minor/major 或 yarn bumpVersions 来调整版本号"],"ja":["変更ログの自動化","現在のブランチの変更に基づいて変更ログを生成","バージョン番号の設定が必要","yarn version check による検証をサポート","yarn version patch/minor/major または yarn bumpVersions を使用してバージョン番号を調整可能"],"ko":["자동 버전 로그 작성","현재 분기의 변경 사항을 기반으로 버전 로그를 생성","버전 번호 구성이 필요","yarn version check를 통해 검증할 수 있음","yarn version patch/minor/major 또는 yarn bumpVersions를 사용하여 버전 번호를 조정할 수 있음"],"es":["Automatización de registros de cambios con yarn","Validación de versiones con yarn version check","Compatibilidad con versiones patch, minor y major","Uso de yarn bumpVersions para ajustar versiones","Soporte para ramas actuales y versiones"],"fr":["Automatisation des journaux de modifications avec yarn","Validation des versions avec yarn version check","Compatibilité avec les versions patch, minor et major","Utilisation de yarn bumpVersions pour ajuster les versions","Prise en charge des branches actuelles et des versions"],"de":["Automatisierung von Änderungsprotokollen mit yarn","Validierung von Versionen mit yarn version check","Unterstützung für Versionen patch, minor und major","Verwendung von yarn bumpVersions zur Anpassung von Versionen","Unterstützung für aktuelle Branches und Versionen"],"pt":["Validação de configuração de versão com `yarn version check`","Suporte a versionamento com `yarn version patch/minor/major`","Integração com `yarn bumpVersions` para ajustes interativos","Automatização de entradas de changelog com base em alterações no branch","Compatibilidade com ambientes de desenvolvimento baseados em CLI"],"ru":["Валидация конфигурации версии с помощью `yarn version check`","Поддержка версионирования с помощью `yarn version patch/minor/major`","Интеграция с `yarn bumpVersions` для интерактивных настроек","Автоматизация записей журнала изменений на основе изменений в ветке","Совместимость с средами разработки на основе CLI"],"ar":["التحقق من صحة إعداد الإصدار باستخدام `yarn version check`","دعم 版本 مع `yarn version patch/minor/major`","التكامل مع `yarn bumpVersions` لتعديلات التفاعل","توفير automatizar إدخال سجل التغييرات بناءً على التغييرات في الفرع","التوافق مع بيئات التطوير القائمة على CLI"]},"keywords":{"en":["how to use fill-changelog","fill-changelog setup guide","automated changelog management","fill-changelog vs manual changelog","fill-changelog install","yarn version check tutorial"],"zh":["fill-changelog","自动化版本日志填充","Git 分支","yarn version check","版本号配置","AI工具","自动化开发工具"],"ja":["fill-changelog","変更ログの自動化","Git ブランチ","yarn version check","バージョン番号の設定","AIエージェント","自動化開発ツール"],"ko":["fill-changelog","자동 버전 로그 작성","Git 분기","yarn version check","버전 번호 구성","AI 에이전트","자동화 개발 도구"],"es":["fill-changelog","automatización de registros de cambios","yarn","versiones","registros de cambios","ramas actuales","versiones patch","versiones minor","versiones major","Herramientas de desarrollo"],"fr":["fill-changelog","automatisation de journaux de modifications","yarn","versions","journaux de modifications","branches actuelles","versions patch","versions minor","versions major","Outils de développement"],"de":["fill-changelog","Automatisierung von Änderungsprotokollen","yarn","Versionen","Änderungsprotokolle","aktuelle Branches","Versionen patch","Versionen minor","Versionen major","Entwicklungstools"],"pt":["fill-changelog","automação de changelog","versionamento","yarn version check","desenvolvimento de software","ferramentas de desenvolvimento","CLI","configuração de versão"],"ru":["fill-changelog","автоматизация журнала изменений","версионирование","yarn version check","разработка программного обеспечения","инструменты разработки","CLI","настройка версии","ИИ Агенты"],"ar":["fill-changelog","توفير automatizar سجل التغييرات","نسخ","yarn version check","تطوير البرمجيات","أدوات التطوير","CLI","إعداد الإصدار","أدوات الذكاء الاصطناعي"]}},"owner":"furystack","repo":"pi-rat","repoPath":"furystack/pi-rat","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.472Z","topics":[],"category":"community","skillMd":{"name":"fill-changelog","description":"Fill changelog entries for the current branch. Use when the user asks to fill changelog, write changelog entries, update changelog, or prepare changelog for a PR.","bodyPreview":"# fill-changelog\n\nAutomate filling changelog entries based on the changes in the current branch.\n\n## Prerequisites\n\nVersion bumps MUST be configured before running this skill. If `yarn version check` fails, version files need to be adjusted first using `yarn version patch/minor/major` or `yarn bumpVersions` (interactive).\n\n## Workflow\n\n### Step 1: Validate Version Configuration\n\nRun `yarn version check` to validate version manifests exist:\n\n```bash\nyarn version check\n```\n\n**If fails:** Stop and","body":"# fill-changelog\n\nAutomate filling changelog entries based on the changes in the current branch.\n\n## Prerequisites\n\nVersion bumps MUST be configured before running this skill. If `yarn version check` fails, version files need to be adjusted first using `yarn version patch/minor/major` or `yarn bumpVersions` (interactive).\n\n## Workflow\n\n### Step 1: Validate Version Configuration\n\nRun `yarn version check` to validate version manifests exist:\n\n```bash\nyarn version check\n```\n\n**If fails:** Stop and report error. The user must run `yarn version patch`, `yarn version minor`, `yarn version major`, or `yarn bumpVersions` first to configure version bumps.\n\n### Step 2: Create/Recreate Changelog Drafts\n\nRun with force flag to ensure all drafts are created or recreated:\n\n```bash\nyarn changelog create -f\n```\n\nThis creates files in `.yarn/changelogs/` with the pattern `{package-name}.{manifest-id}.md`.\n\n### Step 3: Analyze Branch Changes\n\nGather information about changes:\n\n```bash\ngit diff develop...HEAD --stat\ngit log develop...HEAD --oneline\n```\n\nRead the changed files to understand what was actually modified.\n\n### Step 4: Read Changelog Drafts\n\nUse Glob to find `.yarn/changelogs/*.md` files, then Read to load their content.\n\n### Step 5: Fill Changelog Entries\n\nMap changes to the appropriate sections and fill the changelog drafts.\n\n## Section Mapping\n\n| Section             | When to Use                                    |\n| ------------------- | ---------------------------------------------- |\n| ✨ Features         | New functionality, new files, new capabilities |\n| 🐛 Bug Fixes        | Corrections to existing behavior               |\n| 📚 Documentation    | README, comments, documentation files          |\n| ⚡ Performance      | Optimizations                                  |\n| ♻️ Refactoring      | Code restructuring without behavior change     |\n| 🧪 Tests            | Test additions/modifications                   |\n| 📦 Build            | Build system, dependencies configuration       |\n| 👷 CI               | CI/CD configuration changes                    |\n| ⬆️ Dependencies     | Dependency updates                             |\n| 🔧 Chores           | Other maintenance tasks                        |\n| 💥 Breaking Changes | Major version only (REQUIRED)                  |\n| 🗑️ Deprecated       | Minor/Major versions only                      |\n\n## Quality Guidelines\n\n### Writing Style: Documentation, NOT Git Log\n\nWrite for package consumers, not as git history.\n\n**Avoid vague terms:**\n\n- \"improved\", \"updated\", \"refactored\", \"fixed bugs\", \"changed internal implementation\"\n\n**Use specific, actionable language:**\n\n- \"Added pagination support to `getUserList()` with page and limit parameters\"\n- \"Fixed date picker not respecting user timezone in profile settings\"\n\n### Version-Specific Requirements\n\n**Major Versions:**\n\n- Document ALL breaking changes with descriptive titles\n- Explain WHAT changed and WHY\n- Include before/after code examples using ❌/✅ markers\n- Provide migration guide with step-by-step instructions\n- Explain impact (who is affected)\n\n**Minor Versions:**\n\n- Document new features with descriptive titles\n- Provide usage examples\n- Explain benefits/use cases\n\n**Patch Versions:**\n\n- Be specific about bug fixes (not vague \"fixed bugs\")\n- Describe what was broken\n\n### List Items Need Descriptions\n\nWhen listing multiple items (features, agents, tools, etc.), each item should include a brief description of what it does and why it matters:\n\n```markdown\n// ❌ Bad - just names without context\n\n- Added `reviewer-changelog`\n- Added `reviewer-eslint`\n- Added `reviewer-prettier`\n\n// ✅ Good - each item explains its purpose\n\n- Added `reviewer-changelog` - Validates changelog entries have high-quality, descriptive content\n- Added `reviewer-eslint` - Runs ESLint checks to catch linting violations automatically\n- Added `reviewer-prettier` - Validates code formatting matches project standards\n```\n\nEven for simple list items, the reader should understand **what** the item does without needing to look elsewhere.\n\n## Entry Format Examples\n\n### Simple List (straightforward changes)\n\n```markdown\n## ✨ Features\n\n- Added `exportToCSV()` function for data export\n- Implemented multi-select filtering in list views\n```\n\n### Detailed Entry (complex changes)\n\n```markdown\n## ✨ Features\n\n### New Data Export Feature\n\nExport data in multiple formats for analysis and reporting.\n\n**Usage:**\n\n\\`\\`\\`typescript\nimport { exportData } from ''common'';\n\nconst result = await exportData(items, { format: ''csv'' });\n\\`\\`\\`\n```\n\n### Breaking Changes (major versions)\n\n```markdown\n## 💥 Breaking Changes\n\n### API Methods Now Use Object Parameters\n\nMethods now accept object parameters instead of positional arguments.\n\n**Examples:**\n\n\\`\\`\\`typescript\n// ❌ Before\nawait injector.getInstance(MyService, arg1, arg2);\n\n// ✅ After\nawait injector.getInstance(MyService, { arg1, arg2 });\n\\`\\`\\`\n\n**Impact:** All callers of the affected methods need to be updated.\n\n**Migration:** Search for method calls with `grep -r \"getInstance\" service/` and update to object syntax.\n```\n\n## Validation\n\nAfter filling entries, run:\n\n```bash\nyarn changelog check\n```\n\nThis validates:\n\n- Every release has a changelog file\n- Major releases have filled \"💥 Breaking Changes\" section\n- At least one section has content\n- Version type matches the manifest\n\n## Reference\n\nFor detailed guidelines, see:\n\n- `.cursor/rules/` for coding guidelines\n- `.cursor/agents/reviewer-changelog.md` (will review the filled entries)\n"},"lastSynced":"2026-03-08T02:09:38.218Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Automation Agents managing software versioning and release documentation workflows.","zh":"非常适合开发自动化代理管理软件版本和发布文档工作流。","ja":"開発自動化エージェントがソフトウェアのバージョニングとリリース文書化のワークフローを管理するには最適です。","ko":"소프트웨어 버전 관리 및 릴리즈 문서 작업 흐름을 관리하는 개발 자동화 에이전트에 적합합니다.","es":"Perfecto para Agentes de Automatización de Desarrollo que gestionan flujos de trabajo de versionado y documentación de software.","fr":"Parfait pour les Agents d''Automatisation de Développement gérant les flux de travail de versionnage et de documentation logicielle.","de":"Perfekt für Entwicklungsautomatisierungsagenten, die Softwareversionierung und Release-Dokumentationsworkflows verwalten.","pt":"Perfeito para Agentes de Automação de Desenvolvimento que gerenciam a versionagem de software e fluxos de trabalho de documentação de lançamento.","ru":"Идеально для агентов автоматизации разработки, которые управляют версионностью программного обеспечения и рабочими процессами документации выпуска.","ar":"مثالي للعمليات الذكية لآليّة التطوير التي تدير إصدارات البرمجيات وعمليات سير عمل توثيق الإصدار."},"recommendation":{"en":"Automates changelog population by analyzing branch changes and version configurations, streamlining release management. Integrates directly with yarn versioning commands and requires proper version manifest validation before execution.","zh":"通过分析分支更改和版本配置，自动执行变更日志填充，简化发布管理。直接与yarn版本命令集成，并在执行前需要正确的版本清单验证。","ja":"ブランチの変更とバージョン構成を分析して自動で変更ログを埋めることで、リリース管理を簡素化します。yarnバージョンコマンドとの直接的な統合を必要とし、実行前にバージョンマニフェストの適切な検証が必要です。","ko":"브랜치 변경과 버전 구성 분석을 통해 변경 로그 자동화 Populate를 자동으로 Populate 하여 릴리즈 관리를 간소화합니다. yarn 버전 명령어와 직접 통합되며, 실행 전에 올바른 버전 매니페스트 검증이 필요합니다.","es":"Automatiza la población del registro de cambios al analizar los cambios de rama y las configuraciones de versión, simplificando la gestión de versiones. Se integra directamente con los comandos de versionado de yarn y requiere una validación adecuada del manifiesto de versión antes de la ejecución.","fr":"Automatise la population du journal des modifications en analysant les modifications de branche et les configurations de version, rationalisant ainsi la gestion de version. Intègre directement les commandes de versionnage yarn et nécessite une validation appropriée du manifeste de version avant l''exécution.","de":"Automatisiert die Bevölkerung des Änderungsprotokolls durch Analyse von Branch-Änderungen und Versionskonfigurationen, wodurch die Versionsverwaltung rationalisiert wird. Integriert sich direkt in die yarn-Versionierungsbefehle und erfordert eine ordnungsgemäße Validierung des Versionsmanifests vor der Ausführung.","pt":"Automatiza a população do changelog analisando alterações de branch e configurações de versão, simplificando a gestão de lançamento. Integra-se diretamente com comandos de versionamento do yarn e exige uma validação adequada do manifesto de versão antes da execução.","ru":"Автоматизирует заполнение журнала изменений путем анализа изменений веток и конфигураций версий, упрощая управление выпусками. Интегрируется直接 с командами версионирования yarn и требует надлежащей проверки манифеста версии перед выполнением.","ar":"يعمل على توفير سجل التغييرات عن طريق تحليل التغييرات في الفروع وإعدادات الإصدار، وتبسيط إدارة الإصدار. يتكامل مباشرة مع أوامر إصدار yarn ويحتاج إلى التحقق من صحة إعلان الإصدار قبل التنفيذ."},"useCases":{"en":["Automating release note generation for version updates","Validating version configuration before deployment","Streamlining changelog maintenance in CI/CD pipelines"],"zh":["自动为版本更新生成发布说明","在部署前验证版本配置","简化CI/CD管道中的变更日志维护"],"ja":["バージョン更新のリリースノート自動生成","デプロイ前にバージョン構成を検証する","CI/CDパイプラインでの変更ログの維持を簡素化する"],"ko":["버전 업데이트에 대한 릴리스 노트 자동 생성","배포 전 버전 구성 확인","CI/CD 파이프라인에서 변경 로그 유지 보수를 간소화"],"es":["Automatización de la generación de notas de lanzamiento para actualizaciones de versiones","Validación de la configuración de versión antes de la implementación","Optimización del mantenimiento del registro de cambios en las canalizaciones de CI/CD"],"fr":["Automatisation de la génération de notes de version pour les mises à jour de version","Validation de la configuration de version avant le déploiement","Optimisation de la maintenance du journal des modifications dans les pipelines CI/CD"],"de":["Automatisierung der Generierung von Release-Hinweisen für Versionen-Updates","Validierung der Versionskonfiguration vor der Bereitstellung","Optimierung der Wartung des Änderungsprotokolls in CI/CD-Pipelines"],"pt":["Automatizar a geração de notas de lançamento para atualizações de versão","Validar a configuração de versão antes do deploy","Otimizar a manutenção do changelog em pipelines de CI/CD"],"ru":["Автоматизировать генерацию заметок о выпуске для обновлений версий","Проверить конфигурацию версии перед развертыванием","Оптимизировать поддержку журнала изменений в конвейерах CI/CD"],"ar":["توفير إنتاج ملاحظات الإصدار للتحديثات الإصدار","التحقق من صحة إعدادات الإصدار قبل النشر","تحسين صيانة سجل التغييرات في خطوط أنابيب CI/CD"]},"limitations":{"en":["Requires yarn version check validation first","Depends on properly configured version manifests","Only compatible with yarn-based version management systems"],"zh":["需要先进行yarn版本检查验证","依赖于正确配置的版本清单","仅与基于yarn的版本管理系统兼容"],"ja":["yarnバージョンチェックの検証が最初に必要","適切に構成されたバージョンマニフェストに依存する","yarnベースのバージョン管理システムのみと互換性がある"],"ko":["yarn 버전 검사 유효성 검증이 먼저 필요","적절하게 구성된 버전 매니페스트에 의존","yarn 기반 버전 관리 시스템만과 호환"],"es":["Requiere la validación de la versión de yarn primero","Depende de manifiestos de versión debidamente configurados","Solo es compatible con sistemas de gestión de versiones basados en yarn"],"fr":["Nécessite la validation de la version yarn en premier","Dépend de manifestes de version correctement configurés","N''est compatible qu''avec les systèmes de gestion de version basés sur yarn"],"de":["Erfordert die Überprüfung der yarn-Version zuerst","Hängt von ordnungsgemäß konfigurierten Versionsmanifesten ab","Ist nur mit yarn-basierten Versionsverwaltungssystemen kompatibel"],"pt":["Exige validação de verificação de versão do yarn primeiro","Depende de manifestos de versão configurados corretamente","Compatível apenas com sistemas de gerenciamento de versão baseados em yarn"],"ru":["Требует проверки версии yarn сначала","Зависит от правильно настроенных манифестов версий","Компатибелен только с системами управления версиями на основе yarn"],"ar":["يتطلب التحقق من صحة التحقق من إصدار yarn أولا","يعتمد على إعلانات إصدار معدة بشكل صحيح","متوافق فقط مع أنظمة إدارة الإصدارات المستندة إلى yarn"]},"version":4},"contentHash":"7f934309e6801e3b3cf9c3c28996a6d9aba3684dfbe0863c17b30f0f28415efd","qualityScore":60}');
