INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('BasedHardware/omi/omi-backend-patterns', 'omi-backend-patterns', 'BasedHardware', 'omi', 'community', 'omi-backend-patterns BasedHardware omi community omi-backend-patterns provides guidance for working with the Omi backend, including conversation processing and LangGraph integration, benefiting AI wearables developers Omi Backend Patterns提供了会话处理、内存提取和LangGraph集成的技术指导，帮助开发者提高AI开发效率 Omi Backend Patternsは会話処理、メモリ抽出、LangGraph統合に関する技術的ガイダンスを提供し、AI開発の効率を上げます Omi Backend Patterns는 대화 처리, 메모리 추출 및 LangGraph 통합에 대한 기술적 지침을 제공하여 AI 개발 효율성을 높입니다 El patrón de backend de Omi proporciona orientación para trabajar con el procesamiento de conversaciones y la extracción de memorias con Python y LangGraph. Le modèle de backend Omi fournit des conseils pour travailler avec le traitement des conversations et l''extraction des mémoires avec Python et LangGraph. Das Omi-Backend-Muster bietet Anleitung zur Arbeit mit der Konversationsverarbeitung und der Erinnerungsextraktion mit Python und LangGraph. O Omi Backend Patterns fornece orientação para trabalhar com o Omi backend, incluindo processamento de conversas e integração com LangGraph Шаблоны Omi Backend предоставляют руководство для работы с Omi backend, включая обработку разговоров и интеграцию с LangGraph для ИИ Агентов أنماط Omi Backend توفر إرشادات للعمل مع.backend Omi ، بما في ذلك معالجة المحادثات وتكامل LangGraph لأدوات الذكاء الاصطناعي how to use omi-backend-patterns omi-backend-patterns setup guide omi-backend-patterns alternative omi-backend-patterns vs LangGraph omi-backend-patterns install omi-backend-patterns conversation processing omi-backend-patterns LangGraph integration omi-backend-patterns Redis setup omi-backend-patterns Firestore development omi-backend-patterns AI wearables development Omi Backend Patterns AI开发 会话处理 内存提取 LangGraph Firestore Pinecone Redis AIエージェント Provides conversation processing guidance for backend Python code in `backend/` Supports implementing new API endpoints for LangGraph integration Enables memory extraction and chat system development with Firestore, Pinecone, or Redis Offers integration with LangGraph for advanced chat functionality Works with Redis for efficient data storage and retrieval Facilitates conversation processing and transcription for AI wearables omi-backend-patterns is a skill that provides guidance for working with the Omi backend, including conversation processing, memory extraction, and chat system integration');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('razorpay/blade/review-changes', 'community', 'razorpay', 'blade', 'razorpay/blade', 'review-changes', 0, 0, 60, '2026-03-08T01:57:15.481Z', '2026-03-08T02:09:54.689Z', '2e72a55c513d0e6c3b956fe735d861a65eb6975396d3ac604745d61a89bbae80', '{"id":"razorpay/blade/review-changes","name":"review-changes","description":{"en":"The review-changes skill streamlines PR reviews for Razorpay''s Design System by automating diff fetching, CI status checks, and Storybook preview URL extraction. It benefits developers working with the razorpay/blade repository.","zh":"Review Changes AIエージェント 为 Razorpay 设计系统提供代码审查和测试功能，支持 Git 和 Storybook","ja":"Review Changes AIエージェント は、Razorpay デザインシステムのコードレビューとテストを提供し、Git と Storybook をサポートします","ko":"리뷰 변경 사항 AI 에이전트는 Razorpay 디자인 시스템에 대한 코드 리뷰 및 테스트 기능을 제공하며 Git 및 Storybook를 지원합니다","es":"El agente de IA review-changes permite revisar PRs en Razorpay/blade con GitH y Storybook","fr":"L''agent IA review-changes permet d''examiner les PRs dans Razorpay/blade avec GitH et Storybook","de":"Der IA-Agent review-changes ermöglicht die Überprüfung von PRs in Razorpay/blade mit GitH und Storybook","pt":"O review-changes é uma ferramenta de revisão de código que verifica as alterações no repositório Razorpay/blade, fornecendo uma visão geral das mudanças e melhorando a colaboração","ru":"ИИ Агент review-changes - это инструмент для проверки изменений в репозитории Razorpay/blade, который предоставляет обзор изменений и улучшает сотрудничество","ar":"أداة مراجعة التغييرات review-changes هي أداة لمراجعة التغييرات في مستودع Razorpay/blade، توفر نظرة عامة على التغييرات وتحسن التعاون"},"seo":{"title":{"en":"review-changes: Razorpay Design System Setup Guide | AI A...","zh":"Review Changes Setup Guide - AIエージェント for Razorpay","ja":"Review Changes ベストプラクティス - AIエージェント for Razorpay","ko":"리뷰 변경 사항 설정 가이드 - A