INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('razorpay/blade/review-changes', 'review-changes', 'razorpay', 'blade', 'community', 'review-changes razorpay blade community The review-changes skill streamlines PR reviews for Razorpay''s Design System by automating diff fetching, CI status checks, and Storybook preview URL extraction. It benefits developers working with the razorpay/blade repository. Review Changes AIエージェント 为 Razorpay 设计系统提供代码审查和测试功能，支持 Git 和 Storybook Review Changes AIエージェント は、Razorpay デザインシステムのコードレビューとテストを提供し、Git と Storybook をサポートします 리뷰 변경 사항 AI 에이전트는 Razorpay 디자인 시스템에 대한 코드 리뷰 및 테스트 기능을 제공하며 Git 및 Storybook를 지원합니다 El agente de IA review-changes permite revisar PRs en Razorpay/blade con GitH y Storybook L''agent IA review-changes permet d''examiner les PRs dans Razorpay/blade avec GitH et Storybook Der IA-Agent review-changes ermöglicht die Überprüfung von PRs in Razorpay/blade mit GitH und Storybook O review-changes é uma ferramenta de revisão de código que verifica as alterações no repositório Razorpay/blade, fornecendo uma visão geral das mudanças e melhorando a colaboração ИИ Агент review-changes - это инструмент для проверки изменений в репозитории Razorpay/blade, который предоставляет обзор изменений и улучшает сотрудничество أداة مراجعة التغييرات review-changes هي أداة لمراجعة التغييرات في مستودع Razorpay/blade، توفر نظرة عامة على التغييرات وتحسن التعاون how to use review-changes review-changes setup guide review-changes alternative review-changes vs GitHub code review review-changes install what is review-changes review-changes for Razorpay review-changes and Storybook review-changes CI status check review-changes Git integration Review Changes AIエージェント Razorpay 设计系统 代码审查工具 Git 代码审查 Storybook 预览 URL CI 状态检查 UI 审查 headed 浏览器模式 代码 diff Fetches diffs for PRs in the razorpay/blade repository Checks CI status for PRs Extracts Storybook preview URLs Supports headed and headless browser modes Utilizes Git for repository interactions Integrates with Cursor''s AskQuestion tool for clarifications review-changes is a skill that automates the review process of pull requests in the razorpay/blade repository, utilizing Git and Storybook.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('thegameband/BadDateDemo/skill-editor', 'community', 'thegameband', 'BadDateDemo', 'thegameband/BadDateDemo', 'skill-editor', 0, 0, 60, '2026-03-08T01:57:15.484Z', '2026-03-08T02:10:00.745Z', 'b718e619dc919d904cc142d67f3ef8d150d1630d440ccbc54bcd510399b26c9f', '{"id":"thegameband/BadDateDemo/skill-editor","name":"skill-editor","description":{"en":"The skill-editor allows developers to create or edit skills based on user requirements, following the AgentSkills.io open standard. It benefits AI agent developers by providing a structured approach to skill creation.","zh":"AIエージェント技能编辑器允许开发者创建和编辑技能，基于AgentSkills.io开放标准。每个技能都是一个包含SKILL.md文件的目录","ja":"AIエージェントスキルエディターは、開発者がスキルを作成および編集できるようにします。AgentSkills.ioオープン標準に基づいています。各スキルは、SKILL.mdファイルを含むディレクトリです","ko":"AI 에이전트 스킬 편집기는 개발자가 스킬을 생성하고 편집할 수 있도록 합니다. AgentSkills.io 오픈 표준을 따릅니다. 각 스킬은 SKILL.md 파일을 포함하는 디렉토리입니다","es":"El editor de habilidades es una herramienta para crear o editar habilidades de agentes de IA según los requisitos del usuario, siguiendo el estándar abierto de AgentSkills.io","fr":"L''éditeur de compétences est un outil pour créer ou modifier des compétences d''agents IA en fonction des exigences de l''utilisateur, suivant la norme ouverte d''AgentSkills.io","de":"Der Fähigkeits-Editor ist ein Werkzeug zum Erstellen oder Bearbeiten von Fähigkeiten von KI-Agents gemäß den Benutzeranforderungen, basierend auf dem offenen Standard von AgentSkills.io","pt":"O editor de habilidades permite criar e editar habilidades para ferramentas de IA com base em requisitos do usuário, seguindo o padrão aberto do AgentSkills.io.","ru":"Редактор навыков позволяет создавать и редактировать навыки для ИИ Агентов на основе требований пользователя, следуя открытому стандарту AgentSkills.io.","ar":"محرر المهارات يسمح بإنشاء وتحرير المهارات للأدوات الذكية بناءً على متطلبات المستخدم، متبعًا المعيار المفتوح لشركة AgentSkills.io."},"seo":{"title":{"en":"skill-editor: Setup Guide for AI Agents","zh":"AIエージェント技能编辑器Setup Guide","ja":"AIエージェントスキルエディターベストプラクティス","ko":"AI 에이전트 스킬 편집기 설정 가이드","es":"Guía de Configuración del Editor de Habilidades de Agente...","fr":"Guide d''Installation de l''Éditeur de Compétences d''Agents IA","de":"Setup-Leitfaden für den Fähigkeits-Editor von KI-Agents","pt":"Guia de Configuração do Editor de Habilidades para Ferram...","ru":"Настройка редактора навыков для ИИ Агентов","ar":"دليل إعداد محرر المهارات للأدوات الذكية"},"description":{"en":"Discover how to create and edit skills with skill-editor. Learn to leverage directory-based skills and YAML frontmatter for AI agents.","zh":"了解AIエージェント技能编辑器的功能和特点，掌握技能编辑的最佳实践和目录结构","ja":"AIエージェントスキルエディターの機能と特徴をご紹介。スキルの編集と構造について学びましょう","ko":"AI 에이전트 스킬 편집기의 기능과 특징을 알아보세요. 스킬 편집과 디렉토리 구조에 대한 최고의 방법을 배우세요","es":"Aprende a configurar y utilizar el editor de habilidades para agentes de IA con nuestro tutorial paso a paso y mejora tus habilidades de desarrollo","fr":"Découvrez comment configurer et utiliser l''éditeur de compétences pour les agents IA avec notre tutoriel étape par étape et améliorez vos compétences de déve...","de":"Erfahren Sie, wie Sie den Fähigkeits-Editor für KI-Agents konfigurieren und verwenden können, mit unserem Schritt-für-Schritt-Tutorial und verbessern Sie Ihr...","pt":"Aprenda a criar e editar habilidades para ferramentas de IA com o editor de habilidades, seguindo o padrão aberto do AgentSkills.io","ru":"Узнайте, как создавать и редактировать навыки для ИИ Агентов с помощью редактора навыков, следуя открытому стандарту AgentSkills.io","ar":"تعلم كيفية إنشاء وتحرير المهارات للأدوات الذكية باستخدام محرر المهارات، متبعًا المعيار المفتوح لشركة AgentSkills.io"},"definition":{"en":"skill-editor is a tool for creating and editing skills based on the AgentSkills.io open standard, utilizing directory-based structures and YAML frontmatter.","zh":"AIエージェント技能编辑器是一种基于AgentSkills.io开放标准的技能创建和编辑工具","ja":"AIエージェントスキルエディターは、AgentSkills.ioオープン標準に基づいたスキルの作成および編集ツールです","ko":"AI 에이전트 스킬 편집기는 AgentSkills.io 오픈 표준을 기반으로 하는 스킬 생성 및 편집 도구입니다","es":"El editor de habilidades es una herramienta de desarrollo para agentes de IA que permite crear y editar habilidades según los requisitos del usuario","fr":"L''éditeur de compétences est un outil de développement pour les agents IA qui permet de créer et de modifier des compétences en fonction des exigences de l''utilisateur","de":"Der Fähigkeits-Editor ist ein Entwicklungstool für KI-Agents, das das Erstellen und Bearbeiten von Fähigkeiten gemäß den Benutzeranforderungen ermöglicht","pt":"O que é um editor de habilidades? É uma ferramenta para criar e editar habilidades para ferramentas de IA.","ru":"Что такое редактор навыков? Это инструмент для создания и редактирования навыков для ИИ Агентов.","ar":"ما هو محرر المهارات؟ هو أداة لإنشاء وتحرير المهارات للأدوات الذكية."},"features":{"en":["Directory-based skill structure in .cursor/skills/<skill-name>/","Requires a SKILL.md file with YAML frontmatter for main instructions","Supports project or personal scope skills in .cursor/skills/","Utilizes markdown instructions for skill development","Follows the AgentSkills.io open standard for skill creation"],"zh":["基于目录的技能结构","SKILL.md文件的YAML前置和Markdown指令","项目或个人范围的技能管理","支持AgentSkills.io开放标准","灵活的技能编辑和创建功能"],"ja":["ディレクトリベースのスキル構造","SKILL.mdファイルのYAMLフロントマターとMarkdown指令","プロジェクトまたは個人の範囲のスキル管理","AgentSkills.ioオープン標準のサポート","柔軟なスキルの編集と作成機能"],"ko":["디렉토리 기반의 스킬 구조","SKILL.md 파일의 YAML 전면과 Markdown 지시","프로젝트 또는 개인 범위의 스킬 관리","AgentSkills.io 오픈 표준 지원","유연한 스킬 편집과 생성 기능"],"es":["Basado en directorios: cada habilidad se encuentra en .cursor/skills/<nombre-de-habilidad>/","Requiere un archivo SKILL.md con frontmatter y instrucciones en markdown","Alcance de proyecto o personal: habilidades de proyecto en .cursor/skills/","Seguimiento del estándar abierto de AgentSkills.io","Compatibilidad con habilidades personalizadas"],"fr":["Basé sur des répertoires : chaque compétence se trouve dans .cursor/skills/<nom-de-compétence>/","Nécessite un fichier SKILL.md avec frontmatter et instructions en markdown","Portée de projet ou personnelle : compétences de projet dans .cursor/skills/","Suivi de la norme ouverte d''AgentSkills.io","Compatibilité avec des compétences personnalisées"],"de":["Basiert auf Verzeichnissen: jede Fähigkeit befindet sich in .cursor/skills/<fähigkeitsname>/","Benötigt eine Datei SKILL.md mit Frontmatter und Markdown-Anweisungen","Projekt- oder persönlicher Umfang: Projekt-Fähigkeiten in .cursor/skills/","Basiert auf dem offenen Standard von AgentSkills.io","Kompatibilität mit benutzerdefinierten Fähigkeiten"],"pt":["Diretório-base para cada habilidade","Arquivo SKILL.md obrigatório com frontmatter e instruções em markdown","Escopo de projeto ou pessoal para habilidades","Compatibilidade com o padrão aberto do AgentSkills.io","Criação e edição de habilidades com base em requisitos do usuário"],"ru":["Директория-база для каждого навыка","Обязательный файл SKILL.md с frontmatter и инструкциями в markdown","Объем проекта или личный для навыков","Совместимость с открытым стандартом AgentSkills.io","Создание и редактирование навыков на основе требований пользователя"],"ar":["دليل قائم على دليل لمهارات كل","ملف SKILL.md إجباري مع(frontmatter) وتعليمات بالتنسيق markdown","نطاق مشروع أو شخصي للمهارات","التوافق مع المعيار المفتوح لشركة AgentSkills.io","إنشاء وتحرير المهارات بناءً على متطلبات المستخدم"]},"keywords":{"en":["how to use skill-editor","what is skill-editor","skill-editor alternative","skill-editor vs AgentSkills.io","skill-editor install","skill-editor setup guide","AgentSkills.io open standard","directory-based skills","YAML frontmatter for skills"],"zh":["AIエージェント技能编辑器","AgentSkills.io开放标准","技能创建和编辑","基于目录的技能结构","SKILL.md文件的YAML前置","项目或个人范围的技能管理","AI工具","AI开发"],"ja":["AIエージェントスキルエディター","AgentSkills.ioオープン標準","スキルの作成と編集","ディレクトリベースのスキル構造","SKILL.mdファイルのYAMLフロントマター","プロジェクトまたは個人の範囲のスキル管理","AIエージェント","AI開発"],"ko":["AI 에이전트 스킬 편집기","AgentSkills.io 오픈 표준","스킬 생성과 편집","디렉토리 기반의 스킬 구조","SKILL.md 파일의 YAML 전면","프로젝트 또는 개인 범위의 스킬 관리","AI 에이전트","AI 개발"],"es":["agentes de IA","editor de habilidades","desarrollo de habilidades","AgentSkills.io","estándar abierto","herramientas de desarrollo","competencias de agentes","configuración de habilidades","desarrollo de software"],"fr":["agents IA","éditeur de compétences","développement de compétences","AgentSkills.io","norme ouverte","outils de développement","compétences d''agents","configuration de compétences","développement de logiciels"],"de":["KI-Agents","Fähigkeits-Editor","Fähigkeits-Entwicklung","AgentSkills.io","offener Standard","Entwicklungstools","Fähigkeiten von KI-Agents","Konfiguration von Fähigkeiten","Software-Entwicklung"],"pt":["editor de habilidades","ferramentas de IA","AgentSkills.io","criação de habilidades","edição de habilidades","padrão aberto","desenvolvimento de habilidades","IA","inteligência artificial"],"ru":["редактор навыков","ИИ Агенты","AgentSkills.io","создание навыков","редактирование навыков","открытый стандарт","разработка навыков","ИИ","искусственный интеллект"],"ar":["محرر المهارات","الأدوات الذكية","AgentSkills.io","إنشاء المهارات","تحرير المهارات","المعيار المفتوح","تطوير المهارات","الذكاء الاصطناعي","الأدوات الذكية"]}},"owner":"thegameband","repo":"BadDateDemo","repoPath":"thegameband/BadDateDemo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.484Z","topics":[],"category":"community","skillMd":{"name":"skill-editor","description":"Create or edit skills following the AgentSkills.io standard. Use when user wants to create a new skill, modify an existing skill, or asks about skill configuration. Triggers on keywords like create skill, edit skill, new skill, skill-editor, SKILL.md, or make a skill that....","bodyPreview":"# Skill Editor\n\nCreate or edit skills based on user requirements.\n\n## Understanding Skills\n\nSkills follow the [AgentSkills.io](https://agentskills.io) open standard. Each skill is a **directory** containing a `SKILL.md` file with frontmatter and markdown instructions.\n\n### Key Features\n- **Directory-based**: Each skill lives in `.cursor/skills/<skill-name>/`\n- **SKILL.md Required**: Main instructions file with YAML frontmatter\n- **Project or Personal Scope**: Project skills in `.cursor/skills/`,","body":"# Skill Editor\n\nCreate or edit skills based on user requirements.\n\n## Understanding Skills\n\nSkills follow the [AgentSkills.io](https://agentskills.io) open standard. Each skill is a **directory** containing a `SKILL.md` file with frontmatter and markdown instructions.\n\n### Key Features\n- **Directory-based**: Each skill lives in `.cursor/skills/<skill-name>/`\n- **SKILL.md Required**: Main instructions file with YAML frontmatter\n- **Project or Personal Scope**: Project skills in `.cursor/skills/`, personal in `~/.cursor/skills/`\n- **Optional Supporting Files**: `scripts/`, `references/`, `assets/` subdirectories\n\n### Directory Structure\n\n```\n.cursor/skills/<skill-name>/\n├── SKILL.md           # Required - main instructions\n├── scripts/           # Optional - executable code\n├── references/        # Optional - additional docs\n└── assets/            # Optional - templates, data files\n```\n\n## Steps\n\n### Step 0: Determine Operation Mode\n\nAnalyze the request to determine whether this is a create or edit operation:\n\n1. **Edit Mode** indicators:\n   - File path mentioned (e.g., `.cursor/skills/my-skill/SKILL.md`)\n   - Skill name with edit intent (e.g., \"edit the deploy skill\", \"modify my-skill\")\n   - Explicit edit request with existing skill\n\n2. **Create Mode** indicators:\n   - Capability description (e.g., \"skill for parsing JSON\")\n   - \"create skill for...\", \"make a skill that...\"\n   - No existing skill matches\n\n3. **Ambiguous**: Search `.cursor/skills/**/SKILL.md`, ask user to clarify\n\n---\n\n## EDIT MODE\n\n### Step 1: Find the Skill\n\nSearch `.cursor/skills/**/SKILL.md`:\n- If multiple matches, list and ask user to select\n- If none found, offer to create a new skill\n\n### Step 2: Read and Analyze\n\n- Load the SKILL.md file\n- Identify frontmatter fields and content sections\n- Understand current functionality\n\n### Step 3: Get Edit Type\n\nAsk user:\n- \"What would you like to modify?\"\n- Options: \"Update frontmatter\" | \"Modify instructions\" | \"Add supporting files\" | \"Change invocation settings\"\n\n### Step 4: Apply Changes\n\n- Apply modifications to the file\n- Preserve sections not being changed\n- Confirm modifications were successful\n- Provide updated file path\n\nThen STOP.\n\n---\n\n## CREATE MODE\n\n### Step 1: Check for Duplicates\n\nSearch for similar skills:\n- Search `.cursor/skills/**/SKILL.md`\n- Search for similar functionality\n- If found, ask: edit existing, create anyway, or cancel\n\n### Step 2: Generate Skill Name\n\nBased on the request, suggest a name following these rules:\n- **Max 64 characters**\n- **Lowercase letters, numbers, and hyphens only** (`a-z`, `0-9`, `-`)\n- **Must NOT start or end with hyphen**\n- **No consecutive hyphens** (`--`)\n- Pattern: `verb-noun` or `verb-noun-qualifier` (e.g., `parse-json`, `validate-email`)\n\nConfirm with user or let them provide custom name. **Validate name before proceeding.**\n\n### Step 3: Gather Requirements\n\nAsk user:\n\n**Invocation** - \"Who should invoke this skill?\"\nOptions:\n- \"Both user and agent (Recommended)\" - Default behavior\n- \"User only\" - Add `disable-model-invocation: true`\n\n**Execution** - \"How should this skill run?\"\nOptions:\n- \"Inline (Recommended)\" - Runs in current context\n\n### Step 4: Create Skill Directory and File\n\n```bash\nmkdir -p .cursor/skills/<skill-name>\n```\n\nWrite `.cursor/skills/<skill-name>/SKILL.md`:\n\n```yaml\n---\nname: <skill-name>\ndescription: <What this skill does and when to use it. Include keywords that help identify relevant tasks. Max 1024 chars.>\n# Optional fields:\n# disable-model-invocation: true\n# license: MIT\n# compatibility: Requires git CLI\n# metadata:\n#   author: \"Team\"\n#   version: \"1.0\"\n---\n\n<Markdown instructions to follow when skill is invoked>\n\n## Steps\n\n1. [First step - be specific about tools/methods]\n2. [Second step]\n3. [Validation/error handling]\n\n## Examples\n\n### Example 1: [Scenario]\n**Input:** `[input]`\n**Expected behavior:** [what should happen]\n\n## Notes\n\n- [Edge cases, limitations, best practices]\n```\n\n### Step 5: Confirm Creation\n\nReport:\n- Skill name and location\n- Invocation method (`/skill-name` or automatic)\n- How to test it\n- Mention editing with skill-editor for future changes\n\nThen STOP.\n\n---\n\n## SKILL.md Format Reference\n\n### Required Frontmatter\n\n| Field | Required | Description |\n|-------|----------|-------------|\n| `name` | Yes | Must match directory name. Max 64 chars, lowercase + hyphens only |\n| `description` | Yes | What it does and when to use. Max 1024 chars. Include trigger keywords |\n\n### Optional Frontmatter\n\n| Field | Description |\n|-------|-------------|\n| `disable-model-invocation` | `true` = only user can invoke via `/name` |\n| `license` | License name or reference to LICENSE file |\n| `compatibility` | Environment requirements (max 500 chars) |\n| `metadata` | Arbitrary key-value pairs (e.g., `author`, `version`) |\n\n## Quality Standards\n\n**Good skills**:\n- Focused (one task well)\n- Clear description with trigger keywords\n- Well-documented with examples\n- Under 500 lines (move details to `references/`)\n\n**Name validation checklist**:\n- [ ] Lowercase only\n- [ ] No spaces (use hyphens)\n- [ ] No consecutive hyphens\n- [ ] Doesn''t start/end with hyphen\n- [ ] Matches directory name\n- [ ] Max 64 characters\n\n## Error Handling\n\n| Error | Cause | Resolution |\n|-------|-------|------------|\n| Skill not found | Invalid path or name | Verify path, search for files |\n| Invalid frontmatter | Malformed YAML | Check syntax, ensure proper indentation |\n| Duplicate skill | Name already exists | Rename or offer to edit existing |\n| Missing directory | Parent doesn''t exist | Create with `mkdir -p` |\n| Invalid name | Uppercase, spaces, or special chars | Convert to valid kebab-case |\n\n## Limitations (Cursor-specific)\n\n**Note**: The following Claude Code features are NOT supported in Cursor:\n- `$ARGUMENTS` string substitutions\n- `` !`command` `` dynamic context injection\n- `argument-hint` field\n- `user-invocable` field\n- `allowed-tools` field\n- `model` field\n- `context: fork` field\n- `agent` field\n- `hooks` field\n"},"lastSynced":"2026-03-08T02:10:00.745Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agent Developers needing structured skill creation based on the AgentSkills.io open standard.","zh":"非常适合需要根据 AgentSkills.io 开放标准创建结构化技能的 AI Agent 开发人员。","ja":"AgentSkills.io オープン標準に基づいた構造化スキルの作成が必要な AI エージェント開発者に最適です。","ko":"AgentSkills.io 오픈 표준에 기반한 구조화된 스킬 생성이 필요한 AI 에이전트 개발자를 위한 최적의 솔루션입니다.","es":"Perfecto para desarrolladores de Agentes de IA que necesitan una creación de habilidades estructuradas basada en el estándar abierto de AgentSkills.io.","fr":"Parfait pour les développeurs d''agents d''IA qui ont besoin d''une création de compétences structurée basée sur la norme ouverte d''AgentSkills.io.","de":"Perfekt für Entwickler von KI-Agents, die eine strukturierte Fähigkeitserstellung auf Basis des offenen AgentSkills.io-Standards benötigen.","pt":"Perfeito para desenvolvedores de Agentes de IA que necessitam de criação de habilidades estruturadas com base no padrão aberto do AgentSkills.io.","ru":"Идеально для разработчиков агентов ИИ, которым необходима структурированная создание навыков на основе открытого стандарта AgentSkills.io.","ar":"مثالي لمطوري وكلاء الذكاء الاصطناعي الذين يحتاجون إلى إنشاء مهارات منظم على أساس معيار AgentSkills.io المفتوح."},"recommendation":{"en":"Empowers agents to create or edit skills using directory-based structures, YAML frontmatter, and markdown instructions, following the AgentSkills.io protocol for seamless integration.","zh":"赋予代理创建或编辑技能的能力，使用基于目录的结构、YAML 前置内容和 markdown 指令，遵循 AgentSkills.io 协议以实现无缝集成。","ja":"エージェントに、ディレクトリベースの構造、YAML フロントマター、Markdown 指令を使用してスキルを作成または編集する能力を提供し、AgentSkills.io プロトコルに従ってシームレスに統合します。","ko":"에이전트가 디렉토리 기반 구조, YAML 프론트매터, 마크다운 지침을 사용하여 스킬을 생성 또는 편집할 수 있는 기능을 제공하며, 에이전트스킬즈.IO 프로토콜을 따르는 시ーム리스 통합을 지원합니다.","es":"Habilita a los agentes a crear o editar habilidades utilizando estructuras basadas en directorios, frontmatter YAML y instrucciones en markdown, siguiendo el protocolo de AgentSkills.io para una integración sin problemas.","fr":"Autorise les agents à créer ou à modifier des compétences en utilisant des structures basées sur des répertoires, des données YAML de frontmatter et des instructions en markdown, en suivant le protocole d''AgentSkills.io pour une intégration sans problème.","de":"Ermöglicht es Agents, Fähigkeiten zu erstellen oder zu bearbeiten, indem sie directorybasierte Strukturen, YAML-Frontmatter und Markdown-Anweisungen verwenden, und folgt dem AgentSkills.io-Protokoll für eine nahtlose Integration.","pt":"Habilita agentes a criar ou editar habilidades usando estruturas baseadas em diretórios, frontmatter YAML e instruções em markdown, seguindo o protocolo do AgentSkills.io para integração sem problemas.","ru":"Наделяет агентов возможностью создавать или редактировать навыки, используя структуры, основанные на директориях, YAML-заголовки и инструкции markdown, следуя протоколу AgentSkills.io для беспрепятственной интеграции.","ar":"تمكين الوكلاء من إنشاء أو تحرير المهارات باستخدام هياكل تستند إلى الدلائل و YAML و تعليمات markdown ، متبعة بروتوكول AgentSkills.io من أجل التكامل دون مشاكل."},"useCases":{"en":["Creating custom skills for specific user requirements","Editing existing skills to adapt to new user needs","Organizing skills into project or personal scopes within the .cursor/skills/ directory"],"zh":["为特定用户需求创建自定义技能","编辑现有技能以适应新用户需求","将技能组织到项目或个人范围内的 .cursor/skills/ 目录中"],"ja":["特定ユーザー要件に基づくカスタムスキルの作成","新しいユーザーニーズに適応するために既存のスキルを編集",".cursor/skills/ ディレクトリ内のプロジェクトまたは個人スコープへのスキルの組織"],"ko":["특정 사용자 요구 사항에 맞춰 사용자 지정 스킬 생성","새로운 사용자 요구 사항에 적응하기 위해 기존 스킬 편집",".cursor/skills/ 디렉토리 내의 프로젝트 또는 개인 범위 내에서 스킬을组织"],"es":["Crear habilidades personalizadas para requisitos de usuario específicos","Editar habilidades existentes para adaptarse a nuevas necesidades de los usuarios","Organizar habilidades en ámbitos de proyecto o personales dentro del directorio .cursor/skills/"],"fr":["Créer des compétences personnalisées pour des exigences spécifiques des utilisateurs","Modifier des compétences existantes pour s''adapter à de nouvelles besoins des utilisateurs","Organiser des compétences dans des portées de projet ou personnelles à l''intérieur du répertoire .cursor/skills/"],"de":["Erstellen von benutzerdefinierten Fähigkeiten für spezifische Benutzeranforderungen","Bearbeiten von bestehenden Fähigkeiten, um sich an neue Benutzerbedürfnisse anzupassen","Organisieren von Fähigkeiten in Projekt- oder Personenscope innerhalb des .cursor/skills/-Verzeichnisses"],"pt":["Criando habilidades personalizadas para requisitos de usuário específicos","Editando habilidades existentes para se adaptar às novas necessidades do usuário","Organizando habilidades em projetos ou escopos pessoais dentro do diretório .cursor/skills/"],"ru":["Создание пользовательских навыков для конкретных требований пользователей","Редактирование существующих навыков для адаптации к новым потребностям пользователей","Организация навыков в проекты или личные области внутри директории .cursor/skills/"],"ar":["إنشاء مهارات مخصصة لمتطلبات المستخدم الخاصة","تحرير المهارات الحالية للتكيف مع احتياجات المستخدم الجديدة","تنظيم المهارات في نطاقات المشروع أو الشخصية داخل الدليل .cursor/skills/"]},"limitations":{"en":["Requires adherence to the AgentSkills.io open standard","Each skill must be contained within a directory with a SKILL.md file"],"zh":["需要遵守 AgentSkills.io 开放标准","每个技能必须包含在具有 SKILL.md 文件的目录中"],"ja":["AgentSkills.io オープン標準の遵守が必要","各スキルは SKILL.md ファイルを含むディレクトリ内に含まれている必要があります"],"ko":["에이전트스킬즈.IO 오픈 표준을 준수해야 함","각 스킬은 SKILL.md 파일을 포함하는 디렉토리 내에 포함되어야 함"],"es":["Requiere la adhesión al estándar abierto de AgentSkills.io","Cada habilidad debe estar contenida dentro de un directorio con un archivo SKILL.md"],"fr":["Exige l''adhésion à la norme ouverte d''AgentSkills.io","Chaque compétence doit être contenue dans un répertoire avec un fichier SKILL.md"],"de":["Erfordert die Einhaltung des offenen AgentSkills.io-Standards","Jede Fähigkeit muss innerhalb eines Verzeichnisses mit einer SKILL.md-Datei enthalten sein"],"pt":["Exige aderência ao padrão aberto do AgentSkills.io","Cada habilidade deve estar contida dentro de um diretório com um arquivo SKILL.md"],"ru":["Требует соблюдения открытого стандарта AgentSkills.io","Каждый навык должен быть содержан внутри директории с файлом SKILL.md"],"ar":["يتطلب الالتزام بمعيار AgentSkills.io المفتوح","يجب أن تكون كل مهارة محتوية داخل دليل مع ملف SKILL.md"]},"version":4},"contentHash":"b718e619dc919d904cc142d67f3ef8d150d1630d440ccbc54bcd510399b26c9f","qualityScore":60}');
