INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('thegameband/BadDateDemo/skill-editor', 'skill-editor', 'thegameband', 'BadDateDemo', 'community', 'skill-editor thegameband BadDateDemo community The skill-editor allows developers to create or edit skills based on user requirements, following the AgentSkills.io open standard. It benefits AI agent developers by providing a structured approach to skill creation. AIエージェント技能编辑器允许开发者创建和编辑技能，基于AgentSkills.io开放标准。每个技能都是一个包含SKILL.md文件的目录 AIエージェントスキルエディターは、開発者がスキルを作成および編集できるようにします。AgentSkills.ioオープン標準に基づいています。各スキルは、SKILL.mdファイルを含むディレクトリです AI 에이전트 스킬 편집기는 개발자가 스킬을 생성하고 편집할 수 있도록 합니다. AgentSkills.io 오픈 표준을 따릅니다. 각 스킬은 SKILL.md 파일을 포함하는 디렉토리입니다 El editor de habilidades es una herramienta para crear o editar habilidades de agentes de IA según los requisitos del usuario, siguiendo el estándar abierto de AgentSkills.io L''éditeur de compétences est un outil pour créer ou modifier des compétences d''agents IA en fonction des exigences de l''utilisateur, suivant la norme ouverte d''AgentSkills.io Der Fähigkeits-Editor ist ein Werkzeug zum Erstellen oder Bearbeiten von Fähigkeiten von KI-Agents gemäß den Benutzeranforderungen, basierend auf dem offenen Standard von AgentSkills.io O editor de habilidades permite criar e editar habilidades para ferramentas de IA com base em requisitos do usuário, seguindo o padrão aberto do AgentSkills.io. Редактор навыков позволяет создавать и редактировать навыки для ИИ Агентов на основе требований пользователя, следуя открытому стандарту AgentSkills.io. محرر المهارات يسمح بإنشاء وتحرير المهارات للأدوات الذكية بناءً على متطلبات المستخدم، متبعًا المعيار المفتوح لشركة AgentSkills.io. how to use skill-editor what is skill-editor skill-editor alternative skill-editor vs AgentSkills.io skill-editor install skill-editor setup guide AgentSkills.io open standard directory-based skills YAML frontmatter for skills AIエージェント技能编辑器 AgentSkills.io开放标准 技能创建和编辑 基于目录的技能结构 SKILL.md文件的YAML前置 项目或个人范围的技能管理 AI工具 AI开发 Directory-based skill structure in .cursor/skills/<skill-name>/ Requires a SKILL.md file with YAML frontmatter for main instructions Supports project or personal scope skills in .cursor/skills/ Utilizes markdown instructions for skill development Follows the AgentSkills.io open standard for skill creation skill-editor is a tool for creating and editing skills based on the AgentSkills.io open standard, utilizing directory-based structures and YAML frontmatter.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('samsamit/fgj26-project/godot', 'community', 'samsamit', 'fgj26-project', 'samsamit/fgj26-project', 'godot', 0, 0, 60, '2026-03-08T01:57:15.486Z', '2026-03-08T02:10:04.540Z', '42344298a8f1c63ac70753f6775dc68267f468c9a17d3be730de78312bbc6df9', '{"id":"samsamit/fgj26-project/godot","name":"godot","description":{"en":"The Godot skill provides specialized guidance for developing games and applications with Godot Engine, focusing on collaboration between LLM coding assistants and Godot''s unique file structure.","zh":"Godot Engine开发涉及GDScript代码文件和文本资源文件，需要注意格式要求","ja":"Godotエンジン開発では、GDScriptコードファイルとテキストリソースファイルを使用します。フォーマット要件に注意が必要です","ko":"Godot 엔진 개발은 GDScript 코드 파일과 텍스트 리소스 파일을 사용하며, 형식 요구 사항에 주의가 필요합니다","es":"Godot Engine es un motor de juego que utiliza una mezcla de archivos de código GDScript y recursos de texto, con una estructura de archivos única que requiere una colaboración efectiva entre asistentes de codificación LLM","fr":"Godot Engine est un moteur de jeu qui utilise un mélange de fichiers de code GDScript et de ressources de texte, avec une structure de fichiers unique qui nécessite une collaboration efficace entre les assistants de codage LLM","de":"Godot Engine ist ein Spiel-Engine, der eine Mischung aus GDScript-Code-Dateien und Text-Ressourcen verwendet, mit einer einzigartigen Dateistruktur, die eine effektive Zusammenarbeit zwischen LLM-Coding-Assistenten erfordert","pt":"O Godot é um motor de jogo que utiliza GDScript e recursos de texto, permitindo uma colaboração eficaz entre assistentes de codificação e estrutura de arquivos única","ru":"Godot Engine - это игровой движок, который использует GDScript и текстовые ресурсы, обеспечивая эффективное сотрудничество между кодировочными помощниками и уникальной структурой файлов для ИИ Агентов","ar":"محرك Godot هو محرك ألعاب يستخدم GDScript وموارد النص، مما يسمح بالتعاون الفعال بين مساعدي الترميز وهيكل الملفات الفريد للآلات الذكية"},"seo":{"title":{"en":"Godot: Expert Guidance for AI Agents | AI Agent Skill","zh":"Godot Engine 开发最佳实践","ja":"Godot エンジン開発ガイド - AIエージェントとの連携","ko":"Godot 엔진 개발 설정 가이드","es":"Guía de configuración de Godot para desarrolladores","fr":"Guide de mise en route de Godot pour les développeurs","de":"Godot-Setup-Anleitung für Entwickler","pt":"Guia de Configuração do Godot para Desenvolvedores","ru":"Настройка Godot Engine для разработчиков ИИ Агентов","ar":"إعداد محرك Godot لمنشئي أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock Godot''s full potential with specialized guidance for AI coding assistants, ensuring seamless collaboration and effective file structure management.","zh":"了解Godot Engine开发的技术细节，包括GDScript和资源文件的格式要求","ja":"Godotエンジン開発のための技術情報。GDScriptとリソースファイルのフォーマット要件について","ko":"Godot 엔진 개발을 위한 기술 정보. GDScript와 리소스 파일의 형식 요구 사항","es":"Aprende a desarrollar juegos y aplicaciones con Godot Engine, con énfasis en la colaboración efectiva entre asistentes de codificación LLM y la estructura de...","fr":"Découvrez comment développer des jeux et des applications avec Godot Engine, en mettant l''accent sur la collaboration efficace entre les assistants de codage...","de":"Erfahren Sie, wie Sie Spiele und Anwendungen mit Godot Engine entwickeln, mit dem Schwerpunkt auf effektiver Zusammenarbeit zwischen LLM-Coding-Assistenten u...","pt":"Aprenda a configurar o Godot para desenvolver jogos e aplicações com eficácia, utilizando GDScript e recursos de texto","ru":"Узнайте, как настроить Godot Engine для разработки игр и приложений с помощью GDScript и текстовых ресурсов для ИИ Агентов","ar":"تعلم كيفية إعداد محرك Godot لتطوير الألعاب والتطبيقات باستخدام GDScript وموارد النص للآلات الذكية"},"definition":{"en":"Godot is a game engine development skill that offers specialized guidance for developing games and applications with a mix of GDScript code files and text-based resource files.","zh":"Godot Engine是一种游戏引擎，支持GDScript编程语言和特定的资源文件格式","ja":"Godotエンジンは、GDScriptプログラミング言語と特定のリソースファイル形式をサポートするゲームエンジンです","ko":"Godot 엔진은 GDScript 프로그래밍 언어와 특정 리소스 파일 형식을 지원하는 게임 엔진입니다","es":"Godot es un motor de juego de código abierto que utiliza GDScript y recursos de texto para desarrollar juegos y aplicaciones","fr":"Godot est un moteur de jeu open source qui utilise GDScript et des ressources de texte pour développer des jeux et des applications","de":"Godot ist ein Open-Source-Spiel-Engine, der GDScript und Text-Ressourcen verwendet, um Spiele und Anwendungen zu entwickeln","pt":"O Godot é um motor de jogo de código aberto que suporta desenvolvimento de jogos e aplicações com GDScript e recursos de texto","ru":"Godot Engine - это открытый игровой движок, поддерживающий разработку игр и приложений с помощью GDScript и текстовых ресурсов","ar":"محرك Godot هو محرك ألعاب مفتوح المصدر يدعم تطوير الألعاب والتطبيقات باستخدام GDScript وموارد النص"},"features":{"en":["Supports GDScript code files (.gd) for straightforward coding","Manages text-based resource files (.tscn for scenes, .tres for resources) with strict formatting requirements","Enables effective collaboration between LLM coding assistants and Godot''s unique file structure","Handles Godot projects with a mix of code and resource files","Provides guidance on working with Godot''s scene (.tscn) and resource (.tres) files"],"zh":["支持GDScript编程语言","使用特定的资源文件格式（.tscn、.tres）","与AI编码助手的有效协作","严格的资源文件格式要求","混合使用GDScript代码文件和资源文件","适用于游戏和应用程序开发"],"ja":["GDScriptプログラミング言語をサポート","特定のリソースファイル形式（.tscn、.tres）を使用","AIコーディングアシスタントとの効果的なコラボレーション","リソースファイルの厳格なフォーマット要件","GDScriptコードファイルとリソースファイルの混合使用","ゲームおよびアプリケーション開発に適しています"],"ko":["GDScript 프로그래밍 언어 지원","특정 리소스 파일 형식（.tscn、.tres） 사용","AI 코딩 도우미와의 효과적인 협력","리소스 파일의 엄격한 형식 요구 사항","GDScript 코드 파일과 리소스 파일의 혼합 사용","게임 및 애플리케이션 개발에 적합"],"es":["Desarrollo de juegos y aplicaciones con Godot Engine","Colaboración efectiva entre asistentes de codificación LLM y la estructura de archivos única de Godot","Uso de GDScript y recursos de texto para desarrollar juegos y aplicaciones","Compatibilidad con archivos de código GDScript (.gd) y recursos de texto (.tscn, .tres)","Soporte para la creación de escenas y recursos personalizados"],"fr":["Développement de jeux et d''applications avec Godot Engine","Collaboration efficace entre les assistants de codage LLM et la structure de fichiers unique de Godot","Utilisation de GDScript et de ressources de texte pour développer des jeux et des applications","Compatibilité avec les fichiers de code GDScript (.gd) et les ressources de texte (.tscn, .tres)","Prise en charge de la création de scènes et de ressources personnalisées"],"de":["Entwicklung von Spielen und Anwendungen mit Godot Engine","Effektive Zusammenarbeit zwischen LLM-Coding-Assistenten und der einzigartigen Dateistruktur von Godot","Verwendung von GDScript und Text-Ressourcen zur Entwicklung von Spielen und Anwendungen","Kompatibilität mit GDScript-Code-Dateien (.gd) und Text-Ressourcen (.tscn, .tres)","Unterstützung für die Erstellung von benutzerdefinierten Szenen und Ressourcen"],"pt":["Utilização de GDScript para desenvolvimento de jogos e aplicações","Suporte a recursos de texto, incluindo arquivos .tscn e .tres","Colaboração eficaz entre assistentes de codificação e estrutura de arquivos única","Desenvolvimento de jogos e aplicações com eficácia e flexibilidade","Suporte a integração com outras tecnologias e ferramentas de desenvolvimento"],"ru":["Использование GDScript для разработки игр и приложений","Поддержка текстовых ресурсов, включая файлы .tscn и .tres","Эффективное сотрудничество между кодировочными помощниками и уникальной структурой файлов","Разработка игр и приложений с эффективностью и гибкостью","Поддержка интеграции с другими технологиями и инструментами разработки для ИИ Агентов"],"ar":["استخدام GDScript لتطوير الألعاب والتطبيقات","دعم موارد النص، بما في ذلك الملفات .tscn و .tres","التعاون الفعال بين مساعدي الترميز وهيكل الملفات الفريد","تطوير الألعاب والتطبيقات بفعالية ومرونة","دعم التكامل مع تقنيات وأدوات تطوير أخرى للآلات الذكية"]},"keywords":{"en":["how to use godot","godot engine development","godot alternative","godot vs unity","godot install","godot setup guide","gdscript tutorial","godot resource files"],"zh":["Godot Engine","GDScript","游戏引擎","AI编码助手","资源文件格式","游戏开发","应用程序开发","Godot Engine开发最佳实践"],"ja":["Godotエンジン","GDScript","ゲームエンジン","AIコーディングアシスタント","リソースファイル形式","ゲーム開発","アプリケーション開発","Godotエンジン開発ガイド"],"ko":["Godot 엔진","GDScript","게임 엔진","AI 코딩 도우미","리소스 파일 형식","게임 개발","애플리케이션 개발","Godot 엔진 개발 설정 가이드"],"es":["godot engine","desarrollo de juegos","gdscript","recursos de texto","asistentes de codificación LLM","estructura de archivos única","creación de escenas y recursos","motor de juego de código abierto"],"fr":["godot engine","développement de jeux","gdscript","ressources de texte","assistants de codage LLM","structure de fichiers unique","création de scènes et de ressources","moteur de jeu open source"],"de":["godot engine","spielentwicklung","gdscript","text-ressourcen","llm-coding-assistenten","einzigartige dateistruktur","erstellung von szenen und ressourcen","open-source-spiel-engine"],"pt":["Godot","GDScript","recursos de texto","desenvolvimento de jogos","aplicações","assistente de codificação","estrutura de arquivos","motor de jogo","código aberto"],"ru":["Godot Engine","GDScript","текстовые ресурсы","разработка игр","приложения","кодировочный помощник","уникальная структура файлов","игровой движок","открытый код","ИИ Агенты"],"ar":["محرك Godot","GDScript","موارد النص","تطوير الألعاب","التطبيقات","مساعد الترميز","هيكل الملفات الفريد","محرك الألعاب","مفتوح المصدر","الآلات الذكية"]}},"owner":"samsamit","repo":"fgj26-project","repoPath":"samsamit/fgj26-project","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.486Z","topics":[],"category":"community","skillMd":{"name":"godot","description":"This skill should be used when working on Godot Engine projects. It provides specialized knowledge of Godots file formats (.gd, .tscn, .tres), architecture patterns (component-based, signal-driven, resource-based), common pitfalls, validation tools, code templates, and CLI workflows. The `godot` command is available for running the game, validating scripts, importing resources, and exporting builds. Use this skill for tasks involving Godot game development, debugging scene/resource files, implementing game systems, or creating new Godot components.","bodyPreview":"# Godot Engine Development Skill\n\nSpecialized guidance for developing games and applications with Godot Engine, with emphasis on effective collaboration between LLM coding assistants and Godot''s unique file structure.\n\n## Overview\n\nGodot projects use a mix of GDScript code files (.gd) and text-based resource files (.tscn for scenes, .tres for resources). While GDScript is straightforward, the resource files have strict formatting requirements that differ significantly from GDScript syntax. This","body":"# Godot Engine Development Skill\n\nSpecialized guidance for developing games and applications with Godot Engine, with emphasis on effective collaboration between LLM coding assistants and Godot''s unique file structure.\n\n## Overview\n\nGodot projects use a mix of GDScript code files (.gd) and text-based resource files (.tscn for scenes, .tres for resources). While GDScript is straightforward, the resource files have strict formatting requirements that differ significantly from GDScript syntax. This skill provides file format expertise, proven architecture patterns, validation tools, code templates, and debugging workflows to enable effective development of Godot projects.\n\n## When to Use This Skill\n\nInvoke this skill when:\n\n- Working on any Godot Engine project\n- Creating or modifying .tscn (scene) or .tres (resource) files\n- Implementing game systems (interactions, attributes, spells, inventory, etc.)\n- Debugging \"file failed to load\" or similar resource errors\n- Setting up component-based architectures\n- Creating signal-driven systems\n- Implementing resource-based data (items, spells, abilities)\n\n## Key Principles\n\n### 1. Understand File Format Differences\n\n**GDScript (.gd) - Full Programming Language:**\n\n```gdscript\nextends Node\nclass_name MyClass\n\nvar speed: float = 5.0\nconst MAX_HEALTH = 100\n\nfunc _ready():\n    print(\"Ready\")\n```\n\n**Scene Files (.tscn) - Strict Serialization Format:**\n\n```\n[ext_resource type=\"Script\" path=\"res://script.gd\" id=\"1\"]\n\n[node name=\"Player\" type=\"CharacterBody3D\"]\nscript = ExtResource(\"1\")  # NOT preload()!\n```\n\n**Resource Files (.tres) - NO GDScript Syntax:**\n\n```\n[ext_resource type=\"Script\" path=\"res://item.gd\" id=\"1\"]\n\n[resource]\nscript = ExtResource(\"1\")  # NOT preload()!\nitem_name = \"Sword\"        # NOT var item_name = \"Sword\"!\n```\n\n### 2. Critical Rules for .tres and .tscn Files\n\n**NEVER use in .tres/.tscn files:**\n\n- `preload()` - Use `ExtResource(\"id\")` instead\n- `var`, `const`, `func` - These are GDScript keywords\n- Untyped arrays - Use `Array[Type]([...])` syntax\n\n**ALWAYS use in .tres/.tscn files:**\n\n- `ExtResource(\"id\")` for external resources\n- `SubResource(\"id\")` for inline resources\n- Typed arrays: `Array[Resource]([...])`\n- Proper ExtResource declarations before use\n\n### 3. Separation of Concerns\n\n**Keep logic in .gd files, data in .tres files:**\n\n```\nsrc/\n  spells/\n    spell_resource.gd      # Class definition + logic\n    spell_effect.gd        # Effect logic\nresources/\n  spells/\n    fireball.tres          # Data only, references scripts\n    ice_spike.tres         # Data only\n```\n\nThis makes LLM editing much safer and clearer.\n\n### 4. Component-Based Architecture\n\nBreak functionality into small, focused components:\n\n```\nPlayer (CharacterBody3D)\n├─ HealthAttribute (Node)     # Component\n├─ ManaAttribute (Node)        # Component\n├─ Inventory (Node)            # Component\n└─ StateMachine (Node)         # Component\n    ├─ IdleState (Node)\n    ├─ MoveState (Node)\n    └─ AttackState (Node)\n```\n\n**Benefits:**\n\n- Each component is a small, focused file\n- Easy to understand and modify\n- Clear responsibilities\n- Reusable across different entities\n\n### 5. Signal-Driven Communication\n\nUse signals for loose coupling:\n\n```gdscript\n# Component emits signals\nsignal health_changed(current, max)\nsignal death()\n\n# Parent connects to signals\nfunc _ready():\n    $HealthAttribute.health_changed.connect(_on_health_changed)\n    $HealthAttribute.death.connect(_on_death)\n```\n\n**Benefits:**\n\n- No tight coupling between systems\n- Easy to add new listeners\n- Self-documenting (signals show available events)\n- UI can connect without modifying game logic\n\n## Using Bundled Resources\n\n### Validation Scripts\n\nValidate .tres and .tscn files before testing in Godot to catch syntax errors early.\n\n**Validate .tres file:**\n\n```bash\npython3 scripts/validate_tres.py resources/spells/fireball.tres\n```\n\n**Validate .tscn file:**\n\n```bash\npython3 scripts/validate_tscn.py scenes/player/player.tscn\n```\n\nUse these scripts when:\n\n- After creating or editing .tres/.tscn files programmatically\n- When debugging \"failed to load\" errors\n- Before committing scene/resource changes\n- When user reports issues with custom resources\n\n### Reference Documentation\n\nLoad reference files when needed for detailed information:\n\n**`references/file-formats.md`** - Deep dive into .gd, .tscn, .tres syntax:\n\n- Complete syntax rules for each file type\n- Common mistakes with examples\n- Safe vs risky editing patterns\n- ExtResource and SubResource usage\n\n**`references/architecture-patterns.md`** - Proven architectural patterns:\n\n- Component-based interaction system\n- Attribute system (health, mana, etc.)\n- Resource-based effect system (spells, items)\n- Inventory system\n- State machine pattern\n- Examples of combining patterns\n\nRead these references when:\n\n- Implementing new game systems\n- Unsure about .tres/.tscn syntax\n- Debugging file format errors\n- Planning architecture for new features\n\n### Code Templates\n\nUse templates as starting points for common patterns. Templates are in `assets/templates/`:\n\n**`component_template.gd`** - Base component with signals, exports, activation:\n\n```gdscript\n# Copy and customize for new components\ncp assets/templates/component_template.gd src/components/my_component.gd\n```\n\n**`attribute_template.gd`** - Numeric attribute (health, mana, stamina):\n\n```gdscript\n# Use for any numeric attribute with min/max\ncp assets/templates/attribute_template.gd src/attributes/stamina_attribute.gd\n```\n\n**`interaction_template.gd`** - Interaction component base class:\n\n```gdscript\n# Extend for custom interactions (pickup, door, switch, etc.)\ncp assets/templates/interaction_template.gd src/interactions/lever_interaction.gd\n```\n\n**`spell_resource.tres`** - Example spell with effects:\n\n```bash\n# Use as reference for creating new spell data\ncat assets/templates/spell_resource.tres\n```\n\n**`item_resource.tres`** - Example item resource:\n\n```bash\n# Use as reference for creating new item data\ncat assets/templates/item_resource.tres\n```\n\n## Workflows\n\n### Workflow 1: Creating a New Component System\n\nExample: Adding a health system to enemies.\n\n**Steps:**\n\n1. **Read architecture patterns reference:**\n\n   ```bash\n   # Check for similar patterns\n   Read references/architecture-patterns.md\n   # Look for \"Attribute System\" section\n   ```\n\n2. **Create base class using template:**\n\n   ```bash\n   cp assets/templates/attribute_template.gd src/attributes/attribute.gd\n   # Customize the base class\n   ```\n\n3. **Create specialized subclass:**\n\n   ```bash\n   # Create health_attribute.gd extending attribute.gd\n   # Add health-specific signals (damage_taken, death)\n   ```\n\n4. **Add to scene via .tscn edit:**\n\n   ```\n   [ext_resource type=\"Script\" path=\"res://src/attributes/health_attribute.gd\" id=\"4_health\"]\n\n   [node name=\"HealthAttribute\" type=\"Node\" parent=\"Enemy\"]\n   script = ExtResource(\"4_health\")\n   value_max = 50.0\n   value_start = 50.0\n   ```\n\n5. **Test immediately in Godot editor**\n\n6. **If issues, validate the scene file:**\n   ```bash\n   python3 scripts/validate_tscn.py scenes/enemies/base_enemy.tscn\n   ```\n\n### Workflow 2: Creating Resource Data Files (.tres)\n\nExample: Creating a new spell.\n\n**Steps:**\n\n1. **Reference the template:**\n\n   ```bash\n   cat assets/templates/spell_resource.tres\n   ```\n\n2. **Create new .tres file with proper structure:**\n\n   ```tres\n   [gd_resource type=\"Resource\" script_class=\"SpellResource\" load_steps=3 format=3]\n\n   [ext_resource type=\"Script\" path=\"res://src/spells/spell_resource.gd\" id=\"1\"]\n   [ext_resource type=\"Script\" path=\"res://src/spells/spell_effect.gd\" id=\"2\"]\n\n   [sub_resource type=\"Resource\" id=\"Effect_1\"]\n   script = ExtResource(\"2\")\n   effect_type = 0\n   magnitude_min = 15.0\n   magnitude_max = 25.0\n\n   [resource]\n   script = ExtResource(\"1\")\n   spell_name = \"Fireball\"\n   spell_id = \"fireball\"\n   mana_cost = 25.0\n   effects = Array[ExtResource(\"2\")]([SubResource(\"Effect_1\")])\n   ```\n\n3. **Validate before testing:**\n\n   ```bash\n   python3 scripts/validate_tres.py resources/spells/fireball.tres\n   ```\n\n4. **Fix any errors reported by validator**\n\n5. **Test in Godot editor**\n\n### Workflow 3: Debugging Resource Loading Issues\n\nWhen user reports \"resource failed to load\" or similar errors.\n\n**Steps:**\n\n1. **Read the file reported in error:**\n\n   ```bash\n   # Check file syntax\n   Read resources/spells/problem_spell.tres\n   ```\n\n2. **Run validation script:**\n\n   ```bash\n   python3 scripts/validate_tres.py resources/spells/problem_spell.tres\n   ```\n\n3. **Check for common mistakes:**\n\n   - Using `preload()` instead of `ExtResource()`\n   - Using `var`, `const`, `func` keywords\n   - Missing ExtResource declarations\n   - Incorrect array syntax (not typed)\n\n4. **Read file format reference if needed:**\n\n   ```bash\n   Read references/file-formats.md\n   # Focus on \"Resource Files (.tres)\" section\n   # Check \"Common Mistakes Reference\"\n   ```\n\n5. **Fix errors and re-validate**\n\n### Workflow 4: Implementing from Architecture Patterns\n\nWhen implementing a known pattern (interaction system, state machine, etc.).\n\n**Steps:**\n\n1. **Read the relevant pattern:**\n\n   ```bash\n   Read references/architecture-patterns.md\n   # Find the specific pattern (e.g., \"Component-Based Interaction System\")\n   ```\n\n2. **Copy relevant template:**\n\n   ```bash\n   cp assets/templates/interaction_template.gd src/interactions/door_interaction.gd\n   ```\n\n3. **Customize the template:**\n\n   - Override `_perform_interaction()`\n   - Add custom exports for configuration\n   - Add custom signals if needed\n\n4. **Create scene structure following pattern:**\n\n   ```\n   [node name=\"Door\" type=\"StaticBody3D\"]\n   script = ExtResource(\"base_interactable.gd\")\n\n   [node name=\"DoorInteraction\" type=\"Node\" parent=\".\"]\n   script = ExtResource(\"door_interaction.gd\")\n   interaction_text = \"Open Door\"\n   ```\n\n5. **Test incrementally**\n\n## Common Pitfalls and Solutions\n\n### Pitfall 1: Using GDScript Syntax in .tres Files\n\n**Problem:**\n\n```tres\n# ❌ WRONG\nscript = preload(\"res://script.gd\")\nvar items = [1, 2, 3]\n```\n\n**Solution:**\n\n```tres\n# ✅ CORRECT\n[ext_resource type=\"Script\" path=\"res://script.gd\" id=\"1\"]\nscript = ExtResource(\"1\")\nitems = Array[int]([1, 2, 3])\n```\n\n**Prevention:** Run validation script before testing.\n\n### Pitfall 2: Missing ExtResource Declarations\n\n**Problem:**\n\n```tres\n[resource]\nscript = ExtResource(\"1_script\")  # Not declared!\n```\n\n**Solution:**\n\n```tres\n[ext_resource type=\"Script\" path=\"res://script.gd\" id=\"1_script\"]\n\n[resource]\nscript = ExtResource(\"1_script\")\n```\n\n**Detection:** Validation script will catch this.\n\n### Pitfall 3: Editing Complex .tscn Hierarchies\n\n**Problem:** Modifying instanced scene children can break when editor re-saves.\n\n**Solution:**\n\n- Make only simple property edits in .tscn files\n- For complex changes, use Godot editor\n- Test immediately after text edits\n- Use git to track changes and revert if needed\n\n### Pitfall 4: Untyped Arrays in .tres Files\n\n**Problem:**\n\n```tres\neffects = [SubResource(\"Effect_1\")]  # Missing type\n```\n\n**Solution:**\n\n```tres\neffects = Array[Resource]([SubResource(\"Effect_1\")])\n```\n\n**Prevention:** Validation script warns about this.\n\n### Pitfall 5: Forgetting Instance Property Overrides\n\n**Problem:** When instancing a scene, forgetting to override child node properties. The instance uses default values (often `null`), causing silent bugs.\n\n```\n# level.tscn\n[node name=\"KeyPickup\" parent=\".\" instance=ExtResource(\"6_pickup\")]\n# Oops! PickupInteraction.item_resource is null - pickup won''t work!\n```\n\n**Solution:** Always configure instanced scene properties using the `index` syntax:\n\n```\n[node name=\"KeyPickup\" parent=\".\" instance=ExtResource(\"6_pickup\")]\n\n[node name=\"PickupInteraction\" parent=\"KeyPickup\" index=\"0\"]\nitem_resource = ExtResource(\"7_key\")\n```\n\n**Detection:**\n\n- Test the instance in-game immediately\n- Read `references/file-formats.md` \"Instance Property Overrides\" section for details\n- When creating scene instances, ask: \"Does this scene have configurable components that need properties set?\"\n\n**Prevention:** After instancing any scene with configurable children (PickupInteraction, DoorInteraction, etc.), always verify critical properties are overridden.\n\n### Pitfall 6: CPUParticles3D color_ramp Not Displaying Colors\n\n**Problem:** Setting `color_ramp` on CPUParticles3D, but particles still appear white or don''t show the gradient colors.\n\n```tres\n[node name=\"CPUParticles3D\" type=\"CPUParticles3D\" parent=\".\"]\nmesh = SubResource(\"SphereMesh_1\")\ncolor_ramp = SubResource(\"Gradient_1\")  # Gradient is set but doesn''t work!\n```\n\n**Root Cause:** The mesh needs a material with `vertex_color_use_as_albedo = true` to apply particle colors to the mesh surface.\n\n**Solution:** Add a StandardMaterial3D to the mesh with vertex color enabled:\n\n```tres\n[sub_resource type=\"StandardMaterial3D\" id=\"StandardMaterial3D_1\"]\nvertex_color_use_as_albedo = true\n\n[sub_resource type=\"SphereMesh\" id=\"SphereMesh_1\"]\nmaterial = SubResource(\"StandardMaterial3D_1\")\nradius = 0.12\nheight = 0.24\n\n[node name=\"CPUParticles3D\" type=\"CPUParticles3D\" parent=\".\"]\nmesh = SubResource(\"SphereMesh_1\")\ncolor_ramp = SubResource(\"Gradient_1\")  # Now works!\n```\n\n**Prevention:** When creating CPUParticles3D with `color` or `color_ramp`, always add a material with `vertex_color_use_as_albedo = true` to the mesh.\n\n## Best Practices\n\n### 1. Consult References for Common Issues\n\nWhen encountering issues, consult the reference documentation:\n\n**`references/common-pitfalls.md`** - Common Godot gotchas and solutions:\n\n- Initialization and @onready timing issues\n- Node reference and get_node() problems\n- Signal connection issues\n- Resource loading and modification\n- CharacterBody3D movement\n- Transform and basis confusion\n- Input handling\n- Type safety issues\n- Scene instancing pitfalls\n- Tween issues\n\n**`references/godot4-physics-api.md`** - Physics API quick reference:\n\n- Correct raycast API (`PhysicsRayQueryParameters3D`)\n- Shape queries and collision detection\n- Collision layers and masks\n- Area3D vs RigidBody3D vs CharacterBody3D\n- Common physics patterns\n- Performance tips\n\nLoad these when:\n\n- Getting null reference errors\n- Implementing physics/collision systems\n- Debugging timing issues with @onready\n- Working with CharacterBody3D movement\n- Setting up raycasts or shape queries\n\n### 2. Always Validate After Editing .tres/.tscn\n\n```bash\npython3 scripts/validate_tres.py path/to/file.tres\npython3 scripts/validate_tscn.py path/to/file.tscn\n```\n\n### 2. Use Templates as Starting Points\n\nDon''t write components from scratch - adapt templates:\n\n```bash\ncp assets/templates/component_template.gd src/my_component.gd\n```\n\n### 3. Read References for Detailed Syntax\n\nWhen unsure about syntax, load the reference:\n\n```bash\nRead references/file-formats.md\n```\n\n### 4. Follow Separation of Concerns\n\n- Logic → .gd files\n- Data → .tres files\n- Scene structure → .tscn files (prefer editor for complex changes)\n\n### 5. Use Signals for Communication\n\nPrefer signals over direct method calls:\n\n```gdscript\n# ✅ Good - Loose coupling\nsignal item_picked_up(item)\nitem_picked_up.emit(item)\n\n# ❌ Avoid - Tight coupling\nget_parent().get_parent().add_to_inventory(item)\n```\n\n### 6. Test Incrementally\n\nAfter each change:\n\n1. Validate with scripts\n2. Test in Godot editor\n3. Verify functionality\n4. Commit to git\n\n### 7. Use Export Variables Liberally\n\nMake configuration visible and editable:\n\n```gdscript\n@export_group(\"Movement\")\n@export var speed: float = 5.0\n@export var jump_force: float = 10.0\n\n@export_group(\"Combat\")\n@export var damage: int = 10\n```\n\n## Using the Godot CLI\n\nThe `godot` command-line tool is available for running the game and performing various operations without opening the editor.\n\n### Running the Game\n\n**Run the current project:**\n\n```bash\ngodot --path . --headless\n```\n\n**Run a specific scene:**\n\n```bash\ngodot --path . --scene scenes/main_menu.tscn\n```\n\n**Run with debug flags:**\n\n```bash\n# Show collision shapes\ngodot --path . --debug-collisions\n\n# Show navigation debug visuals\ngodot --path . --debug-navigation\n\n# Show path lines\ngodot --path . --debug-paths\n```\n\n### Checking/Validating Code\n\n**Check GDScript syntax without running:**\n\n```bash\ngodot --path . --check-only --script path/to/script.gd\n```\n\n**Run headless tests (for automated testing):**\n\n```bash\ngodot --path . --headless --quit --script path/to/test_script.gd\n```\n\n### Editor Operations from CLI\n\n**Import resources without opening editor:**\n\n```bash\ngodot --path . --import --headless --quit\n```\n\n**Export project:**\n\n```bash\n# Export release build\ngodot --path . --export-release \"Preset Name\" builds/game.exe\n\n# Export debug build\ngodot --path . --export-debug \"Preset Name\" builds/game_debug.exe\n```\n\n### Common CLI Workflows\n\n**Workflow: Quick Test Run**\n\n```bash\n# Run the project and quit after testing\ngodot --path . --quit-after 300  # Runs for 300 frames then quits\n```\n\n**Workflow: Automated Resource Import**\n\n```bash\n# Import all resources and exit (useful in CI/CD)\ngodot --path . --import --headless --quit\n```\n\n**Workflow: Script Validation**\n\n```bash\n# Validate a GDScript file before committing\ngodot --path . --check-only --script src/player/player.gd\n```\n\n**Workflow: Headless Server**\n\n```bash\n# Run as dedicated server (no rendering)\ngodot --path . --headless --scene scenes/multiplayer_server.tscn\n```\n\n### CLI Usage Tips\n\n1. **Always specify `--path .`** when running from project directory to ensure Godot finds `project.godot`\n2. **Use `--headless`** for CI/CD and automated testing (no window, no rendering)\n3. **Use `--quit` or `--quit-after N`** to exit automatically after task completion\n4. **Combine `--check-only` with `--script`** to validate GDScript syntax quickly\n5. **Use debug flags** (`--debug-collisions`, `--debug-navigation`) to visualize systems during development\n6. **Check exit codes** - Non-zero indicates errors (useful for CI/CD scripts)\n\n### Example: Pre-commit Hook for GDScript Validation\n\n```bash\n#!/bin/bash\n# Validate all changed .gd files before committing\n\nfor file in $(git diff --cached --name-only --diff-filter=ACM | grep ''\\.gd$''); do\n    if ! godot --path . --check-only --script \"$file\" --headless --quit; then\n        echo \"GDScript validation failed for $file\"\n        exit 1\n    fi\ndone\n```\n\n## Quick Reference\n\n### File Type Decision Tree\n\n**Writing game logic?** → Use .gd file\n\n**Storing data (item stats, spell configs)?** → Use .tres file\n\n**Creating scene structure?** → Use .tscn file (prefer Godot editor for complex structures)\n\n### Syntax Quick Check\n\n**In .gd files:** Full GDScript - `var`, `func`, `preload()`, etc. ✅\n\n**In .tres/.tscn files:**\n\n- `preload()` ❌ → Use `ExtResource(\"id\")` ✅\n- `var`, `const`, `func` ❌ → Just property values ✅\n- `[1, 2, 3]` ❌ → `Array[int]([1, 2, 3])` ✅\n\n### When to Use Each Validation Script\n\n**`validate_tres.py`** - For resource files:\n\n- Items, spells, abilities\n- Custom resource data\n- After creating .tres files\n\n**`validate_tscn.py`** - For scene files:\n\n- Player, enemies, levels\n- UI scenes\n- After editing .tscn files\n\n### When to Read Each Reference\n\n**`file-formats.md`** - When:\n\n- Creating/editing .tres/.tscn files\n- Getting \"failed to load\" errors\n- Unsure about syntax rules\n\n**`architecture-patterns.md`** - When:\n\n- Implementing new game systems\n- Planning component structure\n- Looking for proven patterns\n\n## Summary\n\nWork with Godot projects effectively by:\n\n1. **Understanding file formats** - .gd is code, .tres/.tscn are data with strict syntax\n2. **Using validation tools** - Catch errors before testing\n3. **Following patterns** - Use proven architectures from references\n4. **Starting from templates** - Adapt rather than create from scratch\n5. **Testing incrementally** - Validate, test, commit frequently\n\nThe key insight: Godot''s text-based files are LLM-friendly when you respect the syntax differences between GDScript and resource serialization formats.\n"},"lastSynced":"2026-03-08T02:10:04.540Z","agentAnalysis":{"suitability":{"en":"Ideal for Game Development Agents requiring expertise in Godot Engine and GDScript coding","zh":"适合需要Godot Engine和GDScript编码专业知识的游戏开发代理","ja":"Godot EngineおよびGDScriptコーディングの専門知識を必要とするゲーム開発エージェントに最適","ko":"Godot Engine 및 GDScript 코딩 전문 지식이 필요한 게임 개발 에이전트에 적합","es":"Ideal para Agentes de Desarrollo de Juegos que requieren experiencia en Godot Engine y codificación en GDScript","fr":"Idéal pour les Agents de Développement de Jeux nécessitant une expertise en Godot Engine et en codage GDScript","de":"Ideal für Game-Development-Agents, die Expertenwissen in Godot Engine und GDScript-Codierung erfordern","pt":"Ideal para Agentes de Desenvolvimento de Jogos que requerem especialização no Godot Engine e codificação em GDScript","ru":"Идеально для агентов разработки игр, требующих опыта работы с Godot Engine и кодирования на GDScript","ar":"مثالي لعميل تطوير الألعاب الذي يتطلب خبرة في Godot Engine وبرمجة GDScript"},"recommendation":{"en":"Empowers agents to collaborate seamlessly with Godot''s unique file structure, leveraging GDScript code files and text-based resource files like .tscn and .tres, to develop complex game applications","zh":"赋予代理无缝地与Godot的独特文件结构进行协作，利用GDScript代码文件和基于文本的资源文件（如.tscn和.tres），以开发复杂的游戏应用","ja":"Godotのユニークなファイル構造とGDScriptコードファイルやテキストベースのリソースファイル（.tscnや.tresなど）を利用して、複雑なゲームアプリケーションを開発するためにエージェントがシームレスに協力できるようにする","ko":"Godot의 고유한 파일 구조와 GDScript 코드 파일 및 텍스트 기반 리소스 파일(.tscn 및 .tres 등)을 활용하여 복잡한 게임 애플리케이션을 개발하기 위해 에이전트가 무중단으로 협업할 수 있도록 하는 것","es":"Habilita a los agentes a colaborar de forma transparente con la estructura de archivos única de Godot, aprovechando archivos de código GDScript y archivos de recursos basados en texto como .tscn y .tres, para desarrollar aplicaciones de juegos complejas","fr":"Permet aux agents de collaborer de manière transparente avec la structure de fichiers unique de Godot, en exploitant les fichiers de code GDScript et les fichiers de ressources basés sur du texte comme .tscn et .tres, pour développer des applications de jeux complexes","de":"Ermächtigt die Agenten, nahtlos mit der einzigartigen Dateistruktur von Godot zusammenzuarbeiten, indem sie GDScript-Code-Dateien und textbasierte Ressourcendateien wie .tscn und .tres nutzen, um komplexe Spielanwendungen zu entwickeln","pt":"Habilita agentes a colaborar perfeitamente com a estrutura de arquivos única do Godot, aproveitando arquivos de código GDScript e arquivos de recursos baseados em texto como .tscn e .tres, para desenvolver aplicações de jogos complexas","ru":"Позволяет агентам бесшовно сотрудничать с уникальной структурой файлов Godot, используя файлы кода GDScript и текстовые файлы ресурсов, такие как .tscn и .tres, для разработки сложных игровых приложений","ar":"تمكين العملاء من التعاون بسلاسة مع هيكل الملفات الفريد لبرنامج Godot، واستخدام ملفات كود GDScript وملفات الموارد القائمة على النص مثل .tscn و .tres، لتطوير تطبيقات الألعاب المعقدة"},"useCases":{"en":["Developing 2D and 3D games with Godot Engine","Generating GDScript code for game logic","Managing scene and resource files in Godot projects"],"zh":["使用Godot Engine开发2D和3D游戏","为游戏逻辑生成GDScript代码","管理Godot项目中的场景和资源文件"],"ja":["Godot Engineを使用した2Dおよび3Dゲームの開発","ゲームロジック用のGDScriptコードの生成","Godotプロジェクト内のシーンとリソースファイルの管理"],"ko":["Godot Engine을 사용한 2D 및 3D 게임 개발","게임 로직을 위한 GDScript 코드 생성","Godot 프로젝트 내의 씬과 리소스 파일 관리"],"es":["Desarrollar juegos 2D y 3D con Godot Engine","Generar código GDScript para lógica de juego","Administrar archivos de escena y recursos en proyectos de Godot"],"fr":["Développer des jeux 2D et 3D avec Godot Engine","Générer du code GDScript pour la logique de jeu","Gérer les fichiers de scène et les ressources dans les projets Godot"],"de":["Entwicklung von 2D- und 3D-Spielen mit Godot Engine","Generierung von GDScript-Code für Spiellogik","Verwaltung von Szene- und Ressourcendateien in Godot-Projekten"],"pt":["Desenvolver jogos 2D e 3D com o Godot Engine","Gerar código GDScript para lógica de jogo","Gerenciar arquivos de cena e recursos em projetos do Godot"],"ru":["Разработка 2D- и 3D-игр с помощью Godot Engine","Генерация кода GDScript для игровой логики","Управление файлами сцены и ресурсами в проектах Godot"],"ar":["تطوير ألعاب 2D و 3D باستخدام Godot Engine","генерация كود GDScript لمنطق اللعبة","إدارة ملفات المشهد والموارد في مشاريع Godot"]},"limitations":{"en":["Requires understanding of GDScript syntax","Compatibility with Godot Engine''s specific file structure and formatting requirements"],"zh":["需要了解GDScript语法","兼容Godot Engine的特定文件结构和格式要求"],"ja":["GDScriptの構文を理解する必要がある","Godot Engineの特定のファイル構造とフォーマット要件との互換性"],"ko":["GDScript 구문을 이해해야 함","Godot Engine의 특정 파일 구조 및 형식 요구 사항과 호환"],"es":["Requiere comprensión de la sintaxis de GDScript","Compatibilidad con la estructura de archivos específica de Godot Engine y los requisitos de formato"],"fr":["Nécessite une compréhension de la syntaxe de GDScript","Compatibilité avec la structure de fichiers spécifique de Godot Engine et les exigences de format"],"de":["Benötigt Verständnis für die GDScript-Syntax","Kompatibilität mit der spezifischen Dateistruktur von Godot Engine und den Formatierungsanforderungen"],"pt":["Exige compreensão da sintaxe do GDScript","Compatibilidade com a estrutura de arquivos específica do Godot Engine e requisitos de formatação"],"ru":["Требует понимания синтаксиса GDScript","Совместимость со специфической структурой файлов Godot Engine и требованиями форматирования"],"ar":["يتطلب فهم بناء الجملة GDScript","التوافق مع هيكل الملفات الخاص لبرنامج Godot Engine ومتطلبات التنسيق"]},"version":4},"contentHash":"42344298a8f1c63ac70753f6775dc68267f468c9a17d3be730de78312bbc6df9","qualityScore":60}');
