INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('OutSystems/docs-product/content-creation-flow', 'content-creation-flow', 'OutSystems', 'docs-product', 'community', 'content-creation-flow OutSystems docs-product community The content-creation-flow skill enables developers to follow a step-by-step content creation process, ensuring all required MCP servers are reachable and operational before starting tasks. It benefits developers working with OutSystems 11. 内容创建流程是一种确保MCP服务器可达性和操作性的步骤式流程，用于创建高质量内容 コンテンツ作成フローは、MCPサーバーの到達性と操作性を確保するためのステップバイステップのプロセスです 컨텐츠 생성 흐름은 MCP 서버의 연결 가능성과 작동 가능성을 보장하는 단계별 프로세스입니다 El flujo de creación de contenido es un proceso que sigue un conjunto de reglas para garantizar la creación de contenido de alta calidad con OutSystems 11 y herramientas de AI Le flux de création de contenu est un processus qui suit un ensemble de règles pour garantir la création de contenu de haute qualité avec OutSystems 11 et des outils d''IA Der Content-Erstellungsprozess ist ein Prozess, der eine Reihe von Regeln befolgt, um die Erstellung von hochwertigem Content mit OutSystems 11 und KI-Tools zu gewährleisten O fluxo de criação de conteúdo é um processo passo-a-passo que garante a segurança e operacionalidade das conexões MCP antes da criação de conteúdo com OutSystems 11. Поток создания контента - это пошаговый процесс, обеспечивающий безопасность и работоспособность подключений MCP перед созданием контента с OutSystems 11 и ИИ Агентами. تدفق إنشاء المحتوى هو عملية متتالية تضمن أمان الاتصالات MCP وعملياتها قبل إنشاء المحتوى مع OutSystems 11 وأدوات الذكاء الاصطناعي how to use content-creation-flow content-creation-flow setup guide OutSystems 11 product documentation MCP connection validation step-by-step content creation flow content-creation-flow alternative content-creation-flow vs OutSystems 10 内容创建流程 MCP服务器 CLI 步骤式流程 AIエージェント 内容生成 Validates MCP connections to ensure servers are reachable and operational Runs status or health checks against specified MCP servers Requires explicit user confirmation before proceeding to the next step Follows a step-by-step content creation flow for OutSystems 11 product documentation Ensures all required MCP servers are operational before starting content creation tasks content-creation-flow is a systematic approach to creating content, involving a series of validated steps, including MCP connection validation and explicit user confirmation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aussiegingersnap/ai-project-start/feature-build', 'community', 'aussiegingersnap', 'ai-project-start', 'aussiegingersnap/ai-project-start', 'feature-build', 0, 0, 60, '2026-03-08T01:57:15.493Z', '2026-03-08T02:10:10.587Z', 'd993c31e5eaa125ab642761037729df0083c20f5012d9077c9917095ae570802', '{"id":"aussiegingersnap/ai-project-start/feature-build","name":"feature-build","description":{"en":"The feature-build skill orchestrates the complete feature development lifecycle, transforming feature requests into shipped, tested, and documented code. It benefits developers by providing clear phases and conversation loop patterns.","zh":"Feature Build 是一个实现功能开发和测试自动化的 AIエージェント，基于清晰的阶段、入口/出口标准和对话循环模式","ja":"Feature Build は、機能開発とテストの自動化を実現する AIエージェントで、明確な段階、入力/出力基準、および対話ループパターンに基づいています","ko":"Feature Build는 기능 개발과 테스트 자동화를 구현하는 AI 에이전트로, 明確한 단계, 입출력 기준 및 대화 루프 패턴을 기반으로 합니다","es":"Feature Build es una habilidad que orquesta el ciclo de vida de desarrollo de características con fases claras y criterios de aceptación. Permite transformar solicitudes de características en código probado y documentado","fr":"Feature Build est une compétence qui orchestre le cycle de vie de développement de fonctionnalités avec des phases claires et des critères d''acceptation. Elle permet de transformer les demandes de fonctionnalités en code testé et documenté","de":"Feature Build ist eine Fähigkeit, die den Entwicklungszyklus von Funktionen mit klaren Phasen und Akzeptanzkriterien orchestriert. Sie ermöglicht die Umwandlung von Funktionsanfragen in getesteten und dokumentierten Code","pt":"O feature-build é uma habilidade que orquestra o ciclo de vida de desenvolvimento de recursos com fases claras e critérios de aceitação.","ru":"Функция feature-build - это навык, который управляет жизненным циклом разработки функций с четкими фазами и критериями приемки.","ar":"ميزة feature-build هي مهارة تحكم دورة حياة تطوير الميزات مع مراحل واضحة ومعايير قبول"},"seo":{"title":{"en":"feature-build: Orchestrating Feature Development Lifecycl...","zh":"Feature Build Setup Guide - AIエージェント","ja":"Feature Build ベストプラクティス - AIエージェント","ko":"Feature Build 개발 가이드 - AI 에이전트","es":"Guía de configuración de Feature Build para desarrolladores","fr":"Mise en place de Feature Build pour les développeurs","de":"Feature Build-Setup-Anleitung für Entwickler","pt":"Guia de Configuração feature-build: Desenvolvimento de Re...","ru":"ИИ Агенты feature-build: Настройка Жизненного Цикла Разра...","ar":"دليل إعداد feature-build: تطوير الميزات مع معايير القبول"},"description":{"en":"Streamline your feature development with feature-build. Learn how to define acceptance criteria, manage UI components, and ship tested code. Get started now!","zh":"使用 Feature Build AIエージェント，实现自动化的功能开发和测试，提高开发效率","ja":"Feature Build AIエージェントを使用して、機能開発とテストを自動化し、開発効率を向上させる","ko":"Feature Build AI 에이전트를 사용하여 자동화된 기능 개발과 테스트를 구현하고 개발 효율을 향상시키세요","es":"Aprende a implementar Feature Build para agilizar el ciclo de vida de desarrollo de características con criterios de aceptación y patrones de conversación","fr":"Découvrez comment mettre en place Feature Build pour accélérer le cycle de vie de développement de fonctionnalités avec des critères d''acceptation et des mod...","de":"Erfahren Sie, wie Sie Feature Build implementieren, um den Entwicklungszyklus von Funktionen mit Akzeptanzkriterien und Konversationsmustern zu beschleunigen","pt":"Aprenda a configurar o feature-build para transformar solicitações de recursos em código testado e documentado com Acceptance Criteria","ru":"Узнайте, как настроить feature-build для chuyểnения запросов функций в протестированный и задокументированный код с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد feature-build لتحويل طلبات الميزات إلى كود مختبَر ومدوّن مع معايير القبول"},"definition":{"en":"feature-build is a skill that automates the feature development lifecycle, emphasizing acceptance criteria and UI component management.","zh":"Feature Build 是一种 AIエージェント，用于自动化功能开发和测试","ja":"Feature Build は、機能開発とテストを自動化する AIエージェントです","ko":"Feature Build는 기능 개발과 테스트를 자동화하는 AI 에이전트입니다","es":"Feature Build es una habilidad de desarrollo que define criterios de aceptación y patrones de conversación para agilizar el ciclo de vida de características","fr":"Feature Build est une compétence de développement qui définit des critères d''acceptation et des modèles de conversation pour accélérer le cycle de vie de fonctionnalités","de":"Feature Build ist eine Entwicklungs-Fähigkeit, die Akzeptanzkriterien und Konversationsmuster definiert, um den Entwicklungszyklus von Funktionen zu beschleunigen","pt":"O que é feature-build? É uma habilidade que define critérios de aceitação para desenvolvimento de recursos.","ru":"Что такое feature-build? Это навык, который определяет критерии приемки для разработки функций.","ar":"ما هي ميزة feature-build؟ هي مهارة تحدد معايير القبول لتطوير الميزات"},"features":{"en":["Defines acceptance criteria first to prevent scope creep","Manages UI components in a style guide for consistency","Orchestrates the complete feature development lifecycle","Enables verification through testable criteria","Transforms feature requests into shipped, tested, and documented code","Utilizes conversation loop patterns for efficient development"],"zh":["基于 Acceptance Criteria First 的功能开发","组件存储在 Style Guide 中","自动化功能开发和测试","清晰的阶段和入口/出口标准","对话循环模式"],"ja":["Acceptance Criteria First に基づく機能開発","コンポーネントは Style Guide に保存される","機能開発とテストの自動化","明確な段階と入力/出力基準","対話ループパターン"],"ko":["Acceptance Criteria First 기반의 기능 개발","컴포넌트는 스타일 가이드에 저장됨","기능 개발과 테스트의 자동화","명확한 단계와 입출력 기준","대화 루프 패턴"],"es":["Definición de criterios de aceptación para prevenir el crecimiento del alcance","Implementación de patrones de conversación para agilizar el ciclo de vida de características","Transformación de solicitudes de características en código probado y documentado","Integración con style guides para garantizar la coherencia de la interfaz de usuario","Soporte para la creación de componentes de interfaz de usuario reutilizables"],"fr":["Définition de critères d''acceptation pour prévenir la croissance de la portée","Mise en place de modèles de conversation pour accélérer le cycle de vie de fonctionnalités","Transformation des demandes de fonctionnalités en code testé et documenté","Intégration avec des guides de style pour garantir la cohérence de l''interface utilisateur","Support pour la création de composants d''interface utilisateur réutilisables"],"de":["Definition von Akzeptanzkriterien, um das Wachstum des Umfangs zu verhindern","Implementierung von Konversationsmustern, um den Entwicklungszyklus von Funktionen zu beschleunigen","Transformation von Funktionsanfragen in getesteten und dokumentierten Code","Integration mit Style-Guides, um die Konsistenz der Benutzeroberfläche zu gewährleisten","Unterstützung für die Erstellung von wiederverwendbaren Benutzeroberflächenkomponenten"],"pt":["Definição de critérios de aceitação antes da escrita de código","Componentes UI vivem no Style Guide","Transformação de solicitações de recursos em código testado e documentado","Orquestração do ciclo de vida de desenvolvimento de recursos com fases claras","Prevenção de scope creep com critérios de aceitação testáveis"],"ru":["Определение критериев приемки до написания кода","Компоненты UI живут в Style Guide","Преобразование запросов функций в протестированный и задокументированный код","Управление жизненным циклом разработки функций с четкими фазами","Предотвращение scope creep с помощью тестируемых критериев приемки"],"ar":["تحديد معايير القبول قبل كتابة الكود","المكونات.UI تعيش في دليل الأسلوب","تحويل طلبات الميزات إلى كود مختبَر ومدوّن","تنسيق دورة حياة تطوير الميزات مع مراحل واضحة","منع scope creep مع معايير القبول القابلة للاختبار"]},"keywords":{"en":["how to use feature-build","what is feature-build","feature-build alternative","feature-build vs agile development","feature-build install","feature-build setup guide","feature-build for AI agents","feature development lifecycle management","acceptance criteria first approach"],"zh":["AIエージェント","功能开发","自动化测试","Acceptance Criteria First","Style Guide","功能开发自动化","测试自动化"],"ja":["AIエージェント","機能開発","自動テスト","Acceptance Criteria First","Style Guide","機能開発自動化","テスト自動化"],"ko":["AI 에이전트","기능 개발","자동화 테스트","Acceptance Criteria First","스타일 가이드","기능 개발 자동화","테스트 자동화"],"es":["Feature Build","desarrollo de características","criterios de aceptación","patrones de conversación","ciclo de vida de desarrollo","agilidad en el desarrollo","herramientas de desarrollo de software","Agentes de IA para desarrolladores"],"fr":["Feature Build","développement de fonctionnalités","critères d''acceptation","modèles de conversation","cycle de vie de développement","agilité dans le développement","outils de développement de logiciels","Agents de l''IA pour les développeurs"],"de":["Feature Build","Entwicklung von Funktionen","Akzeptanzkriterien","Konversationsmuster","Entwicklungszyklus","Agilität in der Entwicklung","Entwicklertools","KI-Agents für Entwickler"],"pt":["feature-build","desenvolvimento de recursos","ciclo de vida de desenvolvimento","critérios de aceitação","Style Guide","prevenção de scope creep","ÍI Agenst","desenvolvimento de software"],"ru":["feature-build","разработка функций","жизненный цикл разработки","критерии приемки","Style Guide","предотвращение scope creep","ИИ Агенты","разработка программного обеспечения"],"ar":["feature-build","تطوير الميزات","دورة حياة التطوير","معايير القبول","دليل الأسلوب","منع scope creep","وكلاء الذكاء الاصطناعي","تطوير البرمجيات"]}},"owner":"aussiegingersnap","repo":"ai-project-start","repoPath":"aussiegingersnap/ai-project-start","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.493Z","topics":[],"category":"community","skillMd":{"name":"feature-build","description":"Complete feature development lifecycle from task selection through commit. Orchestrates component design, build loops with browser testing, PostHog analytics, and documentation updates. Use when building any new feature or enhancement.","bodyPreview":"# Feature Build Skill\n\nOrchestrates the complete feature development lifecycle with clear phases, entry/exit criteria, and conversation loop patterns. This skill transforms feature requests into shipped, tested, and documented code.\n\n## Philosophy\n\n### Core Principles\n\n1. **Acceptance Criteria First** — Define what \"done\" looks like before writing code. Testable criteria prevent scope creep and enable verification.\n\n2. **Components Live in Style Guide** — Every UI component starts in the style-g","body":"# Feature Build Skill\n\nOrchestrates the complete feature development lifecycle with clear phases, entry/exit criteria, and conversation loop patterns. This skill transforms feature requests into shipped, tested, and documented code.\n\n## Philosophy\n\n### Core Principles\n\n1. **Acceptance Criteria First** — Define what \"done\" looks like before writing code. Testable criteria prevent scope creep and enable verification.\n\n2. **Components Live in Style Guide** — Every UI component starts in the style-guide page. This ensures reusability, documents all states, and provides a living reference.\n\n3. **Test What You Build** — Use browser tools to verify each step. Don''t wait until the end to discover issues.\n\n4. **KISS (Keep It Simple, Stupid)** — Implement the simplest solution that meets the criteria. Avoid over-engineering.\n\n5. **Loop Back, Don''t Push Forward** — When something doesn''t work, return to the appropriate phase rather than patching around issues.\n\n### Conversation Loop Model\n\nFeatures are built through phases that can loop back when issues arise:\n\n```\n┌─────────────────────────────────────────────────────────────────┐\n│                                                                 │\n│  ┌──────────┐   ┌──────────┐   ┌──────────┐   ┌──────────────┐ │\n│  │  Task    │──▶│Component │──▶│  Build   │──▶│  Analytics   │ │\n│  │Selection │   │ Design   │   │  Loop    │   │    Setup     │ │\n│  └──────────┘   └──────────┘   └──────────┘   └──────────────┘ │\n│       ▲              │              │               │          │\n│       │              ▼              ▼               ▼          │\n│       │         ◀────────────◀─────────────────────────────────│\n│       │         (loop back if criteria fail)                   │\n│       │                                                        │\n│       │                                     ┌──────────────┐   │\n│       └─────────────────────────────────────│   Commit &   │◀──│\n│                (next feature)               │  Document    │   │\n│                                             └──────────────┘   │\n└─────────────────────────────────────────────────────────────────┘\n```\n\n### Relationship to Other Skills\n\n- **design-system** — Reference for UI patterns, component design principles, style-guide template\n- **feature-gating** — Use when building pro/freemium features with PostHog flags\n- **versioning** — Follow semantic versioning for releases\n\n---\n\n## Phase 1: Task Selection\n\n### Entry Criteria\n- Fresh conversation or user requests a feature\n- TASKS.md exists in project\n\n### Actions\n\n1. **Read TASKS.md** — Identify the next item from Current Sprint\n   ```\n   Read TASKS.md and identify the next unchecked item in Current Sprint\n   ```\n\n2. **Confirm Scope** — Clarify with user what''s included and excluded\n   - What exactly should this feature do?\n   - What should it NOT do?\n   - Are there edge cases to consider?\n\n3. **Break Down if Complex** — Split large features into sub-tasks\n   - Each sub-task should be completable in one conversation\n   - Sub-tasks should have clear dependencies\n\n4. **Define Acceptance Criteria** — Write testable criteria\n\n### Acceptance Criteria Format\n\n```markdown\n### Feature: [Name]\n\n**Acceptance Criteria:**\n- [ ] User can [specific action]\n- [ ] System [specific behavior] when [condition]\n- [ ] Error case: [scenario] displays [message]\n- [ ] Mobile: [behavior] works on viewport < 768px\n```\n\n### Exit Criteria\n- [ ] Feature scope is clearly defined\n- [ ] Acceptance criteria are written and agreed\n- [ ] Sub-tasks identified if feature is complex\n\n---\n\n## Phase 2: Component Design\n\n### Entry Criteria\n- Feature scope is clear\n- Acceptance criteria are defined\n\n### Actions\n\n1. **Check Style Guide First** — Look for existing components that can be reused or extended\n   ```\n   Navigate to /style-guide and snapshot to see existing components\n   ```\n\n2. **Design in Style Guide** — Build new components in the style-guide page\n   - Components should be isolated and reusable\n   - Import from `components/ui/` barrel file\n   - Export new components from barrel file\n\n3. **Show All States** — Document every component state:\n   - Default/resting\n   - Hover/focus\n   - Loading/pending\n   - Success/complete\n   - Error/invalid\n   - Disabled\n   - Empty (if applicable)\n\n4. **Mobile Considerations** — Test responsive behavior\n   - Use PhoneFrame component for mobile mockups if available\n   - Consider touch targets (min 44px)\n\n### Style Guide Section Template\n\n```tsx\n<section id=\"my-component\">\n  <SectionHeader title=\"My Component\" />\n  \n  <div className=\"space-y-6\">\n    <h4 className=\"text-xs font-medium text-muted-foreground uppercase tracking-wide\">\n      Variants\n    </h4>\n    <div className=\"flex flex-wrap gap-3\">\n      <MyComponent variant=\"default\" />\n      <MyComponent variant=\"secondary\" />\n    </div>\n    \n    <h4 className=\"text-xs font-medium text-muted-foreground uppercase tracking-wide\">\n      States\n    </h4>\n    <div className=\"flex flex-wrap gap-3\">\n      <MyComponent loading />\n      <MyComponent disabled />\n      <MyComponent error=\"Error message\" />\n    </div>\n  </div>\n</section>\n```\n\n### Exit Criteria\n- [ ] Components visible in `/style-guide`\n- [ ] All states documented and interactive\n- [ ] Components exported from `components/ui/index.ts`\n- [ ] Responsive behavior verified\n\n---\n\n## Phase 3: Build Loop\n\n### Entry Criteria\n- Components designed and in style-guide\n- Acceptance criteria ready for testing\n\n### Actions\n\n#### 3.1 Backend First\nBuild data layer and API before wiring to UI:\n\n1. **Database schema** — Add migrations if needed\n2. **Service layer** — Business logic functions\n3. **API routes** — REST endpoints with Zod validation\n4. **Test API** — Use browser network panel or curl to verify\n\n#### 3.2 Frontend Integration\nWire components to backend:\n\n1. **State management** — Zustand store or React state\n2. **API hooks** — Data fetching with proper loading/error states\n3. **Component wiring** — Connect UI to state and actions\n\n#### 3.3 Browser Testing\nTest at each step using Cursor browser tools:\n\n```\n1. Navigate to the page being tested\n2. Snapshot to get element references\n3. Interact with elements (click, type, etc.)\n4. Re-snapshot after state changes\n5. Verify expected behavior\n6. Screenshot if visual verification needed\n```\n\n**See `references/testing-patterns.md` for detailed testing scenarios.**\n\n### Testing Checklist by Component Type\n\n**Forms:**\n- [ ] Valid submission works\n- [ ] Validation errors display correctly\n- [ ] Loading state during submission\n- [ ] Success feedback shown\n- [ ] Error handling for API failures\n\n**Lists/Tables:**\n- [ ] Items render correctly\n- [ ] Empty state displays\n- [ ] Pagination/infinite scroll works\n- [ ] CRUD operations update UI\n- [ ] Loading skeleton shows\n\n**Modals/Dialogs:**\n- [ ] Opens on trigger\n- [ ] Closes on backdrop click\n- [ ] Closes on escape key\n- [ ] Form inside modal works\n- [ ] Focus management correct\n\n**Navigation:**\n- [ ] Routes load correctly\n- [ ] Active state shows current page\n- [ ] Mobile menu works\n- [ ] Deep links work\n\n### Loop Back Triggers\n\nReturn to **Phase 2** if:\n- Component needs additional states not designed\n- UI pattern isn''t working as expected\n- Need to refactor component API\n\nReturn to **Phase 1** if:\n- Scope is unclear or expanding\n- Acceptance criteria need revision\n- Feature should be split differently\n\n### Exit Criteria\n- [ ] All acceptance criteria pass in browser\n- [ ] No console errors\n- [ ] Mobile viewport tested (if applicable)\n- [ ] Error states handled gracefully\n\n---\n\n## Phase 4: Analytics Setup\n\n### Entry Criteria\n- Feature is working in browser\n- All acceptance criteria pass\n\n### Actions\n\n1. **Identify Tracking Needs** — What user actions matter?\n\n   | Feature Type | Typical Events |\n   |-------------|----------------|\n   | Form | `{form}_submitted`, `{form}_error` |\n   | Feature | `{feature}_used`, `{feature}_completed` |\n   | Navigation | `{page}_viewed` |\n   | Pro Feature | `{feature}_attempted`, `{feature}_upgrade_shown` |\n\n2. **Implement Events** — Add PostHog capture calls\n   ```typescript\n   posthog.capture(''{feature}_{action}'', {\n     feature: ''feature-name'',\n     // action-specific properties\n   })\n   ```\n\n3. **Create Dashboard (if appropriate)** — Use PostHog MCP tools\n   ```\n   Use mcp_posthog-study-bible_dashboard-create for new dashboards\n   Use mcp_posthog-study-bible_insight-create-from-query for insights\n   ```\n\n4. **Pro Features** — If feature is gated, follow feature-gating skill:\n   - Create PostHog feature flag\n   - Implement `useProFeature()` hook\n   - Track `_attempted`, `_upgrade_shown`, `_upgrade_clicked` events\n\n### Event Naming Convention\n\n```\n{feature}_{action}\n\nExamples:\n- notes_created\n- notes_synced\n- chat_message_sent\n- upgrade_modal_shown\n- model_changed\n```\n\n### Exit Criteria\n- [ ] Key user actions instrumented\n- [ ] Events firing correctly (verify in PostHog)\n- [ ] Dashboard created (if feature warrants it)\n- [ ] Pro feature flags configured (if applicable)\n\n---\n\n## Phase 5: Commit & Document\n\n### Entry Criteria\n- Feature complete and tested\n- Analytics implemented\n\n### Actions\n\n1. **Update TASKS.md**\n   - Move completed items to Completed section\n   - Add completion date\n   - Check off sub-tasks\n   - Add any new backlog items discovered\n\n2. **Update CHANGELOG.md**\n   - Add entry under current version or \"Unreleased\"\n   - Summarize what was added/changed/fixed\n   - Reference any breaking changes\n\n3. **Stage and Commit**\n   - Use conventional commit format\n   - Keep commits atomic (one logical change per commit)\n\n### Conventional Commit Format\n\n```\n<type>(<scope>): <subject>\n\nTypes: feat, fix, docs, style, refactor, perf, test, chore, ci, build, revert\n```\n\n### Commit Summary Block\n\nProvide at end of feature for easy copy-paste:\n\n```markdown\n### Done\n\n**Summary**: [Brief description of what was built]\n\n**Commits** (ohmyzsh):\ngaa && gcmsg \"feat(scope): add feature description\"\ngcmsg \"fix(scope): fix related issue\"\ngp\n```\n\n### TASKS.md Update Pattern\n\n```markdown\n## Completed\n\n- [x] Feature name (YYYY-MM-DD)\n  - [x] Sub-task 1 ✓\n  - [x] Sub-task 2 ✓\n  - [x] Sub-task 3 ✓\n```\n\n### Exit Criteria\n- [ ] TASKS.md updated with completion status\n- [ ] CHANGELOG.md updated with feature summary\n- [ ] Clean commit(s) with conventional format\n- [ ] Ready for next feature\n\n---\n\n## Quick Reference\n\n### Phase Entry/Exit Summary\n\n| Phase | Entry | Exit |\n|-------|-------|------|\n| 1. Task Selection | Feature request | Criteria defined |\n| 2. Component Design | Criteria clear | Components in style-guide |\n| 3. Build Loop | Components ready | All criteria pass |\n| 4. Analytics | Feature working | Events instrumented |\n| 5. Commit | Analytics done | Docs updated, committed |\n\n### Common Commands\n\n```bash\n# Start dev server\nnpm run dev\n\n# Clear Next.js cache if issues\nrm -rf .next\n\n# Rebuild native modules\nnpm rebuild better-sqlite3\n\n# Git workflow (ohmyzsh)\ngaa && gcmsg \"feat(scope): description\"\ngp\n```\n\n### Browser Testing Quick Reference\n\n```\n1. mcp_cursor-ide-browser_browser_navigate → load page\n2. mcp_cursor-ide-browser_browser_snapshot → get elements\n3. mcp_cursor-ide-browser_browser_click/type → interact\n4. mcp_cursor-ide-browser_browser_snapshot → verify changes\n5. mcp_cursor-ide-browser_browser_take_screenshot → visual check\n```\n"},"lastSynced":"2026-03-08T02:10:10.587Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing structured feature development lifecycle management.","zh":"非常适合需要结构化特性开发生命周期管理的开发代理。","ja":"開発エージェントが構造化された機能開発ライフサイクル管理を必要とする場合に最適です。","ko":"구조화된 기능 개발 라이프사이클 관리가 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan un ciclo de vida de desarrollo de características estructurado.","fr":"Parfait pour les agents de développement nécessitant une gestion du cycle de vie de développement de fonctionnalités structurée.","de":"Perfekt für Entwicklungssagenten, die ein strukturiertes Feature-Entwicklungslebenszyklus-Management benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de gestão de ciclo de vida de desenvolvimento de recursos estruturada.","ru":"Идеально для агентов разработки, которым необходима структурированная система управления жизненным циклом разработки функций.","ar":"مثالي لعميل التطوير الذي يحتاج إلى إدارة دورة حياة مُطوّرة مُوجزة للسمات."},"recommendation":{"en":"Empowers agents to transform feature requests into shipped, tested, and documented code using clear phases, entry/exit criteria, and conversation loop patterns, while enforcing acceptance criteria first and organizing components within a style guide.","zh":"赋予代理人使用清晰的阶段、入/出标准和对话循环模式将功能请求转化为已发布、测试和记录的代码的能力，同时首先执行验收标准并在样式指南中组织组件。","ja":"エージェントが機能リクエストを明確なフェーズ、入出基準、会話ループパターンを使用して出荷済み、テスト済み、文書化済みのコードに変換する機能を提供し、最初に受け入れ基準を適用し、スタイルガイド内でコンポーネントを整理します。","ko":"에이전트가 기능 요청을 명확한 단계, 입/출 기준 및 대화 루프 패턴을 사용하여 출荷된 코드, 테스트된 코드 및 문서화된 코드로 변환할 수 있는 기능을 제공하며, 이는 먼저 수락 기준을 적용하고 스타일 가이드 내에서 구성 요소를 조직함으로써 달성됩니다.","es":"Habilita a los agentes a transformar solicitudes de características en código enviado, probado y documentado utilizando fases claras, criterios de entrada/salida y patrones de bucle de conversación, mientras se aplican los criterios de aceptación primero y se organizan los componentes dentro de una guía de estilo.","fr":"Permet aux agents de transformer les demandes de fonctionnalités en code expédié, testé et documenté en utilisant des phases claires, des critères d''entrée/sortie et des modèles de boucle de conversation, tout en imposant les critères d''acceptation en premier et en organisant les composants au sein d''un guide de style.","de":"Ermächtigt Agenten, Anfragen für Funktionen in versandten, getesteten und dokumentierten Code umzuwandeln, indem sie klare Phasen, Ein-/Ausgangskriterien und Konversationsloopmuster verwenden, während sie die Akzeptanzkriterien zuerst durchsetzen und Komponenten innerhalb eines Styleguides organisieren.","pt":"Habilita os agentes a transformar solicitações de recursos em código enviado, testado e documentado usando fases claras, critérios de entrada/saída e padrões de loop de conversa, ao mesmo tempo em que impõe critérios de aceitação primeiro e organiza componentes dentro de um guia de estilo.","ru":"Наделяет агентов возможностью превратить запросы на функции в отправленный, протестированный и задокументированный код, используя четкие фазы, критерии входа/выхода и шаблоны цикла разговора, одновременно обеспечивая соблюдение критериев приемки и организацию компонентов внутри руководства по стилю.","ar":"يُمكّن العميل من تحويل طلبات السمات إلى شفرة مرسلة ومدققة ومدوّنة باستخدام مراحل واضحة ومعيار دخول/خروج وأنماط لاتصال حوار، مع فرض معايير القبول أولاً وتحسين المكونات داخل دليل أسلوب."},"useCases":{"en":["Orchestrating feature development lifecycles with defined acceptance criteria","Creating and managing UI components within a centralized style guide","Streamlining conversation loop patterns for efficient feature development"],"zh":["使用定义的验收标准来编排功能开发生命周期","在集中式样式指南中创建和管理UI组件","为高效的功能开发流程优化对话循环模式"],"ja":["定義された受け入れ基準を使用して機能開発ライフサイクルをオーケストレートする","中央集権的なスタイルガイド内でUIコンポーネントを作成および管理する","機能開発の効率化のための会話ループパターンの最適化"],"ko":["정의된 수락 기준을 사용하여 기능 개발 라이프사이클을 오케스트레이션","중앙 집중식 스타일 가이드 내에서 UI 구성 요소를 생성 및 관리","효율적인 기능 개발을 위한 대화 루프 패턴의 최적화"],"es":["Orquestar ciclos de vida de desarrollo de características con criterios de aceptación definidos","Crear y administrar componentes de UI dentro de una guía de estilo centralizada","Optimizar patrones de bucle de conversación para un desarrollo de características eficiente"],"fr":["Orchestrer les cycles de vie de développement de fonctionnalités avec des critères d''acceptation définis","Créer et gérer des composants d''interface utilisateur au sein d''un guide de style centralisé","Optimiser les modèles de boucle de conversation pour un développement de fonctionnalités efficace"],"de":["Orchestrieren von Entwicklungslebenszyklen für Funktionen mit definierten Akzeptanzkriterien","Erstellen und Verwalten von Benutzeroberflächenkomponenten innerhalb eines zentralen Styleguides","Optimieren von Konversationsloopmustern für einen effizienten Funktionsentwicklung"],"pt":["Orquestração de ciclos de vida de desenvolvimento de recursos com critérios de aceitação definidos","Criação e gerenciamento de componentes de UI dentro de um guia de estilo centralizado","Otimização de padrões de loop de conversa para desenvolvimento de recursos eficiente"],"ru":["Оркестровка жизненных циклов разработки функций с определенными критериями приемки","Создание и управление компонентами UI в рамках централизованного руководства по стилю","Оптимизация шаблонов цикла разговора для эффективной разработки функций"],"ar":["توجيه دورات حياة تطوير السمات مع معايير قبول محددة","إنشاء وإدارة مكونات الواجهة الرسومية داخل دليل أسلوب مركزي","تحسين أنماط لاتصال الحوار من أجل تطوير سمة فعال"]},"limitations":{"en":["Requires defined acceptance criteria for each feature request","Needs a style guide for organizing UI components"],"zh":["每个功能请求都需要定义的验收标准","需要样式指南来组织UI组件"],"ja":["各機能リクエストに定義された受け入れ基準が必要","UIコンポーネントを整理するためのスタイルガイドが必要"],"ko":["각 기능 요청에 정의된 수락 기준이 필요","UI 구성 요소를 조직하기 위한 스타일 가이드가 필요"],"es":["Requiere criterios de aceptación definidos para cada solicitud de característica","Necesita una guía de estilo para organizar componentes de UI"],"fr":["Nécessite des critères d''acceptation définis pour chaque demande de fonctionnalité","A besoin d''un guide de style pour organiser les composants d''interface utilisateur"],"de":["Benötigt definierte Akzeptanzkriterien für jede Funktionsanfrage","Benötigt einen Styleguide zur Organisation von Benutzeroberflächenkomponenten"],"pt":["Exige critérios de aceitação definidos para cada solicitação de recurso","Necessita de um guia de estilo para organizar componentes de UI"],"ru":["Требует определенных критериев приемки для каждого запроса на функцию","Требует руководства по стилю для организации компонентов UI"],"ar":["يتطلب معايير قبول محددة لكل طلب سمة","يحتاج إلى دليل أسلوب لتنظيم مكونات الواجهة الرسومية"]},"version":4},"contentHash":"d993c31e5eaa125ab642761037729df0083c20f5012d9077c9917095ae570802","qualityScore":60}');
