INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aussiegingersnap/ai-project-start/feature-build', 'feature-build', 'aussiegingersnap', 'ai-project-start', 'community', 'feature-build aussiegingersnap ai-project-start community The feature-build skill orchestrates the complete feature development lifecycle, transforming feature requests into shipped, tested, and documented code. It benefits developers by providing clear phases and conversation loop patterns. Feature Build 是一个实现功能开发和测试自动化的 AIエージェント，基于清晰的阶段、入口/出口标准和对话循环模式 Feature Build は、機能開発とテストの自動化を実現する AIエージェントで、明確な段階、入力/出力基準、および対話ループパターンに基づいています Feature Build는 기능 개발과 테스트 자동화를 구현하는 AI 에이전트로, 明確한 단계, 입출력 기준 및 대화 루프 패턴을 기반으로 합니다 Feature Build es una habilidad que orquesta el ciclo de vida de desarrollo de características con fases claras y criterios de aceptación. Permite transformar solicitudes de características en código probado y documentado Feature Build est une compétence qui orchestre le cycle de vie de développement de fonctionnalités avec des phases claires et des critères d''acceptation. Elle permet de transformer les demandes de fonctionnalités en code testé et documenté Feature Build ist eine Fähigkeit, die den Entwicklungszyklus von Funktionen mit klaren Phasen und Akzeptanzkriterien orchestriert. Sie ermöglicht die Umwandlung von Funktionsanfragen in getesteten und dokumentierten Code O feature-build é uma habilidade que orquestra o ciclo de vida de desenvolvimento de recursos com fases claras e critérios de aceitação. Функция feature-build - это навык, который управляет жизненным циклом разработки функций с четкими фазами и критериями приемки. ميزة feature-build هي مهارة تحكم دورة حياة تطوير الميزات مع مراحل واضحة ومعايير قبول how to use feature-build what is feature-build feature-build alternative feature-build vs agile development feature-build install feature-build setup guide feature-build for AI agents feature development lifecycle management acceptance criteria first approach AIエージェント 功能开发 自动化测试 Acceptance Criteria First Style Guide 功能开发自动化 测试自动化 Defines acceptance criteria first to prevent scope creep Manages UI components in a style guide for consistency Orchestrates the complete feature development lifecycle Enables verification through testable criteria Transforms feature requests into shipped, tested, and documented code Utilizes conversation loop patterns for efficient development feature-build is a skill that automates the feature development lifecycle, emphasizing acceptance criteria and UI component management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('patrickclery/ruly/command-to-subagent', 'community', 'patrickclery', 'ruly', 'patrickclery/ruly', 'command-to-subagent', 0, 0, 60, '2026-03-08T01:57:15.501Z', '2026-03-08T02:10:18.222Z', '9cdd2c70682733cc9fc6468672005f999dc087e9af436a822525140efbc586f8', '{"id":"patrickclery/ruly/command-to-subagent","name":"command-to-subagent","description":{"en":"The command-to-subagent skill is a CLI tool for managing AI assistant rules and configurations, benefiting developers by reducing token usage and isolating execution complexity.","zh":"命令到子代理的CLI工具用于管理AI助手规则和配置，通过提取执行逻辑到专用子代理，减少令牌使用并隔离执行复杂性","ja":"コマンドからサブエージェントへの移行のCLIツールは、AIエージェントのルールと構成を管理するために使用され、実行ロジックを専用のサブエージェントに抽出し、トークンの使用量を削減し、実行の複雑さを分離します","ko":"명령어를 서브 에이전트로 전환하는 CLI 도구는 AI 도구의 규칙 및 구성 관리에 사용되며, 실행 로직을専用 서브 에이전트로 추출하여 토큰 사용량을 줄이고 실행 복잡성을 분리합니다","es":"Command-to-subagent es una herramienta de línea de comandos para gestionar reglas y configuraciones de asistentes de AI, reduciendo la complejidad en la ejecución de comandos","fr":"Command-to-subagent est un outil de ligne de commande pour gérer les règles et les configurations des assistants d''IA, réduisant la complexité dans l''exécution des commandes","de":"Command-to-subagent ist ein CLI-Tool für die Verwaltung von Regeln und Konfigurationen von AI-Assistenten, reduziert die Komplexität bei der Ausführung von Befehlen","pt":"O command-to-subagent é uma ferramenta CLI para gerenciar regras e configurações de assistentes de AI, isolando a complexidade de API/MCP","ru":"Command-to-subagent - это инструмент CLI для управления правилами и конфигурациями ИИ-ассистентов, изолирующий сложность API/MCP","ar":"command-to-subagent هو أداة سطر أوامر لتدبير قواعد وتكوين مساعدي الإتصال الاصطناعي، معزolaً تعقيدات API/MCP"},"seo":{"title":{"en":"command-to-subagent: Setup Guide for AI Agents | CLI Tool","zh":"命令到子代理设置指南 - CLI 工具最佳实践","ja":"コマンドからサブエージェントへの移行ガイド - AIエージェントのCLIツール","ko":"명령어를 서브 에이전트로 전환하는 방법 - CLI 도구 설정 가이드","es":"Guía de configuración de command-to-subagent para herrami...","fr":"Guide de mise en place de command-to-subagent pour les ou...","de":"Einrichtungsleitfaden für command-to-subagent in AI-Tools","pt":"Guia de Configuração do command-to-subagent para Ferramen...","ru":"Настройка команды command-to-subagent для ИИ Агентов","ar":"دليل إعداد command-to-subagent لأدوات الإتصال الاصطناعي"},"description":{"en":"Discover how to extract execution logic with command-to-subagent. Learn to reduce recipe context and isolate API/MCP complexity. Get started now!","zh":"了解如何使用命令到子代理的CLI工具简化AI助手规则和配置管理，减少令牌使用并隔离执行复杂性","ja":"AIエージェントのCLIツールを使用して、コマンドからサブエージェントへの移行を簡素化し、トークンの使用量を削減し、実行の複雑さを分離する方法を学びます","ko":"명령어를 서브 에이전트로 전환하는 CLI 도구를 사용하여 AI 도구의 규칙 및 구성 관리를 단순화하고 토큰 사용량을 줄이고 실행 복잡성을 분리하는 방법에 대해 알아보세요","es":"Optimice sus herramientas de AI con command-to-subagent, reduzca la complejidad y mejore la eficiencia en la ejecución de comandos","fr":"Optimisez vos outils d''IA avec command-to-subagent, réduisez la complexité et améliorez l''efficacité de l''exécution des commandes","de":"Optimieren Sie Ihre AI-Tools mit command-to-subagent, reduzieren Sie die Komplexität und verbessern Sie die Effizienz bei der Ausführung von Befehlen","pt":"Aprenda a extrair a lógica de execução de comandos para subagentes dedicados com o command-to-subagent, reduzindo a complexidade de recipes","ru":"Изучите, как извлечь логику выполнения команд в посвященных субагентах с помощью command-to-subagent, уменьшая сложность рецептов","ar":"تعلم كيفية استخراج منطق التنفيذ للأوامر إلى وكلاء فرعيون مخصصون باستخدام command-to-subagent، وتقليل تعقيد الوصفات"},"definition":{"en":"command-to-subagent is a CLI tool that extracts execution logic from a command into a dedicated subagent, simplifying user-facing workflows.","zh":"命令到子代理是指将命令的执行逻辑提取到专用子代理的过程，用于简化AI助手规则和配置管理","ja":"コマンドからサブエージェントへの移行は、コマンドの実行ロジックを専用のサブエージェントに抽出するプロセスであり、AIエージェントのルールと構成を管理するために使用されます","ko":"명령어를 서브 에이전트로 전환하는 것은 명령어의 실행 로직을専用 서브 에이전트로 추출하는过程로서, AI 도구의 규칙 및 구성 관리를 단순화하는 데 사용됩니다","es":"Command-to-subagent es una técnica para extraer la lógica de ejecución de un comando en un subagente dedicado","fr":"Command-to-subagent est une technique pour extraire la logique d''exécution d''une commande dans un sous-agent dédié","de":"Command-to-subagent ist eine Technik, um die Ausführungslogik eines Befehls in einen dedizierten Subagent zu extrahieren","pt":"O command-to-subagent é uma técnica para extrair lógica de execução de comandos para subagentes dedicados","ru":"Command-to-subagent - это техника для извлечения логики выполнения команд в посвященных субагентах","ar":"command-to-subagent هو تقنية لاستخراج منطق التنفيذ للأوامر إلى وكلاء فرعيون مخصصون"},"features":{"en":["Extracts execution logic from commands into dedicated subagents","Reduces recipe context by isolating API/MCP complexity","Supports preview, confirmation, and execution patterns","Helps reduce token usage in recipes","Isolates execution complexity from user workflow"],"zh":["提取执行逻辑到专用子代理","减少令牌使用量","隔离执行复杂性","支持preview、confirmation和execute模式","简化AI助手规则和配置管理"],"ja":["実行ロジックを専用のサブエージェントに抽出","トークンの使用量を削減","実行の複雑さを分離","プレビュー、確認、実行モードをサポート","AIエージェントのルールと構成を管理するためのCLIツール"],"ko":["실행 로직을専用 서브 에이전트로 추출","토큰 사용량을 줄임","실행 복잡성을 분리","프리뷰, 확인, 실행 모드를 지원","AI 도구의 규칙 및 구성 관리를 위한 CLI 도구"],"es":["Reducir la complejidad en la ejecución de comandos","Mejorar la eficiencia en la utilización de tokens","Isolar la complejidad de la lógica de ejecución","Seguir el patrón de preview, confirmación y ejecución","Utilizar una herramienta de línea de comandos para gestionar reglas y configuraciones"],"fr":["Réduire la complexité dans l''exécution des commandes","Améliorer l''efficacité dans l''utilisation des tokens","Isoler la complexité de la logique d''exécution","Suivre le modèle de preview, confirmation et exécution","Utiliser un outil de ligne de commande pour gérer les règles et les configurations"],"de":["Komplexität bei der Ausführung von Befehlen reduzieren","Effizienz bei der Verwendung von Tokens verbessern","Komplexität der Ausführungslogik isolieren","Vorgehensmodell von Vorschau, Bestätigung und Ausführung befolgen","CLI-Tool für die Verwaltung von Regeln und Konfigurationen verwenden"],"pt":["Extração de lógica de execução de comandos para subagentes dedicados","Redução da complexidade de recipes","Isolamento de complexidade de API/MCP","Suporte a padrão de preview, confirmação e execução","Integração com ferramentas de linha de comando"],"ru":["Извлечение логики выполнения команд в посвященных субагентах","Уменьшение сложности рецептов","Изоляция сложности API/MCP","Поддержка шаблона предварительного просмотра, подтверждения и выполнения","Интеграция с инструментами командной строки"],"ar":["استخراج منطق التنفيذ للأوامر إلى وكلاء فرعيون مخصصون","تقليل تعقيد الوصفات","عزل تعقيدات API/MCP","دعم نمط المعاينة والتأكيد والتنفيذ","التكامل مع أدوات سطر الأوامر"]},"keywords":{"en":["how to use command-to-subagent","command-to-subagent setup guide","what is command-to-subagent","command-to-subagent alternative","command-to-subagent vs other CLI tools","command-to-subagent install","reducing token usage in recipes","isolating API/MCP complexity","CLI tools for AI agents"],"zh":["命令到子代理","CLI工具","AI助手规则","配置管理","令牌使用量","执行复杂性","preview","confirmation","execute"],"ja":["コマンドからサブエージェントへの移行","CLIツール","AIエージェントのルール","構成管理","トークンの使用量","実行の複雑さ","プレビュー","確認","実行"],"ko":["명령어를 서브 에이전트로 전환","CLI 도구","AI 도구의 규칙","구성 관리","토큰 사용량","실행 복잡성","프리뷰","확인","실행"],"es":["command-to-subagent","herramientas de AI","reglas de asistentes de AI","configuraciones de AI","reducir complejidad en comandos","mejorar eficiencia en tokens","patrón de preview y confirmación"],"fr":["command-to-subagent","outils d''IA","règles d''assistants d''IA","configurations d''IA","réduire la complexité dans les commandes","améliorer l''efficacité dans les tokens","modèle de preview et de confirmation"],"de":["command-to-subagent","AI-Tools","Regeln von AI-Assistenten","Konfigurationen von AI","Komplexität bei der Ausführung von Befehlen reduzieren","Effizienz bei der Verwendung von Tokens verbessern","Vorgehensmodell von Vorschau und Bestätigung"],"pt":["command-to-subagent","ferramentas de AI","CLI","gerenciamento de regras","configuração de assistentes de AI","redução de complexidade","isolamento de complexidade","subagentes dedicados"],"ru":["command-to-subagent","ИИ Агенты","CLI","управление правилами","конфигурация ИИ-ассистентов","уменьшение сложности","изоляция сложности","посвященные субагенты"],"ar":["command-to-subagent","أدوات الإتصال الاصطناعي","CLI","إدارة القواعد","تكوين مساعدي الإتصال الاصطناعي","تقليل التعقيد","عزل التعقيد","وكلاء فرعيون مخصصون"]}},"owner":"patrickclery","repo":"ruly","repoPath":"patrickclery/ruly","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.501Z","topics":[],"category":"community","skillMd":{"name":"command-to-subagent","description":"Use when converting a Ruly command to use subagent execution, when a command has heavy MCP/API logic that should be isolated, or when asked to make this a subagent","bodyPreview":"# Converting Commands to Subagents\n\n## Overview\n\nExtract execution logic from a command into a dedicated subagent, keeping only the user-facing workflow (preview, confirmation) in the command. This reduces recipe context by isolating API/MCP complexity.\n\n## When to Use\n\n- Command has heavy MCP or API call logic\n- Want to reduce token usage in a recipe\n- Need to isolate execution complexity from user workflow\n- Command follows preview → confirm → execute pattern\n\n## Quick Reference\n\n| Component |","body":"# Converting Commands to Subagents\n\n## Overview\n\nExtract execution logic from a command into a dedicated subagent, keeping only the user-facing workflow (preview, confirmation) in the command. This reduces recipe context by isolating API/MCP complexity.\n\n## When to Use\n\n- Command has heavy MCP or API call logic\n- Want to reduce token usage in a recipe\n- Need to isolate execution complexity from user workflow\n- Command follows preview → confirm → execute pattern\n\n## Quick Reference\n\n| Component | Location | Contains |\n|-----------|----------|----------|\n| Command | `commands/{name}.md` | User workflow (preview, confirm, dispatch) |\n| Subagent | `agents/{name}.md` | Execution logic (MCP calls, API operations) |\n| Recipe | `recipes.yml` | Subagent registration |\n\n## Conversion Steps\n\n### Step 1: Identify the Split Point\n\nFind where user interaction ends and execution begins:\n\n```\nUser workflow (COMMAND):     Execution (SUBAGENT):\n├─ Parse input               ├─ API/MCP calls\n├─ Validate/lookup           ├─ Error handling\n├─ Show preview              ├─ Response formatting\n├─ Handle revisions          └─ Return structured result\n└─ Dispatch on confirm\n```\n\n**Split at confirmation** - everything after \"send it\" / \"post it\" goes to subagent.\n\n### Step 2: Create the Subagent File\n\nLocation: `rules/{domain}/agents/{name}.md`\n\n**Structure:**\n```markdown\n---\ndescription: Instructions for the {name} subagent when dispatched\nalwaysApply: true\nrequires:\n  - ../common.md        # Shared patterns\n  - ../../accounts.md   # If needs user lookups\n---\n# {Name} Subagent - EXECUTION REQUIRED\n\n## ⚠️ CRITICAL: You MUST Execute\n\n**Your ONLY job is to {action}.** If you complete with \"0 tool uses\", you have FAILED.\n\n## Input Format\n\nYou will receive a prompt like:\n{show expected input structure}\n\n## Execution Steps\n\n### Step 1: {First action}\n{MCP/API call with example}\n\n### Step 2: {Next action}\n...\n\n### Step N: Return Result\n\n**On success:**\n```json\n{\"status\": \"success\", \"field\": \"value\"}\n```\n\n**On error:**\n```json\n{\"status\": \"error\", \"error\": \"message\", \"step\": \"which failed\"}\n```\n\n## Failure Conditions\n\n❌ **FAILED** if you:\n- Complete with \"0 tool uses\"\n- Return without executing\n- Ask clarifying questions\n\n✅ **SUCCESS** if you:\n- Execute all required steps\n- Return structured result\n```\n\n### Step 3: Update the Command\n\nRemove execution logic, add subagent dispatch:\n\n**Before (inline execution):**\n```markdown\n### Step 4: Send Message\nmcp__teams__send_chat_message with:\n- chatId: ...\n```\n\n**After (dispatch to subagent):**\n```markdown\n### Step 4: Dispatch Subagent\n\nWhen user confirms, dispatch the `{subagent_name}` subagent:\n\nTask tool:\n  subagent_type: \"{subagent_name}\"\n  prompt: |\n    {Action}:\n    - Field1: {value1}\n    - Field2: {value2}\n\n### Step 5: Show Result\n\nDisplay the subagent''s response:\n- On success: ✅ {success message}\n- On error: ❌ {error message}\n```\n\n### Step 4: Register in Recipe\n\nAdd to `recipes.yml`:\n\n```yaml\n# Subagent recipe (what the subagent gets loaded with)\n{subagent-name}:\n  description: \"{Action} (subagent execution)\"\n  files:\n    - /path/to/agents/{name}.md\n    - /path/to/common.md\n    - /path/to/accounts.md  # if needed\n  mcp_servers:\n    - {required-mcp}\n\n# Parent recipes that use the command\n{parent-recipe}:\n  files:\n    - /path/to/commands/{name}.md\n  subagents:\n    - name: {subagent_name}  # underscores for Task tool\n      recipe: {subagent-name}  # hyphens for recipe name\n```\n\n### Step 5: Sync Config Files\n\n```bash\ncp recipes.yml ~/.config/ruly/recipes.yml\ncp recipes.yml ~/Projects/chezmoi/config/ruly/recipes.yml\n```\n\n## Example: MS Teams DM\n\n**Before:** `dm.md` had all Teams MCP logic inline\n\n**After:**\n- `commands/dm.md` - Preview workflow, dispatches on \"send it\"\n- `agents/ms-teams-dm.md` - Teams MCP execution\n\n**Recipe registration:**\n```yaml\nms-teams-dm:\n  files:\n    - rules/comms/ms-teams/agents/ms-teams-dm.md\n    - rules/comms/ms-teams/common.md\n  mcp_servers:\n    - teams\n\ncomms:\n  files:\n    - rules/comms/ms-teams/commands/dm.md\n  subagents:\n    - name: ms_teams_dm\n      recipe: ms-teams-dm\n```\n\n## Common Mistakes\n\n| Mistake | Fix |\n|---------|-----|\n| Subagent asks questions | Add \"EXECUTION REQUIRED\" header, forbid questions |\n| Subagent returns without acting | Add \"0 tool uses = FAILED\" warning |\n| Missing MCP server in recipe | Subagent can''t call APIs without `mcp_servers` |\n| Forgot to sync config files | Always sync to `~/.config/ruly/` and chezmoi |\n| Using wrong name format | Recipe names: hyphens. Task tool names: underscores |\n\n## Directory Convention\n\n```\nrules/{domain}/\n├── common.md           # Shared patterns\n├── commands/\n│   └── {name}.md       # User-facing command\n└── agents/\n    └── {name}.md       # Subagent execution\n```\n\n- `commands/` = User-invocable via `/command-name`\n- `agents/` = Dispatched programmatically (not user-invocable)\n"},"lastSynced":"2026-03-08T02:10:18.222Z","agentAnalysis":{"suitability":{"en":"Ideal for CLI-based AI Agents seeking to optimize token usage and simplify execution complexity through subagent management.","zh":"适用于基于CLI的AI代理，旨在优化令牌使用和通过子代理管理简化执行复杂性。","ja":"CLIベースのAIエージェントがトークンの使用を最適化し、サブエージェントの管理を通じて実行の複雑さを簡素化するのに適しています。","ko":"CLI 기반의 AI 에이전트가 토큰 사용을 최적화하고 서브 에이전트 관리를 통해 실행 복잡성을 단순화하려는 경우에 적합합니다.","es":"Ideal para agentes de IA basados en CLI que buscan optimizar el uso de tokens y simplificar la complejidad de ejecución a través de la gestión de subagentes.","fr":"Idéal pour les agents d''IA basés sur CLI cherchant à optimiser l''utilisation de jetons et à simplifier la complexité d''exécution via la gestion de sous-agents.","de":"Ideal für CLI-basierte KI-Agents, die den Tokenverbrauch optimieren und die Ausführungskomplexität durch Subagenten-Verwaltung vereinfachen möchten.","pt":"Ideal para agentes de IA baseados em CLI que buscam otimizar o uso de tokens e simplificar a complexidade de execução por meio do gerenciamento de subagentes.","ru":"Идеально подходит для агентов ИИ, основанных на CLI, которые стремятся оптимизировать использование токенов и упростить сложность выполнения через управление субагентами.","ar":"مثالي لعميل الوكيل الذكي الذي يعتمد على واجهة سطر الأوامر لتحسين استخدام الرموز والتبسيط من تعقيد التنفيذ من خلال إدارة الوكيل الفرعي."},"recommendation":{"en":"Empowers agents to reduce recipe context by isolating API and MCP complexity, leveraging preview, confirmation, and execution patterns to streamline workflows with reduced token usage, making it a valuable addition for agents utilizing command-line interfaces and token-based interactions.","zh":"赋予代理简化工作流程的能力，通过隔离API和MCP的复杂性，利用预览、确认和执行模式来简化工作流程，减少令牌使用，使其成为使用命令行接口和令牌交互的代理的宝贵补充。","ja":"エージェントにワークフローを簡素化する能力を付与し、APIおよびMCPの複雑さを分離し、プレビュー、確認、実行パターンを利用してワークフローを簡素化し、トークンの使用を削減することで、コマンドラインインターフェイスおよびトークンベースの相互作用を使用するエージェントにとって貴重な補足となります。","ko":"에이전트가 워크플로우를 단순화할 수 있도록 하여 API 및 MCP의 복잡성을 분리하고 미리 보기, 확인 및 실행 패턴을 활용하여 워크플로우를 간소화하고 토큰 사용을 줄여서 명령줄 인터페이스 및 토큰 기반 상호 작용을 사용하는 에이전트에게 귀중한 보완이 됩니다.","es":"Permite a los agentes reducir el contexto de la receta aislado la complejidad de la API y MCP, aprovechando los patrones de vista previa, confirmación y ejecución para simplificar los flujos de trabajo con un uso reducido de tokens, lo que lo convierte en un valioso complemento para los agentes que utilizan interfaces de línea de comandos y interacciones basadas en tokens.","fr":"Permet aux agents de réduire le contexte de la recette en isolant la complexité de l''API et de la MCP, en exploitant les modèles d''aperçu, de confirmation et d''exécution pour rationaliser les flux de travail avec une utilisation réduite de jetons, ce qui en fait un ajout précieux pour les agents utilisant des interfaces en ligne de commande et des interactions basées sur des jetons.","de":"Ermächtigt Agenten, den Rezeptkontext durch Isolierung der API- und MCP-Komplexität zu reduzieren, indem sie Vorschau-, Bestätigungs- und Ausführungsmuster nutzen, um Arbeitsabläufe mit reduziertem Tokenverbrauch zu rationalisieren, was es zu einer wertvollen Ergänzung für Agenten macht, die Kommandozeilen-Interfaces und tokenbasierte Interaktionen nutzen.","pt":"Habilita os agentes a reduzir o contexto da receita, isolando a complexidade da API e MCP, aproveitando padrões de visualização, confirmação e execução para simplificar os fluxos de trabalho com uso reduzido de tokens, tornando-se uma adição valiosa para agentes que utilizam interfaces de linha de comando e interações baseadas em tokens.","ru":"Наделяет агентов возможностью уменьшить контекст рецепта, изолируя сложность API и MCP, используя шаблоны предварительного просмотра, подтверждения и выполнения для оптимизации рабочих процессов с уменьшенным использованием токенов, что делает его ценным дополнением для агентов, использующих интерфейсы командной строки и токен-ориентированное взаимодействие.","ar":"يتمكن الوكيل من تقليل سياق الوصفة من خلال عزل تعقيدات API و MCP، والاستفادة من أنماط المعاينة والتأكيد والتنفيذ لتبسيط سير العمل مع استخدام رموز مخفض، مما يجعله إضافة قيمة للوكلاء الذين يستخدمون واجهات سطر الأوامر والتفاعلات القائمة على الرموز."},"useCases":{"en":["Isolating execution complexity from user-facing workflows","Reducing token usage in recipes with heavy API or MCP logic","Converting commands into dedicated subagents for streamlined execution"],"zh":["从面向用户的工作流程中隔离执行复杂性","在具有大量API或MCP逻辑的配方中减少令牌使用","将命令转换为专用子代理以简化执行"],"ja":["ユーザー向けのワークフローから実行の複雑さを分離する","APIまたはMCPロジックが大量にあるレシピでトークンの使用量を削減する","コマンドを専用のサブエージェントに変換して実行を簡素化する"],"ko":["사용자向け 워크플로우에서 실행 복잡성을 분리","大量의 API 또는 MCP 로직이 있는 레시피에서 토큰 사용량을 줄임","명령을専用 서브 에이전트로 변환하여 실행을 단순화"],"es":["Aislamiento de la complejidad de ejecución de los flujos de trabajo orientados al usuario","Reducción del uso de tokens en recetas con lógica API o MCP pesada","Conversión de comandos en subagentes dedicados para una ejecución simplificada"],"fr":["Isolement de la complexité d''exécution des flux de travail orientés utilisateur","Réduction de l''utilisation de jetons dans les recettes avec une logique API ou MCP lourde","Conversion de commandes en sous-agents dédiés pour une exécution rationalisée"],"de":["Isolierung der Ausführungskomplexität von benutzerorientierten Workflows","Reduzierung des Tokenverbrauchs in Rezepten mit schwerer API- oder MCP-Logik","Umwandlung von Befehlen in dedizierte Subagenten für eine rationalisierte Ausführung"],"pt":["Isolar a complexidade de execução dos fluxos de trabalho orientados para o usuário","Reduzir o uso de tokens em receitas com lógica API ou MCP pesada","Converter comandos em subagentes dedicados para execução simplificada"],"ru":["Изолировать сложность выполнения от пользовательских рабочих процессов","Уменьшить использование токенов в рецептах с тяжелой логикой API или MCP","Преобразовать команды в выделенные субагенты для упрощенного выполнения"],"ar":["عزل تعقيدات التنفيذ من سير العمل الموجهة للمستخدم","تقليل استخدام الرموز في الوصفات التي تحتوي على منطق API أو MCPثقيل","تحويل الأوامر إلى وكلاء فرعيين مخصصين للتنفيذ المبسّط"]},"limitations":{"en":["Requires command logic to follow preview, confirmation, and execution patterns","Beneficial primarily for commands with heavy MCP or API call logic"],"zh":["需要命令逻辑遵循预览、确认和执行模式","主要适用于具有大量MCP或API调用逻辑的命令"],"ja":["コマンドロジックがプレビュー、確認、実行パターンに従う必要がある","主にMCPまたはAPIコールロジックが多いコマンドに有益"],"ko":["명령 논리가 미리 보기, 확인 및 실행 패턴을 따르도록 하는 필요","주로 MCP 또는 API 호출 로직이 많은 명령에 유용"],"es":["Requiere que la lógica de comando siga los patrones de vista previa, confirmación y ejecución","Beneficioso principalmente para comandos con lógica MCP o API pesada"],"fr":["Exige que la logique de commande suive les modèles d''aperçu, de confirmation et d''exécution","Bénéfique principalement pour les commandes avec une logique MCP ou API lourde"],"de":["Benötigt, dass die Befehlslogik den Mustern von Vorschau, Bestätigung und Ausführung folgt","Vorteilhaft vor allem für Befehle mit schwerer MCP- oder API-Logik"],"pt":["Exige que a lógica do comando siga os padrões de visualização, confirmação e execução","É benéfico principalmente para comandos com lógica MCP ou API de chamada pesada"],"ru":["Требует, чтобы логика команды следовала шаблонам предварительного просмотра, подтверждения и выполнения","Преимущественно полезен для команд с тяжелой логикой MCP или API вызовов"],"ar":["يتطلب أن تتبع منطق الأوامر أنماط المعاينة والتأكيد والتنفيذ","مفيد بشكل رئيسي للأوامر التي تحتوي على منطق MCP أو API مكثف"]},"version":4},"contentHash":"9cdd2c70682733cc9fc6468672005f999dc087e9af436a822525140efbc586f8","qualityScore":60}');
DELETE FROM skills_fts WHERE id = 'patrickclery/ruly/command-to-subagent';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('patrickclery/ruly/command-to-subagent', 'command-to-subagent', 'patrickclery', 'ruly', 'community', 'command-to-subagent patrickclery ruly community The command-to-subagent skill is a CLI tool for managing AI assistant rules and configurations, benefiting developers by reducing token usage and isolating execution complexity. 命令到子代理的CLI工具用于管理AI助手规则和配置，通过提取执行逻辑到专用子代理，减少令牌使用并隔离执行复杂性 コマンドからサブエージェントへの移行のCLIツールは、AIエージェントのルールと構成を管理するために使用され、実行ロジックを専用のサブエージェントに抽出し、トークンの使用量を削減し、実行の複雑さを分離します 명령어를 서브 에이전트로 전환하는 CLI 도구는 AI 도구의 규칙 및 구성 관리에 사용되며, 실행 로직을専用 서브 에이전트로 추출하여 토큰 사용량을 줄이고 실행 복잡성을 분리합니다 Command-to-subagent es una herramienta de línea de comandos para gestionar reglas y configuraciones de asistentes de AI, reduciendo la complejidad en la ejecución de comandos Command-to-subagent est un outil de ligne de commande pour gérer les règles et les configurations des assistants d''IA, réduisant la complexité dans l''exécution des commandes Command-to-subagent ist ein CLI-Tool für die Verwaltung von Regeln und Konfigurationen von AI-Assistenten, reduziert die Komplexität bei der Ausführung von Befehlen O command-to-subagent é uma ferramenta CLI para gerenciar regras e configurações de assistentes de AI, isolando a complexidade de API/MCP Command-to-subagent - это инструмент CLI для управления правилами и конфигурациями ИИ-ассистентов, изолирующий сложность API/MCP command-to-subagent هو أداة سطر أوامر لتدبير قواعد وتكوين مساعدي الإتصال الاصطناعي، معزolaً تعقيدات API/MCP how to use command-to-subagent command-to-subagent setup guide what is command-to-subagent command-to-subagent alternative command-to-subagent vs other CLI tools command-to-subagent install reducing token usage in recipes isolating API/MCP complexity CLI tools for AI agents 命令到子代理 CLI工具 AI助手规则 配置管理 令牌使用量 执行复杂性 preview confirmation execute Extracts execution logic from commands into dedicated subagents Reduces recipe context by isolating API/MCP complexity Supports preview, confirmation, and execution patterns Helps reduce token usage in recipes Isolates execution complexity from user workflow command-to-subagent is a CLI tool that extracts execution logic from a command into a dedicated subagent, simplifying user-facing workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('danburonline/public-writings/scientific-writing', 'community', 'danburonline', 'public-writings', 'danburonline/public-writings', 'scientific-writing', 0, 0, 60, '2026-03-08T01:57:15.502Z', '2026-03-08T02:10:19.074Z', '5a3e0eece58981384b763b6cdb68fe1744aa4549d239b46c40079b720edece31', '{"id":"danburonline/public-writings/scientific-writing","name":"scientific-writing","description":{"en":"The scientific writing skill enables developers to generate well-formatted research manuscripts with comprehensive literature search and verified citations. It benefits AI agents and researchers who need to communicate complex research with clarity.","zh":"科学写作AI工具结合AI驱动的深度研究和格式化输出，用于研究论文的撰写","ja":"科学的な文章作成ツールは、AI駆動の深度研究と形式化された出力を組み合わせて研究論文を作成する","ko":"과학적 글쓰기 도구는 AI駆動의 심층 연구와 서식된 출력을 결합하여 연구 논문을 작성하는 데 사용됩니다","es":"La escritura científica es un proceso para comunicar investigaciones con precisión y claridad, utilizando estructuras IMRAD y citas APA/AMA/Vancouver","fr":"L''écriture scientifique est un processus pour communiquer des recherches avec précision et clarté, en utilisant des structures IMRAD et des citations APA/AMA/Vancouver","de":"Das wissenschaftliche Schreiben ist ein Prozess, um Forschungsergebnisse mit Präzision und Klarheit zu kommunizieren, unter Verwendung von IMRAD-Strukturen und Zitaten im APA/AMA/Vancouver-Stil","pt":"A escrita científica é um processo para comunicar pesquisas com precisão e clareza, utilizando estrutura IMRAD e citações APA/AMA/Vancouver","ru":"Научная письменность - это процесс для передачи исследований с точностью и ясностью, используя структуру IMRAD и цитаты APA/AMA/Vancouver","ar":"الكتابة العلمية هي عملية للتواصل مع الأبحاث بدقة ووضوح، باستخدام هيكل IMRAD واقتباسات APA/AMA/Vancouver"},"seo":{"title":{"en":"Scientific Writing: AI-Driven Research Setup Guide | AI A...","zh":"科学写作工具集成指南 - AIエージェント","ja":"科学的な文章作成ツールのベストプラクティス - AIエージェント","ko":"과학적 글쓰기 도구 설정 가이드 - AI 에이전트","es":"Guía de configuración para escritura científica con herra...","fr":"Guide de mise en place pour l''écriture scientifique avec ...","de":"Einrichtungsleitfaden für wissenschaftliches Schreiben mi...","pt":"Guia de Configuração de Escrita Científica com Ferramenta...","ru":"Настройка научной письменности с помощью ИИ Агентов","ar":"دليل إعداد الكتابة العلمية باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock precise research writing with our scientific writing skill, featuring IMRAD structure and verified citations - get started now!","zh":"使用科学写作AI工具，结合深度研究和格式化输出，提高研究论文的质量和效率","ja":"AIエージェントを使用した科学的な文章作成ツールにより、研究論文の品質と効率を向上させる","ko":"과학적 글쓰기 AI 도구를 사용하여 연구 논문의 품질과 효율성을 높이는 방법","es":"Aprende a utilizar herramientas de AI para mejorar tu escritura científica con nuestra guía detallada","fr":"Découvrez comment utiliser des outils d''IA pour améliorer votre écriture scientifique avec notre guide détaillé","de":"Erfahren Sie, wie Sie KI-Tools verwenden können, um Ihr wissenschaftliches Schreiben zu verbessern, mit unserer detaillierten Anleitung","pt":"Aprenda a utilizar a escrita científica com ferramentas de IA para produzir manuscripts de alta qualidade com citações verificadas e estrutura IMRAD","ru":"Изучите научную письменность с помощью ИИ Агентов для создания высококачественных рукописей с проверенными цитатами и структурой IMRAD","ar":"تعرف على كيفية استخدام الكتابة العلمية مع أدوات الذكاء الاصطناعي لإنتاج مخطوطات عالية الجودة مع اقتباسات موثوقة وهيكل IMRAD"},"definition":{"en":"Scientific writing is a process for communicating research with precision and clarity, using formats like IMRAD structure and citations in APA/AMA/Vancouver styles.","zh":"科学写作是指使用AI工具辅助研究论文的撰写，确保内容的准确性和清晰度","ja":"科学的な文章作成とは、AIツールを使用して研究論文を作成し、内容の正確性と明瞭性を確保すること","ko":"과학적 글쓰기는 AI 도구를 사용하여 연구 논문을 작성하고 내용의 정확성과 명확성을 보장하는 것을 말합니다","es":"La escritura científica es una técnica para comunicar resultados de investigación de manera clara y precisa","fr":"L''écriture scientifique est une technique pour communiquer des résultats de recherche de manière claire et précise","de":"Das wissenschaftliche Schreiben ist eine Technik, um Forschungsergebnisse auf klare und präzise Weise zu kommunizieren","pt":"Escrita científica é a criação de documentos de pesquisa com precisão e clareza, utilizando ferramentas de IA para melhorar a qualidade","ru":"Научная письменность - это создание документов исследований с точностью и ясностью, используя ИИ Агенты для улучшения качества","ar":"الكتابة العلمية هي إنشاء وثائق بحث بدقة ووضوح، باستخدام أدوات الذكاء الاصطناعي لتحسين الجودة"},"features":{"en":["Generates manuscripts using IMRAD structure","Supports citations in APA, AMA, and Vancouver styles","Includes comprehensive literature search through research-lookup skill","Produces well-formatted written outputs with figures and tables","Utilizes verified citations for accuracy and reliability"],"zh":["支持IMRAD结构的研究论文撰写","提供APA、AMA、Vancouver等多种引用样式","包含深度研究和文献检索功能","支持图表和报告指南的添加","确保内容的准确性和清晰度"],"ja":["IMRAD構造の研究論文作成をサポート","APA、AMA、Vancouverなどの複数の引用スタイルを提供","深度研究と文献検索機能を含む","図表と報告ガイドラインの追加をサポート","内容の正確性と明瞭性を確保"],"ko":["IMRAD 구조의 연구 논문 작성 지원","APA, AMA, Vancouver 등의 여러 가지 인용 스타일 제공","심층 연구와 문헌 검색 기능 포함","도표와 보고 지침 추가 지원","내용의 정확성과 명확성을 보장"],"es":["Estructura IMRAD para escritura científica","Citas en estilo APA/AMA/Vancouver","Búsqueda de literatura y verificación de citas a través de la habilidad de búsqueda de investigación","Generación de manuscritos con figuras y tablas","Informes basados en directrices de investigación"],"fr":["Structure IMRAD pour l''écriture scientifique","Citations dans le style APA/AMA/Vancouver","Recherche de littérature et vérification de citations via la compétence de recherche","Génération de manuscrits avec des figures et des tableaux","Rapports basés sur des directives de recherche"],"de":["IMRAD-Struktur für wissenschaftliches Schreiben","Zitierstile im APA/AMA/Vancouver-Stil","Literatursuche und Zitierüberprüfung durch die Forschungssuche-Fähigkeit","Erstellung von Manuskripten mit Abbildungen und Tabellen","Berichte basierend auf Forschungsrichtlinien"],"pt":["Estrutura IMRAD para manuscripts","Citações verificadas através da pesquisa-lookup","Suporte a citações APA/AMA/Vancouver","Inclusão de figuras e tabelas","Relatórios de diretrizes de pesquisa"],"ru":["Структура IMRAD для рукописей","Проверенные цитаты через исследование-поиск","Поддержка цитат APA/AMA/Vancouver","Включение рисунков и таблиц","Отчеты о руководящих принципах исследования"],"ar":["هيكل IMRAD لمخطوطات","اقتباسات موثوقة من خلال البحث-البحث","دعم اقتباسات APA/AMA/Vancouver","إدراج الرسومات والجداول","تقارير إرشادات البحث"]},"keywords":{"en":["how to use scientific writing","scientific writing setup guide","what is scientific writing","scientific writing alternative","scientific writing vs research writing","install scientific writing skill","IMRAD structure tutorial","APA citation style guide"],"zh":["科学写作AI工具","研究论文撰写","深度研究","文献检索","IMRAD结构","APA引用样式","AMA引用样式","Vancouver引用样式","图表添加","报告指南"],"ja":["科学的な文章作成AIツール","研究論文作成","深度研究","文献検索","IMRAD構造","APA引用スタイル","AMA引用スタイル","Vancouver引用スタイル","図表追加","報告ガイドライン"],"ko":["과학적 글쓰기 AI 도구","연구 논문 작성","심층 연구","문헌 검색","IMRAD 구조","APA 인용 스타일","AMA 인용 스타일","Vancouver 인용 스타일","도표 추가","보고 지침"],"es":["escritura científica con AI","herramientas de AI para escritura científica","guía de escritura científica","estructura IMRAD","citas APA/AMA/Vancouver","búsqueda de literatura","manuscritos científicos"],"fr":["écriture scientifique avec IA","outils d''IA pour l''écriture scientifique","guide d''écriture scientifique","structure IMRAD","citations APA/AMA/Vancouver","recherche de littérature","manuscrits scientifiques"],"de":["wissenschaftliches Schreiben mit KI","KI-Tools für wissenschaftliches Schreiben","Anleitung für wissenschaftliches Schreiben","IMRAD-Struktur","Zitierstile im APA/AMA/Vancouver-Stil","Literatursuche","wissenschaftliche Manuskripte"],"pt":["escrita científica","ferramentas de IA","manuscripts de pesquisa","citações verificadas","estrutura IMRAD","IA para pesquisa","ferramentas de escrita científica"],"ru":["научная письменность","ИИ Агенты","рукописи исследования","проверенные цитаты","структура IMRAD","ИИ для исследования","инструменты научной письменности"],"ar":["الكتابة العلمية","أدوات الذكاء الاصطناعي","مخطوطات البحث","اقتباسات موثوقة","هيكل IMRAD","الذكاء الاصطناعي للبحث","أدوات الكتابة العلمية"]}},"owner":"danburonline","repo":"public-writings","repoPath":"danburonline/public-writings","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.502Z","topics":[],"category":"community","skillMd":{"name":"scientific-writing","description":"Core skill for the deep research and writing tool. Write scientific manuscripts in full paragraphs (never bullet points). Use two-stage process: (1) create section outlines with key points using research-lookup, (2) convert to flowing prose. IMRAD structure, citations (APA/AMA/Vancouver), figures/tables, reporting guidelines (CONSORT/STROBE/PRISMA), for research papers and journal submissions.","bodyPreview":"# Scientific Writing\n\n## Overview\n\n**This is the core skill for the deep research and writing tool**—combining AI-driven deep research with well-formatted written outputs. Every document produced is backed by comprehensive literature search and verified citations through the research-lookup skill.\n\nScientific writing is a process for communicating research with precision and clarity. Write manuscripts using IMRAD structure, citations (APA/AMA/Vancouver), figures/tables, and reporting guidelines","body":"# Scientific Writing\n\n## Overview\n\n**This is the core skill for the deep research and writing tool**—combining AI-driven deep research with well-formatted written outputs. Every document produced is backed by comprehensive literature search and verified citations through the research-lookup skill.\n\nScientific writing is a process for communicating research with precision and clarity. Write manuscripts using IMRAD structure, citations (APA/AMA/Vancouver), figures/tables, and reporting guidelines (CONSORT/STROBE/PRISMA). Apply this skill for research papers and journal submissions.\n\n**Critical Principle: Always write in full paragraphs with flowing prose. Never submit bullet points in the final manuscript.** Use a two-stage process: first create section outlines with key points using research-lookup, then convert those outlines into complete paragraphs.\n\n## When to Use This Skill\n\nThis skill should be used when:\n- Writing or revising any section of a scientific manuscript (abstract, introduction, methods, results, discussion)\n- Structuring a research paper using IMRAD or other standard formats\n- Formatting citations and references in specific styles (APA, AMA, Vancouver, Chicago, IEEE)\n- Creating, formatting, or improving figures, tables, and data visualizations\n- Applying study-specific reporting guidelines (CONSORT for trials, STROBE for observational studies, PRISMA for reviews)\n- Drafting abstracts that meet journal requirements (structured or unstructured)\n- Preparing manuscripts for submission to specific journals\n- Improving writing clarity, conciseness, and precision\n- Ensuring proper use of field-specific terminology and nomenclature\n- Addressing reviewer comments and revising manuscripts\n\n## Visual Enhancement with Scientific Schematics\n\n**⚠️ MANDATORY: Every scientific paper MUST include at least 1-2 AI-generated figures using the scientific-schematics skill.**\n\nThis is not optional. Scientific papers without visual elements are incomplete. Before finalizing any document:\n1. Generate at minimum ONE schematic or diagram using scientific-schematics\n2. Prefer 2-3 figures for comprehensive papers (methods flowchart, results visualization, conceptual diagram)\n\n**How to generate figures:**\n- Use the **scientific-schematics** skill to generate AI-powered publication-quality diagrams\n- Simply describe your desired diagram in natural language\n- Nano Banana Pro will automatically generate, review, and refine the schematic\n\n**How to generate schematics:**\n```bash\npython scripts/generate_schematic.py \"your diagram description\" -o figures/output.png\n```\n\nThe AI will automatically:\n- Create publication-quality images with proper formatting\n- Review and refine through multiple iterations\n- Ensure accessibility (colorblind-friendly, high contrast)\n- Save outputs in the figures/ directory\n\n**When to add schematics:**\n- Study design and methodology flowcharts (CONSORT, PRISMA, STROBE)\n- Conceptual framework diagrams\n- Experimental workflow illustrations\n- Data analysis pipeline diagrams\n- Biological pathway or mechanism diagrams\n- System architecture visualizations\n- Any complex concept that benefits from visualization\n\nFor detailed guidance on creating schematics, refer to the scientific-schematics skill documentation.\n\n---\n\n## Core Capabilities\n\n### 1. Manuscript Structure and Organization\n\n**IMRAD Format**: Guide papers through the standard Introduction, Methods, Results, And Discussion structure used across most scientific disciplines. This includes:\n- **Introduction**: Establish research context, identify gaps, state objectives\n- **Methods**: Detail study design, populations, procedures, and analysis approaches\n- **Results**: Present findings objectively without interpretation\n- **Discussion**: Interpret results, acknowledge limitations, propose future directions\n\nFor detailed guidance on IMRAD structure, refer to `references/imrad_structure.md`.\n\n**Alternative Structures**: Support discipline-specific formats including:\n- Review articles (narrative, systematic, scoping)\n- Case reports and case series\n- Meta-analyses and pooled analyses\n- Theoretical/modeling papers\n- Methods papers and protocols\n\n### 2. Section-Specific Writing Guidance\n\n**Abstract Composition**: Craft concise, standalone summaries (100-250 words) that capture the paper''s purpose, methods, results, and conclusions. Support both structured abstracts (with labeled sections) and unstructured single-paragraph formats.\n\n**Introduction Development**: Build compelling introductions that:\n- Establish the research problem''s importance\n- Review relevant literature systematically\n- Identify knowledge gaps or controversies\n- State clear research questions or hypotheses\n- Explain the study''s novelty and significance\n\n**Methods Documentation**: Ensure reproducibility through:\n- Detailed participant/sample descriptions\n- Clear procedural documentation\n- Statistical methods with justification\n- Equipment and materials specifications\n- Ethical approval and consent statements\n\n**Results Presentation**: Present findings with:\n- Logical flow from primary to secondary outcomes\n- Integration with figures and tables\n- Statistical significance with effect sizes\n- Objective reporting without interpretation\n\n**Discussion Construction**: Synthesize findings by:\n- Relating results to research questions\n- Comparing with existing literature\n- Acknowledging limitations honestly\n- Proposing mechanistic explanations\n- Suggesting practical implications and future research\n\n### 3. Citation and Reference Management\n\nApply citation styles correctly across disciplines. For comprehensive style guides, refer to `references/citation_styles.md`.\n\n**Major Citation Styles:**\n- **AMA (American Medical Association)**: Numbered superscript citations, common in medicine\n- **Vancouver**: Numbered citations in square brackets, biomedical standard\n- **APA (American Psychological Association)**: Author-date in-text citations, common in social sciences\n- **Chicago**: Notes-bibliography or author-date, humanities and sciences\n- **IEEE**: Numbered square brackets, engineering and computer science\n\n**Best Practices:**\n- Cite primary sources when possible\n- Include recent literature (last 5-10 years for active fields)\n- Balance citation distribution across introduction and discussion\n- Verify all citations against original sources\n- Use reference management software (Zotero, Mendeley, EndNote)\n\n### 4. Figures and Tables\n\nCreate effective data visualizations that enhance comprehension. For detailed best practices, refer to `references/figures_tables.md`.\n\n**When to Use Tables vs. Figures:**\n- **Tables**: Precise numerical data, complex datasets, multiple variables requiring exact values\n- **Figures**: Trends, patterns, relationships, comparisons best understood visually\n\n**Design Principles:**\n- Make each table/figure self-explanatory with complete captions\n- Use consistent formatting and terminology across all display items\n- Label all axes, columns, and rows with units\n- Include sample sizes (n) and statistical annotations\n- Follow the \"one table/figure per 1000 words\" guideline\n- Avoid duplicating information between text, tables, and figures\n\n**Common Figure Types:**\n- Bar graphs: Comparing discrete categories\n- Line graphs: Showing trends over time\n- Scatterplots: Displaying correlations\n- Box plots: Showing distributions and outliers\n- Heatmaps: Visualizing matrices and patterns\n\n### 5. Reporting Guidelines by Study Type\n\nEnsure completeness and transparency by following established reporting standards. For comprehensive guideline details, refer to `references/reporting_guidelines.md`.\n\n**Key Guidelines:**\n- **CONSORT**: Randomized controlled trials\n- **STROBE**: Observational studies (cohort, case-control, cross-sectional)\n- **PRISMA**: Systematic reviews and meta-analyses\n- **STARD**: Diagnostic accuracy studies\n- **TRIPOD**: Prediction model studies\n- **ARRIVE**: Animal research\n- **CARE**: Case reports\n- **SQUIRE**: Quality improvement studies\n- **SPIRIT**: Study protocols for clinical trials\n- **CHEERS**: Economic evaluations\n\nEach guideline provides checklists ensuring all critical methodological elements are reported.\n\n### 6. Writing Principles and Style\n\nApply fundamental scientific writing principles. For detailed guidance, refer to `references/writing_principles.md`.\n\n**Clarity**:\n- Use precise, unambiguous language\n- Define technical terms and abbreviations at first use\n- Maintain logical flow within and between paragraphs\n- Use active voice when appropriate for clarity\n\n**Conciseness**:\n- Eliminate redundant words and phrases\n- Favor shorter sentences (15-20 words average)\n- Remove unnecessary qualifiers\n- Respect word limits strictly\n\n**Accuracy**:\n- Report exact values with appropriate precision\n- Use consistent terminology throughout\n- Distinguish between observations and interpretations\n- Acknowledge uncertainty appropriately\n\n**Objectivity**:\n- Present results without bias\n- Avoid overstating findings or implications\n- Acknowledge conflicting evidence\n- Maintain professional, neutral tone\n\n### 7. Writing Process: From Outline to Full Paragraphs\n\n**CRITICAL: Always write in full paragraphs, never submit bullet points in scientific papers.**\n\nScientific papers must be written in complete, flowing prose. Use this two-stage approach for effective writing:\n\n**Stage 1: Create Section Outlines with Key Points**\n\nWhen starting a new section:\n1. Use the research-lookup skill to gather relevant literature and data\n2. Create a structured outline with bullet points marking:\n   - Main arguments or findings to present\n   - Key studies to cite\n   - Data points and statistics to include\n   - Logical flow and organization\n3. These bullet points serve as scaffolding—they are NOT the final manuscript\n\n**Example outline (Introduction section):**\n```\n- Background: AI in drug discovery gaining traction\n  * Cite recent reviews (Smith 2023, Jones 2024)\n  * Traditional methods are slow and expensive\n- Gap: Limited application to rare diseases\n  * Only 2 prior studies (Lee 2022, Chen 2023)\n  * Small datasets remain a challenge\n- Our approach: Transfer learning from common diseases\n  * Novel architecture combining X and Y\n- Study objectives: Validate on 3 rare disease datasets\n```\n\n**Stage 2: Convert Key Points to Full Paragraphs**\n\nOnce the outline is complete, expand each bullet point into proper prose:\n\n1. **Transform bullet points into complete sentences** with subjects, verbs, and objects\n2. **Add transitions** between sentences and ideas (however, moreover, in contrast, subsequently)\n3. **Integrate citations naturally** within sentences, not as lists\n4. **Expand with context and explanation** that bullet points omit\n5. **Ensure logical flow** from one sentence to the next within each paragraph\n6. **Vary sentence structure** to maintain reader engagement\n\n**Example conversion to prose:**\n\n```\nArtificial intelligence approaches have gained significant traction in drug discovery \npipelines over the past decade (Smith, 2023; Jones, 2024). While these computational \nmethods show promise for accelerating the identification of therapeutic candidates, \ntraditional experimental approaches remain slow and resource-intensive, often requiring \nyears of laboratory work and substantial financial investment. However, the application \nof AI to rare diseases has been limited, with only two prior studies demonstrating \nproof-of-concept results (Lee, 2022; Chen, 2023). The primary obstacle has been the \nscarcity of training data for conditions affecting small patient populations. \n\nTo address this challenge, we developed a transfer learning approach that leverages \nknowledge from well-characterized common diseases to predict therapeutic targets for \nrare conditions. Our novel neural architecture combines convolutional layers for \nmolecular feature extraction with attention mechanisms for protein-ligand interaction \nmodeling. The objective of this study was to validate our approach across three \nindependent rare disease datasets, assessing both predictive accuracy and biological \ninterpretability of the results.\n```\n\n**Key Differences Between Outlines and Final Text:**\n\n| Outline (Planning Stage) | Final Manuscript |\n|--------------------------|------------------|\n| Bullet points and fragments | Complete sentences and paragraphs |\n| Telegraphic notes | Full explanations with context |\n| List of citations | Citations integrated into prose |\n| Abbreviated ideas | Developed arguments with transitions |\n| For your eyes only | For publication and peer review |\n\n**Common Mistakes to Avoid:**\n\n- ❌ **Never** leave bullet points in the final manuscript\n- ❌ **Never** submit lists where paragraphs should be\n- ❌ **Don''t** use numbered or bulleted lists in Results or Discussion sections (except for specific cases like study hypotheses or inclusion criteria)\n- ❌ **Don''t** write sentence fragments or incomplete thoughts\n- ✅ **Do** use occasional lists only in Methods (e.g., inclusion/exclusion criteria, materials lists)\n- ✅ **Do** ensure every section flows as connected prose\n- ✅ **Do** read paragraphs aloud to check for natural flow\n\n**When Lists ARE Acceptable (Limited Cases):**\n\nLists may appear in scientific papers only in specific contexts:\n- **Methods**: Inclusion/exclusion criteria, materials and reagents, participant characteristics\n- **Supplementary Materials**: Extended protocols, equipment lists, detailed parameters\n- **Never in**: Abstract, Introduction, Results, Discussion, Conclusions\n\n**Integration with Research Lookup:**\n\nThe research-lookup skill is essential for Stage 1 (creating outlines):\n1. Search for relevant papers using research-lookup\n2. Extract key findings, methods, and data\n3. Organize findings as bullet points in your outline\n4. Then convert the outline to full paragraphs in Stage 2\n\nThis two-stage process ensures you:\n- Gather and organize information systematically\n- Create logical structure before writing\n- Produce polished, publication-ready prose\n- Maintain focus on the narrative flow\n\n### 8. Journal-Specific Formatting\n\nAdapt manuscripts to journal requirements:\n- Follow author guidelines for structure, length, and format\n- Apply journal-specific citation styles\n- Meet figure/table specifications (resolution, file formats, dimensions)\n- Include required statements (funding, conflicts of interest, data availability, ethical approval)\n- Adhere to word limits for each section\n- Format according to template requirements when provided\n\n### 9. Field-Specific Language and Terminology\n\nAdapt language, terminology, and conventions to match the specific scientific discipline. Each field has established vocabulary, preferred phrasings, and domain-specific conventions that signal expertise and ensure clarity for the target audience.\n\n**Identify Field-Specific Linguistic Conventions:**\n- Review terminology used in recent high-impact papers in the target journal\n- Note field-specific abbreviations, units, and notation systems\n- Identify preferred terms (e.g., \"participants\" vs. \"subjects,\" \"compound\" vs. \"drug,\" \"specimens\" vs. \"samples\")\n- Observe how methods, organisms, or techniques are typically described\n\n**Biomedical and Clinical Sciences:**\n- Use precise anatomical and clinical terminology (e.g., \"myocardial infarction\" not \"heart attack\" in formal writing)\n- Follow standardized disease nomenclature (ICD, DSM, SNOMED-CT)\n- Specify drug names using generic names first, brand names in parentheses if needed\n- Use \"patients\" for clinical studies, \"participants\" for community-based research\n- Follow Human Genome Variation Society (HGVS) nomenclature for genetic variants\n- Report lab values with standard units (SI units in most international journals)\n\n**Molecular Biology and Genetics:**\n- Use italics for gene symbols (e.g., *TP53*), regular font for proteins (e.g., p53)\n- Follow species-specific gene nomenclature (uppercase for human: *BRCA1*; sentence case for mouse: *Brca1*)\n- Specify organism names in full at first mention, then use accepted abbreviations (e.g., *Escherichia coli*, then *E. coli*)\n- Use standard genetic notation (e.g., +/+, +/-, -/- for genotypes)\n- Employ established terminology for molecular techniques (e.g., \"quantitative PCR\" or \"qPCR,\" not \"real-time PCR\")\n\n**Chemistry and Pharmaceutical Sciences:**\n- Follow IUPAC nomenclature for chemical compounds\n- Use systematic names for novel compounds, common names for well-known substances\n- Specify chemical structures using standard notation (e.g., SMILES, InChI for databases)\n- Report concentrations with appropriate units (mM, μM, nM, or % w/v, v/v)\n- Describe synthesis routes using accepted reaction nomenclature\n- Use terms like \"bioavailability,\" \"pharmacokinetics,\" \"IC50\" consistently with field definitions\n\n**Ecology and Environmental Sciences:**\n- Use binomial nomenclature for species (italicized: *Homo sapiens*)\n- Specify taxonomic authorities at first species mention when relevant\n- Employ standardized habitat and ecosystem classifications\n- Use consistent terminology for ecological metrics (e.g., \"species richness,\" \"Shannon diversity index\")\n- Describe sampling methods with field-standard terms (e.g., \"transect,\" \"quadrat,\" \"mark-recapture\")\n\n**Physics and Engineering:**\n- Follow SI units consistently unless field conventions dictate otherwise\n- Use standard notation for physical quantities (scalars vs. vectors, tensors)\n- Employ established terminology for phenomena (e.g., \"quantum entanglement,\" \"laminar flow\")\n- Specify equipment with model numbers and manufacturers when relevant\n- Use mathematical notation consistent with field standards (e.g., ℏ for reduced Planck constant)\n\n**Neuroscience:**\n- Use standardized brain region nomenclature (e.g., refer to atlases like Allen Brain Atlas)\n- Specify coordinates for brain regions using established stereotaxic systems\n- Follow conventions for neural terminology (e.g., \"action potential\" not \"spike\" in formal writing)\n- Use \"neural activity,\" \"neuronal firing,\" \"brain activation\" appropriately based on measurement method\n- Describe recording techniques with proper specificity (e.g., \"whole-cell patch clamp,\" \"extracellular recording\")\n\n**Social and Behavioral Sciences:**\n- Use person-first language when appropriate (e.g., \"people with schizophrenia\" not \"schizophrenics\")\n- Employ standardized psychological constructs and validated assessment names\n- Follow APA guidelines for reducing bias in language\n- Specify theoretical frameworks using established terminology\n- Use \"participants\" rather than \"subjects\" for human research\n\n**General Principles:**\n\n**Match Audience Expertise:**\n- For specialized journals: Use field-specific terminology freely, define only highly specialized or novel terms\n- For broad-impact journals (e.g., *Nature*, *Science*): Define more technical terms, provide context for specialized concepts\n- For interdisciplinary audiences: Balance precision with accessibility, define terms at first use\n\n**Define Technical Terms Strategically:**\n- Define abbreviations at first use: \"messenger RNA (mRNA)\"\n- Provide brief explanations for specialized techniques when writing for broader audiences\n- Avoid over-defining terms well-known to the target audience (signals unfamiliarity with field)\n- Create a glossary if numerous specialized terms are unavoidable\n\n**Maintain Consistency:**\n- Use the same term for the same concept throughout (don''t alternate between \"medication,\" \"drug,\" and \"pharmaceutical\")\n- Follow a consistent system for abbreviations (decide on \"PCR\" or \"polymerase chain reaction\" after first definition)\n- Apply the same nomenclature system throughout (especially for genes, species, chemicals)\n\n**Avoid Field Mixing Errors:**\n- Don''t use clinical terminology for basic science (e.g., don''t call mice \"patients\")\n- Avoid colloquialisms or overly general terms in place of precise field terminology\n- Don''t import terminology from adjacent fields without ensuring proper usage\n\n**Verify Terminology Usage:**\n- Consult field-specific style guides and nomenclature resources\n- Check how terms are used in recent papers from the target journal\n- Use domain-specific databases and ontologies (e.g., Gene Ontology, MeSH terms)\n- When uncertain, cite a key reference that establishes terminology\n\n### 10. Common Pitfalls to Avoid\n\n**Top Rejection Reasons:**\n1. Inappropriate, incomplete, or insufficiently described statistics\n2. Over-interpretation of results or unsupported conclusions\n3. Poorly described methods affecting reproducibility\n4. Small, biased, or inappropriate samples\n5. Poor writing quality or difficult-to-follow text\n6. Inadequate literature review or context\n7. Figures and tables that are unclear or poorly designed\n8. Failure to follow reporting guidelines\n\n**Writing Quality Issues:**\n- Mixing tenses inappropriately (use past tense for methods/results, present for established facts)\n- Excessive jargon or undefined acronyms\n- Paragraph breaks that disrupt logical flow\n- Missing transitions between sections\n- Inconsistent notation or terminology\n\n## Workflow for Manuscript Development\n\n**Stage 1: Planning**\n1. Identify target journal and review author guidelines\n2. Determine applicable reporting guideline (CONSORT, STROBE, etc.)\n3. Outline manuscript structure (usually IMRAD)\n4. Plan figures and tables as the backbone of the paper\n\n**Stage 2: Drafting** (Use two-stage writing process for each section)\n1. Start with figures and tables (the core data story)\n2. For each section below, follow the two-stage process:\n   - **First**: Create outline with bullet points using research-lookup\n   - **Second**: Convert bullet points to full paragraphs with flowing prose\n3. Write Methods (often easiest to draft first)\n4. Draft Results (describing figures/tables objectively)\n5. Compose Discussion (interpreting findings)\n6. Write Introduction (setting up the research question)\n7. Craft Abstract (synthesizing the complete story)\n8. Create Title (concise and descriptive)\n\n**Remember**: Bullet points are for planning only—the final manuscript must be in complete paragraphs.\n\n**Stage 3: Revision**\n1. Check logical flow and \"red thread\" throughout\n2. Verify consistency in terminology and notation\n3. Ensure figures/tables are self-explanatory\n4. Confirm adherence to reporting guidelines\n5. Verify all citations are accurate and properly formatted\n6. Check word counts for each section\n7. Proofread for grammar, spelling, and clarity\n\n**Stage 4: Final Preparation**\n1. Format according to journal requirements\n2. Prepare supplementary materials\n3. Write cover letter highlighting significance\n4. Complete submission checklists\n5. Gather all required statements and forms\n\n## Integration with Other Scientific Skills\n\nThis skill works effectively with:\n- **Data analysis skills**: For generating results to report\n- **Statistical analysis**: For determining appropriate statistical presentations\n- **Literature review skills**: For contextualizing research\n- **Figure creation tools**: For developing publication-quality visualizations\n\n## References\n\nThis skill includes comprehensive reference files covering specific aspects of scientific writing:\n\n- `references/imrad_structure.md`: Detailed guide to IMRAD format and section-specific content\n- `references/citation_styles.md`: Complete citation style guides (APA, AMA, Vancouver, Chicago, IEEE)\n- `references/figures_tables.md`: Best practices for creating effective data visualizations\n- `references/reporting_guidelines.md`: Study-specific reporting standards and checklists\n- `references/writing_principles.md`: Core principles of effective scientific communication\n\nLoad these references as needed when working on specific aspects of scientific writing.\n"},"lastSynced":"2026-03-08T02:10:19.074Z","agentAnalysis":{"suitability":{"en":"Perfect for Research Agents needing to generate well-formatted research manuscripts with comprehensive literature searches and verified citations.","zh":"非常适合需要生成格式良好、文献搜索全面、引用验证严谨的研究论文的研究代理","ja":"リサーチエージェントが整形式の研究論文を生成できるようにするために必要な、包括的な文献検索と検証された引用を備えたものに最適","ko":"잘 구성된 연구 논문과 함께 철저한 문헌 검색 및 확인된 인용문을 생성 할 수있는 연구 에이전트에게 적합","es":"Perfecto para Agentes de Investigación que necesitan generar manuscritos de investigación bien formateados con búsquedas de literatura exhaustivas y citas verificadas.","fr":"Parfait pour les Agents de Recherche ayant besoin de générer des manuscrits de recherche bien formatés avec des recherches de littérature exhaustives et des citations vérifiées.","de":"Perfekt für Forschungsagenten, die gut formatierte Forschungsmanuskripte mit umfassenden Literaturrecherchen und verifizierten Zitaten erstellen müssen.","pt":"Perfeito para Agentes de Pesquisa que precisam gerar manuscritos de pesquisa bem formatados com pesquisas de literatura abrangentes e citações verificadas.","ru":"Идеально подходит для исследовательских агентов, которым необходимо создавать хорошо отформатированные исследовательские рукописи с комплексными литературными поисками и проверенными цитатами.","ar":"مثالي للوكلاء البحثيين الذين يحتاجون إلى إعداد مخطوطات بحثية منسقة بشكل جيد مع عمليات بحث شاملة في الأدب والمراجع المأكدة."},"recommendation":{"en":"Empowers agents to communicate complex research with clarity, utilizing IMRAD structure, APA/AMA/Vancouver citations, and incorporating figures, tables, and reporting guidelines, all backed by comprehensive literature searches and verified citations through research-lookup skills.","zh":"使代理能够以清晰的方式传达复杂的研究，利用IMRAD结构、APA/AMA/Vancouver引用，并结合图表和报告指南，所有这些都得益于通过研究查找技能进行的全面文献搜索和验证引用","ja":"エージェントが複雑なリサーチを明確にコミュニケーションできるようにし、IMRAD構造、APA/AMA/Vancouver引用、図や表、報告ガイドラインを組み込み、研究検索スキルを通じての包括的な文献検索と検証された引用をバックアップ","ko":"에이전트가 복잡한 연구를 명확하게 전달 할 수있게 해주는 것으로 IMRAD 구조, APA / AMA / 밴쿠버 인용 및 그림, 표 및 보고서 지침을 포함하고 연구 조회スキル을 통해 철저한 문헌 검색 및 확인된 인용문을 지원","es":"Habilita a los agentes a comunicar investigaciones complejas con claridad, utilizando la estructura IMRAD, citas APA/AMA/Vancouver, e incorporando figuras, tablas y directrices de informes, todo respaldado por búsquedas de literatura exhaustivas y citas verificadas a través de habilidades de búsqueda de investigación.","fr":"Permet aux agents de communiquer des recherches complexes avec clarté, en utilisant la structure IMRAD, des citations APA/AMA/Vancouver, et en incorporant des figures, des tableaux et des lignes directrices de rapport, le tout étayé par des recherches de littérature exhaustives et des citations vérifiées à travers des compétences de recherche de recherche.","de":"Ermächtigt Agenten, komplexe Forschungsergebnisse klar zu kommunizieren, indem sie die IMRAD-Struktur, APA/AMA/Vancouver-Zitierstile und die Einbindung von Abbildungen, Tabellen und Berichtsleitlinien verwenden, all dies wird durch umfassende Literaturrecherchen und verifizierte Zitaten über Forschungssuche-Fähigkeiten unterstützt.","pt":"Habilita os agentes a comunicar pesquisas complexas com clareza, utilizando estrutura IMRAD, citações APA/AMA/Vancouver, e incorporando figuras, tabelas e diretrizes de relatórios, tudo respaldado por pesquisas de literatura abrangentes e citações verificadas por meio de habilidades de pesquisa-lookup.","ru":"Наделяет агентов возможностью общаться сложными исследованиями с ясностью, используя структуру IMRAD, цитаты APA/AMA/Vancouver, и включающие рисунки, таблицы и руководства по отчетности, все это подтверждается комплексными литературными поисками и проверенными цитатами через навыки поиска-lookup.","ar":"يمنح الوكلاء القدرة على التواصل في البحث المعقد بوضوح، باستخدام هيكل IMRAD، والمراجع APA/AMA/Vancouver، ودمج الرسومات والجداول وإرشادات التقرير، كل ذلك مدعوم bằng عمليات بحث شاملة في الأدب والمراجع المأكدة من خلال مهارات البحث-lookup."},"useCases":{"en":["Generating research manuscripts with verified citations","Automating literature searches for research topics","Creating well-formatted documents using IMRAD structure"],"zh":["使用验证的引用生成研究稿","自动化研究主题的文献搜索","使用IMRAD结构创建格式良好的文档"],"ja":["検証された引用を使用して研究稿を生成","研究トピックの文献検索を自動化","IMRAD構造を使用して整形式の文書を作成"],"ko":["확인된 인용문을 사용하여 연구 초안을 생성","연구 주제에 대한 문헌 검색을 자동화","IMRAD 구조를 사용하여 잘 구성된 문서를 생성"],"es":["Generar manuscritos de investigación con citas verificadas","Automatizar búsquedas de literatura para temas de investigación","Crear documentos bien formateados utilizando la estructura IMRAD"],"fr":["Générer des manuscrits de recherche avec des citations vérifiées","Automatiser les recherches de littérature pour les sujets de recherche","Créer des documents bien formatés en utilisant la structure IMRAD"],"de":["Forschungsmanuskripte mit verifizierten Zitaten generieren","Literaturrecherchen für Forschungsthemen automatisieren","Gut formatierte Dokumente unter Verwendung der IMRAD-Struktur erstellen"],"pt":["Gerar manuscritos de pesquisa com citações verificadas","Automatizar pesquisas de literatura para tópicos de pesquisa","Criar documentos bem formatados usando estrutura IMRAD"],"ru":["Генерировать исследовательские рукописи с проверенными цитатами","Автоматизировать литературные поиски для исследовательских тем","Создавать хорошо отформатированные документы с использованием структуры IMRAD"],"ar":["إعداد مخطوطات بحثية مع المراجع المأكدة","تأتمة عمليات البحث في الأدب لموضوعات البحث","إنشاء وثائق منسقة بشكل جيد باستخدام هيكل IMRAD"]},"limitations":{"en":["Requires research-lookup skill for verified citations","Limited to generating manuscripts in specific citation styles (APA/AMA/Vancouver)"],"zh":["需要研究查找技能来验证引用","仅限于生成特定引用风格（APA/AMA/Vancouver）的稿件"],"ja":["検証された引用を得るために研究検索スキルが必要","特定の引用スタイル（APA/AMA/Vancouver）でのみ稿を生成可能"],"ko":["확인된 인용문을 얻기 위해 연구 조회 스킬이 필요","특정 인용 스타일 (APA / AMA / 밴쿠버) 에서만 초안을 생성"],"es":["Requiere la habilidad de búsqueda de investigación para citas verificadas","Limitado a la generación de manuscritos en estilos de citación específicos (APA/AMA/Vancouver)"],"fr":["Nécessite la compétence de recherche de recherche pour des citations vérifiées","Limité à la génération de manuscrits dans des styles de citation spécifiques (APA/AMA/Vancouver)"],"de":["Benötigt die Forschungssuche-Fähigkeit für verifizierte Zitaten","Begrenzt auf die Generierung von Manuskripten in bestimmten Zitierstilen (APA/AMA/Vancouver)"],"pt":["Requer habilidade de pesquisa-lookup para citações verificadas","Limitado a gerar manuscritos em estilos de citação específicos (APA/AMA/Vancouver)"],"ru":["Требует навыка поиска-lookup для проверенных цитат","Ограничен генерацией рукописей в конкретных стилях цитирования (APA/AMA/Vancouver)"],"ar":["يتطلب مهارة البحث-lookup للمراجع المأكدة","محدود بالгенration من المخطوطات في أنماط المرجع الخاصة (APA/AMA/Vancouver)"]},"version":4},"contentHash":"5a3e0eece58981384b763b6cdb68fe1744aa4549d239b46c40079b720edece31","qualityScore":60}');
