INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('danburonline/public-writings/scientific-writing', 'scientific-writing', 'danburonline', 'public-writings', 'community', 'scientific-writing danburonline public-writings community The scientific writing skill enables developers to generate well-formatted research manuscripts with comprehensive literature search and verified citations. It benefits AI agents and researchers who need to communicate complex research with clarity. 科学写作AI工具结合AI驱动的深度研究和格式化输出，用于研究论文的撰写 科学的な文章作成ツールは、AI駆動の深度研究と形式化された出力を組み合わせて研究論文を作成する 과학적 글쓰기 도구는 AI駆動의 심층 연구와 서식된 출력을 결합하여 연구 논문을 작성하는 데 사용됩니다 La escritura científica es un proceso para comunicar investigaciones con precisión y claridad, utilizando estructuras IMRAD y citas APA/AMA/Vancouver L''écriture scientifique est un processus pour communiquer des recherches avec précision et clarté, en utilisant des structures IMRAD et des citations APA/AMA/Vancouver Das wissenschaftliche Schreiben ist ein Prozess, um Forschungsergebnisse mit Präzision und Klarheit zu kommunizieren, unter Verwendung von IMRAD-Strukturen und Zitaten im APA/AMA/Vancouver-Stil A escrita científica é um processo para comunicar pesquisas com precisão e clareza, utilizando estrutura IMRAD e citações APA/AMA/Vancouver Научная письменность - это процесс для передачи исследований с точностью и ясностью, используя структуру IMRAD и цитаты APA/AMA/Vancouver الكتابة العلمية هي عملية للتواصل مع الأبحاث بدقة ووضوح، باستخدام هيكل IMRAD واقتباسات APA/AMA/Vancouver how to use scientific writing scientific writing setup guide what is scientific writing scientific writing alternative scientific writing vs research writing install scientific writing skill IMRAD structure tutorial APA citation style guide 科学写作AI工具 研究论文撰写 深度研究 文献检索 IMRAD结构 APA引用样式 AMA引用样式 Vancouver引用样式 图表添加 报告指南 Generates manuscripts using IMRAD structure Supports citations in APA, AMA, and Vancouver styles Includes comprehensive literature search through research-lookup skill Produces well-formatted written outputs with figures and tables Utilizes verified citations for accuracy and reliability Scientific writing is a process for communicating research with precision and clarity, using formats like IMRAD structure and citations in APA/AMA/Vancouver styles.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cybereason-labs/owLSM/github-issues', 'community', 'cybereason-labs', 'owLSM', 'cybereason-labs/owLSM', 'github-issues', 0, 0, 60, '2026-03-08T01:57:15.507Z', '2026-03-08T02:10:23.050Z', 'e261db5855b24eb8e31436b90ca4addeba4a2fc51bafb73b00d025bfc9194100', '{"id":"cybereason-labs/owLSM/github-issues","name":"github-issues","description":{"en":"The github-issues skill assists with GitHub issue management using GitHub MCP server tools, benefiting developers and repository owners. It operates on specified repositories with valid GitHub Personal Access Tokens.","zh":"GitHub Issues 管理助手使用 GitHub MCP 服务器工具，帮助您高效管理 GitHub 仓库中的问题","ja":"GitHub Issues 管理アシスタントは、GitHub MCP サーバー ツールを使用して、GitHub リポジトリ内の問題を効率的に管理します","ko":"GitHub 이슈 관리 어시스턴트는 GitHub MCP 서버 툴을 사용하여 GitHub 리포지토리 내의 이슈를 효율적으로 관리합니다","es":"El agente de GitHub Issues es una herramienta para desarrolladores que utiliza el servidor MCP de GitHub para gestionar y administrar problemas en los repositorios","fr":"L''agent de problèmes GitHub est un outil pour les développeurs qui utilise le serveur MCP de GitHub pour gérer et administrer les problèmes dans les référentiels","de":"Der GitHub Issues Agent ist ein Tool für Entwickler, das den GitHub MCP Server verwendet, um Probleme in den Repositories zu verwalten und zu administrieren","pt":"O GitHub Issues é uma ferramenta de gerenciamento de problemas que utiliza o GitHub MCP server tools","ru":"ИИ Агенты для GitHub Issues - это инструмент управления проблемами, использующий GitHub MCP сервер","ar":"إدارة قضايا GitHub هي أداة لإدارة المشكلات التي تستخدم أدوات GitHub MCP"},"seo":{"title":{"en":"github-issues: GitHub Issue Management Setup Guide | AI A...","zh":"GitHub Issues 管理设置指南","ja":"GitHub Issues 管理設定ガイド - AIエージェント","ko":"GitHub 이슈 관리 설정 가이드 - AI 도구","es":"Guía de configuración de GitHub Issues para desarrolladores","fr":"Guide de configuration de GitHub Issues pour les développ...","de":"Konfigurationsleitfaden für GitHub Issues für Entwickler","pt":"Guia de Configuração do GitHub Issues","ru":"Настройка ИИ Агентов для GitHub Issues","ar":"دليل إعداد إدارة قضايا GitHub"},"description":{"en":"Streamline your GitHub workflow with the github-issues AI agent skill. Learn how to configure and utilize GitHub MCP server tools for efficient issue managem...","zh":"使用 GitHub MCP 服务器工具管理 GitHub Issues，提高开发效率","ja":"GitHub Issues を管理するための AI エージェント - GitHub MCP サーバー ツールを使用","ko":"GitHub 이슈를 관리하는 AI 도구 - GitHub MCP 서버 툴을 사용하여 개발 효율성 향상","es":"Aprende a configurar y administrar GitHub Issues con nuestra guía paso a paso para desarrolladores","fr":"Découvrez comment configurer et gérer les problèmes GitHub avec notre guide étape par étape pour les développeurs","de":"Erfahren Sie, wie Sie GitHub Issues konfigurieren und verwalten mit unserer Schritt-für-Schritt-Anleitung für Entwickler","pt":"Aprenda a configurar o GitHub Issues com o GitHub MCP server tools e acesse o repositório alvo","ru":"Узнайте, как настроить ИИ Агенты для GitHub Issues с помощью GitHub MCP сервера и доступа к целевому репозиторию","ar":"تعرف على كيفية إعداد إدارة قضايا GitHub باستخدام أدوات GitHub MCP ووصول إلى المستودع المستهدف"},"definition":{"en":"github-issues is a GitHub issue management assistant using GitHub MCP server tools, enabling efficient issue creation and management for repository owners and developers.","zh":"GitHub Issues 管理是指使用 GitHub MCP 服务器工具管理 GitHub 仓库中的问题","ja":"GitHub Issues 管理とは、GitHub MCP サーバー ツールを使用して GitHub リポジトリ内の問題を管理すること","ko":"GitHub 이슈 관리란 GitHub MCP 서버 툴을 사용하여 GitHub 리포지토리 내의 이슈를 관리하는 것을 말합니다","es":"¿Qué es un agente de GitHub Issues? Es una herramienta que utiliza el servidor MCP de GitHub para gestionar problemas en los repositorios","fr":"Qu''est-ce qu''un agent de problèmes GitHub? C''est un outil qui utilise le serveur MCP de GitHub pour gérer les problèmes dans les référentiels","de":"Was ist ein GitHub Issues Agent? Es ist ein Tool, das den GitHub MCP Server verwendet, um Probleme in den Repositories zu verwalten","pt":"O que é GitHub Issues? É uma ferramenta de gerenciamento de problemas do GitHub","ru":"Что такое ИИ Агенты для GitHub Issues? Это инструмент управления проблемами GitHub","ar":"ما هي إدارة قضايا GitHub؟ هي أداة لإدارة المشكلات في GitHub"},"features":{"en":["Operates on specified repositories using GitHub MCP server tools","Creates issues with valid GitHub Personal Access Tokens having `Issues: Read and write` permission","Defaults to the `cybereason-labs/owLSM_deprecated` repository unless otherwise specified","Allows users to specify a different repository using the `create issue in owner/repo` command","Utilizes GitHub API for issue management and creation"],"zh":["使用 GitHub MCP 服务器工具管理 GitHub Issues","支持创建和管理 GitHub 仓库中的问题","需要有效的 GitHub Personal Access Token","默认操作仓库为 cybereason-labs/owLSM_deprecated","支持指定不同的仓库进行操作","需要 GitHub Issues 的读写权限"],"ja":["GitHub MCP サーバー ツールを使用して GitHub Issues を管理","GitHub リポジトリ内の問題の作成と管理をサポート","有効な GitHub Personal Access Token が必要","デフォルトの操作リポジトリは cybereason-labs/owLSM_deprecated","異なるリポジトリを指定して操作することをサポート","GitHub Issues の読み取りと書き込み権限が必要"],"ko":["GitHub MCP 서버 툴을 사용하여 GitHub 이슈를 관리","GitHub 리포지토리 내의 이슈 생성과 관리를 지원","유효한 GitHub Personal Access Token이 필요","기본 운영 리포지토리는 cybereason-labs/owLSM_deprecated","다른 리포지토리를 지정하여 운영할 수 있음","GitHub 이슈의 읽기와 쓰기 권한이 필요"],"es":["Uso del servidor MCP de GitHub para la gestión de problemas","Configuración de un token de acceso personal de GitHub con permisos de lectura y escritura","Acceso a los repositorios de GitHub para la administración de problemas","Posibilidad de especificar un repositorio diferente para la administración de problemas","Uso de comandos como ''create issue in owner/repo'' para la administración de problemas"],"fr":["Utilisation du serveur MCP de GitHub pour la gestion des problèmes","Configuration d''un jeton d''accès personnel de GitHub avec des autorisations de lecture et d''écriture","Accès aux référentiels de GitHub pour l''administration des problèmes","Possibilité de spécifier un référentiel différent pour l''administration des problèmes","Utilisation de commandes comme ''create issue in owner/repo'' pour l''administration des problèmes"],"de":["Verwendung des GitHub MCP Servers für die Problemmverwaltung","Konfiguration eines persönlichen Zugriffstokens von GitHub mit Lese- und Schreibberechtigungen","Zugriff auf die GitHub-Repositorys für die Problemmverwaltung","Möglichkeit, ein anderes Repository für die Problemmverwaltung anzugeben","Verwendung von Befehlen wie ''create issue in owner/repo'' für die Problemmverwaltung"],"pt":["Utiliza o GitHub MCP server tools","Requer token de acesso pessoal do GitHub com permissão de leitura e escrita de problemas","Acesso ao repositório alvo","Permite a criação de problemas em repositórios diferentes","Opera no repositório owLSM_deprecated por padrão"],"ru":["Использует GitHub MCP сервер","Требует личного токена доступа к GitHub с разрешением на чтение и запись проблем","Доступ к целевому репозиторию","Позволяет создавать проблемы в разных репозиториях","Работает с репозиторием owLSM_deprecated по умолчанию"],"ar":["تستخدم أدوات GitHub MCP","تتطلب رمز وصول شخصي إلى GitHub مع إذن قراءة وكتابة المشكلات","وصول إلى المستودع المستهدف","تمكن من إنشاء مشكلات في مستودعات مختلفة","تعمل على المستودع owLSM_deprecated افتراضيًا"]},"keywords":{"en":["github-issues setup guide","github issue management best practices","github-issues vs github-api","how to use github-issues","github-issues alternative","github-issues install","github mcp server tools","github personal access token","github issue creation"],"zh":["GitHub Issues 管理","GitHub MCP 服务器工具","GitHub 仓库管理","GitHub Personal Access Token","cybereason-labs/owLSM_deprecated","GitHub Issues 创建","GitHub Issues 管理设置","AI 工具","开发效率"],"ja":["GitHub Issues 管理","GitHub MCP サーバー ツール","GitHub リポジトリ管理","GitHub Personal Access Token","cybereason-labs/owLSM_deprecated","GitHub Issues 作成","GitHub Issues 管理設定","AI エージェント","開発効率"],"ko":["GitHub 이슈 관리","GitHub MCP 서버 툴","GitHub 리포지토리 관리","GitHub Personal Access Token","cybereason-labs/owLSM_deprecated","GitHub 이슈 생성","GitHub 이슈 관리 설정","AI 도구","개발 효율성"],"es":["github issues","agente de github issues","herramientas de github","gestión de problemas en github","configuración de github issues","desarrollo de software","herramientas de desarrollo","github para desarrolladores","agentes de ai para github"],"fr":["github issues","agent de problèmes github","outils de github","gestion des problèmes sur github","configuration de github issues","développement de logiciels","outils de développement","github pour les développeurs","agents de l''ia pour github"],"de":["github issues","github issues agent","github tools","problemmverwaltung in github","konfiguration von github issues","softwareentwicklung","entwicklungstools","github für entwickler","künstliche intelligenz agenten für github"],"pt":["github issues","github mcp server","gerenciamento de problemas","token de acesso pessoal","repositório alvo","criação de problemas","owLSM_deprecated"],"ru":["github issues","github mcp сервер","управление проблемами","личный токен доступа","целевой репозиторий","создание проблем","owLSM_deprecated","ИИ Агенты"],"ar":["إدارة قضايا github","أدوات github mcp","إدارة المشكلات","رمز وصول شخصي","مستودع مستهدف","إنشاء مشكلات","owLSM_deprecated","أدوات ذكاء اصطناعي"]}},"owner":"cybereason-labs","repo":"owLSM","repoPath":"cybereason-labs/owLSM","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.507Z","topics":[],"category":"community","skillMd":{"name":"github-issues","description":"Manage GitHub issues - create, edit, close, comment, assign, and delegate to Copilot. Uses GitHub MCP.","bodyPreview":"# GitHub Issues Management\n\nYou are a GitHub issue management assistant using the GitHub MCP server tools.\n\n## Prerequisites\n\n- GitHub MCP server must be configured in Cursor\n- Valid GitHub Personal Access Token with `Issues: Read and write` permission\n- Access to the target repository\n\n## Default Repository\n\nUnless specified otherwise, operate on:\n- **Owner:** `cybereason-labs`\n- **Repo:** `owLSM_deprecated`\n\nUser can specify a different repo: \"create issue in owner/repo\"\n\n## Available Operatio","body":"# GitHub Issues Management\n\nYou are a GitHub issue management assistant using the GitHub MCP server tools.\n\n## Prerequisites\n\n- GitHub MCP server must be configured in Cursor\n- Valid GitHub Personal Access Token with `Issues: Read and write` permission\n- Access to the target repository\n\n## Default Repository\n\nUnless specified otherwise, operate on:\n- **Owner:** `cybereason-labs`\n- **Repo:** `owLSM_deprecated`\n\nUser can specify a different repo: \"create issue in owner/repo\"\n\n## Available Operations\n\n### 1. List Issues\n\n**Triggers:** \"show issues\", \"list issues\", \"what issues are open\"\n\n```\nUse: mcp_GitHub_list_issues\nParameters:\n  - owner: repository owner\n  - repo: repository name\n  - state: OPEN | CLOSED (default: OPEN)\n  - labels: filter by labels (optional)\n  - perPage: results per page (default: 10)\n```\n\n**Example output format:**\n```\nFound 5 open issues:\n\n#42 - Fix memory leak in process cache\n     Labels: bug, high-priority\n     Assignee: @username\n     Created: 2024-01-15\n\n#38 - Add support for network monitoring\n     Labels: enhancement\n     Assignee: none\n     Created: 2024-01-10\n...\n```\n\n### 2. Create Issue\n\n**Triggers:** \"create issue\", \"new issue\", \"open issue for\"\n\n```\nUse: mcp_GitHub_issue_write\nParameters:\n  - method: \"create\"\n  - owner: repository owner\n  - repo: repository name\n  - title: issue title (required)\n  - body: issue description\n  - labels: array of label names\n  - assignees: array of usernames\n```\n\n**When creating issues:**\n1. Ask for title if not provided\n2. Generate a clear, descriptive body if not provided\n3. Suggest relevant labels based on content\n4. Confirm before creating\n5. Add context that I provide in the prompt. Things like code blocks, files, link, screenshots, etc''\n\n**Example:**\n```\nUser: \"create issue for the TCP monitoring bug\"\n\nAgent response:\nI''ll create an issue for the TCP monitoring bug.\n\nTitle: TCP monitoring fails to capture outbound connections\nBody: \n  ## Description\n  TCP monitoring is not capturing outbound connections...\n  \n  ## Steps to Reproduce\n  1. ...\n  \nLabels: bug\nAssignee: (none)\n\nCreate this issue? [Provide details to modify or confirm]\n```\n\n### 3. Read Issue Details\n\n**Triggers:** \"show issue #X\", \"what''s issue #X about\", \"details of #X\"\n\n```\nUse: mcp_GitHub_issue_read\nParameters:\n  - method: \"get\"\n  - owner: repository owner\n  - repo: repository name  \n  - issue_number: the issue number\n```\n\n### 4. Update Issue\n\n**Triggers:** \"update issue\", \"edit issue\", \"change issue\"\n\n```\nUse: mcp_GitHub_issue_write\nParameters:\n  - method: \"update\"\n  - owner: repository owner\n  - repo: repository name\n  - issue_number: issue to update\n  - title: new title (optional)\n  - body: new body (optional)\n  - state: \"open\" | \"closed\"\n  - state_reason: \"completed\" | \"not_planned\" | \"duplicate\"\n  - labels: new labels array\n  - assignees: new assignees array\n```\n\n### 5. Close Issue\n\n**Triggers:** \"close issue #X\", \"mark #X as done\", \"resolve #X\"\n\n```\nUse: mcp_GitHub_issue_write\nParameters:\n  - method: \"update\"\n  - issue_number: X\n  - state: \"closed\"\n  - state_reason: \"completed\" (or \"not_planned\" if won''t fix)\n```\n\n**Always ask for close reason:**\n- `completed` - Issue was fixed/resolved\n- `not_planned` - Won''t fix / out of scope\n- `duplicate` - Duplicate of another issue (ask which one)\n\n### 6. Add Comment\n\n**Triggers:** \"comment on #X\", \"add comment to issue\", \"reply to #X\"\n\n```\nUse: mcp_GitHub_add_issue_comment\nParameters:\n  - owner: repository owner\n  - repo: repository name\n  - issue_number: issue number\n  - body: comment text\n```\n\n### 7. Search Issues\n\n**Triggers:** \"find issues about\", \"search for issues\"\n\n```\nUse: mcp_GitHub_search_issues\nParameters:\n  - query: search query (GitHub search syntax)\n  - owner: repository owner (optional, scopes search)\n  - repo: repository name (optional, scopes search)\n```\n\n**Search syntax examples:**\n- `is:open label:bug` - open bugs\n- `author:username` - issues by specific user\n- `mentions:username` - issues mentioning user\n- `memory leak` - issues containing \"memory leak\"\n\n### 8. Assign to Copilot\n\n**Triggers:** \"have copilot fix #X\", \"assign copilot to #X\", \"let AI fix this\"\n\n```\nUse: mcp_GitHub_assign_copilot_to_issue\nParameters:\n  - owner: repository owner\n  - repo: repository name\n  - issue_number: issue to assign\n  - custom_instructions: additional guidance (optional)\n```\n\n**Before assigning to Copilot:**\n1. Read the issue to understand it\n2. Check if it''s suitable for AI (clear requirements, bounded scope)\n3. Add custom instructions if needed\n4. Confirm with user\n\n**Example:**\n```\nUser: \"have copilot fix issue #42\"\n\nAgent:\nIssue #42: Fix memory leak in process cache\nThis appears to be a bounded bug fix. Copilot should be able to help.\n\nCustom instructions I''ll provide:\n- Focus on the process_cache.cpp file\n- Run existing tests after changes\n- Don''t modify the public API\n\nAssign to Copilot? [y/n]\n```\n\n### 9. Get Issue Comments\n\n**Triggers:** \"show comments on #X\", \"what''s the discussion on #X\"\n\n```\nUse: mcp_GitHub_issue_read\nParameters:\n  - method: \"get_comments\"\n  - owner: repository owner\n  - repo: repository name\n  - issue_number: issue number\n```\n\n### 10. Manage Labels\n\n**Triggers:** \"add label to #X\", \"remove label from #X\"\n\n```\nUse: mcp_GitHub_issue_write with labels parameter\n```\n\n## Workflow Examples\n\n### Bug Report Workflow\n```\nUser: \"I found a bug - the config parser crashes on empty files\"\n\nAgent:\n1. Creates issue with title, description, reproduction steps\n2. Adds \"bug\" label\n3. Asks if it should be assigned to anyone\n4. Optionally assigns to Copilot for a fix\n```\n\n### Issue Triage Workflow\n```\nUser: \"triage the open issues\"\n\nAgent:\n1. Lists all open issues\n2. For each, suggests:\n   - Priority (based on labels, age, content)\n   - Potential assignee\n   - Whether Copilot could help\n3. Asks which actions to take\n```\n\n### Close with PR Workflow\n```\nUser: \"close #42, it was fixed in PR #50\"\n\nAgent:\n1. Adds comment: \"Fixed in #50\"\n2. Closes issue with reason: completed\n```\n\n## Error Handling\n\n| Error | Response |\n|-------|----------|\n| Issue not found | \"Issue #X doesn''t exist. Did you mean #Y?\" |\n| Permission denied | \"Don''t have permission. Check PAT scopes.\" |\n| Rate limited | \"GitHub rate limit hit. Wait a few minutes.\" |\n| Network error | \"Can''t reach GitHub. Check connection.\" |\n\n## Output Formatting\n\nWhen listing issues, use this format:\n```\n📋 Open Issues (5 total)\n\n#42 🐛 Fix memory leak in process cache\n    Labels: bug, high-priority\n    Assigned: @dev1\n    Age: 3 days\n\n#38 ✨ Add network monitoring support  \n    Labels: enhancement\n    Assigned: —\n    Age: 1 week\n```\n\nEmoji guide:\n- 🐛 bug\n- ✨ enhancement/feature\n- 📝 documentation\n- 🔧 maintenance\n- ❓ question\n- 🔒 security\n\n## Safety Guidelines\n\n1. **Confirm destructive actions** — Always confirm before closing or deleting\n2. **Show before create** — Display issue content before creating\n3. **Preserve context** — When updating, show what will change\n4. **Rate limit awareness** — Don''t spam the API with many requests\n\n\n"},"lastSynced":"2026-03-08T02:10:23.050Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing streamlined GitHub issue management and automation capabilities.","zh":"非常适合需要简化 GitHub 问题管理和自动化功能的开发人员代理。","ja":"GitHub の問題管理と自動化機能を効率化する必要がある Developer エージェントに最適です。","ko":"GitHub 문제 관리 및 자동화 기능을 간소화해야 하는 개발자 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan una gestión de problemas de GitHub optimizada y capacidades de automatización.","fr":"Parfait pour les Agents de Développeur ayant besoin d''une gestion de problèmes GitHub rationalisée et de capacités d''automatisation.","de":"Perfekt für Entwickleragenten, die eine optimierte GitHub-Problemmgmt und Automatisierungsfähigkeiten benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de gestão de problemas do GitHub simplificada e capacidades de automação.","ru":"Идеально подходит для агентов разработчиков, которым необходима упрощенная система управления проблемами GitHub и возможности автоматизации.","ar":"مثالي لعميل المطور الذي يحتاج إلى إدارة مشاكل GitHub مبسطة وقدرات آليّة."},"recommendation":{"en":"Empowers agents to create, read, and manage GitHub issues using GitHub MCP server tools and Personal Access Tokens with `Issues: Read and write` permission, streamlining repository maintenance and collaboration.","zh":"赋予代理创建、读取和管理 GitHub 问题的能力，使用 GitHub MCP 服务器工具和具有 `Issues: Read and write` 权限的个人访问令牌，从而简化仓库维护和协作。","ja":"GitHub MCP サーバー ツールと `Issues: Read and write` 権限を持つ Personal Access Token を使用して、エージェントが GitHub の問題を作成、読み取り、管理できるようにし、リポジトリのメンテナンスとコラボレーションを効率化します。","ko":"GitHub MCP 서버 도구 및 `Issues: Read and write` 권한이 있는 개인 접근 토큰을 사용하여 에이전트가 GitHub 문제를 생성, 읽기 및 관리할 수 있도록 하여 리포지토리 유지 보수 및 협업을 간소화합니다.","es":"Permite a los agentes crear, leer y gestionar problemas de GitHub utilizando las herramientas del servidor GitHub MCP y tokens de acceso personal con permiso `Issues: Leer y escribir`, lo que simplifica el mantenimiento y la colaboración del repositorio.","fr":"Permet aux agents de créer, lire et gérer les problèmes GitHub à l''aide des outils de serveur GitHub MCP et des jetons d''accès personnel avec l''autorisation `Issues: Lire et écrire`, ce qui rationalise la maintenance et la collaboration du référentiel.","de":"Ermöglicht es den Agenten, GitHub-Probleme mit GitHub MCP-Server-Tools und persönlichen Zugriffstoken mit `Issues: Lesen und schreiben`-Berechtigung zu erstellen, zu lesen und zu verwalten, wodurch die Wartung und Zusammenarbeit des Repositorys rationalisiert werden.","pt":"Habilita os agentes a criar, ler e gerenciar problemas do GitHub usando as ferramentas do servidor GitHub MCP e Tokens de Acesso Pessoal com permissão `Issues: Ler e escrever`, simplificando a manutenção do repositório e a colaboração.","ru":"Наделяет агентов возможностью создавать, читать и управлять проблемами GitHub с помощью инструментов сервера GitHub MCP и Личных токенов доступа с разрешением `Issues: Чтение и запись`, упрощая обслуживание репозитория и сотрудничество.","ar":"تمكّن الوكلاء من إنشاء مشاكل GitHub وقراءتها وإدارتها باستخدام أدوات خادم GitHub MCP والرموز الشخصية للوصول بالصلاحية `Issues: قراءة وكتابة`، مبسطةً صيانة المستودع والتعاون."},"useCases":{"en":["Automating issue creation in specified repositories","Managing and labeling issues for efficient project tracking","Debugging repository issues using GitHub MCP server tools"],"zh":["在指定的仓库中自动创建问题","管理和标记问题以实现高效的项目跟踪","使用 GitHub MCP 服务器工具调试仓库问题"],"ja":["指定されたリポジトリで問題を自動的に作成する","問題を管理およびラベル付けして効率的なプロジェクト トラッキングを行う","GitHub MCP サーバー ツールを使用してリポジトリの問題をデバッグする"],"ko":["지정된 리포지토리에서 문제를 자동으로 생성하는 것","문제를 관리 및 레이블링하여 효율적인 프로젝트 추적을 수행하는 것","GitHub MCP 서버 도구를 사용하여 리포지토리 문제를 디버깅하는 것"],"es":["Automatización de la creación de problemas en repositorios especificados","Gestión y etiquetado de problemas para un seguimiento de proyectos eficiente","Depuración de problemas de repositorio con herramientas de servidor GitHub MCP"],"fr":["Automatisation de la création de problèmes dans des référentiels spécifiés","Gestion et étiquetage de problèmes pour un suivi de projet efficace","Débogage de problèmes de référentiel à l''aide des outils de serveur GitHub MCP"],"de":["Automatisierung der Problemerstellung in bestimmten Repositorys","Verwaltung und Beschriftung von Problemen für eine effiziente Projektverfolgung","Fehlerbehebung von Repository-Problemen mit GitHub MCP-Server-Tools"],"pt":["Automatizar a criação de problemas em repositórios específicos","Gerenciar e rotular problemas para acompanhamento de projeto eficiente","Depurar problemas do repositório usando as ferramentas do servidor GitHub MCP"],"ru":["Автоматизировать создание проблем в определенных репозиториях","Управлять и маркировать проблемы для эффективного отслеживания проекта","Отладить проблемы репозитория с помощью инструментов сервера GitHub MCP"],"ar":["تأليفة إنشاء مشاكل في مستودعات محددة","إدارة وتسمية المشاكل لتتبعโครงการ فعال","تصحيح أخطاء المستودع باستخدام أدوات خادم GitHub MCP"]},"limitations":{"en":["Requires GitHub MCP server configuration in the agent","Needs a valid GitHub Personal Access Token with `Issues: Read and write` permission","Limited to repositories accessible with the provided credentials"],"zh":["需要在代理中配置 GitHub MCP 服务器","需要具有 `Issues: Read and write` 权限的有效 GitHub 个人访问令牌","仅限于可以使用提供的凭据访问的仓库"],"ja":["エージェント内で GitHub MCP サーバーを構成する必要がある","`Issues: Read and write` 権限を持つ有効な GitHub Personal Access Token が必要","提供された資格情報でアクセスできるリポジトリにのみ制限される"],"ko":["에이전트 내에서 GitHub MCP 서버를 구성해야 함","`Issues: Read and write` 권한이 있는 유효한 GitHub 개인 접근 토큰이 필요","제공된 자격 증명으로 액세스할 수 있는 리포지토리만 제한"],"es":["Requiere configuración del servidor GitHub MCP en el agente","Necesita un token de acceso personal de GitHub válido con permiso `Issues: Leer y escribir`","Limitado a los repositorios accesibles con las credenciales proporcionadas"],"fr":["Nécessite une configuration du serveur GitHub MCP dans l''agent","Nécessite un jeton d''accès personnel GitHub valide avec l''autorisation `Issues: Lire et écrire`","Limité aux référentiels accessibles avec les informations d''identification fournies"],"de":["Benötigt GitHub MCP-Server-Konfiguration im Agenten","Benötigt ein gültiges GitHub-Personal Access Token mit `Issues: Lesen und schreiben`-Berechtigung","Begrenzt auf Repositorys, die mit den bereitgestellten Anmeldeinformationen zugänglich sind"],"pt":["Exige configuração do servidor GitHub MCP no agente","Necessita de um Token de Acesso Pessoal do GitHub válido com permissão `Issues: Ler e escrever`","Limitado a repositórios acessíveis com as credenciais fornecidas"],"ru":["Требует конфигурации сервера GitHub MCP в агенте","Требует действительного Личного токена доступа к GitHub с разрешением `Issues: Чтение и запись`","Ограничен репозиториями, доступными с помощью предоставленных учетных данных"],"ar":["يتطلب تهيئة خادم GitHub MCP في العميل","يحتاج إلى رمز وصول شخصي صالح ل GitHub بالصلاحية `Issues: قراءة وكتابة`","محدود بالمستودعات المتاحة باستخدام بيانات الاعتماد المقدّمة"]},"version":4},"contentHash":"e261db5855b24eb8e31436b90ca4addeba4a2fc51bafb73b00d025bfc9194100","qualityScore":60}');
