INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mathfalcon/revendiste/revendiste-notification-system', 'revendiste-notification-system', 'mathfalcon', 'revendiste', 'community', 'revendiste-notification-system mathfalcon revendiste community The revendiste-notification-system provides a scalable notification solution for developers, utilizing React Email for templating and type-safe notifications. It benefits developers seeking a reliable notification system. Revendiste Notification System是一个类型安全、可扩展的通知系统，使用React Email支持电子邮件模板 Revendiste Notification Systemは、React Emailを使用した型安全でスケーラブルな通知システムです Revendiste Notification System은 React Email을 사용하여 타입 안전하고 확장 가능한 알림 시스템입니다 El sistema de notificación Revendiste es un sistema de notificación escalable y seguro con soporte de plantillas de correo electrónico Le système de notification Revendiste est un système de notification évolutif et sécurisé avec prise en charge des modèles d''e-mail Das Revendiste-Benachrichtigungssystem ist ein skalierbares und sicheres Benachrichtigungssystem mit E-Mail-Vorlagen-Unterstützung O Revendiste Notification System é um sistema de notificações escalável e tipo-seguro que suporta templates de e-mail com React Email. Система уведомлений Revendiste - это масштабируемая и типобезопасная система уведомлений с поддержкой шаблонов электронной почты с помощью React Email и ИИ Агентов. نظام الإشعارات Revendiste هو نظام إشعارات قابل للتوسيع وآمن النوع مع دعم قوالب البريد الإلكتروني باستخدام React Email ووكلاء الذكاء الاصطناعي. how to use revendiste-notification-system revendiste-notification-system setup guide react email template examples type-safe notification system scalable notification architecture revendiste-notification-system vs competitors AIエージェント Revendiste Notification System 类型安全通知 React Email 可扩展通知 TypeScript 通知系统设置 电子邮件模板 Utilizes React Email for customizable email templates Provides type-safe notification functionality Includes helper functions for common notification scenarios, such as notifySellerTicketSold Supports scalable notification architecture Employs TypeScript for robust and maintainable code revendiste-notification-system is a type-safe, scalable notification system with email template support using React Email.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yukikwi/elysia-boiler-plate/elysiajs', 'community', 'yukikwi', 'elysia-boiler-plate', 'yukikwi/elysia-boiler-plate', 'elysiajs', 0, 0, 60, '2026-03-08T01:57:15.539Z', '2026-03-08T02:11:10.289Z', 'c553412bafe02012b323ae7d118841375e58810be4f6984a3970d83bf7988355', '{"id":"yukikwi/elysia-boiler-plate/elysiajs","name":"elysiajs","description":{"en":"Elysiajs is a TypeScript framework for building Bun-first backend servers, providing guidance on routing, validation, and authentication for developers.","zh":"ElysiaJS是一个TypeScript框架，用于构建高性能后端服务器。该技能提供了综合的开发指南，包括路由、验证、认证和部署","ja":"ElysiaJSは、高性能バックエンドサーバーを構築するためのTypeScriptフレームワークです。このスキルでは、ルーティング、バリデーション、認証、プラグイン、デプロイメントに関する包括的な開発ガイドを提供します","ko":"ElysiaJS는 고성능 백엔드 서버를 구축하기 위한 TypeScript 프레임워크입니다. 이 스킬은 라우팅, 유효성 검사, 인증, 플러그인 및 배포와 관련된 포괄적인 개발 가이드를 제공합니다","es":"ElysiaJS es un framework de TypeScript para construir servidores backend de alto rendimiento con Bun. Ofrece routing, validación, autenticación y más.","fr":"ElysiaJS est un framework TypeScript pour créer des serveurs backend haute performance avec Bun. Il propose du routing, de la validation, de l''authentification et plus.","de":"ElysiaJS ist ein TypeScript-Framework für den Bau von Hochleistungs-Backend-Servern mit Bun. Es bietet Routing, Validierung, Authentifizierung und mehr.","pt":"ElysiaJS é um framework TypeScript para desenvolvimento de servidores backend de alto desempenho. Este skill fornece orientação abrangente para desenvolvimento com Elysia","ru":"ElysiaJS - фреймворк TypeScript для разработки серверов backend с высоким уровнем производительности. Этот навык предоставляет всестороннее руководство для разработки с Elysia","ar":"إيليسيا جيه إس هو إطار عمل تايب سكريبت لتطوير خوادم الباك إند عالية الأداء. هذا المهارة يوفر إرشادات شاملة لتطوير إيليسيا"},"seo":{"title":{"en":"elysiajs: TypeScript Framework Setup Guide | AI Agent Skill","zh":"ElysiaJS 开发指南：高性能后端服务器搭建","ja":"ElysiaJS Setup Guide: AIエージェントによる高性能バックエンドサーバー構築","ko":"ElysiaJS 개발 가이드: 고성능 백엔드 서버 구축","es":"Guía de Configuración de ElysiaJS para Desarrolladores","fr":"Guide de Mise en Route d''ElysiaJS pour les Développeurs","de":"ElysiaJS-Setup-Anleitung für Entwickler","pt":"Guia de Configuração do ElysiaJS: Desenvolvimento de Serv...","ru":"ИИ Агенты: Руководство по Настройке ElysiaJS для Разработ...","ar":"دليل إعداد إيليسيا جيه إس: تطوير خوادم الباك إند"},"description":{"en":"Unlock high-performance backend servers with elysiajs! Learn how to develop type-safe applications with routing, validation, and authentication","zh":"使用ElysiaJS构建高性能、类型安全的后端服务器，了解路由、验证、认证、插件和部署","ja":"ElysiaJSを使って高性能のバックエンドサーバーを構築する方法を学び、ルーティング、バリデーション、認証、プラグイン、デプロイメントについて詳しく知る","ko":"ElysiaJS를 사용하여 고성능 백엔드 서버를 구축하는 방법을 알아보고, 라우팅, 유효성 검사, 인증, 플러그인 및 배포에 대해 자세히 알아보세요","es":"Aprende a utilizar ElysiaJS, un framework de TypeScript para construir servidores backend de alto rendimiento con Bun. Descubre sus características y benefic...","fr":"Découvrez ElysiaJS, un framework TypeScript pour créer des serveurs backend haute performance avec Bun. Explorez ses fonctionnalités et avantages.","de":"Erfahren Sie, wie Sie ElysiaJS verwenden, ein TypeScript-Framework für den Bau von Hochleistungs-Backend-Servern mit Bun. Entdecken Sie seine Funktionen und ...","pt":"Aprenda a desenvolver servidores backend com ElysiaJS, um framework TypeScript para construir aplicações de alto desempenho","ru":"Узнайте, как разрабатывать серверы backend с помощью ElysiaJS, фреймворка TypeScript для создания высокопроизводительных приложений","ar":"تعلم كيفية تطوير خوادم الباك إند باستخدام إيليسيا جيه إس، إطار عمل تايب سكريبت لإنشاء تطبيقات عالية الأداء"},"definition":{"en":"elysiajs is a TypeScript framework for building high-performance, type-safe backend servers with comprehensive features for development and deployment","zh":"ElysiaJS是一个用于构建高性能后端服务器的TypeScript框架","ja":"ElysiaJSは、高性能バックエンドサーバーを構築するためのTypeScriptフレームワークです","ko":"ElysiaJS는 고성능 백엔드 서버를 구축하기 위한 TypeScript 프레임워크입니다","es":"ElysiaJS es un framework de TypeScript para desarrollar servidores backend de alto rendimiento con Bun.","fr":"ElysiaJS est un framework TypeScript pour développer des serveurs backend haute performance avec Bun.","de":"ElysiaJS ist ein TypeScript-Framework für die Entwicklung von Hochleistungs-Backend-Servern mit Bun.","pt":"ElysiaJS é um framework TypeScript para desenvolvimento de servidores backend","ru":"ElysiaJS - фреймворк TypeScript для разработки серверов backend","ar":"إيليسيا جيه إس هو إطار عمل تايب سكريبت لتطوير خوادم الباك إند"},"features":{"en":["Provides routing capabilities for building complex backend applications","Supports validation for ensuring data integrity and security","Includes authentication features for secure user management","Allows for plugin integrations to extend functionality","Enables deployment of high-performance backend servers on Bun"],"zh":["支持Bun-first的高性能后端服务器构建","类型安全的路由和验证","认证和授权机制","插件和扩展支持","部署和管理工具"],"ja":["Bun-firstの高性能バックエンドサーバー構築をサポート","タイプセーフのルーティングとバリデーション","認証と認可メカニズム","プラグインと拡張サポート","デプロイメントと管理ツール"],"ko":["Bun-first의 고성능 백엔드 서버 구축을 지원","타입 세이프한 라우팅과 유효성 검사","인증과 인가 메커니즘","플러그인과 확장 지원","배포와 관리 도구"],"es":["Routing avanzado","Validación de datos","Autenticación y autorización","Compatibilidad con plugins y extensiones","Despliegue en servidores Bun"],"fr":["Routing avancé","Validation de données","Authentification et autorisation","Compatibilité avec les plugins et extensions","Déploiement sur des serveurs Bun"],"de":["Erweitertes Routing","Datenvalidierung","Authentifizierung und Autorisierung","Kompatibilität mit Plugins und Erweiterungen","Bereitstellung auf Bun-Servern"],"pt":["Desenvolvimento de servidores backend com TypeScript","Construção de aplicações de alto desempenho","Suporte a routing e validação","Autenticação e integração de plugins","Deploy em ambiente de produção"],"ru":["Разработка серверов backend с помощью TypeScript","Создание высокопроизводительных приложений","Поддержка маршрутизации и валидации","Аутентификация и интеграция плагинов","Развертывание в производственной среде"],"ar":["تطوير خوادم الباك إند باستخدام تايب سكريبت","إنشاء تطبيقات عالية الأداء","دعم التوجيه والتحقق","التحقق والintegration الإضافات","نشر في بيئة الإنتاج"]},"keywords":{"en":["how to use elysiajs","what is elysiajs","elysiajs alternative","elysiajs vs nestjs","elysiajs install","elysiajs setup guide","type-safe backend development","bun-first backend servers"],"zh":["ElysiaJS","TypeScript","后端服务器","高性能","类型安全","路由","验证","认证","插件","部署"],"ja":["ElysiaJS","TypeScript","バックエンドサーバー","高性能","タイプセーフ","ルーティング","バリデーション","認証","プラグイン","デプロイメント","AIエージェント"],"ko":["ElysiaJS","TypeScript","백엔드 서버","고성능","타입 세이프","라우팅","유효성 검사","인증","플러그인","배포","AI 에이전트"],"es":["ElysiaJS","framework de TypeScript","servidores backend de alto rendimiento","Bun","routing avanzado","validación de datos","autenticación y autorización"],"fr":["ElysiaJS","framework TypeScript","serveurs backend haute performance","Bun","routing avancé","validation de données","authentification et autorisation"],"de":["ElysiaJS","TypeScript-Framework","Hochleistungs-Backend-Server","Bun","erweitertes Routing","Datenvalidierung","Authentifizierung und Autorisierung"],"pt":["ElysiaJS","desenvolvimento de servidores backend","TypeScript","alto desempenho","routing","validação","autenticação","plugins","deploy"],"ru":["ElysiaJS","разработка серверов backend","TypeScript","высокий уровень производительности","маршрутизация","валидация","аутентификация","плагины","развертывание"],"ar":["إيليسيا جيه إس","تطوير خوادم الباك إند","تايب سكريبت","أداء عال","التوجيه","التحقق","التحقق","الإضافات","نشر"]}},"owner":"yukikwi","repo":"elysia-boiler-plate","repoPath":"yukikwi/elysia-boiler-plate","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.539Z","topics":[],"category":"community","skillMd":{"name":"elysiajs","description":"Create backend with ElysiaJS, a type-safe, high-performance framework.","bodyPreview":"# ElysiaJS Development Skill\n\nAlways consult [elysiajs.com/llms.txt](https://elysiajs.com/llms.txt) for code examples and latest API.\n\n## Overview\n\nElysiaJS is a TypeScript framework for building Bun-first (but not limited to Bun) type-safe, high-performance backend servers. This skill provides comprehensive guidance for developing with Elysia, including routing, validation, authentication, plugins, integrations, and deployment.\n\n## When to Use This Skill\n\nTrigger this skill when the user asks t","body":"# ElysiaJS Development Skill\n\nAlways consult [elysiajs.com/llms.txt](https://elysiajs.com/llms.txt) for code examples and latest API.\n\n## Overview\n\nElysiaJS is a TypeScript framework for building Bun-first (but not limited to Bun) type-safe, high-performance backend servers. This skill provides comprehensive guidance for developing with Elysia, including routing, validation, authentication, plugins, integrations, and deployment.\n\n## When to Use This Skill\n\nTrigger this skill when the user asks to:\n- Create or modify ElysiaJS routes, handlers, or servers\n- Setup validation with TypeBox or other schema libraries (Zod, Valibot)\n- Implement authentication (JWT, session-based, macros, guards)\n- Add plugins (CORS, OpenAPI, Static files, JWT)\n- Integrate with external services (Drizzle ORM, Better Auth, Next.js, Eden Treaty)\n- Setup WebSocket endpoints for real-time features\n- Create unit tests for Elysia instances\n- Deploy Elysia servers to production\n\n## Quick Start\nQuick scaffold:\n```bash\nbun create elysia app\n```\n\n### Basic Server\n```typescript\nimport { Elysia, t, status } from ''elysia''\n\nconst app = new Elysia()\n  \t.get(''/'', () => ''Hello World'')\n   \t.post(''/user'', ({ body }) => body, {\n    \tbody: t.Object({\n      \t\tname: t.String(),\n        \tage: t.Number()\n     \t})\n    })\n    .get(''/id/:id'', ({ params: { id } }) => {\n   \t\tif(id > 1_000_000) return status(404, ''Not Found'')\n     \n     \treturn id\n    }, {\n    \tparams: t.Object({\n     \t\tid: t.Number({\n       \t\t\tminimum: 1\n       \t\t})\n     \t}),\n     \tresponse: {\n      \t\t200: t.Number(),\n        \t404: t.Literal(''Not Found'')\n      \t}\n    })\n    .listen(3000)\n```\n\n## Basic Usage\n\n### HTTP Methods\n```typescript\nimport { Elysia } from ''elysia''\n\nnew Elysia()\n  .get(''/'', ''GET'')\n  .post(''/'', ''POST'')\n  .put(''/'', ''PUT'')\n  .patch(''/'', ''PATCH'')\n  .delete(''/'', ''DELETE'')\n  .options(''/'', ''OPTIONS'')\n  .head(''/'', ''HEAD'')\n```\n\n### Path Parameters\n```typescript\n.get(''/user/:id'', ({ params: { id } }) => id)\n.get(''/post/:id/:slug'', ({ params }) => params)\n```\n\n### Query Parameters\n```typescript\n.get(''/search'', ({ query }) => query.q)\n// GET /search?q=elysia → \"elysia\"\n```\n\n### Request Body\n```typescript\n.post(''/user'', ({ body }) => body)\n```\n\n### Headers\n```typescript\n.get(''/'', ({ headers }) => headers.authorization)\n```\n\n## TypeBox Validation\n\n### Basic Types\n```typescript\nimport { Elysia, t } from ''elysia''\n\n.post(''/user'', ({ body }) => body, {\n  body: t.Object({\n    name: t.String(),\n    age: t.Number(),\n    email: t.String({ format: ''email'' }),\n    website: t.Optional(t.String({ format: ''uri'' }))\n  })\n})\n```\n\n### Nested Objects\n```typescript\nbody: t.Object({\n  user: t.Object({\n    name: t.String(),\n    address: t.Object({\n      street: t.String(),\n      city: t.String()\n    })\n  })\n})\n```\n\n### Arrays\n```typescript\nbody: t.Object({\n  tags: t.Array(t.String()),\n  users: t.Array(t.Object({\n    id: t.String(),\n    name: t.String()\n  }))\n})\n```\n\n### File Upload\n```typescript\n.post(''/upload'', ({ body }) => body.file, {\n  body: t.Object({\n    file: t.File({\n      type: ''image'',              // image/* mime types\n      maxSize: ''5m''               // 5 megabytes\n    }),\n    files: t.Files({              // Multiple files\n      type: [''image/png'', ''image/jpeg'']\n    })\n  })\n})\n```\n\n### Response Validation\n```typescript\n.get(''/user/:id'', ({ params: { id } }) => ({\n  id,\n  name: ''John'',\n  email: ''john@example.com''\n}), {\n  params: t.Object({\n    id: t.Number()\n  }),\n  response: {\n    200: t.Object({\n      id: t.Number(),\n      name: t.String(),\n      email: t.String()\n    }),\n    404: t.String()\n  }\n})\n```\n\n## Standard Schema (Zod, Valibot, ArkType)\n\n### Zod\n```typescript\nimport { z } from ''zod''\n\n.post(''/user'', ({ body }) => body, {\n  body: z.object({\n    name: z.string(),\n    age: z.number().min(0),\n    email: z.string().email()\n  })\n})\n```\n\n## Error Handling\n\n```typescript\n.get(''/user/:id'', ({ params: { id }, status }) => {\n  const user = findUser(id)\n  \n  if (!user) {\n    return status(404, ''User not found'')\n  }\n  \n  return user\n})\n```\n\n## Guards (Apply to Multiple Routes)\n\n```typescript\n.guard({\n  params: t.Object({\n    id: t.Number()\n  })\n}, app => app\n  .get(''/user/:id'', ({ params: { id } }) => id)\n  .delete(''/user/:id'', ({ params: { id } }) => id)\n)\n```\n\n## Macro\n\n```typescript\n.macro({\n  hi: (word: string) => ({\n    beforeHandle() { console.log(word) }\n  })\n})\n.get(''/'', () => ''hi'', { hi: ''Elysia'' })\n```\n\n### Project Structure (Recommended)\nElysia takes an unopinionated approach but based on user request. But without any specific preference, we recommend a feature-based and domain driven folder structure where each feature has its own folder containing controllers, services, and models.\n\n```\nsrc/\n├── index.ts              # Main server entry\n├── modules/\n│   ├── auth/\n│   │   ├── index.ts      # Auth routes (Elysia instance)\n│   │   ├── service.ts    # Business logic\n│   │   └── model.ts      # TypeBox schemas/DTOs\n│   └── user/\n│       ├── index.ts\n│       ├── service.ts\n│       └── model.ts\n└── plugins/\n    └── custom.ts\n\npublic/                   # Static files (if using static plugin)\ntest/                     # Unit tests\n```\n\nEach file has its own responsibility as follows:\n- **Controller (index.ts)**: Handle HTTP routing, request validation, and cookie.\n- **Service (service.ts)**: Handle business logic, decoupled from Elysia controller if possible.\n- **Model (model.ts)**: Define the data structure and validation for the request and response.\n\n## Best Practice\nElysia is unopinionated on design pattern, but if not provided, we can relies on MVC pattern pair with feature based folder structure.\n\n- Controller:\n\t- Prefers Elysia as a controller for HTTP dependant controller\n\t- For non HTTP dependent, prefers service instead unless explicitly asked\n\t- Use `onError` to handle local custom errors\n\t- Register Model to Elysia instance via `Elysia.models({ ...models })` and prefix model by namespace `Elysia.prefix(''model'', ''Namespace.'')\n\t- Prefers Reference Model by name provided by Elysia instead of using an actual `Model.name`\n- Service:\n\t- Prefers class (or abstract class if possible)\n\t- Prefers interface/type derive from `Model`\n\t- Return `status` (`import { status } from ''elysia''`) for error\n\t- Prefers `return Error` instead of `throw Error`\n- Models:\n\t- Always export validation model and type of validation model\n\t- Custom Error should be in contains in Model\n\n## Elysia Key Concept\nElysia has a every important concepts/rules to understand before use.\n\n## Encapsulation - Isolates by Default\n\nLifecycles (hooks, middleware) **don''t leak** between instances unless scoped.\n\n**Scope levels:**\n- `local` (default) - current instance + descendants\n- `scoped` - parent + current + descendants  \n- `global` - all instances\n\n```ts\n.onBeforeHandle(() => {}) // only local instance\n.onBeforeHandle({ as: ''global'' }, () => {}) // exports to all\n```\n\n## Method Chaining - Required for Types\n\n**Must chain**. Each method returns new type reference.\n\n❌ Don''t:\n```ts\nconst app = new Elysia()\napp.state(''build'', 1) // loses type\napp.get(''/'', ({ store }) => store.build) // build doesn''t exists\n```\n\n✅ Do:\n```ts\nnew Elysia()\n  .state(''build'', 1)\n  .get(''/'', ({ store }) => store.build)\n```\n\n## Explicit Dependencies\n\nEach instance independent. **Declare what you use.**\n\n```ts\nconst auth = new Elysia()\n\t.decorate(''Auth'', Auth)\n\t.model(Auth.models)\n\nnew Elysia()\n  .get(''/'', ({ Auth }) => Auth.getProfile()) // Auth doesn''t exists\n\nnew Elysia()\n  .use(auth) // must declare\n  .get(''/'', ({ Auth }) => Auth.getProfile())\n```\n\n**Global scope when:**\n- No types added (cors, helmet)\n- Global lifecycle (logging, tracing)\n\n**Explicit when:**\n- Adds types (state, models)\n- Business logic (auth, db)\n\n## Deduplication\n\nPlugins re-execute unless named:\n\n```ts\nnew Elysia() // rerun on `.use`\nnew Elysia({ name: ''ip'' }) // runs once across all instances\n```\n\n## Order Matters\n\nEvents apply to routes **registered after** them.\n\n```ts\n.onBeforeHandle(() => console.log(''1''))\n.get(''/'', () => ''hi'') // has hook\n.onBeforeHandle(() => console.log(''2'')) // doesn''t affect ''/''\n```\n\n## Type Inference\n\n**Inline functions only** for accurate types.\n\nFor controllers, destructure in inline wrapper:\n\n```ts\n.post(''/'', ({ body }) => Controller.greet(body), {\n  body: t.Object({ name: t.String() })\n})\n```\n\nGet type from schema:\n```ts\ntype MyType = typeof MyType.static\n```\n\n## Reference Model\nModel can be reference by name, especially great for documenting an API\n```ts\nnew Elysia()\n\t.model({\n\t\tbook: t.Object({\n\t\t\tname: t.String()\n\t\t})\n\t})\n\t.post(''/'', ({ body }) => body.name, {\n\t\tbody: ''book''\n\t})\n```\n\nModel can be renamed by using `.prefix` / `.suffix`\n```ts\nnew Elysia()\n\t.model({\n\t\tbook: t.Object({\n\t\t\tname: t.String()\n\t\t})\n\t})\n\t.prefix(''model'', ''Namespace'')\n\t.post(''/'', ({ body }) => body.name, {\n\t\tbody: ''Namespace.Book''\n\t})\n```\n\nOnce `prefix`, model name will be capitalized by default.\n\n## Technical Terms\nThe following are technical terms that is use for Elysia:\n- `OpenAPI Type Gen` - function name `fromTypes` from `@elysiajs/openapi` for generating OpenAPI from types, see `plugins/openapi.md`\n- `Eden`, `Eden Treaty` - e2e type safe RPC client for share type from backend to frontend\n\n## Resources\nUse the following references as needed.\n\nIt''s recommended to checkout `route.md` for as it contains the most important foundation building blocks with examples.\n\n`plugin.md` and `validation.md` is important as well but can be check as needed.\n\n### references/\nDetailed documentation split by topic:\n- `bun-fullstack-dev-server.md` - Bun Fullstack Dev Server with HMR. React without bundler.\n- `cookie.md` - Detailed documentation on cookie\n- `deployment.md` - Production deployment guide / Docker\n- `eden.md` - e2e type safe RPC client for share type from backend to frontend\n- `guard.md` - Setting validation/lifecycle all at once\n- `macro.md` - Compose multiple schema/lifecycle as a reusable Elysia via key-value (recommended for complex setup, eg. authentication, authorization, Role-based Access Check)\n- `plugin.md` - Decouple part of Elysia into a standalone component\n- `route.md` - Elysia foundation building block: Routing, Handler and Context\n- `testing.md` - Unit tests with examples\n- `validation.md` - Setup input/output validation and list of all custom validation rules\n- `websocket.md` - Real-time features\n\n### plugins/ \nDetailed documentation, usage and configuration reference for official Elysia plugin:\n- `bearer.md` - Add bearer capability to Elysia (`@elysiajs/bearer`)\n- `cors.md` - Out of box configuration for CORS (`@elysiajs/cors`)\n- `cron.md` - Run cron job with access to Elysia context (`@elysiajs/cron`)\n- `graphql-apollo.md` - Integration GraphQL Apollo (`@elysiajs/graphql-apollo`)\n- `graphql-yoga.md` - Integration with GraphQL Yoga (`@elysiajs/graphql-yoga`)\n- `html.md` - HTML and JSX plugin setup and usage (`@elysiajs/html`)\n- `jwt.md` - JWT / JWK plugin (`@elysiajs/jwt`)\n- `openapi.md` - OpenAPI documentation and OpenAPI Type Gen / OpenAPI from types (`@elysiajs/openapi`)\n- `opentelemetry.md` - OpenTelemetry, instrumentation, and record span utilities (`@elysiajs/opentelemetry`)\n- `server-timing.md` - Server Timing metric for debug (`@elysiajs/server-timing`) \n- `static.md` - Serve static files/folders for Elysia Server (`@elysiajs/static`)\n\n### integrations/\nGuide to integrate Elysia with external library/runtime:\n- `ai-sdk.md` - Using Vercel AI SDK with Elysia\n- `astro.md` - Elysia in Astro API route\n- `better-auth.md` - Integrate Elysia with better-auth\n- `cloudflare-worker.md` - Elysia on Cloudflare Worker adapter\n- `deno.md` - Elysia on Deno\n- `drizzle.md` - Integrate Elysia with Drizzle ORM\n- `expo.md` - Elysia in Expo API route\n- `nextjs.md` - Elysia in Nextjs API route\n- `nodejs.md` - Run Elysia on Node.js\n- `nuxt.md` - Elysia on API route\n- `prisma.md` - Integrate Elysia with Prisma\n- `react-email.d` - Create and Send Email with React and Elysia\n- `sveltekit.md` - Run Elysia on Svelte Kit API route\n- `tanstack-start.md` - Run Elysia on Tanstack Start / React Query\n- `vercel.md` - Deploy Elysia to Vercel\n\n### examples/ (optional)\n- `basic.ts` - Basic Elysia example\n- `body-parser.ts` - Custom body parser example via `.onParse`\n- `complex.ts` - Comprehensive usage of Elysia server\n- `cookie.ts` - Setting cookie\n- `error.ts` - Error handling\n- `file.ts` - Returning local file from server\n- `guard.ts` - Setting mulitple validation schema and lifecycle\n- `map-response.ts` - Custom response mapper\n- `redirect.ts` - Redirect response\n- `rename.ts` - Rename context''s property \n- `schema.ts` - Setup validation\n- `state.ts` - Setup global state\n- `upload-file.ts` - File upload with validation\n- `websocket.ts` - Web Socket for realtime communication\n\n### patterns/ (optional)\n- `patterns/mvc.md` - Detail guideline for using Elysia with MVC patterns\n"},"lastSynced":"2026-03-08T02:11:10.289Z","agentAnalysis":{"suitability":{"en":"Perfect for Backend Agents needing high-performance, type-safe server development with Bun-first approach and TypeScript.","zh":"适用于需要高性能、类型安全的服务器开发的后端代理，采用Bun-first方法和TypeScript。","ja":"Bun-firstアプローチとTypeScriptを使用した高性能・型安全のサーバー開発を必要とするバックエンドエージェントに最適。","ko":"Bun-first 접근 방식과 TypeScript를 사용하여 높은 성능과 타입 안전성을 제공하는 서버 개발이 필요한 백엔드 에이전트에 적합합니다.","es":"Perfecto para Agentes de Backend que necesitan un desarrollo de servidor de alto rendimiento, seguro con tipos y enfoque Bun-first con TypeScript.","fr":"Parfait pour les agents Backend nécessitant un développement de serveur haute performance, sécurisé avec des types et une approche Bun-first avec TypeScript.","de":"Perfekt für Backend-Agents, die ein hochleistungsfähiges, typesicheres Server-Entwicklung mit Bun-first-Ansatz und TypeScript benötigen.","pt":"Perfeito para Agentes de Backend que necessitam de desenvolvimento de servidor de alta performance, com segurança de tipo e abordagem Bun-first, com TypeScript.","ru":"Идеально подходит для агентов Backend, которым требуется разработка сервера с высокой производительностью, безопасностью типов и подходом Bun-first, с использованием TypeScript.","ar":"مثالي لعميل الخلفية الذي يحتاج إلى تطوير خادم ذو أداء عالي، وأمان نوع، ونهج Bun-first، مع TypeScript."},"recommendation":{"en":"Empowers agents to build scalable backend servers with ElysiaJS, utilizing routing, validation, and authentication features, and supporting plugins, integrations, and deployment, all while leveraging TypeScript for type safety and Bun for high performance.","zh":"赋予代理构建可扩展的后端服务器的能力，利用ElysiaJS，包括路由、验证和身份验证功能，并支持插件、集成和部署，同时利用TypeScript进行类型安全性和Bun进行高性能。","ja":"ElysiaJSを利用して、ルーティング、バリデーション、認証機能を備えたスケーラブルなバックエンドサーバーを構築するエージェントの能力を付与し、プラグイン、統合、デプロイメントをサポートし、TypeScriptによる型安全性とBunによる高パフォーマンスを活用。","ko":"ElysiaJS를 사용하여 라우팅, 검증, 인증 기능을 갖춘 확장 가능한 백엔드 서버를 구축할 수 있는 에이전트의 능력을 부여하며, 플러그인, 통합, 배포를 지원하며 TypeScript를 통한 타입 안전성과 Bun을 통한 고성능을 활용합니다.","es":"Permite a los agentes crear servidores de backend escalables con ElysiaJS, utilizando características de enrutamiento, validación y autenticación, y admitiendo complementos, integraciones y despliegue, todo mientras aprovecha TypeScript para la seguridad de tipos y Bun para un alto rendimiento.","fr":"Permet aux agents de créer des serveurs de backend évolutifs avec ElysiaJS, en utilisant des fonctionnalités de routage, de validation et d''authentification, et en prenant en charge les plugins, les intégrations et le déploiement, le tout en exploitant TypeScript pour la sûreté des types et Bun pour des performances élevées.","de":"Ermöglicht es den Agenten, skalierbare Backend-Server mit ElysiaJS zu erstellen, indem sie Routing-, Validierungs- und Authentifizierungsfunktionen nutzen und Erweiterungen, Integrationen und Bereitstellung unterstützen, all dies unter Ausnutzung von TypeScript für die Typsicherheit und Bun für hohe Leistung.","pt":"Habilita os agentes a construir servidores backend escaláveis com ElysiaJS, utilizando recursos de roteamento, validação e autenticação, e suportando plugins, integrações e implantação, tudo isso aproveitando o TypeScript para segurança de tipo e o Bun para alto desempenho.","ru":"Позволяет агентам создавать масштабируемые серверы Backend с помощью ElysiaJS, используя функции маршрутизации, валидации и аутентификации, а также поддерживая плагины, интеграции и развертывание, все это при помощи TypeScript для безопасности типов и Bun для высокой производительности.","ar":"تمكّن الوكلاء من بناء خوادم خلفية قابلة للتحجيم مع ElysiaJS، باستخدام ميزات التوجيه والتحقق والتحقق، ودعم الملحقات والتكاملات والنشر، كل ذلك مع الاستفادة من TypeScript لأمان النوع وBun لأداء عال."},"useCases":{"en":["Building high-performance RESTful APIs with type-safe routing","Implementing robust validation and authentication mechanisms for backend servers","Creating scalable and maintainable server architectures with ElysiaJS plugins and integrations"],"zh":["构建具有类型安全路由的高性能RESTful API","实现强大的验证和身份验证机制用于后端服务器","使用ElysiaJS插件和集成创建可扩展且可维护的服务器架构"],"ja":["型安全なルーティングを備えた高性能RESTful APIの構築","バックエンドサーバー用の強力なバリデーションと認証メカニズムの実装","ElysiaJSプラグインと統合を使用したスケーラブルでメンテナンス可能なサーバーアーキテクチャの作成"],"ko":["타입 안전한 라우팅을 갖춘 고성능 RESTful API 구축","백엔드 서버를 위한 강력한 검증 및 인증 메커니즘 구현","ElysiaJS 플러그인 및 통합을 사용하여 확장 가능하고 유지 보수 가능한 서버 아키텍처 생성"],"es":["Creación de API REST de alto rendimiento con enrutamiento seguro con tipos","Implementación de mecanismos de validación y autenticación robustos para servidores de backend","Creación de arquitecturas de servidor escalables y mantenibles con plugins y integraciones de ElysiaJS"],"fr":["Création d''API REST de haute performance avec un routage sécurisé avec des types","Mise en œuvre de mécanismes de validation et d''authentification robustes pour les serveurs de backend","Création d''architectures de serveur évolutives et maintenables avec des plugins et des intégrations ElysiaJS"],"de":["Erstellung von REST-APIs mit hoher Leistung und typesicherem Routing","Implementierung robuster Validierungs- und Authentifizierungsmechanismen für Backend-Server","Erstellung von skalierbaren und wartbaren Server-Architekturen mit ElysiaJS-Plug-ins und -Integrationen"],"pt":["Construir APIs RESTful de alta performance com roteamento seguro de tipo","Implementar mecanismos robustos de validação e autenticação para servidores backend","Criar arquiteturas de servidor escaláveis e mantenedoras com plugins e integrações do ElysiaJS"],"ru":["Построение высокопроизводительных RESTful API с безопасным типом маршрутизации","Реализация надежных механизмов валидации и аутентификации для серверов Backend","Создание масштабируемых и поддерживаемых архитектур сервера с помощью плагинов и интеграций ElysiaJS"],"ar":["بناء واجهات برمجة تطبيقات RESTful عالية الأداء مع توجيه آمن من النوع","تنفيذ آليات التحقق والتحقق القوية لخوادم الخلفية","إنشاء هندسات خادم قابلة للتحجيم وقابلة للصيانة مع ملحقات وتكاملات ElysiaJS"]},"limitations":{"en":["Requires TypeScript knowledge","Bun-first approach may require additional setup for non-Bun environments","Dependent on ElysiaJS framework and its compatibility with other libraries and tools"],"zh":["需要TypeScript知识","Bun-first方法可能需要非Bun环境的额外设置","依赖于ElysiaJS框架及其与其他库和工具的兼容性"],"ja":["TypeScriptの知識が必要","Bun-firstアプローチは非Bun環境では追加の設定が必要","ElysiaJSフレームワークと他のライブラリやツールとの互換性に依存"],"ko":["TypeScript 지식이 필요함","Bun-first 접근 방식은 비-Bun 환경에서는 추가 설정이 필요함","ElysiaJS 프레임워크와 다른 라이브러리 및 툴과의 호환성에 의존"],"es":["Requiere conocimiento de TypeScript","El enfoque Bun-first puede requerir una configuración adicional para entornos no Bun","Dependiente del marco de trabajo ElysiaJS y su compatibilidad con otras bibliotecas y herramientas"],"fr":["Nécessite des connaissances en TypeScript","L''approche Bun-first peut nécessiter une configuration supplémentaire pour les environnements non Bun","Dépendant du framework ElysiaJS et de sa compatibilité avec d''autres bibliothèques et outils"],"de":["Benötigt TypeScript-Kenntnisse","Der Bun-first-Ansatz kann eine zusätzliche Einrichtung für nicht-Bun-Umgebungen erfordern","Abhängig vom ElysiaJS-Framework und seiner Kompatibilität mit anderen Bibliotheken und Tools"],"pt":["Exige conhecimento de TypeScript","Abordagem Bun-first pode exigir configuração adicional para ambientes não-Bun","Dependente do framework ElysiaJS e sua compatibilidade com outras bibliotecas e ferramentas"],"ru":["Требует знания TypeScript","Подход Bun-first может требовать дополнительной настройки для сред, не являющихся Bun","Зависит от фреймворка ElysiaJS и его совместимости с другими библиотеками и инструментами"],"ar":["يتطلب معرفة بTypeScript","يمكن أن تتطلب نهج Bun-first إعدادات إضافية لبيئات غير Bun","يعتمد على إطار عمل ElysiaJS ومدى توافقه مع مكتبات وأدوات أخرى"]},"version":4},"contentHash":"c553412bafe02012b323ae7d118841375e58810be4f6984a3970d83bf7988355","qualityScore":60}');
