INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yukikwi/elysia-boiler-plate/elysiajs', 'elysiajs', 'yukikwi', 'elysia-boiler-plate', 'community', 'elysiajs yukikwi elysia-boiler-plate community Elysiajs is a TypeScript framework for building Bun-first backend servers, providing guidance on routing, validation, and authentication for developers. ElysiaJS是一个TypeScript框架，用于构建高性能后端服务器。该技能提供了综合的开发指南，包括路由、验证、认证和部署 ElysiaJSは、高性能バックエンドサーバーを構築するためのTypeScriptフレームワークです。このスキルでは、ルーティング、バリデーション、認証、プラグイン、デプロイメントに関する包括的な開発ガイドを提供します ElysiaJS는 고성능 백엔드 서버를 구축하기 위한 TypeScript 프레임워크입니다. 이 스킬은 라우팅, 유효성 검사, 인증, 플러그인 및 배포와 관련된 포괄적인 개발 가이드를 제공합니다 ElysiaJS es un framework de TypeScript para construir servidores backend de alto rendimiento con Bun. Ofrece routing, validación, autenticación y más. ElysiaJS est un framework TypeScript pour créer des serveurs backend haute performance avec Bun. Il propose du routing, de la validation, de l''authentification et plus. ElysiaJS ist ein TypeScript-Framework für den Bau von Hochleistungs-Backend-Servern mit Bun. Es bietet Routing, Validierung, Authentifizierung und mehr. ElysiaJS é um framework TypeScript para desenvolvimento de servidores backend de alto desempenho. Este skill fornece orientação abrangente para desenvolvimento com Elysia ElysiaJS - фреймворк TypeScript для разработки серверов backend с высоким уровнем производительности. Этот навык предоставляет всестороннее руководство для разработки с Elysia إيليسيا جيه إس هو إطار عمل تايب سكريبت لتطوير خوادم الباك إند عالية الأداء. هذا المهارة يوفر إرشادات شاملة لتطوير إيليسيا how to use elysiajs what is elysiajs elysiajs alternative elysiajs vs nestjs elysiajs install elysiajs setup guide type-safe backend development bun-first backend servers ElysiaJS TypeScript 后端服务器 高性能 类型安全 路由 验证 认证 插件 部署 Provides routing capabilities for building complex backend applications Supports validation for ensuring data integrity and security Includes authentication features for secure user management Allows for plugin integrations to extend functionality Enables deployment of high-performance backend servers on Bun elysiajs is a TypeScript framework for building high-performance, type-safe backend servers with comprehensive features for development and deployment');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('khushparag/agentic_learning_coach/browser-use', 'community', 'khushparag', 'agentic_learning_coach', 'khushparag/agentic_learning_coach', 'browser-use', 0, 0, 60, '2026-03-08T01:57:15.542Z', '2026-03-08T02:11:13.605Z', '44c7977eaa481427ddbeb7f84d72e36b06d457901cb195f4d9d90a8846bae5a8', '{"id":"khushparag/agentic_learning_coach/browser-use","name":"browser-use","description":{"en":"The browser-use skill provides intelligent multi-agent system for personalized coding education, utilizing FastAPI, React, and PostgreSQL. It benefits developers seeking efficient browser automation and adaptive learning","zh":"browser-use提供快速持久的浏览器自动化，支持复杂的多步骤工作流程","ja":"browser-useは高速で永続的なブラウザ自動化を提供し、複雑なマルチステップのワークフローをサポートします","ko":"browser-use는 빠르고 지속적인 브라우저 자동화를 제공하며, 복잡한 멀티스텝 워크플로를 지원합니다","es":"browser-use es un sistema de automatización de navegador que mantiene sesiones de navegador a través de comandos, permitiendo flujos de trabajo complejos","fr":"browser-use est un système d''automatisation de navigateur qui maintient les sessions de navigateur à travers les commandes, permettant des flux de travail complexes","de":"browser-use ist ein Browser-Automatisierungssystem, das Browser-Sitzungen über Befehle hinweg beibehält und komplexe Arbeitsabläufe ermöglicht","pt":"O browser-use é uma ferramenta de automação de navegador que utiliza CLI e suporta tecnologias como FastAPI e React. Oferece uma forma personalizada de melhorar a produtividade","ru":"Browser-use - это инструмент для автоматизации браузера, который использует CLI и поддерживает технологии как FastAPI и React. Предлагает персонализированный способ повышения производительности с ИИ Агентами","ar":"browser-use هي أداة آليّة المتصفح التي تستخدم واجهة سطر الأوامر وتدعم تقنيات مثل FastAPI و React. توفر طريقة مخصصة لتحسين الإنتاجية باستخدام أدوات الإي أى"},"seo":{"ti