INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pengelbrecht/ticks/ticks', 'ticks', 'pengelbrecht', 'ticks', 'community', 'ticks pengelbrecht ticks community Ticks is an issue tracker for AI agents, managing tasks and providing a web-based board. It benefits AI developers and teams working on complex projects. Ticks是一种AI代理任务管理工具，支持持续循环运行和Web监控 TicksはAIエージェントのタスク管理ツールであり、継続的なループ実行とWeb監視をサポート Ticks는 AI 에이전트 작업 관리 도구로 연속 루프 실행 및 웹 모니터링을 지원 Ticks es una herramienta de seguimiento de problemas para agentes de inteligencia artificial que utiliza la línea de comandos tk para gestionar tareas. Ticks est un outil de suivi de problèmes pour les agents d''intelligence artificielle qui utilise la ligne de commande tk pour gérer des tâches. Ticks ist ein Tool zur Fehlerverfolgung für künstliche Intelligenz-Agenten, das die Kommandozeile tk zur Aufgabenverwaltung verwendet. O Ticks é um rastreador de problemas projetado para agentes de IA, com recursos como gerenciamento de tarefas e execução contínua de agentes Ticks - это отслеживатель проблем, предназначенный для ИИ Агентов, с функциями как управление задачами и непрерывное выполнение агентов التيكات هو عامل تتبع للمشاكل مصمم لأدوات الذكاء الاصطناعي، مع ميزات مثل إدارة المهام وتنفيذ متواصل للوكلاء how to use ticks ticks vs TodoWrite ticks setup guide ticks alternative ticks install what is ticks ticks for AI agents task management with ticks AI代理任务管理 Ticks设置指南 AI工具任务管理 持续循环运行 Web监控 CLI命令行管理 任务依赖管理 持久历史和笔记 Manages tasks using the tk CLI Runs agents in continuous loops Provides a web-based board for monitoring Supports human handoff and approval gates Offers persistent history and notes for tasks Ticks is an issue tracker designed for AI agents, providing a workflow management system with the tk CLI and web-based monitoring board.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('muspelheim/claude-roaster/roast', 'community', 'muspelheim', 'claude-roaster', 'muspelheim/claude-roaster', 'roast', 0, 0, 60, '2026-03-08T01:57:15.549Z', '2026-03-08T02:11:23.961Z', '095952be4fcc78565a8cf8fc5cd6cf5ffbefa22407473063179f5b0a1ea8f822', '{"id":"muspelheim/claude-roaster/roast","name":"roast","description":{"en":"The roast skill provides brutally honest UI/UX critique with multi-perspective analysis, helping developers and designers improve their applications through iterative refinement.","zh":"Roast 是一个提供 UI/UX 评估和改进的工具，支持多视角分析和迭代改进","ja":"Roast は、UI/UX を評価し、改善するツールです。多視点分析とイテレーション改善をサポートします","ko":"Roast는 UI/UX를 평가하고 개선하는 도구로 다각도 분석 및 반복적 개선을 지원합니다","es":"Roast es una herramienta de análisis UI/UX que ofrece una crítica honesta y análisis multi-perspectivo para mejorar la experiencia del usuario","fr":"Roast est un outil d''analyse UI/UX qui offre une critique honnête et une analyse multi-perspective pour améliorer l''expérience utilisateur","de":"Roast ist ein UI/UX-Analyse-Tool, das eine ehrliche Kritik und eine multi-perspektivische Analyse bietet, um die Benutzererfahrung zu verbessern","pt":"O Roast é uma ferramenta de análise UI/UX avançada que fornece uma crítica honesta e multi-perspectiva para melhorar a experiência do usuário","ru":"ИИ Агент Roast - это инструмент для анализа UI/UX, который предоставляет честную и многофакторную критику для улучшения пользовательского опыта","ar":"أداة Roast هي أداة تحليل واجهة المستخدم وتجربة المستخدم المتقدمة التي توفر نقدًا صادقًا ومتعدد المنظورات لتحسين تجربة المستخدم"},"seo":{"title":{"en":"roast: UI/UX Critique and Improvement Setup Guide | AI Ag...","zh":"Roast Setup Guide: UI/UX 评估和改进工具","ja":"Roast 導入ガイド: UI/UX レビューと改善ツール","ko":"Roast 설정 가이드: UI/UX 평가 및 개선 도구","es":"Guía de configuración de Roast: Análisis UI/UX con herram...","fr":"Configurer Roast: Outil d''analyse UI/UX avec des agents d''IA","de":"Roast-Setup-Leitfaden: UI/UX-Analyse mit KI-Tools","pt":"Guia de Configuração do Roast: Análise UI/UX Avançada","ru":"ИИ Агент Roast: Руководство по Настройке и Использованию","ar":"دليل إعداد أداة Roast: تحليل واجهة المستخدم وتجربة المستخ..."},"description":{"en":"Unlock brutally honest UI/UX critique with roast. Learn how to use multi-perspective analysis for iterative improvement and boost your design skills today!","zh":"使用 Roast 进行 UI/UX 评估和改进，支持多视角分析和迭代改进","ja":"Roast を使用して UI/UX を評価し、改善する。多視点分析とイテレーション改善をサポート","ko":"Roast를 사용하여 UI/UX를 평가하고 개선하세요. 다각도 분석 및 반복적 개선을 지원합니다","es":"Aprende a utilizar Roast para analizar y mejorar la experiencia del usuario con opciones de análisis de pantalla única, flujo de usuario y revisión de aplica...","fr":"Découvrez comment utiliser Roast pour analyser et améliorer l''expérience utilisateur avec des options d''analyse d''écran unique, de flux utilisateur et de rév...","de":"Erfahren Sie, wie Sie Roast verwenden, um die Benutzererfahrung zu analysieren und zu verbessern, mit Optionen für Einzelscreen-Analyse, Benutzerfluss und vo...","pt":"Aprenda a configurar e usar o Roast para análise UI/UX avançada e melhore a experiência do usuário com nossa ferramenta de análise multi-perspectiva","ru":"Узнайте, как настроить и использовать ИИ Агент Roast для анализа UI/UX и улучшения пользовательского опыта с помощью нашей многофакторной аналитической инстр...","ar":"تعلم كيفية إعداد واستخدام أداة Roast لتحليل واجهة المستخدم وتجربة المستخدم المتقدمة و تحسين تجربة المستخدم مع أداة تحليل متعددة المنظورات"},"definition":{"en":"roast is a UI/UX critique skill that offers multi-perspective analysis and iterative improvement for single screen, flow, and full application reviews","zh":"Roast 是一个 UI/UX 评估和改进工具，提供多视角分析和迭代改进","ja":"Roast は、UI/UX を評価し、改善するツールで、多視点分析とイテレーション改善をサポートする","ko":"Roast는 UI/UX를 평가하고 개선하는 도구로 다각도 분석 및 반복적 개선을 지원하는 AI 에이전트입니다","es":"Roast es una herramienta de análisis UI/UX que utiliza técnicas de AI para evaluar y mejorar la experiencia del usuario","fr":"Roast est un outil d''analyse UI/UX qui utilise des techniques d''IA pour évaluer et améliorer l''expérience utilisateur","de":"Roast ist ein UI/UX-Analyse-Tool, das AI-Techniken verwendet, um die Benutzererfahrung zu bewerten und zu verbessern","pt":"O Roast é uma ferramenta de análise UI/UX que realiza uma crítica honesta e multi-perspectiva para melhorar a experiência do usuário","ru":"ИИ Агент Roast - это инструмент для анализа UI/UX, который выполняет честную и многофакторную критику для улучшения пользовательского опыта","ar":"أداة Roast هي أداة تحليل واجهة المستخدم وتجربة المستخدم التي تقوم بنقد صادق ومتعدد المنظورات لتحسين تجربة المستخدم"},"features":{"en":["Supports single screen analysis via `/roast screen` command","Performs multi-screen user journey audits with `/roast flow` mode","Allows full application reviews for comprehensive critique","Customizable roast cycles with `--iterations` option","Prioritizes specific areas of focus using `--focus` option (a11y, conversion, usability, visual, implementation)"],"zh":["支持多视角分析","迭代改进功能","命令行接口（CLI）支持","多种模式支持（screen、flow、full）","自定义输出路径"],"ja":["多視点分析をサポート","イテレーション改善機能","コマンドラインインターフェース（CLI）をサポート","複数のモードをサポート（screen、flow、full）","出力パスのカスタマイズ"],"ko":["다각도 분석 지원","반복적 개선 기능","명령줄 인터페이스（CLI） 지원","다양한 모드 지원（screen、flow、full）","출력 경로 사용자 지정"],"es":["Análisis de pantalla única con opciones de personalización","Análisis de flujo de usuario para evaluar la experiencia del usuario","Revisión de aplicaciones completas para identificar áreas de mejora","Opciones de iteración para refinar y mejorar la experiencia del usuario","Análisis de accesibilidad y usabilidad para garantizar la compatibilidad","Compatibilidad con CLI para una integración fácil con herramientas de desarrollo"],"fr":["Analyse d''écran unique avec des options de personnalisation","Analyse de flux utilisateur pour évaluer l''expérience utilisateur","Révision d''applications complètes pour identifier les domaines d''amélioration","Options d''itération pour affiner et améliorer l''expérience utilisateur","Analyse d''accessibilité et d''usabilité pour garantir la compatibilité","Compatibilité avec CLI pour une intégration facile avec les outils de développement"],"de":["Einzelscreen-Analyse mit Anpassungsoptionen","Benutzerfluss-Analyse zur Bewertung der Benutzererfahrung","Vollständige Anwendungsüberprüfung zur Identifizierung von Verbesserungsbereichen","Iterations-Optionen zur Verfeinerung und Verbesserung der Benutzererfahrung","Barrierefreiheits- und Bedienbarkeitsanalyse zur Gewährleistung der Kompatibilität","CLI-Kompatibilität für eine einfache Integration mit Entwicklungstools"],"pt":["Análise de tela única com comando ''screen''","Análise de fluxo de usuário com comando ''flow''","Revisão completa da aplicação com comando ''full''","Opção de iterações personalizadas com ''--iterations''","Foco personalizado com ''--focus'' para acessibilidade, conversão, usabilidade, visual ou implementação","Saída personalizada com ''--output''"],"ru":["Анализ единственного экрана с командой ''screen''","Анализ потока пользователя с командой ''flow''","Полный обзор приложения с командой ''full''","Вариант настраиваемых итераций с ''--iterations''","Настройка фокуса с ''--focus'' для доступности, конверсии, удобства использования, визуального или реализации","Настройка вывода с ''--output''"],"ar":["تحليل الشاشة الفردي مع الأمر ''screen''","تحليل تدفق المستخدم مع الأمر ''flow''","استعراض كامل للتطبيق مع الأمر ''full''","خيار التكرارات المخصصة مع ''--iterations''","التركيز المخصص مع ''--focus'' لسهولة الوصول أو التحويل أو سهولة الاستخدام أو البصري أو التنفيذ","إخراج مخصص مع ''--output''"]},"keywords":{"en":["how to use roast","roast ui/ux critique","roast alternative tools","roast vs other design tools","roast setup guide","roast install for developers","what is roast skill","roast iterative improvement","roast multi-perspective analysis"],"zh":["UI/UX 评估","UI/UX 改进","多视角分析","迭代改进","命令行接口","Roast Setup","AI 에이전트工具","用户体验设计"],"ja":["UI/UX レビュー","UI/UX 改善","多視点分析","イテレーション改善","コマンドラインインターフェース","Roast 導入","AI エージェントツール","ユーザーエクスペリエンス設計"],"ko":["UI/UX 평가","UI/UX 개선","다각도 분석","반복적 개선","명령줄 인터페이스","Roast 설정","AI 에이전트 도구","사용자 경험 설계"],"es":["herramientas de AI para UI/UX","análisis de experiencia del usuario","mejora de la accesibilidad","desarrollo de aplicaciones móviles","diseño de interfaz de usuario","análisis de usabilidad","integración con CLI","agentes de IA para desarrollo"],"fr":["outils d''IA pour UI/UX","analyse de l''expérience utilisateur","amélioration de l''accessibilité","développement d''applications mobiles","conception d''interface utilisateur","analyse de l''usabilité","intégration avec CLI","agents d''IA pour développement"],"de":["KI-Tools für UI/UX","Benutzererfahrungsanalyse","Barrierefreiheitsverbesserung","Entwicklung von mobilen Anwendungen","Benutzeroberflächen-Design","Bedienbarkeitsanalyse","CLI-Integration","KI-Agents für Entwicklung"],"pt":["análise UI/UX","ferramenta de análise","melhoria da experiência do usuário","Roast","comando screen","comando flow","iterações personalizadas","foco personalizado","saída personalizada"],"ru":["анализ UI/UX","инструмент для анализа","улучшение пользовательского опыта","ИИ Агент Roast","команда screen","команда flow","настраиваемые итерации","настройка фокуса","настройка вывода"],"ar":["تحليل واجهة المستخدم","أداة تحليل","تحسين تجربة المستخدم","أداة Roast","أمر الشاشة","أمر التدفق","تكرارات مخصصة","تركيز مخصص","إخراج مخصص"]}},"owner":"muspelheim","repo":"claude-roaster","repoPath":"muspelheim/claude-roaster","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.549Z","topics":[],"category":"community","skillMd":{"name":"roast","description":"Multi-perspective UI/UX roasting workflow with iterative improvement cycles","bodyPreview":"# 🔥 UI/UX Roast Skill\n\nBrutally honest UI/UX critique with multi-perspective analysis and iterative improvement.\n\n## Command Syntax\n\n```bash\n/roast [mode] [target] [options]\n\n# Modes\nscreen <target>     # Single screen analysis (default)\nflow <target>       # Multi-screen user journey\naudit               # Full application review\n\n# Options\n--iterations=<1-10> # Roast cycles (default: 3)\n--focus=<area>      # Priority: a11y|conversion|usability|visual|implementation\n--output=<path>     # Output","body":"# 🔥 UI/UX Roast Skill\n\nBrutally honest UI/UX critique with multi-perspective analysis and iterative improvement.\n\n## Command Syntax\n\n```bash\n/roast [mode] [target] [options]\n\n# Modes\nscreen <target>     # Single screen analysis (default)\nflow <target>       # Multi-screen user journey\naudit               # Full application review\n\n# Options\n--iterations=<1-10> # Roast cycles (default: 3)\n--focus=<area>      # Priority: a11y|conversion|usability|visual|implementation\n--output=<path>     # Output directory (default: reports/roast/)\n--fix=<mode>        # Fix handling: auto|report|ask (default: ask)\n```\n\n## Examples\n\n```bash\n/roast screen login                     # Roast login screen\n/roast screen settings --focus=a11y     # Focus on accessibility\n/roast flow checkout --iterations=5     # 5-iteration checkout flow\n/roast flow onboarding --fix=auto       # Auto-fix issues found\n/roast audit                            # Full app audit\n```\n\n## Execution Workflow\n\n### 1. Immediate Start\n\n**Do NOT ask questions upfront.** Apply smart defaults and begin immediately.\n\n```\n🔥 ROAST SESSION STARTED\n├─ Mode: screen\n├─ Target: login\n├─ Iterations: 3\n├─ Focus: balanced\n└─ Output: reports/roast/\n```\n\n### 2. Screenshot Capture\n\nAuto-detect screenshot method:\n\n```\n📸 Capturing screenshot...\n├─ Xcode MCP: [✓ found | ✗ not found]\n├─ Playwright MCP: [✓ found | ✗ not found]\n└─ Using: [xcode | playwright | manual upload]\n```\n\n**Detection priority:**\n1. `mcp__xcodebuildmcp__screenshot` → iOS/macOS\n2. `mcp__playwright__browser_take_screenshot` → Web\n3. Request user upload → Fallback\n\n**CRITICAL: Always specify the output path explicitly!**\n\n```typescript\n// First, ensure directory exists\nBash: mkdir -p reports/roast/screenshots\n\n// Playwright MCP - specify filename parameter\nmcp__playwright__browser_take_screenshot({\n  type: \"png\",\n  filename: \"reports/roast/screenshots/[target]_[iteration].png\"\n})\n\n// Xcode MCP - specify path parameter\nmcp__xcodebuildmcp__screenshot({\n  path: \"reports/roast/screenshots/[target]_[iteration].png\"\n})\n```\n\nWithout explicit path, screenshots go to wrong location (e.g., `.playwright-mcp/`).\n\n### 3. Parallel Analysis with Progress\n\nShow real-time progress:\n\n```\n🔥 Roasting: login (1/3)\n├─ 📸 Screenshot ✓\n├─ 🎨 Designer: analyzing...\n├─ 💻 Developer: analyzing...\n├─ 👤 User: analyzing...\n├─ ♿ A11y: analyzing...\n└─ 📈 Marketing: analyzing...\n```\n\nLaunch agents in parallel:\n\n```typescript\n// All 5 agents run simultaneously\nTask(subagent_type=\"claude-roaster:roaster-designer\", prompt=\"...\")\nTask(subagent_type=\"claude-roaster:roaster-developer\", prompt=\"...\")\nTask(subagent_type=\"claude-roaster:roaster-user\", prompt=\"...\")\nTask(subagent_type=\"claude-roaster:roaster-a11y\", prompt=\"...\")\nTask(subagent_type=\"claude-roaster:roaster-marketing\", prompt=\"...\")\n```\n\nUpdate as each completes:\n\n```\n├─ 🎨 Designer: ✓ 3 issues\n├─ 💻 Developer: ✓ 2 issues\n├─ 👤 User: ✓ 4 issues\n├─ ♿ A11y: ✓ 5 issues (2 critical!)\n└─ 📈 Marketing: ✓ 2 issues\n```\n\n### 4. Results Summary\n\nDisplay in terminal before asking about fixes:\n\n```\n🔥 ROAST RESULTS (Iteration 1/3)\n\nFound 16 issues:\n├─ 🔴 Critical: 2\n├─ 🟠 Major: 6\n└─ 🟡 Minor: 8\n\nTop Critical Issues:\n1. Missing form labels - add aria-label to inputs\n2. Contrast ratio 2.1:1 - increase to 4.5:1 minimum\n\n📄 Full report: reports/roast/roast_login_1.md\n```\n\n### 5. Fix Decision (After Results)\n\nAsk ONLY after showing results:\n\n```\nHow should we handle these 16 issues?\n\n[1] Auto-fix critical & major (8 fixes)\n[2] Fix all issues (16 fixes)\n[3] Cherry-pick fixes\n[4] Report only (no changes)\n```\n\n### 6. Fix Implementation\n\nIf fixes chosen:\n\n```\n🔧 Implementing fixes...\n├─ [1/8] Adding aria-labels... ✓\n├─ [2/8] Fixing contrast... ✓\n├─ [3/8] Increasing touch targets... ✓\n...\n└─ ✓ Complete\n\n📸 Capturing updated screenshot...\n```\n\n### 7. Next Iteration\n\n```\nIteration 2/3 starting...\n[Repeat steps 2-6]\n```\n\n### 8. Final Summary\n\n```\n🔥 FINAL ROAST SUMMARY\n\nSession Complete!\n├─ Iterations: 3\n├─ Issues found: 24\n├─ Issues fixed: 18\n└─ Resolution: 75%\n\nScore Improvement:\n| Category      | Before | After | Δ    |\n|---------------|--------|-------|------|\n| Visual        | 4/10   | 8/10  | +4   |\n| Usability     | 5/10   | 9/10  | +4   |\n| Accessibility | 3/10   | 8/10  | +5   |\n| Overall       | 4/10   | 8/10  | +4   |\n\n📄 reports/roast/roast_login_final.md\n```\n\n---\n\n## Mode-Specific Behavior\n\n### Screen Mode\n\nSingle screen, multiple iterations:\n\n```\n/roast screen login --iterations=3\n\nIteration 1: Capture → Analyze → Report → Fix?\nIteration 2: Capture → Analyze → Report → Fix?\nIteration 3: Capture → Analyze → Final Report\n```\n\n### Flow Mode\n\nMultiple screens, analyze journey:\n\n```\n/roast flow checkout\n\n🗺️ Flow: checkout (5 steps)\n├─ [1/5] Cart → 📸 analyzing...\n├─ [2/5] Shipping → 📸 analyzing...\n├─ [3/5] Payment → 📸 analyzing...\n├─ [4/5] Review → 📸 analyzing...\n└─ [5/5] Confirmation → 📸 analyzing...\n\nCross-screen checks:\n├─ Visual consistency\n├─ Navigation clarity\n├─ Progress indication\n└─ Drop-off risk points\n```\n\n### Audit Mode\n\nAuto-detect and roast all critical screens:\n\n```\n/roast audit\n\n🔍 Scanning for critical screens...\n├─ Login ✓\n├─ Dashboard ✓\n├─ Settings ✓\n├─ Checkout ✓\n└─ Profile ✓\n\nRoasting 5 screens (3 iterations each)...\n```\n\n---\n\n## Agent Configuration\n\n| Agent | Model | Focus | Weight |\n|-------|-------|-------|--------|\n| roaster (orchestrator) | Opus | Synthesis | - |\n| roaster-designer | Sonnet | Visual, typography, color | 1.0x |\n| roaster-developer | Sonnet | Implementation, structure | 1.0x |\n| roaster-user | Sonnet | Usability, friction | 1.0x |\n| roaster-a11y | Sonnet | Accessibility, WCAG | 1.0x |\n| roaster-marketing | Sonnet | Conversion, trust | 1.0x |\n\n**With `--focus` option:**\n- Focused agent: 1.5x weight\n- Other agents: 0.5x weight\n\n---\n\n## Output Structure\n\n```\nreports/roast/\n├─ roast_[target]_1.md\n├─ roast_[target]_2.md\n├─ roast_[target]_final.md\n└─ screenshots/\n   ├─ [target]_1.png\n   ├─ [target]_2.png\n   └─ [target]_final.png\n```\n\n---\n\n## Report Format\n\n```markdown\n# 🔥 Roast Report: [Target] - Iteration [N]\n\n**Mode:** screen | **Focus:** balanced | **Date:** 2024-01-15\n\n![Screenshot](screenshots/login_1.png)\n\n## The Verdict\n\n[Brutal 2-3 sentence summary]\n\n## Issues by Severity\n\n### 🔴 Critical (2)\n| Issue | Agent | Fix |\n|-------|-------|-----|\n| Missing labels | A11y | Add aria-label=\"Email\" |\n| Low contrast | Designer | Change #999 to #595959 |\n\n### 🟠 Major (6)\n...\n\n### 🟡 Minor (8)\n...\n\n## Agent Deep Dives\n\n### 🎨 Designer\n[Full analysis]\n\n### ♿ A11y Expert\n[Full analysis]\n\n...\n\n## Quick Wins\n- [ ] Fix 1 (< 2 min)\n- [ ] Fix 2 (< 2 min)\n\n## Scores\n| Category | Score |\n|----------|-------|\n| Visual | 4/10 |\n| Usability | 5/10 |\n| Accessibility | 3/10 |\n| Overall | 4/10 |\n```\n\n---\n\n## Voice Guidelines\n\n1. **Brutal but fair** - Harsh critique, always with solutions\n2. **Specific values** - \"#2563eb\", \"48px\", \"font-weight: 600\"\n3. **Actionable fixes** - Every issue has a concrete fix\n4. **Fast start** - Begin immediately, ask questions later\n5. **Progress visibility** - Always show what''s happening\n"},"lastSynced":"2026-03-08T02:11:23.961Z","agentAnalysis":{"suitability":{"en":"Perfect for UI/UX Analysis Agents needing brutally honest multi-perspective critique and iterative refinement capabilities.","zh":"非常适合需要毫无保留的多角度批评和迭代改进能力的UI/UX分析代理。","ja":"UI/UX分析エージェントが必要とする冷静な多角的批評と反復的改良機能に最適です。","ko":"무시무시하게 솔직한 다각도 비평과 반복적인 개선 기능이 필요한 UI/UX 분석 에이전트에게 완벽합니다.","es":"Perfecto para Agentes de Análisis de UI/UX que necesitan una crítica honesta y multifacética y capacidades de refinamiento iterativo.","fr":"Parfait pour les Agents d''Analyse UI/UX ayant besoin d''une critique honnête et multiforme ainsi que de capacités de raffinement itératif.","de":"Perfekt für UI/UX-Analyse-Agenten, die eine brutal ehrliche, mehrperspektivische Kritik und iterative Verfeinerungsfähigkeiten benötigen.","pt":"Perfeito para Agentes de Análise de UI/UX que necessitam de crítica multi-perspectiva honesta e capacidades de refinamento iterativo.","ru":"Идеально подходит для агентов анализа UI/UX, которым необходима честная многосторонняя критика и возможности итеративного совершенствования.","ar":"مثالي لعمليات تحليل واجهة المستخدم وتجربة المستخدم التي تحتاج إلى نقد متعدد وجهات النظر صريح وقدرات تعديل تكراري."},"recommendation":{"en":"Empowers agents to perform screen and flow analysis using command syntax with options like --iterations and --focus, providing output in specified paths, and leveraging modes such as screen, flow, and audit for comprehensive UI/UX critique.","zh":"赋予代理使用命令语法（如--iterations和--focus选项）执行屏幕和流程分析的能力，提供指定路径的输出，并利用诸如屏幕、流程和审计等模式进行综合的UI/UX批评。","ja":"エージェントがコマンド構文（--iterationsや--focusなどのオプション）を使用してスクリーンとフローの分析を実行し、指定されたパスに出力し、スクリーン、フロー、監査などのモードを利用して包括的なUI/UX批評を行うことができるようにします。","ko":"에이전트가 명령 구문(예: --iterations 및 --focus 옵션)을 사용하여 화면 및 흐름 분석을 수행하고, 지정된 경로에 출력을 제공하고, 화면, 흐름 및 감사 등의 모드를 활용하여 포괄적인 UI/UX 비평을 수행할 수 있도록 합니다.","es":"Habilita a los agentes a realizar análisis de pantalla y flujo utilizando sintaxis de comandos con opciones como --iterations y --focus, proporcionando salida en rutas especificadas y aprovechando modos como pantalla, flujo y auditoría para una crítica UI/UX integral.","fr":"Permet aux agents d''effectuer des analyses d''écran et de flux en utilisant une syntaxe de commande avec des options comme --iterations et --focus, fournissant une sortie dans des chemins spécifiés et exploitant des modes tels que l''écran, le flux et l''audit pour une critique UI/UX complète.","de":"Ermächtigt Agenten, Bildschirm- und Flussanalysen mithilfe von Befehlssyntax mit Optionen wie --iterations und --focus durchzuführen, Ausgaben in angegebenen Pfaden bereitzustellen und Modi wie Bildschirm, Fluss und Audit für eine umfassende UI/UX-Kritik zu nutzen.","pt":"Habilita os agentes a realizar análise de tela e fluxo usando sintaxe de comando com opções como --iterations e --focus, fornecendo saída em caminhos especificados e utilizando modos como tela, fluxo e auditoria para crítica abrangente de UI/UX.","ru":"Позволяет агентам выполнять анализ экрана и потока, используя командную синтаксис с опциями, такими как --iterations и --focus, предоставляя вывод в указанных путях и используя режимы, такие как экран, поток и аудит для всесторонней критики UI/UX.","ar":"تمكين الوكلاء من أداء تحليل الشاشة والتدفق باستخدام بناء الجملة الأمر مع خيارات مثل --iterations و --focus ، وتقديم الإخراج في المسارات المحددة ، واستخدام أوضاع مثل الشاشة والتدفق والتدقيق لتعليق شاملة على UI/UX."},"useCases":{"en":["Automating UI/UX audits for accessibility and usability","Generating multi-screen user journey analysis","Debugging conversion rate optimization issues through iterative refinement"],"zh":["自动执行UI/UX可访问性和可用性审计","生成多屏用户旅程分析","通过迭代改进调试转化率优化问题"],"ja":["UI/UXアクセシビリティとユーザビリティの監査を自動化する","複数画面のユーザージャーニー分析を生成する","反復的改良によりコンバージョン率の最適化問題をデバッグする"],"ko":["UI/UX 접근성 및 사용성 감사를 자동화하는 것","다중 화면 사용자 여정 분석을 생성하는 것","반복적인 개선으로 전환률 최적화 문제를 디버깅하는 것"],"es":["Automatizar auditorías de UI/UX para accesibilidad y usabilidad","Generar análisis de recorridos de usuario de varias pantallas","Depurar problemas de optimización de la tasa de conversión a través de un refinamiento iterativo"],"fr":["Automatiser les audits UI/UX pour l''accessibilité et l''ergonomie","Générer des analyses de parcours utilisateur à plusieurs écrans","Déboguer les problèmes d''optimisation du taux de conversion via un raffinement itératif"],"de":["Automatisierung von UI/UX-Audits für Zugänglichkeit und Benutzerfreundlichkeit","Erzeugen von Analyseberichten für Benutzerreisen über mehrere Bildschirme","Fehlerbehebung bei Problemen der Konvertierungsrate-Optimierung durch iteratives Verfeinern"],"pt":["Automatizar auditorias de UI/UX para acessibilidade e usabilidade","Gerar análise de jornada do usuário de multi-tela","Depurar problemas de otimização de taxa de conversão por meio de refinamento iterativo"],"ru":["Автоматизировать аудиты UI/UX для доступности и удобства использования","Генерировать анализ пути пользователя на нескольких экранах","Отлаживать проблемы оптимизации коэффициента конверсии с помощью итеративного совершенствования"],"ar":["تأتميم عمليات تدقيق UI/UX للوصول واستخدام الملفات الشخصية","توليد تحليل مسار المستخدم للشاشات المتعددة","تصحيح مشاكل تحسين معدل التحويل من خلال التعديل التكراري"]},"limitations":{"en":["Requires specific target and mode specification","Limited to 10 roast cycles","Output path must be specified for results"],"zh":["需要指定目标和模式","有限制，仅10个烘烤周期","输出路径必须指定以获得结果"],"ja":["特定のターゲットとモードの指定が必要","10回のローストサイクルに制限される","結果を得るために出力パスを指定する必要がある"],"ko":["특정 대상 및 모드 지정이 필요합니다","10개의 로스트 주기에 제한됩니다","결과를 얻으려면 출력 경로를 지정해야 합니다"],"es":["Requiere una especificación de objetivo y modo específicos","Limitado a 10 ciclos de tostado","La ruta de salida debe ser especificada para los resultados"],"fr":["Nécessite une spécification de cible et de mode spécifiques","Limité à 10 cycles de torréfaction","Le chemin de sortie doit être spécifié pour les résultats"],"de":["Erfordert eine spezifische Ziel- und Modusspezifikation","Begrenzt auf 10 Röstzyklen","Der Ausgabepfad muss für die Ergebnisse angegeben werden"],"pt":["Requer especificação de alvo e modo","Limitado a 10 ciclos de torrefação","