INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('muspelheim/claude-roaster/roast', 'roast', 'muspelheim', 'claude-roaster', 'community', 'roast muspelheim claude-roaster community The roast skill provides brutally honest UI/UX critique with multi-perspective analysis, helping developers and designers improve their applications through iterative refinement. Roast 是一个提供 UI/UX 评估和改进的工具，支持多视角分析和迭代改进 Roast は、UI/UX を評価し、改善するツールです。多視点分析とイテレーション改善をサポートします Roast는 UI/UX를 평가하고 개선하는 도구로 다각도 분석 및 반복적 개선을 지원합니다 Roast es una herramienta de análisis UI/UX que ofrece una crítica honesta y análisis multi-perspectivo para mejorar la experiencia del usuario Roast est un outil d''analyse UI/UX qui offre une critique honnête et une analyse multi-perspective pour améliorer l''expérience utilisateur Roast ist ein UI/UX-Analyse-Tool, das eine ehrliche Kritik und eine multi-perspektivische Analyse bietet, um die Benutzererfahrung zu verbessern O Roast é uma ferramenta de análise UI/UX avançada que fornece uma crítica honesta e multi-perspectiva para melhorar a experiência do usuário ИИ Агент Roast - это инструмент для анализа UI/UX, который предоставляет честную и многофакторную критику для улучшения пользовательского опыта أداة Roast هي أداة تحليل واجهة المستخدم وتجربة المستخدم المتقدمة التي توفر نقدًا صادقًا ومتعدد المنظورات لتحسين تجربة المستخدم how to use roast roast ui/ux critique roast alternative tools roast vs other design tools roast setup guide roast install for developers what is roast skill roast iterative improvement roast multi-perspective analysis UI/UX 评估 UI/UX 改进 多视角分析 迭代改进 命令行接口 Roast Setup AI 에이전트工具 用户体验设计 Supports single screen analysis via `/roast screen` command Performs multi-screen user journey audits with `/roast flow` mode Allows full application reviews for comprehensive critique Customizable roast cycles with `--iterations` option Prioritizes specific areas of focus using `--focus` option (a11y, conversion, usability, visual, implementation) roast is a UI/UX critique skill that offers multi-perspective analysis and iterative improvement for single screen, flow, and full application reviews');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('severity1/claude-code-auto-memory/codebase-analyzer', 'community', 'severity1', 'claude-code-auto-memory', 'severity1/claude-code-auto-memory', 'codebase-analyzer', 0, 0, 60, '2026-03-08T01:57:15.549Z', '2026-03-08T02:11:25.476Z', 'd7b38c9023a0c21cb261705fe2f47a00d23e60909578a3bc3e85f7edeaecf268', '{"id":"severity1/claude-code-auto-memory/codebase-analyzer","name":"codebase-analyzer","description":{"en":"The codebase-analyzer skill automatically maintains CLAUDE.md files by analyzing project structure and generating content interactively, benefiting developers working with Claude Code plugins.","zh":"代码库分析器是一种自动维护CLAUDE.md文件的工具，通过分析项目结构和生成CLAUDE.md文件来提高开发效率","ja":"コードベース分析ツールは、プロジェクト構造を分析し、CLAUDE.mdファイルを生成して開発効率を向上させるツールです","ko":"코드베이스 분석기는 프로젝트 구조를 분석하고 CLAUDE.md 파일을 생성하여 개발 효율성을 높이는 툴입니다","es":"Codebase-analyzer es una herramienta que analiza la estructura del proyecto y genera archivos CLAUDE.md de forma interactiva","fr":"Codebase-analyzer est un outil qui analyse la structure du projet et génère des fichiers CLAUDE.md de manière interactive","de":"Codebase-analyzer ist ein Tool, das die Projektstruktur analysiert und CLAUDE.md-Dateien interaktiv generiert","pt":"O Codebase Analyzer é uma ferramenta que mantém arquivos CLAUDE.md atualizados e interativos em seus projetos de desenvolvimento","ru":"Codebase Analyzer — это инструмент, который автоматически обслуживает файлы CLAUDE.md в ваших проектах разработки","ar":"_codebase analyzer_هو أداة تحافظ على ملفات CLAUDE.md محدثة وتفاعلية في مشاريع التطوير"},"seo":{"title":{"en":"codebase-analyzer: Automated CLAUDE.md Generation Setup G...","zh":"代码库分析器Setup Guide - 自动维护CLAUDE.md文件","ja":"コードベース分析ツールのベストプラクティス - CLAUDE.md自動生成","ko":"코드베이스 분석기 Setup Guide - CLAUDE.md 파일 자동 관리","es":"Guía de configuración de codebase-analyzer para análisis ...","fr":"Guide d''installation de codebase-analyzer pour l''analyse ...","de":"Einrichtungsleitfaden für codebase-analyzer zur Codeanalyse","pt":"Guia de Configuração do Codebase Analyzer para Ferramenta...","ru":"Настройка Codebase Analyzer: Руководство для ИИ Агентов","ar":"دليل إعداد_codebase analyzer_لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how codebase-analyzer streamlines project structure analysis and CLAUDE.md file maintenance. Learn how to set up and use this AI agent skill today!","zh":"了解代码库分析器的功能和特点，自动维护CLAUDE.md文件，提高开发效率","ja":"コードベース分析ツールの機能と特徴を紹介します。CLAUDE.mdファイルを自動生成して開発効率を向上させます","ko":"코드베이스 분석기의 기능과 특징을 알아보세요. CLAUDE.md 파일을 자동으로 관리하여 개발 효율성을 높입니다","es":"Automatice el mantenimiento de archivos CLAUDE.md con codebase-analyzer. Obtenga más información sobre esta herramienta de análisis de código","fr":"Automatisez la maintenance des fichiers CLAUDE.md avec codebase-analyzer. Découvrez plus sur cet outil d''analyse de code","de":"Automatisieren Sie die Wartung von CLAUDE.md-Dateien mit codebase-analyzer. Erfahren Sie mehr über dieses Codeanalyse-Tool","pt":"Aprenda a configurar o Codebase Analyzer para manter arquivos CLAUDE.md atualizados e interativos em seus projetos de desenvolvimento","ru":"Узнайте, как настроить Codebase Analyzer для автоматического обслуживания файлов CLAUDE.md в ваших проектах разработки с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد_codebase analyzer_لتحديث ملفات CLAUDE.md وتفاعلها في مشاريع التطوير باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"codebase-analyzer is a Claude Code plugin that analyzes project structure and generates CLAUDE.md files interactively, following specific guidelines to ensure correct content generation.","zh":"代码库分析器是一种自动化工具，用于维护CLAUDE.md文件并分析项目结构","ja":"コードベース分析ツールは、CLAUDE.mdファイルを自動生成し、プロジェクト構造を分析するツールです","ko":"코드베이스 분석기는 CLAUDE.md 파일을 자동으로 관리하고 프로젝트 구조를 분석하는 툴입니다","es":"Codebase-analyzer es una herramienta de análisis de código que mantiene automáticamente los archivos CLAUDE.md","fr":"Codebase-analyzer est un outil d''analyse de code qui maintient automatiquement les fichiers CLAUDE.md","de":"Codebase-analyzer ist ein Codeanalyse-Tool, das CLAUDE.md-Dateien automatisch wartet","pt":"O Codebase Analyzer é uma ferramenta de análise de código que gera arquivos CLAUDE.md interativos","ru":"Codebase Analyzer — это инструмент анализа кода, который генерирует интерактивные файлы CLAUDE.md","ar":"_codebase analyzer_هو أداة تحليل الشفرة التي تتولى生成 ملفات CLAUDE.md التفاعلية"},"features":{"en":["Analyzes project structure to generate CLAUDE.md files","Provides options to migrate, backup, or merge existing CLAUDE.md files","Follows mandatory guidelines to ensure correct CLAUDE.md content generation","Supports interactive generation of CLAUDE.md files","Handles existing CLAUDE.md files through user-defined actions"],"zh":["自动维护CLAUDE.md文件","分析项目结构并生成CLAUDE.md文件","支持Migrate、Backup和Merge操作","提供交互式的CLAUDE.md文件生成","遵循特定的指导原则以确保正确的CLAUDE.md内容"],"ja":["CLAUDE.mdファイルを自動生成","プロジェクト構造を分析し、CLAUDE.mdファイルを生成","Migrate、Backup、Merge操作をサポート","インタラクティブにCLAUDE.mdファイルを生成","特定のガイドラインに従って正確なCLAUDE.md内容を生成"],"ko":["CLAUDE.md 파일을 자동으로 관리","프로젝트 구조를 분석하고 CLAUDE.md 파일을 생성","Migrate, Backup, Merge 연산을 지원","인터랙티브하게 CLAUDE.md 파일을 생성","특정 가이드라인을 따르며 정확한 CLAUDE.md 내용을 생성"],"es":["Análisis de la estructura del proyecto","Generación interactiva de archivos CLAUDE.md","Opciones de migración, copia de seguridad y fusión de archivos CLAUDE.md existentes","Compatibilidad con formatos de archivo auto-administrados","Marcadores para la administración de archivos CLAUDE.md"],"fr":["Analyse de la structure du projet","Génération interactive de fichiers CLAUDE.md","Options de migration, de sauvegarde et de fusion de fichiers CLAUDE.md existants","Compatibilité avec les formats de fichiers auto-administrés","Balises pour l''administration de fichiers CLAUDE.md"],"de":["Analyse der Projektstruktur","Interaktive Generierung von CLAUDE.md-Dateien","Optionen für Migration, Sicherung und Zusammenführung von vorhandenen CLAUDE.md-Dateien","Kompatibilität mit selbstverwalteten Dateiformaten","Markierungen für die Verwaltung von CLAUDE.md-Dateien"],"pt":["Análise de estrutura de projeto","Geração interativa de arquivos CLAUDE.md","Opções de migração, backup e mesclagem de arquivos CLAUDE.md existentes","Suporte a marcadores para formatos auto-gerenciados","Integração com plugins Claude Code"],"ru":["Анализ структуры проекта","Интерактивная генерация файлов CLAUDE.md","Варианты миграции, резервного копирования и слияния существующих файлов CLAUDE.md","Поддержка маркеров для форматов с автоматическим управлением","Интеграция с плагинами Claude Code"],"ar":["تحليل هيكل المشروع","توليد ملفات CLAUDE.md التفاعلية","خيارات هجرة ونسخ احتياطي ودمج ملفات CLAUDE.md الحالية","دعم العلامات للمواصفات المدارة تلقائيًا","التكامل مع الإضافات Claude Code"]},"keywords":{"en":["how to use codebase-analyzer","codebase-analyzer setup guide","what is codebase-analyzer","codebase-analyzer alternative","codebase-analyzer vs other plugins","codebase-analyzer install","CLAUDE.md file generation","automated project structure analysis","Claude Code plugin"],"zh":["代码库分析器","CLAUDE.md自动生成","项目结构分析","代码库管理","AI工具","代码分析","自动化工具"],"ja":["コードベース分析ツール","CLAUDE.md自動生成","プロジェクト構造分析","コードベース管理","AIエージェント","コード分析","自動化ツール"],"ko":["코드베이스 분석기","CLAUDE.md 자동 생성","프로젝트 구조 분석","코드베이스 관리","AI 에이전트","코드 분석","자동화 툴"],"es":["herramientas de análisis de código","codebase-analyzer","CLAUDE.md","análisis de proyecto","generación de archivos","automatización de código","desarrollo de software","herramientas de desarrollo"],"fr":["outils d''analyse de code","codebase-analyzer","CLAUDE.md","analyse de projet","génération de fichiers","automatisation de code","développement de logiciels","outils de développement"],"de":["Codeanalyse-Tools","codebase-analyzer","CLAUDE.md","Projektanalyse","Dateigenerierung","Code-Automatisierung","Software-Entwicklung","Entwicklungstools"],"pt":["codebase analyzer","ferramentas de IA","análise de código","geração de arquivos CLAUDE.md","desenvolvimento de software","plugins Claude Code","guias de configuração"],"ru":["Codebase Analyzer","ИИ Агенты","анализ кода","генерация файлов CLAUDE.md","разработка программного обеспечения","плагины Claude Code","руководства по настройке"],"ar":["codebase analyzer","أدوات الذكاء الاصطناعي","تحليل الشفرة","توليد ملفات CLAUDE.md","تطوير البرمجيات","الإضافات Claude Code","دلائل الإعداد"]}},"owner":"severity1","repo":"claude-code-auto-memory","repoPath":"severity1/claude-code-auto-memory","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.549Z","topics":[],"category":"community","skillMd":{"name":"codebase-analyzer","description":"This skill should be used when the user asks to initialize auto-memory, create CLAUDE.md, set up project memory, or runs the /auto-memory:init command. Analyzes codebase structure and generates CLAUDE.md files using the exact template format with AUTO-MANAGED markers.","bodyPreview":"# Codebase Analyzer\n\nAnalyze project structure and generate CLAUDE.md files interactively.\n\n## Guidelines\n\n**MANDATORY**: All rules below must be followed exactly. Violations produce incorrect CLAUDE.md content.\n\n@../shared/references/guidelines.md\n\n## Algorithm\n\n### 1. Check Existing CLAUDE.md\n\nIf CLAUDE.md already exists, ask the user how to handle it:\n- **Migrate**: Convert to auto-managed format (add markers)\n- **Backup**: Create CLAUDE.md.backup and generate fresh\n- **Merge**: Keep manual s","body":"# Codebase Analyzer\n\nAnalyze project structure and generate CLAUDE.md files interactively.\n\n## Guidelines\n\n**MANDATORY**: All rules below must be followed exactly. Violations produce incorrect CLAUDE.md content.\n\n@../shared/references/guidelines.md\n\n## Algorithm\n\n### 1. Check Existing CLAUDE.md\n\nIf CLAUDE.md already exists, ask the user how to handle it:\n- **Migrate**: Convert to auto-managed format (add markers)\n- **Backup**: Create CLAUDE.md.backup and generate fresh\n- **Merge**: Keep manual sections, add auto-managed sections\n- **Cancel**: Abort initialization\n\n### 2. Scan Directory Structure\n\nDetect frameworks and build systems:\n- `package.json` - Node.js/JavaScript\n- `pyproject.toml`, `setup.py` - Python\n- `Cargo.toml` - Rust\n- `go.mod` - Go\n- `Makefile` - Make-based builds\n- `Dockerfile` - Container builds\n\nExtract build/test/lint commands from config files.\n\n### 3. Identify Subtree Candidates\n\nLook for framework boundaries that warrant separate CLAUDE.md files:\n- `src/` with 10+ source files\n- `lib/` directory\n- `packages/*` (monorepo packages)\n- `apps/*` (monorepo applications)\n\n### 4. Detect Code Patterns\n\nAnalyze source files for conventions:\n- **Naming**: PascalCase, camelCase, snake_case usage\n- **Imports**: ES6 modules, CommonJS, ordering patterns\n- **Architecture**: Feature-based, layered, MVC patterns\n- **Style**: Indentation, quotes, semicolons\n\n### 5. Fetch Memory Guidelines (Optional)\n\nIf network available, fetch from `https://code.claude.com/docs/en/memory`:\n- Use WebFetch tool\n- Extract relevant sections for context\n- Reference official guidelines above as primary source\n\n### 6. Present Findings\n\nUse AskUserQuestion to confirm:\n- Detected framework and commands\n- Suggested subtree locations\n- Detected patterns\n\n### 7. Generate CLAUDE.md\n\nGenerate files using the EXACT template structure. Follow these steps precisely:\n\n1. **Copy template skeleton** - Use template file as the base structure\n2. **Use exact marker format** - See Marker Syntax section below\n3. **Replace placeholders** - Substitute `{{PLACEHOLDER}}` with detected content\n4. **Include all required sections** - Even if content is minimal, include the section\n5. **Add MANUAL section** at the end for user notes\n6. **Size limits**: Root 150-200 lines, Subtrees 50-75 lines\n\n## Marker Syntax\n\n**CRITICAL**: Use the EXACT marker format below. Do NOT use variations.\n\n```markdown\n<!-- AUTO-MANAGED: section-name -->\n## Section Heading\n\nContent goes here\n\n<!-- END AUTO-MANAGED -->\n```\n\nFor user-editable content:\n\n```markdown\n<!-- MANUAL -->\n## Custom Notes\n\nAdd project-specific notes here. This section is never auto-modified.\n\n<!-- END MANUAL -->\n```\n\n**Common mistakes to avoid**:\n- `<!-- BEGIN AUTO-MANAGED: name -->` - WRONG (no BEGIN prefix)\n- `<!-- END AUTO-MANAGED: name -->` - WRONG (no name in closing tag)\n- `<!-- AUTO-MANAGED section-name -->` - WRONG (missing colon)\n\n## Section Definitions\n\n### Root CLAUDE.md Sections\n\nGenerate these sections in order:\n\n| Section Name | Heading | Required | Placeholder | Content |\n|--------------|---------|----------|-------------|---------|\n| `project-description` | ## Overview | Yes | `{{DESCRIPTION}}` | Project name, tagline, key features |\n| `build-commands` | ## Build & Development Commands | Yes | `{{BUILD_COMMANDS}}` | Build, test, lint, run commands |\n| `architecture` | ## Architecture | Yes | `{{ARCHITECTURE}}` | Directory tree, key files, data flow |\n| `conventions` | ## Code Conventions | Yes | `{{CONVENTIONS}}` | Naming, imports, formatting rules |\n| `patterns` | ## Detected Patterns | Yes | `{{PATTERNS}}` | AI-detected recurring code patterns |\n| `git-insights` | ## Git Insights | No | `{{GIT_INSIGHTS}}` | Key commits, design decisions |\n| `best-practices` | ## Best Practices | No | `{{BEST_PRACTICES}}` | From official Claude Code docs |\n\n### Subtree CLAUDE.md Sections\n\nGenerate these sections in order:\n\n| Section Name | Heading | Required | Placeholder | Content |\n|--------------|---------|----------|-------------|---------|\n| `module-description` | ## Purpose | Yes | `{{DESCRIPTION}}` | Module purpose and responsibility |\n| `architecture` | ## Module Architecture | Yes | `{{ARCHITECTURE}}` | Module structure, key files |\n| `conventions` | ## Module-Specific Conventions | Yes | `{{CONVENTIONS}}` | Module-specific rules |\n| `dependencies` | ## Key Dependencies | Yes | `{{DEPENDENCIES}}` | Module dependencies |\n\n## Templates\n\nReference the template files for exact structure:\n\n### Root Template\n@templates/CLAUDE.root.md.template\n\n### Subtree Template\n@templates/CLAUDE.subtree.md.template\n\n## User Interactions\n\nUse AskUserQuestion for:\n1. Existing CLAUDE.md handling (migrate/backup/merge/cancel)\n2. Subtree location confirmation\n3. Final approval before writing files\n\n## Output\n\nAfter generating files, report:\n- Files created/modified\n- Sections populated\n- Any warnings or suggestions\n"},"lastSynced":"2026-03-08T02:11:25.476Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents working with Claude Code plugins, needing automated CLAUDE.md file management and project structure analysis.","zh":"非常适合使用 Claude Code 插件的 Developer Agents，需要自动管理 CLAUDE.md 文件和项目结构分析。","ja":"Claude Code プラグインを使用する Developer Agents に最適で、CLAUDE.md ファイルの自動管理とプロジェクト構造分析が必要です。","ko":"Claude Code 플러그인을 사용하는 Developer Agents 에 적합하며 자동으로 CLAUDE.md 파일을 관리하고 프로젝트 구조를 분석해야 합니다.","es":"Perfecto para Agentes de Desarrollador que trabajan con plugins de Claude Code, necesitando una gestión automatizada de archivos CLAUDE.md y análisis de estructura de proyecto.","fr":"Parfait pour les Agents de Développeur travaillant avec des plugins Claude Code, ayant besoin d''une gestion automatique de fichiers CLAUDE.md et d''analyse de structure de projet.","de":"Perfekt für Entwickleragenten, die mit Claude Code-Plugins arbeiten und eine automatisierte Verwaltung von CLAUDE.md-Dateien und Projektstrukturanalyse benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que trabalham com plugins do Claude Code, necessitando de gerenciamento automatizado de arquivos CLAUDE.md e análise da estrutura do projeto.","ru":"Идеально подходит для агентов-разработчиков, работающих с плагинами Claude Code, требующих автоматизированного управления файлами CLAUDE.md и анализа структуры проекта.","ar":"مثالي للوكلاء المطورين الذين يعملون مع إضافات Claude Code ، و kteří بحاجة إلى إدارة ملفات CLAUDE.md أوتوماتيكيا وتحليل هيكل المشروع."},"recommendation":{"en":"Empowers agents to interactively generate and maintain CLAUDE.md files by analyzing project structures, supporting features like migration, backup, and merge of existing files, utilizing markers for auto-managed formats.","zh":"赋予代理交互式生成和维护 CLAUDE.md 文件的能力，通过分析项目结构，支持诸如迁移、备份和合并现有文件等功能，利用标记实现自动管理格式。","ja":"エージェントにプロジェクト構造を分析して CLAUDE.md ファイルを対話的に生成および維持する能力を与え、既存のファイルの移行、バックアップ、統合などの機能をサポートし、自動管理形式のマーカーを使用します。","ko":"에이전트가 프로젝트 구조를 분석하여 CLAUDE.md 파일을 상호 작용적으로 생성 및 유지할 수 있는 능력을 부여하고 기존 파일의 마이그레이션, 백업 및 병합等의 기능을 지원하며 자동 관리 형식의 마커를 사용합니다.","es":"Habilita a los agentes a generar y mantener interactivamente archivos CLAUDE.md analizando estructuras de proyecto, soportando características como migración, respaldo y fusión de archivos existentes, utilizando marcadores para formatos autoadministrados.","fr":"Permet aux agents de générer et de maintenir de manière interactive des fichiers CLAUDE.md en analysant les structures de projet, en prenant en charge des fonctionnalités telles que la migration, la sauvegarde et la fusion de fichiers existants, en utilisant des marqueurs pour les formats auto-gérés.","de":"Ermächtigt Agenten, CLAUDE.md-Dateien interaktiv zu generieren und zu pflegen, indem sie Projektstrukturen analysieren, Funktionen wie Migration, Sicherung und Zusammenführung bestehender Dateien unterstützen und Marker für autoverwaltete Formate verwenden.","pt":"Habilita os agentes a interativamente gerar e manter arquivos CLAUDE.md, analisando estruturas de projeto, suportando recursos como migração, backup e mesclagem de arquivos existentes, utilizando marcadores para formatos auto-gerenciados.","ru":"Позволяет агентам интерактивно генерировать и поддерживать файлы CLAUDE.md, анализируя структуры проекта, поддерживая функции, такие как миграция, резервное копирование и слияние существующих файлов, используя маркеры для форматов с автоматическим управлением.","ar":"يمكّن الوكلاء من توليد وتحديث ملفات CLAUDE.md بشكل تفاعلي ، من خلال تحليل هيكل المشروع ، ودعم ميزات مثل الهجرة ونسخ احتياطي ودمج الملفات الحالية ، باستخدام علامات لتنسيقات إدارة أوتوماتيكية."},"useCases":{"en":["Automating CLAUDE.md file generation for project documentation","Migrating existing CLAUDE.md files to auto-managed formats","Backing up and merging manual changes with auto-generated content"],"zh":["项目文档的自动化 CLAUDE.md 文件生成","将现有的 CLAUDE.md 文件迁移到自动管理格式","备份和合并手动更改与自动生成的内容"],"ja":["プロジェクト文書の自動化 CLAUDE.md ファイル生成","既存の CLAUDE.md ファイルを自動管理形式に移行","手動変更と自動生成コンテンツのバックアップと統合"],"ko":["프로젝트 문서를 위한 자동화된 CLAUDE.md 파일 생성","기존의 CLAUDE.md 파일을 자동 관리 형식으로 마이그레이션","수동 변경 사항과 자동 생성된 내용의 백업 및 병합"],"es":["Automatización de la generación de archivos CLAUDE.md para la documentación de proyectos","Migración de archivos CLAUDE.md existentes a formatos autoadministrados","Respaldo y fusión de cambios manuales con contenido auto-generado"],"fr":["Automatisation de la génération de fichiers CLAUDE.md pour la documentation de projet","Migration de fichiers CLAUDE.md existants vers des formats auto-gérés","Sauvegarde et fusion de modifications manuelles avec du contenu auto-généré"],"de":["Automatisierung der Erzeugung von CLAUDE.md-Dateien für die Projektdokumentation","Migration bestehender CLAUDE.md-Dateien in autoverwaltete Formate","Sicherung und Zusammenführung manueller Änderungen mit auto-generiertem Inhalt"],"pt":["Automatizar a geração de arquivos CLAUDE.md para documentação de projeto","Migrar arquivos CLAUDE.md existentes para formatos auto-gerenciados","Fazer backup e mesclar alterações manuais com conteúdo auto-gerado"],"ru":["Автоматизировать генерацию файлов CLAUDE.md для документации проекта","Мигрировать существующие файлы CLAUDE.md в форматы с автоматическим управлением","Создать резервную копию и слить ручные изменения с автоматически сгенерированным контентом"],"ar":["أتمتة توليد ملفات CLAUDE.md لتوثيق المشروع","هجرة ملفات CLAUDE.md الحالية إلى تنسيقات إدارة أوتوماتيكية","إنشاء نسخة احتياطية ودمج التغييرات اليدوية مع المحتوى المولّد أوتوماتيكيا"]},"limitations":{"en":["Requires Claude Code plugin compatibility","Must follow specific guidelines for correct CLAUDE.md content generation"],"zh":["需要 Claude Code 插件兼容性","必须遵循特定的指南以正确生成 CLAUDE.md 内容"],"ja":["Claude Code プラグインの互換性が必要","CLAUDE.md コンテンツを正しく生成するために特定のガイドラインに従う必要があります"],"ko":["Claude Code 플러그인과 호환성이 필요","CLAUDE.md 내용을 올바르게 생성하기 위해서는 특정한 지침을 따라야 함"],"es":["Requiere compatibilidad con plugin de Claude Code","Debe seguir pautas específicas para la generación correcta de contenido CLAUDE.md"],"fr":["Nécessite la compatibilité du plugin Claude Code","Doit suivre des lignes directrices spécifiques pour la génération correcte de contenu CLAUDE.md"],"de":["Benötigt Kompatibilität mit Claude Code-Plugin","Muss bestimmte Richtlinien für die korrekte Erzeugung von CLAUDE.md-Inhalt befolgen"],"pt":["Requer compatibilidade com o plugin Claude Code","Deve seguir diretrizes específicas para geração correta de conteúdo CLAUDE.md"],"ru":["Требует совместимости с плагином Claude Code","Должен следовать определенным рекомендациям для правильной генерации содержимого CLAUDE.md"],"ar":["يتطلب توافقا مع إضافة Claude Code","يجب اتباع إرشادات محددة لإنشاء محتوى CLAUDE.md بشكل صحيح"]},"version":4},"contentHash":"d7b38c9023a0c21cb261705fe2f47a00d23e60909578a3bc3e85f7edeaecf268","qualityScore":60}');
