INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('severity1/claude-code-auto-memory/codebase-analyzer', 'codebase-analyzer', 'severity1', 'claude-code-auto-memory', 'community', 'codebase-analyzer severity1 claude-code-auto-memory community The codebase-analyzer skill automatically maintains CLAUDE.md files by analyzing project structure and generating content interactively, benefiting developers working with Claude Code plugins. 代码库分析器是一种自动维护CLAUDE.md文件的工具，通过分析项目结构和生成CLAUDE.md文件来提高开发效率 コードベース分析ツールは、プロジェクト構造を分析し、CLAUDE.mdファイルを生成して開発効率を向上させるツールです 코드베이스 분석기는 프로젝트 구조를 분석하고 CLAUDE.md 파일을 생성하여 개발 효율성을 높이는 툴입니다 Codebase-analyzer es una herramienta que analiza la estructura del proyecto y genera archivos CLAUDE.md de forma interactiva Codebase-analyzer est un outil qui analyse la structure du projet et génère des fichiers CLAUDE.md de manière interactive Codebase-analyzer ist ein Tool, das die Projektstruktur analysiert und CLAUDE.md-Dateien interaktiv generiert O Codebase Analyzer é uma ferramenta que mantém arquivos CLAUDE.md atualizados e interativos em seus projetos de desenvolvimento Codebase Analyzer — это инструмент, который автоматически обслуживает файлы CLAUDE.md в ваших проектах разработки _codebase analyzer_هو أداة تحافظ على ملفات CLAUDE.md محدثة وتفاعلية في مشاريع التطوير how to use codebase-analyzer codebase-analyzer setup guide what is codebase-analyzer codebase-analyzer alternative codebase-analyzer vs other plugins codebase-analyzer install CLAUDE.md file generation automated project structure analysis Claude Code plugin 代码库分析器 CLAUDE.md自动生成 项目结构分析 代码库管理 AI工具 代码分析 自动化工具 Analyzes project structure to generate CLAUDE.md files Provides options to migrate, backup, or merge existing CLAUDE.md files Follows mandatory guidelines to ensure correct CLAUDE.md content generation Supports interactive generation of CLAUDE.md files Handles existing CLAUDE.md files through user-defined actions codebase-analyzer is a Claude Code plugin that analyzes project structure and generates CLAUDE.md files interactively, following specific guidelines to ensure correct content generation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('evolving-machines-lab/evolve/tailored-resume-generator', 'community', 'evolving-machines-lab', 'evolve', 'evolving-machines-lab/evolve', 'tailored-resume-generator', 0, 0, 60, '2026-03-08T01:57:15.550Z', '2026-03-08T02:11:26.656Z', '7a64d9aa79a21a24f50c90a10d1a30f3c8a686d4869648e976ef69a784ba16e6', '{"id":"evolving-machines-lab/evolve/tailored-resume-generator","name":"tailored-resume-generator","description":{"en":"The tailored-resume-generator skill analyzes job descriptions to extract key requirements and skills, helping developers create customized resumes for different industries and roles.","zh":"定制简历生成器是一种使用CLI代理的工具，用于分析工作描述，生成针对特定职位的简历","ja":"カスタム_resume_生成ツールは、CLIエージェントを使用して求人情報を分析し、特定の仕事に合った履歴書を生成するツールです","ko":"맞춤형 이력서 생성기는 CLI 에이전트를 사용하여 작업 설명을 분석하고 특정 직무에 맞는 이력서를 생성하는 도구입니다","es":"El generador de currículums personalizados analiza descripciones de trabajo y resalta habilidades relevantes para mejorar las solicitudes de empleo","fr":"Le générateur de CV sur mesure analyse les descriptions de travail et met en évidence les compétences pertinentes pour améliorer les candidatures","de":"Der maßgeschneiderte Lebenslauf-Generator analysiert Stellenbeschreibungen und betont relevante Fähigkeiten, um Bewerbungen zu verbessern","pt":"O gerador de currículos personalizados é uma ferramenta que ajuda a criar resumos personalizados para diferentes vagas e indústrias, destacando habilidades relevantes e otimizando para sistemas de rastreamento de candidatos","ru":"ИИ Агент для создания индивидуальных резюме - это инструмент, который помогает создать персонализированные резюме для разных вакансий и отраслей, подчеркивая актуальные навыки и оптимизируя для систем отслеживания кандидатов","ar":"جهاز العرض السيرة الذاتية المخصص هو أداة تساعد على إنشاء سير ذاتية مخصصة لمختلف الوظائف والصناعات، وتسلط الضوء على المهارات ذات الصلة وتحسّن للأنظمة التي تتبع المرشحين"},"seo":{"title":{"en":"tailored-resume-generator: Automated Resume Customization...","zh":"定制简历生成器设置指南","ja":"カスタム_resume_生成ツールのベストプラクティス","ko":"맞춤형 이력서 생성기 사용법","es":"Generador de currículums personalizados: Guía de configur...","fr":"Générateur de CV sur mesure: Meilleures pratiques","de":"Maßgeschneiderter Lebenslauf-Generator: Einrichtungsanlei...","pt":"Guia de Configuração do Gerador de Currículos Personalizados","ru":"Настройка ИИ Агента для Создания Индивидуальных Резюме","ar":"دليل إعداد جهاز العرض السيرة الذاتية المخصص"},"description":{"en":"Unlock the power of tailored resumes with our AI agent skill. Discover how to analyze job descriptions and create customized resumes for different industries...","zh":"使用定制简历生成器，分析工作描述，提取关键要求，生成针对特定职位的简历","ja":"カスタム_resume_生成ツールを使用して、求人情報を分析し、キースキルを抽出して、特定の仕事に合った履歴書を生成します","ko":"맞춤형 이력서 생성기를 사용하여 작업 설명을 분석하고 핵심 요구 사항을 추출하여 특정 직무에 맞는 이력서를 생성합니다","es":"Aprende a utilizar el generador de currículums personalizados para optimizar tus solicitudes de empleo con herramientas de inteligencia artificial como agent...","fr":"Découvrez comment utiliser le générateur de CV sur mesure pour améliorer vos candidatures avec des outils d''intelligence artificielle tels que les agents dan...","de":"Erfahren Sie, wie Sie den maßgeschneiderten Lebenslauf-Generator nutzen können, um Ihre Bewerbungen mit künstlicher Intelligenz-Tools wie Cloud-Agents zu opt...","pt":"Aprenda a configurar o gerador de currículos personalizados para melhorar suas chances de contratação com resumos otimizados para sistemas de rastreamento de...","ru":"Узнайте, как настроить ИИ Агент для создания индивидуальных резюме, чтобы повысить свои шансы на трудоустройство с резюме, оптимизированными для систем отсле...","ar":"تعلم كيفية إعداد جهاز العرض السيرة الذاتية المخصص لتحسين فرصك في الحصول على وظيفة مع سير ذاتية محسّنة للأنظمة التي تتبع المرشحين"},"definition":{"en":"tailored-resume-generator is a skill that analyzes job descriptions to extract key requirements and skills, enabling the creation of customized resumes for various industries and roles.","zh":"定制简历生成器是一种AIエージェント，用于生成针对特定职位的简历","ja":"カスタム_resume_生成ツールは、特定の仕事に合った履歴書を生成するAIエージェントの一種です","ko":"맞춤형 이력서 생성기는 특정 직무에 맞는 이력서를 생성하는 AI 에이전트의 일종입니다","es":"Un generador de currículums personalizados es una herramienta de inteligencia artificial que ayuda a crear currículums adaptados a puestos de trabajo específicos","fr":"Un générateur de CV sur mesure est un outil d''intelligence artificielle qui aide à créer des CV adaptés à des postes spécifiques","de":"Ein maßgeschneideter Lebenslauf-Generator ist ein künstlicher Intelligenz-Tool, das dabei hilft, Lebensläufe für bestimmte Stellen zu erstellen","pt":"O que é um gerador de currículos personalizados? É uma ferramenta que analisa descrições de vagas e cria resumos personalizados","ru":"Что такое ИИ Агент для создания индивидуальных резюме? Это инструмент, который анализирует описания вакансий и создает персонализированные резюме","ar":"ما هو جهاز العرض السيرة الذاتية المخصص? هو أداة تحليل وصفات الوظائف وتقوم بإنشاء سير ذاتية مخصصة"},"features":{"en":["Analyzes job descriptions to extract key requirements and skills","Customizes resumes for different industries or roles","Highlights relevant experience for career transitions","Optimizes resumes for ATS (Applicant Tracking Systems)","Creates multiple resume versions for different job applications","Emphasizes specific skills mentioned in job postings"],"zh":["分析工作描述，提取关键要求","生成针对特定职位的简历","使用CLI代理，确保安全和可靠","支持多种职位和行业","优化简历以适应申请者跟踪系统（ATS）"],"ja":["求人情報を分析してキースキルを抽出","特定の仕事に合った履歴書を生成","CLIエージェントを使用してセキュリティと信頼性を確保","複数の仕事と業界をサポート","履歴書をATS（アプリケーショントラッキングシステム）に最適化"],"ko":["작업 설명을 분석하고 핵심 요구 사항을 추출","특정 직무에 맞는 이력서를 생성","CLI 에이전트를 사용하여 보안과 안정성을 제공","다양한 직무와 산업을 지원","이력서를 ATS（응용 프로그램 추적 시스템）에 최적화"],"es":["Análisis de descripciones de trabajo para extraer requisitos clave","Resaltado de habilidades relevantes para mejorar las solici